window.SOP_DEPTS={"people":{"name":"People and HR","short":"HR","code":"HR","d":"Hiring, onboarding, reviews, leave and leaving."},"sales":{"name":"Sales","short":"Sales","code":"SAL","d":"Leads, proposals, closing, handoffs and renewals."},"marketing":{"name":"Marketing","short":"Marketing","code":"MKT","d":"Content, campaigns, launches, events and PR."},"support":{"name":"Customer support and success","short":"Support","code":"CS","d":"Tickets, escalations, refunds and churn."},"finance":{"name":"Finance and accounting","short":"Finance","code":"FIN","d":"Invoicing, payables, close, payroll and tax."},"ops":{"name":"Operations and procurement","short":"Operations","code":"OPS","d":"Purchasing, vendors, stock, shipping and quality."},"it":{"name":"IT and security","short":"IT","code":"IT","d":"Access, backups, incidents, patching and devices."},"product":{"name":"Product and engineering","short":"Product","code":"ENG","d":"Releases, code review, bugs, on-call and post-mortems."},"legal":{"name":"Legal and compliance","short":"Legal","code":"LEG","d":"Contracts, NDAs, privacy requests and audits."},"safety":{"name":"Health, safety and facilities","short":"Safety","code":"HSE","d":"Inspections, accidents, fire drills and visitors."},"leadership":{"name":"Leadership and strategy","short":"Leadership","code":"EXE","d":"Meetings, OKRs, business reviews and crises."},"retail":{"name":"Retail, food and ecommerce","short":"Retail","code":"RET","d":"Store open and close, food safety and orders."},"pm":{"name":"Project management","short":"Projects","code":"PMO","d":"Kickoff, change control, status and closure."}};
window.SOP_TEMPLATES=[{"id":"people-recruitment-job-requisition","dept":"people","title":"Recruitment and Job Requisition","summary":"Turns an approved hiring need into a budgeted, well-defined job requisition and a live job advert.","tags":["hiring request","headcount","job requisition","job description","vacancy","recruiting"],"purpose":"To make sure every new role is justified, budgeted and approved before recruiting starts. It also ensures job descriptions are accurate, inclusive and consistent so the right candidates apply.","scope":"Covers new permanent and fixed-term roles and backfills for leavers at [Company]. It does not cover contractor engagements, internal transfers without a vacancy, or interviewing, which are covered by separate SOPs.","definitions":[["Requisition","A formal request to open a role, including budget, level, reporting line and justification."],["Headcount plan","The approved annual or quarterly plan listing budgeted roles by team."],["Backfill","A role opened to replace a leaver at the same level and budget."],["Hiring Manager","The person the new hire will report to and who owns the hiring decision."]],"roles":[["Hiring Manager","Raises the requisition, writes the role outcomes and owns the hiring decision."],["Department Head","Confirms business need and that the role is in the headcount plan."],["Finance Lead","Confirms budget, salary band affordability and cost centre."],["People Lead","Checks level and pay band, finalises the job description and publishes the advert."],["Recruiter","Builds the sourcing plan, posts adverts and manages the applicant pipeline."]],"prereqs":["Approved headcount plan for the period","Current salary bands and levelling framework","Requisition form in [ATS tool]","Job description template and inclusive language checklist","Org chart showing the proposed reporting line"],"steps":[{"t":"Raise the requisition","d":"Hiring Manager completes the requisition in [ATS tool] with title, level, start date, location, reason (new or backfill) and the three to five outcomes the role must deliver in its first year.","o":"Hiring Manager"},{"t":"Confirm business need","d":"Department Head confirms within 2 business days that the role is in the headcount plan or writes a short case for an unplanned hire.","o":"Department Head"},{"t":"Approve budget","d":"Finance Lead checks the fully loaded cost (salary, taxes, benefits, equipment) against budget and approves or rejects within 3 business days. Unplanned roles above [approval limit] also need CEO approval.","o":"Finance Lead"},{"t":"Set level and pay band","d":"People Lead maps the role to the levelling framework and confirms the salary range to be advertised or used in offers.","o":"People Lead"},{"t":"Write the job description","d":"Hiring Manager drafts responsibilities and must-have versus nice-to-have skills, keeping must-haves to six or fewer. People Lead edits for inclusive, plain language and removes unnecessary degree or years-of-experience requirements.","o":"Hiring Manager"},{"t":"Agree the hiring plan","d":"Recruiter and Hiring Manager hold a 30-minute intake meeting to agree interview stages, panel members, scorecard criteria, target hire date and sourcing channels.","o":"Recruiter"},{"t":"Consider internal candidates","d":"Recruiter posts the role on the internal jobs board for at least 3 business days before or alongside external advertising, unless confidential.","o":"Recruiter"},{"t":"Publish the advert","d":"Recruiter publishes the approved advert on the careers page and agreed job boards, including salary range where required by local law or company policy.","o":"Recruiter"},{"t":"Activate sourcing","d":"Recruiter runs outbound sourcing, referrals and any agency briefs. Agencies may only be used with a signed terms agreement and People Lead approval.","o":"Recruiter"},{"t":"Review pipeline weekly","d":"Recruiter shares a weekly pipeline update (applicants, screened, interviewing) with the Hiring Manager and adjusts sourcing if fewer than [10] qualified applicants after 2 weeks.","o":"Recruiter"},{"t":"Close or hold the requisition","d":"When an offer is accepted, or if the need changes, the Recruiter closes the requisition, removes adverts within 1 business day and informs remaining candidates.","o":"Recruiter"}],"checks":["No advert goes live without Finance and Department Head approval recorded in [ATS tool]","Job description reviewed against the inclusive language checklist","Advertised salary range matches the approved pay band","Scorecard criteria agreed before the first interview","Adverts removed within 1 business day of the role closing"],"kpis":[["Requisition approval time","90% approved within 5 business days"],["Time to fill","Median under [45] days from approval to accepted offer"],["Qualified applicants per role","At least [10] within 14 days"],["Hires within approved budget","100%"]],"risks":[["Hiring without budget approval","System workflow blocks publishing until Finance approval is recorded."],["Biased or exclusionary job adverts","Inclusive language review and limited must-have criteria."],["Role scope unclear, leading to mis-hire","Outcome-based requisition and intake meeting before sourcing."],["Agency fees incurred without agreement","Only approved agencies with signed terms may submit candidates."]],"related":["Interviewing and Candidate Selection","Job Offer and Pre-employment Checks","Headcount Planning Policy","Compensation and Promotion Review"],"review":"Every 12 months, or after a change to the headcount planning process or ATS"},{"id":"people-interviewing-candidate-selection","dept":"people","title":"Interviewing and Candidate Selection","summary":"Runs a fair, structured interview process that produces consistent evidence and a documented hiring decision.","tags":["interview","candidate assessment","scorecard","selection","hiring panel","debrief"],"purpose":"To assess candidates fairly and consistently against agreed criteria so that hiring decisions are based on evidence rather than gut feel. It also gives candidates a timely, respectful experience.","scope":"Covers screening, interviews, work samples and the final hiring decision for all roles at [Company]. It does not cover requisition approval or offer and background checks.","definitions":[["Scorecard","The list of competencies and skills each interviewer rates, with a defined rating scale."],["Structured interview","An interview where every candidate for the role is asked the same core questions and rated on the same scale."],["Debrief","The meeting where the panel shares evidence and reaches a hire or no-hire decision."],["Work sample","A short, realistic task that reflects the actual job, used to assess skill directly."]],"roles":[["Recruiter","Screens applicants, schedules interviews, manages candidate communication and runs the ATS."],["Hiring Manager","Defines the scorecard, leads the debrief and makes the final decision."],["Interviewer","Conducts their assigned interview, records ratings and evidence before the debrief."],["People Lead","Trains interviewers, monitors fairness and resolves process issues."]],"prereqs":["Approved requisition and job description","Agreed scorecard and interview plan in [ATS tool]","Trained interview panel","Question bank and work sample brief","Video conferencing and calendar access"],"steps":[{"t":"Screen applications","d":"Recruiter reviews new applications against must-have criteria within 3 business days of receipt and moves, rejects or holds each candidate in [ATS tool].","o":"Recruiter"},{"t":"Hold a screening call","d":"Recruiter runs a 20 to 30 minute call to confirm motivation, salary expectations, notice period and right to work, and shares the process and timeline.","o":"Recruiter"},{"t":"Assign interview focus areas","d":"Hiring Manager allocates each scorecard competency to one interviewer so there is no overlap and every area is covered.","o":"Hiring Manager"},{"t":"Schedule interviews","d":"Recruiter offers slots within 5 business days of the screen and sends candidates the format, names of interviewers and any adjustments offered.","o":"Recruiter"},{"t":"Run structured interviews","d":"Interviewers ask the agreed core questions, probe with follow-ups and take notes on evidence, not impressions. Questions about protected characteristics are not permitted.","o":"Interviewer"},{"t":"Assess the work sample","d":"Where used, the work sample takes no more than [3] hours of candidate time and is marked against a written rubric by two reviewers.","o":"Interviewer"},{"t":"Submit feedback independently","d":"Each interviewer submits ratings and written evidence in [ATS tool] within 24 hours and before seeing other panel feedback.","o":"Interviewer"},{"t":"Hold the debrief","d":"Hiring Manager runs a debrief within 2 business days of the final interview, reviewing evidence competency by competency before any overall vote.","o":"Hiring Manager"},{"t":"Make and record the decision","d":"Hiring Manager records hire or no-hire with a reason linked to the scorecard. A hire needs no 'strong no' ratings unresolved in the debrief.","o":"Hiring Manager"},{"t":"Take references","d":"Recruiter takes at least two references, with candidate consent, for the preferred candidate before or alongside the offer.","o":"Recruiter"},{"t":"Inform candidates","d":"Recruiter informs unsuccessful candidates within 3 business days of the decision. Candidates who reached final stage receive a call or personalised feedback.","o":"Recruiter"},{"t":"Review process fairness","d":"People Lead reviews stage pass rates and feedback quality each quarter and coaches interviewers where scoring is inconsistent.","o":"People Lead"}],"checks":["Every interviewer has completed interview training","Feedback submitted before the debrief for 100% of interviews","Decision reason recorded against the scorecard","Reasonable adjustments offered to all candidates","Candidate data retained only for the period stated in the privacy notice"],"kpis":[["Feedback submitted within 24 hours","95%"],["Time from first interview to decision","Under [10] business days"],["Candidate experience score","Average 4 out of 5 or above"],["Offer acceptance rate","At least [80]%"]],"risks":[["Inconsistent or biased assessments","Structured questions, independent scoring and debrief by competency."],["Losing strong candidates to slow processes","Scheduling and decision time targets monitored weekly."],["Discriminatory questions","Interviewer training and question bank with prohibited topics listed."],["Personal data mishandled","Notes kept only in [ATS tool] and deleted per the retention schedule."]],"related":["Recruitment and Job Requisition","Job Offer and Pre-employment Checks","Candidate Privacy Notice","Equal Opportunities Policy"],"review":"Every 12 months, or after a complaint or audit finding about the hiring process"},{"id":"people-job-offer-preemployment-checks","dept":"people","title":"Job Offer and Pre-employment Checks","summary":"Makes approved, accurate job offers and completes required checks before the new hire's start date.","tags":["offer letter","background check","right to work","references","contract","pre-employment"],"purpose":"To make offers that are approved, competitive and legally sound, and to verify a candidate is eligible and suitable to work before they start. This protects both [Company] and the candidate.","scope":"Covers verbal and written offers, employment contracts and pre-employment screening for all employees. It does not cover contractor agreements or onboarding activities after the contract is signed.","definitions":[["Conditional offer","An offer that depends on satisfactory completion of listed checks."],["Right to work check","Verification that a person is legally permitted to work in the country of employment."],["Background screening","Checks such as identity, employment history, qualifications and, where lawful and relevant, criminal records."],["Offer approval","Sign-off of salary, equity and start date by the authorised approvers."]],"roles":[["Hiring Manager","Proposes offer terms and makes the verbal offer with the Recruiter."],["People Lead","Checks terms against pay bands, prepares the contract and manages checks."],["Finance Lead","Approves offers above the band midpoint or outside budget."],["Recruiter","Communicates with the candidate, negotiates within limits and tracks acceptance."],["Candidate","Provides documents and consents needed for checks."]],"prereqs":["Hiring decision recorded in [ATS tool]","Approved pay band and benefits summary","Contract and offer letter templates reviewed by legal","Screening provider account and consent forms","Check local law on which checks are permitted for the role"],"steps":[{"t":"Prepare offer terms","d":"Hiring Manager and People Lead agree base pay, variable pay, equity, start date and job title within 1 business day of the hire decision.","o":"People Lead"},{"t":"Obtain approval","d":"Offers within band go to the Department Head. Offers above band midpoint by more than [10]% or including a sign-on bonus need Finance Lead approval, recorded in [ATS tool].","o":"Finance Lead"},{"t":"Make the verbal offer","d":"Recruiter or Hiring Manager calls the candidate, explains the full package and conditions, and agrees a response date, normally within 5 business days.","o":"Recruiter"},{"t":"Handle negotiation","d":"Recruiter negotiates only within approved limits. Any change outside limits returns to the approval step before being promised.","o":"Recruiter"},{"t":"Issue the written offer and contract","d":"People Lead sends the conditional offer letter and contract via [e-signature tool] within 1 business day of verbal acceptance.","o":"People Lead"},{"t":"Collect consent and documents","d":"Candidate provides identity documents, right to work evidence and signed consent for screening. Recruiter chases outstanding items every 2 business days.","o":"Candidate"},{"t":"Run the checks","d":"People Lead initiates the agreed checks for the role level and logs results. Criminal record checks only where lawful and justified for the role.","o":"People Lead"},{"t":"Review adverse results","d":"Any discrepancy is discussed with the candidate before a decision. People Lead and Hiring Manager decide whether to proceed, documenting the reason.","o":"People Lead"},{"t":"Confirm the offer is unconditional","d":"Once all checks pass, People Lead confirms in writing that conditions are met and the start date is fixed.","o":"People Lead"},{"t":"Trigger onboarding","d":"People Lead creates the employee record in [HRIS tool] and starts the onboarding SOP at least 10 business days before the start date where possible.","o":"People Lead"}],"checks":["Offer terms match approval record exactly","Right to work verified and copies stored securely before day one","Signed contract on file before start date","Candidate consent recorded for every check","Unsuccessful finalists informed once offer is accepted"],"kpis":[["Offer acceptance rate","At least [80]%"],["Offer letter issued after verbal acceptance","100% within 1 business day"],["Checks completed before start date","100%"],["Offers outside band without approval","Zero"]],"risks":[["Illegal working","Right to work check completed and recorded before day one, no exceptions."],["Pay inequity from ad hoc offers","Band checks and approval thresholds."],["Unlawful or excessive screening","Check matrix by role reviewed against local law."],["Candidate withdraws during delay","Regular contact and fast document turnaround."]],"related":["Interviewing and Candidate Selection","Employee Onboarding","Data Retention Policy","Compensation and Promotion Review"],"review":"Every 12 months, or when employment or screening law changes"},{"id":"people-employee-onboarding","dept":"people","title":"Employee Onboarding","summary":"Prepares, welcomes and integrates new hires so they are equipped, compliant and productive by day 90.","tags":["new hire","first day","induction","orientation","welcome","30 60 90"],"purpose":"To give every new employee a consistent, well-organised start with the equipment, access, knowledge and relationships they need. Good onboarding shortens time to productivity and reduces early attrition.","scope":"Covers all new employees from signed contract to the end of their first 90 days. It does not cover contractors, internal transfers or the formal probation decision, which has its own SOP.","definitions":[["Preboarding","Activities between contract signature and day one."],["Onboarding buddy","A peer, not the manager, who helps the new hire with informal questions in the first weeks."],["30-60-90 plan","A written plan of goals and learning for the first three months."],["Access provisioning","Creating accounts and permissions the role needs, following least privilege."]],"roles":[["People Lead","Owns the onboarding checklist, HR paperwork and induction sessions."],["Hiring Manager","Writes the 30-60-90 plan, sets first tasks and holds weekly check-ins."],["IT Administrator","Provides equipment and system access before day one."],["Onboarding Buddy","Supports the new hire socially and with day-to-day questions."],["New Hire","Completes required forms, training and acknowledgements on time."]],"prereqs":["Signed contract and completed pre-employment checks","Onboarding checklist in [HRIS tool]","Role access matrix","Equipment stock or supplier order lead time","Employee handbook and mandatory policies"],"steps":[{"t":"Start the checklist","d":"People Lead opens the onboarding checklist in [HRIS tool] at least 10 business days before the start date and assigns tasks to each owner.","o":"People Lead"},{"t":"Order equipment and access","d":"IT Administrator orders the laptop and peripherals and creates accounts per the role access matrix, ready 2 business days before day one.","o":"IT Administrator"},{"t":"Send the welcome pack","d":"People Lead emails the new hire a week before start with day-one time, location or video link, what to bring, first-week agenda and payroll forms.","o":"People Lead"},{"t":"Prepare the 30-60-90 plan","d":"Hiring Manager writes the plan with clear outcomes for each period and lines up a meaningful first task achievable in week one.","o":"Hiring Manager"},{"t":"Assign a buddy","d":"Hiring Manager picks a buddy from a different reporting line where possible and briefs them on their role.","o":"Hiring Manager"},{"t":"Deliver day one","d":"People Lead runs the welcome session covering company story, values, policies and tools. Hiring Manager meets the new hire for at least 1 hour the same day.","o":"People Lead"},{"t":"Complete mandatory items","d":"New Hire completes tax and bank forms, policy acknowledgements and mandatory training such as security awareness within the first 5 business days.","o":"New Hire"},{"t":"Schedule introductions","d":"Hiring Manager books introductions with key colleagues and cross-functional partners across the first 2 weeks.","o":"Hiring Manager"},{"t":"Hold weekly check-ins","d":"Hiring Manager holds a 30-minute check-in every week for the first 6 weeks, reviewing progress against the plan and any blockers.","o":"Hiring Manager"},{"t":"Run a 30-day pulse","d":"People Lead sends a short survey at day 30 on equipment, clarity of role and support, and follows up on any score below 3 out of 5.","o":"People Lead"},{"t":"Review at 90 days","d":"Hiring Manager reviews the 30-60-90 outcomes with the New Hire and records a summary, feeding into the probation review.","o":"Hiring Manager"},{"t":"Close the checklist","d":"People Lead confirms all tasks are complete and closes the checklist, logging any onboarding improvements raised.","o":"People Lead"}],"checks":["Equipment and access ready before day one","All policy acknowledgements recorded within 5 business days","Access granted matches the role access matrix, no extra privileges","30-60-90 plan shared by end of day one","Payroll details captured before first pay run cut-off"],"kpis":[["Day-one readiness","95% of hires have working equipment and access on day one"],["New hire 30-day survey score","4 out of 5 or above"],["90-day retention","At least [95]%"],["Mandatory training completion in week one","100%"]],"risks":[["Excess access granted","Role access matrix and manager approval for any exception."],["Poor first impression causing early exit","Checklist with lead times and 30-day pulse."],["Missed first payroll","Payroll forms in welcome pack and cut-off tracking."],["Compliance training skipped","System tracking with reminders and manager escalation at day 7."]],"related":["Job Offer and Pre-employment Checks","Probation Review","Training and Development","IT Access Management Policy"],"review":"Every 12 months, or after new hire survey scores fall below target for a quarter"},{"id":"people-probation-review","dept":"people","title":"Probation Review","summary":"Gives new employees clear feedback during probation and reaches a timely, documented confirm, extend or end decision.","tags":["probation","trial period","confirmation","new hire review","extension"],"purpose":"To make sure every new employee receives regular feedback in their probation period and a fair decision at the end. Clear records protect both the employee and [Company].","scope":"Covers employees whose contract includes a probation period, normally [3 to 6] months. It does not cover performance issues after probation, which follow the Grievance and Disciplinary Process or performance improvement plans.","definitions":[["Probation period","An initial employment period stated in the contract during which suitability is assessed."],["Confirmation","Written confirmation that the employee has passed probation."],["Extension","A one-off lengthening of probation with specific objectives, where permitted by the contract and local law."],["Mid-point review","A formal check-in halfway through probation."]],"roles":[["Line Manager","Sets expectations, gives feedback, holds reviews and recommends the outcome."],["People Lead","Tracks dates, advises managers and issues outcome letters."],["Employee","Takes part in reviews and raises concerns or support needs."],["Department Head","Approves extensions and terminations at the end of probation."]],"prereqs":["Contract stating probation length and notice","Probation dates tracked in [HRIS tool]","30-60-90 plan from onboarding","Probation review form template"],"steps":[{"t":"Set objectives in week one","d":"Line Manager confirms probation objectives in writing, drawn from the 30-60-90 plan, and explains how they will be assessed.","o":"Line Manager"},{"t":"Diarise review dates","d":"People Lead sets reminders in [HRIS tool] for the mid-point and for 3 weeks before the end date.","o":"People Lead"},{"t":"Give ongoing feedback","d":"Line Manager gives specific feedback in weekly 1:1s and notes concerns as they arise rather than saving them for the review.","o":"Line Manager"},{"t":"Hold the mid-point review","d":"Line Manager completes the review form, rating progress against each objective, and agrees any support or training needed.","o":"Line Manager"},{"t":"Escalate early concerns","d":"If performance or conduct is below standard at mid-point, Line Manager informs People Lead within 2 business days and sets a written improvement plan.","o":"Line Manager"},{"t":"Prepare the final review","d":"Three weeks before the end date, Line Manager gathers evidence and seeks input from 2 to 3 colleagues who work closely with the employee.","o":"Line Manager"},{"t":"Hold the final meeting","d":"Line Manager meets the Employee at least 1 week before probation ends to discuss the evidence and the recommended outcome.","o":"Line Manager"},{"t":"Approve the outcome","d":"Extensions and terminations need Department Head and People Lead approval before being communicated as final.","o":"Department Head"},{"t":"Issue the outcome letter","d":"People Lead issues a confirmation, extension (with objectives and new end date) or termination letter within 2 business days of the decision.","o":"People Lead"},{"t":"Update records","d":"People Lead updates employment status in [HRIS tool] and files the review forms in the personnel record.","o":"People Lead"}],"checks":["Mid-point review completed for every employee on probation","No probation passes by default without a recorded decision","Concerns documented with examples before any extension or termination","Termination decisions checked against local law and contract notice terms"],"kpis":[["Reviews completed on time","95% of mid-point and final reviews"],["Outcome letters within 2 business days","100%"],["Probation pass rate","Tracked, target [85 to 95]%"],["Extensions resolved within extended period","100%"]],"risks":[["Probation lapses with no decision","Automated reminders and People Lead weekly report of upcoming end dates."],["Unfair dismissal claim","Documented feedback, improvement plan and People Lead review."],["Surprise negative outcome for employee","Mid-point review and feedback in regular 1:1s."]],"related":["Employee Onboarding","Performance Review Cycle","Grievance and Disciplinary Process","Employment Contract Template"],"review":"Every 12 months, or after a probation-related dispute"},{"id":"people-employee-offboarding","dept":"people","title":"Employee Offboarding","summary":"Manages leavers consistently, securing company assets and access while capturing knowledge and feedback.","tags":["leaver","resignation","exit interview","termination","access removal","last day"],"purpose":"To close every employment relationship professionally and securely. It ensures access is revoked on time, equipment and data are returned, final pay is correct and knowledge is handed over.","scope":"Covers voluntary resignations, dismissals, redundancies and end of fixed-term contracts. It does not cover the disciplinary or redundancy decision itself, which follows separate procedures.","definitions":[["Leaving date","The last day of employment, which may differ from the last working day if garden leave applies."],["Exit interview","A confidential conversation to understand reasons for leaving."],["Access revocation","Disabling all accounts, keys and badges belonging to the leaver."],["Handover plan","A document listing the leaver's responsibilities, open work and who takes each over."]],"roles":[["Line Manager","Confirms the leaving date, owns the handover plan and redistributes work."],["People Lead","Runs the offboarding checklist, exit interview and final documentation."],["IT Administrator","Revokes access, recovers equipment and preserves data as required."],["Payroll Administrator","Calculates final pay, accrued holiday and deductions."],["Leaver","Completes handover, returns equipment and company data."]],"prereqs":["Resignation letter or termination decision","Offboarding checklist in [HRIS tool]","Asset register showing equipment issued","System access list for the leaver","Contract terms on notice, restrictive covenants and holiday"],"steps":[{"t":"Acknowledge the notice","d":"People Lead acknowledges the resignation in writing within 2 business days, confirming notice period and leaving date.","o":"People Lead"},{"t":"Open the checklist","d":"People Lead opens the offboarding checklist in [HRIS tool] and notifies IT, Payroll and the Line Manager of the leaving date.","o":"People Lead"},{"t":"Agree the handover plan","d":"Line Manager and Leaver list all responsibilities, open work, client relationships and passwords held in shared vaults, assigning an owner to each within the first week of notice.","o":"Line Manager"},{"t":"Communicate the departure","d":"Line Manager agrees wording with the Leaver and informs the team, then clients if relevant, within 5 business days of notice.","o":"Line Manager"},{"t":"Calculate final pay","d":"Payroll Administrator calculates salary to leaving date, accrued untaken holiday, expenses and any deductions, and confirms with People Lead before the final payroll cut-off.","o":"Payroll Administrator"},{"t":"Hold the exit interview","d":"People Lead holds an exit interview in the final 2 weeks, using a standard question set, and records themes without personal attribution in reporting.","o":"People Lead"},{"t":"Recover equipment","d":"IT Administrator arranges return of laptop, phone, badges and keys on or before the last day, with prepaid courier for remote staff.","o":"IT Administrator"},{"t":"Revoke access","d":"IT Administrator disables all accounts by end of the last working day, or immediately for involuntary exits, and transfers file and mailbox ownership to the Line Manager.","o":"IT Administrator"},{"t":"Issue leaving documents","d":"People Lead issues the leaving letter, reminder of confidentiality and any restrictive covenants, and required tax or employment documents.","o":"People Lead"},{"t":"Close records","d":"People Lead updates status in [HRIS tool], removes the leaver from benefits and schedules data deletion per the retention policy.","o":"People Lead"}],"checks":["All access disabled within [4] hours of the last working day, immediately for involuntary exits","100% of issued assets returned or written off with approval","Final pay reviewed by a second person","Handover plan signed off by the Line Manager","Shared credentials rotated where the leaver had access"],"kpis":[["Access revoked on time","100%"],["Assets recovered within 10 business days","At least 98%"],["Final pay errors","Zero"],["Exit interview completion rate","At least [80]% of voluntary leavers"]],"risks":[["Former employee retains system access","Checklist linked to the access list and same-day revocation control."],["Loss of knowledge or client relationships","Handover plan started in week one of notice."],["Data taken by the leaver","Device return, access logs reviewed for unusual downloads in the notice period."],["Incorrect final pay","Two-person review before payroll cut-off."]],"related":["Employee Onboarding","Grievance and Disciplinary Process","Data Retention Policy","IT Access Management Policy"],"review":"Every 12 months, or after a security incident involving a former employee"},{"id":"people-performance-review-cycle","dept":"people","title":"Performance Review Cycle","summary":"Runs a fair, calibrated performance review cycle with clear ratings, feedback and development goals.","tags":["performance review","appraisal","calibration","feedback","goals","annual review"],"purpose":"To give every employee regular, evidence-based feedback on their contribution and agreed goals for the next period. Calibrated ratings make reward and promotion decisions fair and defensible.","scope":"Covers the [annual or twice-yearly] review cycle for all employees past probation. It does not cover probation reviews, pay decisions (see Compensation and Promotion Review) or formal performance improvement plans.","definitions":[["Self-assessment","The employee's own written reflection on results and growth."],["Peer feedback","Input from colleagues who work closely with the employee."],["Calibration","A meeting where managers compare proposed ratings to apply standards consistently."],["Rating scale","The defined performance levels, for example [Below, Meets, Exceeds, Outstanding]."]],"roles":[["People Lead","Designs the cycle, publishes the timeline, runs calibration and reports completion."],["Line Manager","Gathers evidence, writes the review, proposes a rating and holds the conversation."],["Employee","Completes the self-assessment and agrees next-period goals."],["Peer Reviewer","Gives specific, constructive feedback when requested."],["Department Head","Chairs calibration for their area and approves final ratings."]],"prereqs":["Published rating scale and competency framework","Goals set at the start of the period","Review forms in [performance tool]","Cycle timeline communicated at least 4 weeks ahead","Manager training on writing reviews"],"steps":[{"t":"Publish the timeline","d":"People Lead announces cycle dates, forms and guidance at least 4 weeks before launch.","o":"People Lead"},{"t":"Train managers","d":"People Lead runs a 1-hour refresher on evidence-based writing, the rating scale and avoiding common biases such as recency and halo effects.","o":"People Lead"},{"t":"Complete self-assessment","d":"Employee completes the self-assessment within 10 business days of launch, covering results against goals, strengths and development areas.","o":"Employee"},{"t":"Request peer feedback","d":"Line Manager requests feedback from 2 to 4 peers, chosen with the Employee. Peers respond within 7 business days using the standard questions.","o":"Peer Reviewer"},{"t":"Draft the review","d":"Line Manager drafts the review with specific examples and a proposed rating, without sharing it with the Employee before calibration.","o":"Line Manager"},{"t":"Calibrate ratings","d":"Department Head runs calibration with all managers in the area. Managers justify ratings with evidence and People Lead checks the distribution for patterns by team or demographic group.","o":"Department Head"},{"t":"Finalise ratings","d":"Department Head approves final ratings and People Lead locks them in [performance tool] within 2 business days of calibration.","o":"Department Head"},{"t":"Hold the review conversation","d":"Line Manager meets each Employee for at least 45 minutes within 2 weeks of calibration to discuss the review and rating.","o":"Line Manager"},{"t":"Set next-period goals","d":"Line Manager and Employee agree 3 to 5 measurable goals and one development goal, recorded within 10 business days of the conversation.","o":"Employee"},{"t":"Sign off the review","d":"Employee acknowledges the review in [performance tool] and may add comments. Disagreements may be raised with the Department Head within 10 business days.","o":"Employee"},{"t":"Report and improve","d":"People Lead reports completion, rating distribution and survey feedback on the cycle to leadership and logs changes for the next cycle.","o":"People Lead"}],"checks":["Every review includes at least two specific examples","Ratings calibrated before being communicated","Distribution checked for unexplained differences across groups","Completion tracked weekly with reminders to late managers","Employee comment and appeal route available"],"kpis":[["Review completion by deadline","At least 95%"],["Employees with agreed goals within 30 days","100%"],["Employee agreement that review was fair","At least [75]% in post-cycle survey"],["Appeals upheld","Tracked, investigated where above [5]%"]],"risks":[["Biased or inconsistent ratings","Calibration, evidence requirements and demographic distribution check."],["Reviews seen as tick-box exercise","Short forms, quality checks and goal follow-up in 1:1s."],["Surprise poor ratings","Expect ongoing feedback in 1:1s, flagged in manager training."],["Confidential data leaked","Role-based access in [performance tool]."]],"related":["Compensation and Promotion Review","Probation Review","Training and Development","Grievance and Disciplinary Process"],"review":"After every cycle, with a full review every 12 months"},{"id":"people-leave-time-off-requests","dept":"people","title":"Leave and Time-off Requests","summary":"Handles holiday, sick and other leave requests consistently, keeping cover in place and balances accurate.","tags":["holiday","vacation","annual leave","sick leave","PTO","absence","parental leave"],"purpose":"To make taking leave simple for employees while making sure teams keep enough cover and records stay accurate for payroll. It also ensures statutory leave entitlements are respected.","scope":"Covers annual leave, sickness absence, compassionate leave, parental and family leave requests and unpaid leave for all employees. It does not cover long-term sickness case management or remote work arrangements.","definitions":[["Leave year","The 12-month period over which annual leave entitlement is calculated, for example [January to December]."],["Accrual","The rate at which leave entitlement builds up over the leave year."],["Blackout period","Dates when leave is restricted due to business peaks, published in advance."],["Return-to-work conversation","A short check-in after sickness absence to support the employee and agree any adjustments."]],"roles":[["Employee","Requests leave in advance, reports sickness on time and keeps records accurate."],["Line Manager","Approves or declines requests and arranges cover."],["People Lead","Maintains the leave policy, balances and statutory leave cases."],["Payroll Administrator","Applies leave to pay, including sick pay and unpaid leave deductions."]],"prereqs":["Leave policy and entitlements per contract","Leave module in [HRIS tool]","Team calendar and published blackout periods","Check local law for statutory minimums and family leave rules"],"steps":[{"t":"Submit the request","d":"Employee submits annual leave in [HRIS tool] with notice of at least twice the length of the leave, for example 2 weeks' notice for a 1-week holiday.","o":"Employee"},{"t":"Check cover and decide","d":"Line Manager checks team calendar and cover and approves or declines within 3 business days. A decline must give a reason and suggest alternative dates.","o":"Line Manager"},{"t":"Resolve clashes fairly","d":"Where several requests clash, Line Manager applies first come, first served unless a documented exceptional reason applies.","o":"Line Manager"},{"t":"Report sickness","d":"Employee notifies the Line Manager by [time] on the first day of absence by phone or message and gives an expected return date where possible.","o":"Employee"},{"t":"Record sickness","d":"Line Manager logs the absence in [HRIS tool] the same day. Absence over [7] calendar days requires a medical certificate where local law allows.","o":"Line Manager"},{"t":"Hold return-to-work check-in","d":"Line Manager holds a short, supportive conversation on the first day back, records it and refers to People Lead if absences exceed [3 occasions in 6 months].","o":"Line Manager"},{"t":"Handle family and special leave","d":"Employee notifies People Lead of parental, adoption or other statutory leave within the notice period set by local law. People Lead confirms entitlements and pay in writing within 5 business days.","o":"People Lead"},{"t":"Process pay effects","d":"Payroll Administrator applies sick pay, statutory pay and unpaid leave deductions from [HRIS tool] reports before each payroll cut-off.","o":"Payroll Administrator"},{"t":"Monitor balances","d":"People Lead reviews balances quarterly and reminds employees with more than [50]% of entitlement unused in the last quarter of the leave year.","o":"People Lead"},{"t":"Apply year-end rules","d":"People Lead applies carry-over limits and pays or forfeits balances in line with policy and local law at the end of the leave year.","o":"People Lead"}],"checks":["No team falls below minimum cover levels","All sickness recorded in [HRIS tool] on the day it starts","Statutory leave entitlements checked before confirming terms","Health information stored securely with restricted access","Payroll leave report reconciled each pay run"],"kpis":[["Leave requests decided within 3 business days","95%"],["Leave balance accuracy","100% match between HRIS and payroll"],["Return-to-work check-ins completed","At least 95%"],["Employees using at least 80% of entitlement","At least [90]%"]],"risks":[["Understaffing in peak periods","Published blackout periods and minimum cover rules."],["Burnout from untaken leave","Quarterly balance reminders and manager visibility."],["Breach of statutory leave rights","People Lead review of all statutory leave cases."],["Confidential health data exposure","Restricted access to medical notes."]],"related":["Remote and Hybrid Work","Payroll Processing","Employee Wellbeing Policy","Grievance and Disciplinary Process"],"review":"Every 12 months, or when leave law changes"},{"id":"people-remote-hybrid-work","dept":"people","title":"Remote and Hybrid Work","summary":"Sets how employees request, set up and work in remote or hybrid arrangements safely, securely and productively.","tags":["remote work","hybrid","work from home","WFH","flexible working","home office"],"purpose":"To give clear, fair rules for working away from the office so collaboration, security and wellbeing are maintained. It sets expectations on availability, equipment and communication.","scope":"Covers employees working fully remotely or on a hybrid pattern, including requests to change arrangements. It does not cover temporary working abroad beyond [10] business days, which needs separate tax and legal approval, or contractors.","definitions":[["Hybrid pattern","An agreed split of office and remote days, for example [2 office days per week]."],["Core hours","The hours when all employees are expected to be available, for example [10:00 to 15:00 local time]."],["Home workstation assessment","A self-check of the home desk set-up for health and safety."],["Work from abroad","Working from a country other than the contracted one."]],"roles":[["Employee","Requests the arrangement, maintains a safe workspace and follows security rules."],["Line Manager","Assesses requests, agrees the pattern and reviews how it is working."],["People Lead","Maintains the policy, keeps records and advises on legal and tax issues."],["IT Administrator","Provides equipment, secure access and support for remote set-ups."]],"prereqs":["Remote and hybrid work policy","Request form in [HRIS tool]","Home workstation self-assessment checklist","VPN or zero-trust access and device management","Home office equipment allowance of [amount]"],"steps":[{"t":"Submit the request","d":"Employee submits a request in [HRIS tool] stating the pattern, location and how the role's duties will be met.","o":"Employee"},{"t":"Assess the request","d":"Line Manager reviews role suitability, team needs and performance and responds in writing within 10 business days. Check local law for any statutory flexible working request process.","o":"Line Manager"},{"t":"Agree the arrangement","d":"Line Manager and Employee agree days, core hours, communication norms and a trial period of [3] months where appropriate.","o":"Line Manager"},{"t":"Record the arrangement","d":"People Lead records the pattern and work location in [HRIS tool] and updates the contract or issues a variation letter if permanent.","o":"People Lead"},{"t":"Set up equipment and access","d":"IT Administrator ships equipment, enrols the device in management and confirms secure access within 5 business days of approval.","o":"IT Administrator"},{"t":"Complete the workstation assessment","d":"Employee completes the home workstation self-assessment within 2 weeks and flags any issues. People Lead arranges equipment or adjustments where needed.","o":"Employee"},{"t":"Follow security rules","d":"Employee uses only managed devices, locks screens, avoids public Wi-Fi without VPN and keeps confidential calls private.","o":"Employee"},{"t":"Hold in-person time","d":"Line Manager organises team in-person days at least [quarterly] for planning and connection, with travel costs reimbursed per the expenses policy.","o":"Line Manager"},{"t":"Approve work from abroad","d":"Employee requests any work outside the contracted country at least 4 weeks ahead. People Lead checks tax, immigration and insurance before approval.","o":"People Lead"},{"t":"Review the arrangement","d":"Line Manager reviews the arrangement at the end of the trial and then annually, recording outcome and any changes.","o":"Line Manager"}],"checks":["Every remote worker has a completed workstation assessment","All remote devices enrolled in device management","Work location recorded for tax and insurance purposes","Decisions on requests given in writing with reasons","Core hours and response expectations documented for each team"],"kpis":[["Requests answered within 10 business days","100%"],["Workstation assessments completed","100% within 2 weeks"],["Remote devices compliant with security baseline","At least 98%"],["Employee engagement score for remote staff","Within [5] points of office-based staff"]],"risks":[["Data breach from insecure home set-up","Managed devices, VPN and security training."],["Isolation and lower engagement","Regular in-person days and structured 1:1s."],["Unapproved working abroad creating tax exposure","Mandatory approval and location tracking."],["Inconsistent decisions between teams","Documented criteria and People Lead review of declined requests."]],"related":["Leave and Time-off Requests","Information Security Policy","Expenses Policy","Health and Safety Policy"],"review":"Every 12 months, or after a change in office strategy or a related security incident"},{"id":"people-grievance-disciplinary-process","dept":"people","title":"Grievance and Disciplinary Process","summary":"Handles employee complaints and conduct issues fairly, promptly and consistently, with a clear record.","tags":["grievance","disciplinary","misconduct","complaint","investigation","warning","appeal"],"purpose":"To resolve concerns raised by employees and address misconduct or capability problems through a fair, consistent process. It protects employees' rights and reduces legal risk for [Company].","scope":"Covers formal grievances, disciplinary matters for conduct or capability, investigations, hearings and appeals for all employees. It does not cover whistleblowing reports, which follow the whistleblowing policy, or probation reviews unless the contract applies this process.","definitions":[["Grievance","A formal complaint by an employee about work, colleagues or treatment."],["Gross misconduct","Serious conduct that may justify dismissal without notice, as listed in the disciplinary policy."],["Investigation","Fact-finding by a neutral person before any decision on outcome."],["Companion","A colleague or representative who may accompany the employee at formal meetings, where local law or policy allows."]],"roles":[["People Lead","Manages the process, advises all parties and keeps records."],["Investigating Officer","Gathers facts neutrally and writes the investigation report."],["Hearing Manager","Chairs the hearing and decides the outcome. Must not be the investigator."],["Appeal Manager","Hears any appeal. Must be more senior than and independent of the Hearing Manager."],["Employee","Raises concerns or responds to allegations and attends meetings."]],"prereqs":["Grievance and disciplinary policy","Investigation report and letter templates","Secure case file location with restricted access","Check local law and any applicable code of practice","Access to external HR or legal adviser for complex cases"],"steps":[{"t":"Try informal resolution","d":"For minor issues, Line Manager or People Lead discusses the concern informally first and records the agreed outcome, unless the matter is serious.","o":"People Lead"},{"t":"Log the case","d":"People Lead logs any formal grievance or disciplinary concern within 1 business day, opens a confidential case file and appoints an Investigating Officer.","o":"People Lead"},{"t":"Consider precautionary measures","d":"For serious allegations, People Lead considers suspension on full pay or temporary changes, which are neutral acts, and reviews them every 2 weeks.","o":"People Lead"},{"t":"Investigate","d":"Investigating Officer interviews the employee, witnesses and reviews documents, aiming to finish within 15 business days, and writes a factual report with recommendations.","o":"Investigating Officer"},{"t":"Invite to a hearing","d":"People Lead sends a written invitation at least 3 business days ahead, stating the allegations or grievance, evidence, the right to be accompanied and possible outcomes.","o":"People Lead"},{"t":"Hold the hearing","d":"Hearing Manager lets the Employee respond fully, considers any mitigation and adjourns before deciding. People Lead takes notes.","o":"Hearing Manager"},{"t":"Decide the outcome","d":"Hearing Manager decides on the balance of evidence and chooses a proportionate outcome, from no action to warning to dismissal, consistent with past cases.","o":"Hearing Manager"},{"t":"Confirm in writing","d":"People Lead sends the outcome letter within 5 business days, with reasons, the warning duration if any, and the right to appeal.","o":"People Lead"},{"t":"Hear any appeal","d":"Employee appeals in writing within [5] business days. Appeal Manager holds an appeal meeting within 10 business days and the decision is final.","o":"Appeal Manager"},{"t":"Close and follow up","d":"People Lead closes the case, sets warning expiry reminders and checks in with grievance raisers after 4 weeks to confirm no retaliation.","o":"People Lead"}],"checks":["Investigator, hearing and appeal managers are three different people","Written notice and evidence provided before every hearing","Right to be accompanied offered at each formal meeting","Outcomes compared with previous similar cases for consistency","Case files restricted to People Lead and named decision-makers"],"kpis":[["Cases resolved within 30 business days","At least [85]%"],["Outcome letters within 5 business days","100%"],["Appeals overturned","Tracked, root cause review if above [20]%"],["Retaliation complaints after grievances","Zero"]],"risks":[["Unfair process leading to legal claim","Policy follows local code of practice, with external advice for dismissal cases."],["Bias or conflict of interest","Independent investigator and decision-makers, declared conflicts."],["Confidentiality breach","Restricted case files and need-to-know communication."],["Retaliation against complainant","Follow-up check-in and clear anti-retaliation policy."]],"related":["Employee Offboarding","Whistleblowing Policy","Anti-harassment and Bullying Policy","Probation Review"],"review":"Every 12 months, or after an employment tribunal claim or legal change"},{"id":"people-training-development","dept":"people","title":"Training and Development","summary":"Plans, approves, delivers and tracks training so employees build skills the business needs and compliance training is met.","tags":["training","learning","L&D","upskilling","courses","development plan","compliance training"],"purpose":"To make sure employees complete mandatory training and have fair access to development that builds skills the business needs. It also ensures training spend is approved and its impact is reviewed.","scope":"Covers mandatory compliance training, role-specific training, external courses, conferences and certifications. It does not cover onboarding induction content or formal academic sponsorship above [amount], which needs a separate agreement.","definitions":[["Mandatory training","Training required by law, client contract or policy, for example security awareness or anti-harassment."],["Learning budget","The annual amount available per employee or team for development."],["Individual development plan","A short plan of skills to build and how, agreed between employee and manager."],["Training clawback","An agreement to repay costly training if the employee leaves within a set period, where lawful."]],"roles":[["People Lead","Owns the training calendar, mandatory training matrix and records."],["Line Manager","Agrees development plans and approves requests within budget."],["Employee","Requests, completes and applies training and shares learning."],["Finance Lead","Approves spend above manager limits and tracks budget."],["Trainer","Delivers internal sessions and records attendance."]],"prereqs":["Mandatory training matrix by role","Learning management system or tracker in [LMS tool]","Annual learning budget by team","Training request form","Training agreement template for high-cost courses"],"steps":[{"t":"Maintain the training matrix","d":"People Lead keeps a matrix of mandatory training per role with refresh intervals and assigns courses automatically on start and on expiry.","o":"People Lead"},{"t":"Agree development plans","d":"Line Manager and Employee agree a development plan with 1 to 3 skill goals during each performance cycle.","o":"Line Manager"},{"t":"Submit training requests","d":"Employee submits a request stating the course, cost, dates, link to the development plan and expected benefit at least 4 weeks before the start date.","o":"Employee"},{"t":"Approve the request","d":"Line Manager approves requests up to [manager limit] within 5 business days. Finance Lead approves above that limit, and a training agreement is signed for courses above [clawback threshold].","o":"Line Manager"},{"t":"Book and pay","d":"People Lead books the course using company payment methods and records the cost against the team budget.","o":"People Lead"},{"t":"Deliver internal training","d":"Trainer runs internal sessions to a set outline, records attendance in [LMS tool] and collects a short feedback survey.","o":"Trainer"},{"t":"Chase mandatory completion","d":"People Lead sends reminders at 7 days and 1 day before deadlines and escalates overdue items to the Line Manager after 5 business days.","o":"People Lead"},{"t":"Record completion","d":"Employee uploads certificates to [LMS tool] within 5 business days of finishing and People Lead verifies them.","o":"Employee"},{"t":"Share and apply learning","d":"Employee shares key takeaways with the team within 1 month and agrees with the Line Manager how to apply them.","o":"Employee"},{"t":"Review impact and spend","d":"People Lead reports training completion, spend against budget and feedback scores to leadership each quarter.","o":"People Lead"}],"checks":["Mandatory training completion checked monthly","Spend approved before booking, no retrospective claims without Finance approval","Training agreements signed before high-cost courses start","Certificates verified and expiry dates tracked","Fair access monitored across teams and groups"],"kpis":[["Mandatory training completion","100% by deadline, 98% minimum"],["Employees with a development plan","At least [90]%"],["Learning budget utilisation","[70 to 100]% per year"],["Training satisfaction score","4 out of 5 or above"]],"risks":[["Lapsed compliance training breaching client or legal requirement","Automated assignment, reminders and escalation."],["Spend without business value","Link to development plan and post-training review."],["Unequal access to development","Quarterly review of spend and uptake by team and group."],["Loss of investment through early leavers","Training agreements for high-cost courses where lawful."]],"related":["Performance Review Cycle","Employee Onboarding","Expenses Policy","Compensation and Promotion Review"],"review":"Every 12 months, or when mandatory training requirements change"},{"id":"people-contractor-freelancer-engagement","dept":"people","title":"Contractor and Freelancer Engagement","summary":"Engages contractors and freelancers lawfully with clear scope, contracts, access controls and payment terms.","tags":["contractor","freelancer","consultant","independent contractor","statement of work","misclassification"],"purpose":"To engage external individuals quickly while controlling cost, protecting intellectual property and avoiding misclassification of workers. It gives managers a repeatable route from need to signed contract to closure.","scope":"Covers individual contractors, freelancers and single-person consultancies engaged directly or through platforms. It does not cover agency temps placed by employment agencies, larger supplier contracts or employees.","definitions":[["Statement of work","A document defining deliverables, timeline, fees and acceptance criteria."],["Misclassification","Treating someone as self-employed when, in practice, the relationship looks like employment under local law."],["IP assignment","Contract terms transferring ownership of work created to [Company]."],["Engagement owner","The manager responsible for the contractor's work and spend."]],"roles":[["Engagement Owner","Defines the scope, manages the work and approves invoices."],["People Lead","Assesses employment status risk and manages contract templates."],["Finance Lead","Approves budget and sets up supplier payment details."],["IT Administrator","Grants and removes limited, time-bound system access."],["Contractor","Delivers agreed work, invoices accurately and follows security rules."]],"prereqs":["Approved budget for the engagement","Contractor agreement and SOW templates with IP and confidentiality terms","Employment status assessment checklist for relevant jurisdictions","Supplier set-up form and tax documents","Access request form"],"steps":[{"t":"Define the need","d":"Engagement Owner writes a short brief covering deliverables, duration, estimated cost and why an employee is not suitable.","o":"Engagement Owner"},{"t":"Approve budget","d":"Finance Lead approves the spend. Engagements above [approval limit] or longer than [6] months also need Department Head approval.","o":"Finance Lead"},{"t":"Assess employment status","d":"People Lead completes the status checklist covering control, substitution, integration and exclusivity, and records the result. Check local law, as tests vary.","o":"People Lead"},{"t":"Select the contractor","d":"Engagement Owner reviews portfolio, references and rates of at least two candidates for engagements above [amount], and records the choice.","o":"Engagement Owner"},{"t":"Sign the contract and SOW","d":"People Lead issues the agreement with IP assignment, confidentiality, data protection terms and a SOW. Work does not start before both parties sign.","o":"People Lead"},{"t":"Set up supplier records","d":"Finance Lead collects tax forms and bank details, verifies them by phone on a known number and sets up the supplier in [accounting tool].","o":"Finance Lead"},{"t":"Grant limited access","d":"IT Administrator provides only the access in the access request, with an expiry date matching the SOW end date.","o":"IT Administrator"},{"t":"Manage delivery","d":"Engagement Owner reviews deliverables against acceptance criteria at agreed milestones and avoids directing day-to-day working hours or methods.","o":"Engagement Owner"},{"t":"Approve invoices","d":"Engagement Owner checks invoices against the SOW and approves within 5 business days. Finance Lead pays per agreed terms.","o":"Engagement Owner"},{"t":"Review long engagements","d":"People Lead re-checks employment status every [6] months or when the scope changes significantly.","o":"People Lead"},{"t":"Close the engagement","d":"Engagement Owner confirms final deliverables and handover. IT Administrator removes access on the last day and Finance Lead closes the purchase order.","o":"Engagement Owner"}],"checks":["No work starts without a signed agreement and SOW","Employment status assessment recorded for every engagement","Bank details verified independently before first payment","Access expires automatically at SOW end date","Invoices matched to SOW before payment"],"kpis":[["Engagements with signed contract before start","100%"],["Invoices paid within agreed terms","At least 95%"],["Contractor access removed by end date","100%"],["Engagements re-assessed on schedule","100%"]],"risks":[["Worker misclassification and tax liability","Status checklist, periodic re-assessment and local advice for borderline cases."],["IP not owned by the company","Signed IP assignment before work starts."],["Invoice or bank detail fraud","Independent verification of bank details and changes."],["Lingering system access","Time-bound accounts with automatic expiry."]],"related":["Recruitment and Job Requisition","Supplier Onboarding","Purchase Order and Approval","Information Security Policy"],"review":"Every 12 months, or when employment status law changes"},{"id":"people-compensation-promotion-review","dept":"people","title":"Compensation and Promotion Review","summary":"Runs a fair, budgeted annual pay and promotion review linked to performance and market data.","tags":["salary review","pay rise","promotion","compensation","merit increase","pay equity"],"purpose":"To make pay and promotion decisions consistently, within budget and based on performance, role level and market data. It also checks for unjustified pay gaps before changes are communicated.","scope":"Covers the [annual] salary review, promotions and off-cycle pay adjustments for all employees. It does not cover sales commission plans, executive pay set by the board, or offers to new hires.","definitions":[["Pay band","The minimum to maximum salary range for a job level."],["Compa-ratio","An employee's salary divided by the midpoint of their pay band."],["Merit matrix","A grid setting suggested increase percentages by performance rating and position in band."],["Off-cycle adjustment","A pay change outside the annual review, for example for retention or a role change."]],"roles":[["People Lead","Prepares data, guidance and budgets, and runs pay equity analysis."],["Line Manager","Proposes increases and promotions with written justification."],["Department Head","Calibrates proposals across the department within budget."],["Finance Lead","Sets the overall budget and checks cost impact."],["CEO","Gives final approval of the review outcomes."]],"prereqs":["Final performance ratings from the review cycle","Current pay bands and market benchmark data no older than 12 months","Approved review budget as a % of payroll","Merit matrix and promotion criteria by level","Compensation planning sheet or [comp tool]"],"steps":[{"t":"Set the budget","d":"Finance Lead and CEO agree the total increase and promotion budget as a % of payroll, at least 6 weeks before the effective date.","o":"Finance Lead"},{"t":"Refresh bands","d":"People Lead updates pay bands against benchmark data and flags employees below band minimum.","o":"People Lead"},{"t":"Publish guidance","d":"People Lead shares the merit matrix, promotion criteria, budget per team and timeline with managers.","o":"People Lead"},{"t":"Prepare proposals","d":"Line Manager proposes increases and promotions in the planning sheet within 10 business days. Promotions require a written case against the next level's criteria.","o":"Line Manager"},{"t":"Calibrate within department","d":"Department Head reviews proposals across teams for consistency and keeps the total within budget.","o":"Department Head"},{"t":"Run pay equity analysis","d":"People Lead compares proposed pay by gender and other lawful groupings at the same level and explains or corrects any gap above [3]% before approval.","o":"People Lead"},{"t":"Approve outcomes","d":"CEO approves the final list. Any individual increase above [15]% or exception to band needs a documented reason.","o":"CEO"},{"t":"Update payroll","d":"People Lead updates [HRIS tool] and payroll before the cut-off, with a second person checking every changed record.","o":"People Lead"},{"t":"Issue letters","d":"People Lead prepares individual pay letters stating new salary, effective date and any new title.","o":"People Lead"},{"t":"Communicate to employees","d":"Line Manager tells each employee face to face or by video before the letter is released, explaining the reasoning.","o":"Line Manager"},{"t":"Handle off-cycle requests","d":"Outside the cycle, Line Manager submits a case to People Lead. Off-cycle changes need Department Head and Finance Lead approval.","o":"People Lead"}],"checks":["Total spend within approved budget","Every promotion supported by a written case against level criteria","Pay equity analysis completed and gaps explained before approval","All payroll changes checked by a second person","Pay data shared only on a need-to-know basis"],"kpis":[["Review completed by effective date","100%"],["Spend versus budget","Within plus or minus [2]%"],["Unexplained pay gap at same level","Under [3]%"],["Employees below band minimum after review","Zero"]],"risks":[["Pay inequity and discrimination claims","Pay equity analysis and documented justification."],["Budget overrun","Planning sheet totals locked to budget per team."],["Payroll errors","Two-person check before cut-off."],["Loss of key staff due to below-market pay","Annual band refresh and compa-ratio review."]],"related":["Performance Review Cycle","Job Offer and Pre-employment Checks","Payroll Processing","Sales Commission Calculation"],"review":"Every 12 months, before each review cycle"},{"id":"sales-lead-qualification","dept":"sales","title":"Lead Qualification","summary":"Scores and qualifies inbound and outbound leads consistently so sales time goes to buyers who fit and are ready.","tags":["lead scoring","MQL","SQL","BANT","ICP","inbound leads","prospect"],"purpose":"To decide quickly and consistently which leads deserve sales time, using an agreed ideal customer profile and qualification criteria. It also ensures every lead gets a timely response and a recorded outcome.","scope":"Covers inbound leads from forms, chat, events and referrals, and outbound prospects, from first response to sales-accepted or disqualified. It does not cover marketing campaign execution or the discovery call itself.","definitions":[["ICP","Ideal customer profile: the firmographic and situational traits of customers most likely to buy and succeed."],["MQL","Marketing qualified lead: a lead that meets the agreed fit and engagement threshold."],["SQL","Sales qualified lead: a lead a sales rep has confirmed has need, authority and timing worth a discovery call."],["Lead score","A points total based on fit and engagement signals."]],"roles":[["Marketing Lead","Owns the lead scoring model and routing rules."],["SDR","Responds to leads, qualifies them and books discovery calls."],["Account Executive","Accepts or rejects SQLs and gives feedback on quality."],["Sales Manager","Monitors response times, conversion and agrees criteria with marketing."],["RevOps Analyst","Maintains CRM fields, automation and reporting."]],"prereqs":["Agreed written ICP and qualification criteria","Lead scoring and routing rules in [CRM tool]","Email and call templates for first response","Calendar booking link for discovery calls","Disqualification reason picklist"],"steps":[{"t":"Capture and route the lead","d":"RevOps Analyst ensures every new lead is created in [CRM tool] with source and is routed to an SDR by territory or round robin within 5 minutes.","o":"RevOps Analyst"},{"t":"Enrich and score","d":"Automation enriches company size, industry and location. Leads scoring above [MQL threshold] are flagged as MQL.","o":"Marketing Lead"},{"t":"Respond fast","d":"SDR makes first contact on inbound MQLs within 1 business hour by email and phone, and on demo requests within 15 minutes during working hours.","o":"SDR"},{"t":"Run the follow-up sequence","d":"SDR runs a [6]-touch sequence over 14 days across email, phone and social for leads that do not respond.","o":"SDR"},{"t":"Hold a qualification call","d":"SDR runs a 15-minute call checking fit with ICP, the problem to solve, decision-making process, budget range and timing.","o":"SDR"},{"t":"Apply criteria","d":"SDR marks the lead SQL only if it meets ICP fit and at least [3 of 4] criteria. Otherwise it is set to nurture or disqualified with a reason.","o":"SDR"},{"t":"Book the discovery call","d":"SDR books the discovery call with the AE within 5 business days and writes a handover note in the CRM covering context, pain and stakeholders.","o":"SDR"},{"t":"Accept or reject the SQL","d":"Account Executive reviews the note and accepts or rejects within 1 business day. Rejections need a reason from the picklist.","o":"Account Executive"},{"t":"Return to nurture","d":"Leads that are not ready are returned to marketing nurture with a reason and a follow-up date, not deleted.","o":"SDR"},{"t":"Review weekly","d":"Sales Manager reviews speed to lead, MQL to SQL and SQL acceptance rates weekly and agrees changes to scoring with the Marketing Lead monthly.","o":"Sales Manager"}],"checks":["Every lead has an owner and status within 1 business day","Disqualification reasons recorded for 100% of closed leads","Marketing consent and opt-outs respected in sequences","Scoring model reviewed against closed-won data quarterly"],"kpis":[["Speed to lead (inbound)","Median under [1] business hour"],["MQL to SQL conversion","At least [20]%"],["SQL acceptance by AEs","At least [85]%"],["Leads with no activity after 3 days","Zero"]],"risks":[["Hot leads go cold due to slow response","Instant routing and response time alerts."],["Sales time wasted on poor-fit leads","Written ICP and minimum criteria before booking."],["Spam or privacy complaints","Consent checks, opt-out handling and sequence limits per GDPR or local law."],["Marketing and sales disagree on quality","Shared definitions and monthly calibration."]],"related":["Discovery Call","CRM Data Hygiene","Marketing Consent and Data Policy","Weekly Pipeline Review and Forecast"],"review":"Every 6 months, or after a change in ICP or pricing"},{"id":"sales-discovery-call","dept":"sales","title":"Discovery Call","summary":"Runs a structured discovery call that uncovers the buyer's problem, impact and buying process before any proposal.","tags":["discovery","first meeting","needs analysis","MEDDIC","qualification","sales call"],"purpose":"To understand the prospect's situation, pain, impact and buying process well enough to decide whether to pursue the deal and how. Strong discovery leads to better proposals, accurate forecasts and fewer lost deals late in the cycle.","scope":"Covers the first substantive sales meeting with a qualified prospect and its follow-up. It does not cover lead qualification by SDRs, product demos for already qualified deals or pricing negotiation.","definitions":[["Pain","The business problem the buyer wants to solve, stated in their words."],["Economic buyer","The person with authority to approve the spend."],["Decision process","The steps, people and criteria the buyer will use to choose a supplier."],["Mutual action plan","A shared, dated list of next steps agreed by buyer and seller."]],"roles":[["Account Executive","Prepares, runs and follows up the call and updates the opportunity."],["SDR","Provides the handover note and context from qualification."],["Sales Engineer","Joins technical discoveries to assess fit and requirements."],["Sales Manager","Reviews discovery quality and coaches through call reviews."]],"prereqs":["Accepted SQL with handover note in [CRM tool]","Discovery question guide and qualification framework","Research on the account: website, news, LinkedIn, existing contacts","Call recording tool with consent notice","Opportunity stage definitions"],"steps":[{"t":"Research the account","d":"Account Executive spends 15 to 20 minutes reviewing the handover note, company site, recent news and stakeholders, and writes 3 hypotheses about their pain.","o":"Account Executive"},{"t":"Send an agenda","d":"Account Executive confirms the meeting 1 business day ahead with a short agenda and asks who else should attend.","o":"Account Executive"},{"t":"Open the call","d":"Account Executive confirms time available, the agenda and the goal of deciding together whether to continue. Recording consent is requested before recording.","o":"Account Executive"},{"t":"Explore the current situation","d":"Account Executive asks open questions about current process, tools, team and what triggered the search now, talking no more than 40% of the time.","o":"Account Executive"},{"t":"Quantify impact","d":"Account Executive asks what the problem costs in time, money or risk and what happens if nothing changes, capturing numbers where possible.","o":"Account Executive"},{"t":"Map the decision process","d":"Account Executive identifies the economic buyer, other stakeholders, evaluation criteria, competing options, budget status and target decision date.","o":"Account Executive"},{"t":"Check technical fit","d":"For technical deals, Sales Engineer confirms integrations, security and must-have requirements and flags any blockers.","o":"Sales Engineer"},{"t":"Agree next steps","d":"Before the call ends, Account Executive agrees a dated next step with the buyer, such as a demo with stakeholders, and sends the calendar invite on the call where possible.","o":"Account Executive"},{"t":"Send the recap","d":"Account Executive emails a recap within 1 business day covering their goals, impact, decision process and next steps, and asks them to correct anything missed.","o":"Account Executive"},{"t":"Update the CRM","d":"Account Executive updates the opportunity with qualification fields, amount estimate, close date and stage within 1 business day, or marks it closed lost with reason.","o":"Account Executive"},{"t":"Review call quality","d":"Sales Manager reviews at least [2] recorded discovery calls per rep per month against the discovery scorecard and gives written coaching.","o":"Sales Manager"}],"checks":["No opportunity moves past discovery without pain, impact and economic buyer recorded","Recap email sent for every discovery call","Dated next step agreed and in the calendar","Recording consent obtained and logged","Disqualified opportunities closed with a reason"],"kpis":[["Discovery to next-stage conversion","At least [50]%"],["Recap sent within 1 business day","95%"],["Opportunities with complete qualification fields","At least 90%"],["Discovery call scorecard average","At least [3.5] out of 5"]],"risks":[["Pursuing deals with no real need","Clear exit criteria and disqualification encouraged."],["Late surprises from unknown stakeholders","Decision process mapping and early multi-threading."],["Recording without consent","Consent script and tool settings per local law."],["Inaccurate forecast from weak discovery","Required qualification fields before stage change."]],"related":["Lead Qualification","Proposal and Quotation","Weekly Pipeline Review and Forecast","CRM Data Hygiene"],"review":"Every 12 months, or after a change in sales methodology"},{"id":"sales-proposal-quotation","dept":"sales","title":"Proposal and Quotation","summary":"Produces accurate, approved proposals and quotes quickly, with pricing and discounts inside agreed limits.","tags":["proposal","quote","quotation","pricing","discount approval","CPQ","RFP"],"purpose":"To send prospects clear, accurate proposals that reflect their needs and are priced within approved rules. Consistent quoting protects margin and speeds up the buying decision.","scope":"Covers written proposals, price quotes and responses to simple RFPs for new business and expansions. It does not cover contract negotiation of legal terms or large formal tenders, which need a bid process.","definitions":[["Price book","The approved list prices for all products and services."],["Discount","Any reduction from list price, including free months, credits or extra services."],["Deal desk","The person or group that reviews non-standard pricing and terms."],["Quote validity","The period for which the quoted price is guaranteed, for example [30] days."]],"roles":[["Account Executive","Builds the proposal and quote and presents it to the buyer."],["Sales Manager","Approves discounts within their limit and reviews proposal quality."],["Deal Desk","Reviews non-standard pricing, payment terms and margin."],["Sales Engineer","Writes the solution and scope sections for technical deals."],["Finance Lead","Approves discounts and terms above the Sales Manager limit."]],"prereqs":["Completed discovery with requirements recorded in [CRM tool]","Current price book and discount matrix","Proposal and quote templates","Standard terms and service descriptions","Delivery team input on effort for services work"],"steps":[{"t":"Confirm requirements","d":"Account Executive confirms scope, quantities, start date and decision criteria with the buyer before drafting.","o":"Account Executive"},{"t":"Draft the solution","d":"Account Executive and Sales Engineer write a proposal that restates the buyer's goals, the recommended solution, scope, timeline and success measures.","o":"Sales Engineer"},{"t":"Build the quote","d":"Account Executive builds the quote in [CPQ or CRM tool] from the price book, never as a free-text document, with validity of [30] days.","o":"Account Executive"},{"t":"Check delivery effort","d":"For services, Account Executive gets a written effort estimate from Delivery and includes assumptions and exclusions.","o":"Account Executive"},{"t":"Request discount approval","d":"Discounts up to [10]% need Sales Manager approval, up to [20]% need Deal Desk, and above [20]% or non-standard payment terms need Finance Lead approval, all recorded in the CRM.","o":"Sales Manager"},{"t":"Review non-standard terms","d":"Deal Desk reviews any non-standard payment terms, multi-year price locks or bundled services for margin and revenue recognition within 2 business days.","o":"Deal Desk"},{"t":"Approve above limit","d":"Finance Lead approves or rejects deals above the Deal Desk limit within 2 business days, stating any conditions.","o":"Finance Lead"},{"t":"Quality check the document","d":"Sales Manager or a peer checks names, figures, totals and tax treatment before sending for deals above [amount].","o":"Sales Manager"},{"t":"Present the proposal","d":"Account Executive walks the buyer through the proposal on a call rather than only emailing it, and agrees a decision date.","o":"Account Executive"},{"t":"Track and follow up","d":"Account Executive logs the sent date and follows up within 3 business days. Expired quotes must be re-issued, not extended informally.","o":"Account Executive"}],"checks":["All quotes generated from the current price book","Every discount has a recorded approval at the right level","Assumptions and exclusions stated for services","Totals and tax checked before sending","Quote validity date shown"],"kpis":[["Proposal turnaround","Within [3] business days of discovery"],["Average discount","Under [12]%"],["Quotes sent without required approval","Zero"],["Proposal to close win rate","At least [30]%"]],"risks":[["Margin erosion from ad hoc discounting","Discount matrix with tiered approvals."],["Under-scoped services leading to loss-making delivery","Delivery effort estimate with assumptions."],["Pricing errors","CPQ quotes from price book and quality check."],["Revenue recognition issues from unusual terms","Deal Desk and Finance review."]],"related":["Discovery Call","Contract Negotiation and Closing","Sales to Delivery Handoff","Pricing and Discount Policy"],"review":"Every 12 months, or when the price book changes"},{"id":"sales-contract-negotiation-closing","dept":"sales","title":"Contract Negotiation and Closing","summary":"Negotiates and signs customer contracts within approved limits and books closed deals accurately.","tags":["contract","negotiation","closing","signature","redlines","MSA","order form"],"purpose":"To get deals signed efficiently while protecting [Company] from unacceptable legal, financial and delivery risk. It also makes sure every closed deal is recorded correctly for billing and revenue.","scope":"Covers order forms, master service agreements, legal redlines, security questionnaires and final signature for customer contracts. It does not cover supplier contracts, partnerships or pricing approval before the proposal.","definitions":[["MSA","Master services agreement: the main legal terms governing the relationship."],["Order form","A document listing products, quantities, price and term under the MSA."],["Redline","Tracked changes a party proposes to contract wording."],["Fallback position","Pre-approved alternative wording a negotiator may accept without further approval."]],"roles":[["Account Executive","Leads the negotiation and coordinates all parties to signature."],["Legal Counsel","Reviews redlines and approves non-standard legal terms."],["Sales Manager","Approves commercial concessions within limits and unblocks stalled deals."],["Finance Lead","Approves payment terms, billing changes and signatory authority above limits."],["Authorised Signatory","Signs contracts within their delegated authority."]],"prereqs":["Approved proposal and pricing","Standard MSA and order form templates","Negotiation playbook with fallback positions","Signature authority matrix","Security questionnaire answer library"],"steps":[{"t":"Send standard paper","d":"Account Executive sends the standard MSA and order form with the final proposal, encouraging the buyer to use company templates.","o":"Account Executive"},{"t":"Agree a closing plan","d":"Account Executive agrees with the buyer the steps, owners and dates to signature, including legal, security and procurement review.","o":"Account Executive"},{"t":"Triage redlines","d":"Account Executive logs buyer redlines and sends them to Legal Counsel. Changes covered by playbook fallbacks may be accepted without legal review.","o":"Account Executive"},{"t":"Review legal terms","d":"Legal Counsel reviews non-standard terms such as liability caps, indemnities and data protection within [3] business days, escalating unacceptable risk.","o":"Legal Counsel"},{"t":"Complete security reviews","d":"Account Executive answers security questionnaires using the answer library, with new answers approved by the security owner before sending.","o":"Account Executive"},{"t":"Approve commercial concessions","d":"Any further price, term or scope concession follows the discount approval matrix. Concessions are traded for something of value, such as longer term or faster signature.","o":"Sales Manager"},{"t":"Approve payment terms","d":"Finance Lead approves payment terms beyond [30] days, upfront credits or unusual billing schedules.","o":"Finance Lead"},{"t":"Prepare the final version","d":"Account Executive confirms the final documents match all approvals and that names, entities and amounts are correct before sending for signature.","o":"Account Executive"},{"t":"Sign the contract","d":"Authorised Signatory signs via [e-signature tool] only after the customer has signed and within their delegated authority.","o":"Authorised Signatory"},{"t":"Book the deal","d":"Account Executive marks the opportunity closed won within 1 business day, attaches the signed contract and completes billing fields.","o":"Account Executive"},{"t":"Trigger the handoff","d":"Account Executive starts the Sales to Delivery Handoff and notifies Finance to raise the first invoice.","o":"Account Executive"}],"checks":["Signatory acts within the authority matrix","Signed contract stored in the contract repository with key dates","Every non-standard clause approved by Legal Counsel","CRM amounts match the signed order form","Closed won date matches the date of last signature"],"kpis":[["Average days from verbal yes to signature","Under [14] days"],["Contracts on standard paper","At least [70]%"],["Legal review turnaround","90% within 3 business days"],["Booking errors found by Finance","Zero"]],"risks":[["Unlimited liability or unacceptable indemnities","Playbook limits and Legal Counsel approval."],["Unauthorised signature","Signature authority matrix enforced in e-signature tool."],["Deals slipping quarter end","Closing plan with dates agreed early."],["Booking errors affecting billing and revenue","Finance check of order form against CRM."]],"related":["Proposal and Quotation","Sales to Delivery Handoff","Contract Management Policy","Delegation of Authority Policy"],"review":"Every 12 months, or after changes to standard terms"},{"id":"sales-crm-data-hygiene","dept":"sales","title":"CRM Data Hygiene","summary":"Keeps CRM records accurate, complete and de-duplicated so pipeline, forecasts and customer data can be trusted.","tags":["CRM","data quality","duplicates","Salesforce","HubSpot","data hygiene","pipeline data"],"purpose":"To keep customer, contact and opportunity data in [CRM tool] reliable for forecasting, reporting and customer communication. It also keeps personal data accurate and lawfully held.","scope":"Covers accounts, contacts, leads and opportunities in [CRM tool] used by sales, marketing and customer success. It does not cover finance or billing systems, except for checking that key fields match.","definitions":[["Required field","A field that must be completed before a record can be saved or moved to a stage."],["Duplicate","Two or more records representing the same company or person."],["Stale opportunity","An open opportunity with no activity for [30] days or a close date in the past."],["Data steward","The person accountable for data standards in the CRM."]],"roles":[["RevOps Analyst","Acts as data steward: sets standards, runs reports, merges duplicates and fixes automation."],["Account Executive","Keeps their own records accurate and updated."],["Sales Manager","Enforces hygiene in team reviews and resolves ownership disputes."],["Marketing Lead","Ensures imported lists meet data standards and consent rules."]],"prereqs":["Written data standards with field definitions","CRM admin access and validation rule capability","Data quality dashboard","Deduplication tool or process","Data retention schedule"],"steps":[{"t":"Define standards","d":"RevOps Analyst maintains a data dictionary listing required fields per object and stage, naming conventions and picklist values.","o":"RevOps Analyst"},{"t":"Enforce at entry","d":"RevOps Analyst sets validation rules and required fields so records cannot advance stage without key data such as amount, close date and next step.","o":"RevOps Analyst"},{"t":"Check imports","d":"Marketing Lead cleans and de-duplicates lists against the CRM, with consent source recorded, before any import. Imports above [500] rows are approved by RevOps.","o":"Marketing Lead"},{"t":"Update records daily","d":"Account Executive logs meetings, next steps and stage changes in the CRM by end of each working day.","o":"Account Executive"},{"t":"Fix stale opportunities","d":"Account Executive reviews the stale opportunity report every Monday and updates, pushes with a reason, or closes each one.","o":"Account Executive"},{"t":"Merge duplicates weekly","d":"RevOps Analyst runs a duplicate report weekly and merges confirmed duplicates, keeping the record with the most activity as master.","o":"RevOps Analyst"},{"t":"Review in team meetings","d":"Sales Manager reviews the data quality dashboard in the weekly team meeting and follows up on reps below target.","o":"Sales Manager"},{"t":"Reconcile with billing","d":"RevOps Analyst checks closed won amounts and customer records against the billing system monthly and corrects mismatches.","o":"RevOps Analyst"},{"t":"Purge per retention rules","d":"RevOps Analyst deletes or anonymises contacts with no activity or lawful basis for [24] months, and processes erasure requests within the legal deadline.","o":"RevOps Analyst"},{"t":"Audit quarterly","d":"RevOps Analyst samples [50] random records each quarter, scores completeness and accuracy, and reports results with fixes to sales leadership.","o":"RevOps Analyst"}],"checks":["Required fields enforced by validation rules, not reminders","Duplicate rate tracked weekly","Every open opportunity has a future close date and next step","Consent source recorded for all marketing contacts","Quarterly audit results reported"],"kpis":[["Open opportunities with past close date","Zero at Monday pipeline review"],["Duplicate account rate","Under [2]%"],["Required field completeness","At least 95%"],["CRM to billing amount match","100% of closed won deals"]],"risks":[["Unreliable forecast","Validation rules and weekly stale report."],["Contacting people who opted out","Consent fields synced with marketing tools."],["Holding personal data longer than allowed","Retention purge and erasure process."],["Ownership disputes over accounts","Clear assignment rules and manager decision."]],"related":["Lead Qualification","Weekly Pipeline Review and Forecast","Data Retention Policy","Marketing Consent and Data Policy"],"review":"Every 12 months, or after a CRM migration or major configuration change"},{"id":"sales-to-delivery-handoff","dept":"sales","title":"Sales to Delivery Handoff","summary":"Transfers every closed deal to delivery or customer success with full context, so customers never repeat themselves.","tags":["handoff","handover","kickoff","implementation","customer success","onboarding","closed won"],"purpose":"To pass everything learned in the sales process to the team that will deliver, so the customer has a smooth start and promises made are known and achievable. It reduces early churn and scope disputes.","scope":"Covers all new customers and significant expansions once a contract is signed, up to the customer kickoff meeting. It does not cover the delivery or onboarding project itself after kickoff.","definitions":[["Handoff document","A standard record of the customer's goals, scope, stakeholders, commitments and risks."],["Kickoff","The first meeting between the customer and the delivery team to start the project."],["Commitment","Anything promised to the customer during the sale, including dates, features and service levels."],["Success criteria","The measurable outcomes the customer expects to achieve."]],"roles":[["Account Executive","Completes the handoff document and leads the internal handoff meeting."],["Delivery Lead","Reviews the handoff, raises questions and runs the customer kickoff."],["Customer Success Manager","Owns the ongoing relationship and success plan after kickoff."],["Finance Lead","Confirms billing set-up and first invoice."],["Sales Manager","Resolves disputes over commitments and ensures handoffs are on time."]],"prereqs":["Signed contract and order form","Handoff document template in [CRM tool]","Discovery notes, proposal and call recordings","Delivery capacity and scheduling calendar"],"steps":[{"t":"Complete the handoff document","d":"Account Executive completes the handoff document within 2 business days of closed won, covering goals, success criteria, scope, stakeholders, commitments, risks and competitors considered.","o":"Account Executive"},{"t":"Attach source material","d":"Account Executive links the signed contract, proposal, security answers and key call recordings to the CRM record.","o":"Account Executive"},{"t":"Assign the delivery team","d":"Delivery Lead assigns the project team and Customer Success Manager within 2 business days, based on capacity and skills.","o":"Delivery Lead"},{"t":"Hold the internal handoff","d":"Account Executive runs a 30 to 45 minute internal meeting with the delivery team and CSM to walk through the document and answer questions.","o":"Account Executive"},{"t":"Flag unrealistic commitments","d":"Delivery Lead raises any commitment that cannot be met within 1 business day of the handoff meeting. Sales Manager agrees a resolution and who tells the customer.","o":"Delivery Lead"},{"t":"Set up billing","d":"Finance Lead confirms billing contacts, PO numbers and invoicing schedule and raises the first invoice per contract terms.","o":"Finance Lead"},{"t":"Send the welcome email","d":"Customer Success Manager sends a welcome email within 1 business day of the internal handoff, introducing the team and proposing kickoff dates.","o":"Customer Success Manager"},{"t":"Run the kickoff","d":"Delivery Lead runs the customer kickoff within [10] business days of signature, with the Account Executive attending to confirm continuity.","o":"Delivery Lead"},{"t":"Confirm success plan","d":"Customer Success Manager records the agreed success criteria and milestones in the customer record after kickoff.","o":"Customer Success Manager"},{"t":"Review handoff quality","d":"Sales Manager reviews delivery feedback scores on handoffs monthly and coaches Account Executives on gaps.","o":"Sales Manager"}],"checks":["Handoff document completed for 100% of closed won deals before kickoff","All commitments outside standard scope listed explicitly","Delivery has confirmed every non-standard commitment is achievable","First invoice raised per contract terms","Customer not asked to repeat information already captured"],"kpis":[["Handoff document within 2 business days","At least 95%"],["Signature to kickoff time","Median under [10] business days"],["Delivery team rating of handoff quality","At least 4 out of 5"],["Customers churning in first 90 days","Under [2]%"]],"risks":[["Overpromising during sale","Commitments section reviewed by Delivery and escalation route."],["Customer frustration repeating information","Complete handoff document and recordings shared."],["Delayed revenue from late billing","Finance step in the handoff checklist."],["Delivery capacity shortage","Early visibility of late-stage pipeline to Delivery Lead."]],"related":["Contract Negotiation and Closing","Customer Onboarding","Account Renewal and Upsell","Proposal and Quotation"],"review":"Every 12 months, or after a customer escalation caused by a handoff gap"},{"id":"sales-weekly-pipeline-review-forecast","dept":"sales","title":"Weekly Pipeline Review and Forecast","summary":"Runs a disciplined weekly pipeline review and produces a forecast leadership can rely on.","tags":["pipeline review","forecast","commit","best case","deal review","sales meeting","quota"],"purpose":"To give leadership an accurate view of expected revenue and to spot and fix deal risks early. A consistent weekly rhythm improves forecast accuracy and coaching.","scope":"Covers new business and expansion pipeline for the current and next quarter. It does not cover renewals forecasting, which is reported separately, or quota setting.","definitions":[["Commit","Deals the rep is confident will close this period, with evidence such as an agreed signature date."],["Best case","Deals that could close this period if known risks are resolved."],["Pipeline coverage","Total open pipeline for the period divided by the remaining target."],["Slippage","A deal whose close date moves out of the forecast period."]],"roles":[["Account Executive","Updates deals and submits their forecast call before the review."],["Sales Manager","Runs the team review, challenges deals and submits the team forecast."],["Head of Sales","Consolidates forecasts and reports to leadership."],["RevOps Analyst","Prepares the pipeline reports, tracks forecast accuracy and changes week to week."]],"prereqs":["Clean CRM data with required fields","Forecast categories and stage definitions","Pipeline dashboard and week-over-week change report","Quarterly targets by rep and team"],"steps":[{"t":"Update the pipeline","d":"Account Executive updates amounts, close dates, stages, next steps and forecast category by [day and time] each week.","o":"Account Executive"},{"t":"Submit the forecast call","d":"Account Executive submits commit and best case numbers in [CRM tool], with a one-line reason for any commit deal.","o":"Account Executive"},{"t":"Prepare reports","d":"RevOps Analyst publishes the pipeline dashboard, coverage ratio and changes since last week, highlighting slipped, pushed and new deals, 2 hours before the review.","o":"RevOps Analyst"},{"t":"Run the team review","d":"Sales Manager holds a 45 to 60 minute review, focusing on commit deals, deals that changed and large deals, not every opportunity.","o":"Sales Manager"},{"t":"Inspect deal evidence","d":"For each commit deal, Sales Manager checks economic buyer engagement, mutual action plan, legal status and signature date before accepting it as commit.","o":"Sales Manager"},{"t":"Agree actions","d":"Sales Manager records specific actions for at-risk deals with owners and dates, such as an executive sponsor call.","o":"Sales Manager"},{"t":"Check coverage","d":"Sales Manager compares pipeline coverage to the target of [3] times remaining quota and agrees prospecting actions if it is below.","o":"Sales Manager"},{"t":"Submit team forecast","d":"Sales Manager submits the team forecast with a written note on changes and key risks by [day and time].","o":"Sales Manager"},{"t":"Consolidate and report","d":"Head of Sales consolidates team forecasts and reports commit, best case and pipeline to leadership weekly, explaining movements over [5]%.","o":"Head of Sales"},{"t":"Track accuracy","d":"RevOps Analyst compares forecast to actual at the end of each month and quarter and reports accuracy by rep and team.","o":"RevOps Analyst"}],"checks":["Pipeline updated before the review for 100% of reps","Commit deals have a dated signature step","Close dates moved more than twice are flagged for review","Forecast changes over [5]% explained in writing","Accuracy tracked and shared every quarter"],"kpis":[["Forecast accuracy (commit vs actual)","Within plus or minus [10]% each quarter"],["Pipeline coverage","At least [3] times remaining target"],["Deals with past close dates at review","Zero"],["Slippage rate of commit deals","Under [15]%"]],"risks":[["Overly optimistic forecasts","Evidence-based commit criteria and accuracy tracking by rep."],["Late discovery of deal risk","Weekly change report and deal inspection."],["Meeting becomes status reporting","Focus on changes and commit deals, updates done beforehand."],["Pipeline gaps for next quarter","Coverage check and prospecting actions."]],"related":["CRM Data Hygiene","Discovery Call","Account Renewal and Upsell","Sales Commission Calculation"],"review":"Every 6 months, or after a quarter with forecast accuracy outside target"},{"id":"sales-account-renewal-upsell","dept":"sales","title":"Account Renewal and Upsell","summary":"Secures on-time renewals and grows existing accounts through planned, value-based expansion conversations.","tags":["renewal","upsell","cross-sell","expansion","churn","retention","net revenue retention"],"purpose":"To retain customers at renewal and grow accounts where there is real value to add. Starting early and tracking health reduces surprise churn and last-minute discounting.","scope":"Covers subscription and contract renewals and expansion opportunities with existing customers. It does not cover new logo sales, collections of overdue invoices or service incidents.","definitions":[["Renewal date","The date the current contract term ends and a new term must start."],["Health score","A combined indicator of product usage, support issues, engagement and sentiment."],["Net revenue retention","Revenue from existing customers this period, including expansion and churn, divided by the same customers' revenue a year earlier."],["Auto-renewal","A contract clause that renews the term unless notice is given by a set date."]],"roles":[["Customer Success Manager","Owns account health, value reviews and renewal readiness."],["Account Manager","Owns the renewal and expansion commercial process and paperwork."],["Sales Manager","Approves renewal pricing changes and discounts and forecasts renewals."],["Finance Lead","Issues renewal invoices and approves non-standard terms."],["RevOps Analyst","Creates renewal opportunities and tracks retention metrics."]],"prereqs":["Contract repository with renewal dates and notice periods","Customer health score dashboard","Renewal opportunity created in [CRM tool]","Current price book and renewal uplift policy","Product usage data"],"steps":[{"t":"Create renewal opportunities","d":"RevOps Analyst automatically creates a renewal opportunity [120] days before each renewal date, at current contract value.","o":"RevOps Analyst"},{"t":"Assess account health","d":"Customer Success Manager reviews health score, usage, support history and stakeholder changes at 120 days and marks the renewal as low, medium or high risk.","o":"Customer Success Manager"},{"t":"Hold a value review","d":"Customer Success Manager holds a business review 90 days before renewal, showing results against the customer's success criteria and gathering their goals for next year.","o":"Customer Success Manager"},{"t":"Act on at-risk accounts","d":"For high-risk renewals, Customer Success Manager agrees a save plan with actions and an executive sponsor within 5 business days.","o":"Customer Success Manager"},{"t":"Identify expansion","d":"Account Manager reviews usage limits, new teams, and unmet needs from the value review, and creates expansion opportunities only where there is a clear customer benefit.","o":"Account Manager"},{"t":"Send the renewal quote","d":"Account Manager sends the renewal quote 60 days before renewal, applying the uplift policy of [x]%. Any discount or price freeze follows the approval matrix.","o":"Account Manager"},{"t":"Approve pricing changes","d":"Sales Manager approves renewal discounts or waived uplifts. Multi-year terms or non-standard payment terms also need Finance Lead approval.","o":"Sales Manager"},{"t":"Manage notice deadlines","d":"Account Manager tracks notice periods and confirms in writing any cancellation notice received, informing the Sales Manager the same day.","o":"Account Manager"},{"t":"Close the renewal","d":"Account Manager obtains signature or confirms auto-renewal at least 15 days before the renewal date and updates the CRM.","o":"Account Manager"},{"t":"Invoice the renewal","d":"Finance Lead issues the renewal invoice per contract terms and confirms any changes in quantity or price.","o":"Finance Lead"},{"t":"Learn from churn","d":"Customer Success Manager records churn and downgrade reasons and holds a short loss review for any account above [amount].","o":"Customer Success Manager"}],"checks":["Every renewal has an opportunity 120 days ahead","Value review held for all accounts above [amount]","Cancellation notices logged the day they are received","Renewal discounts approved per the matrix","Churn reasons recorded for 100% of lost renewals"],"kpis":[["Gross revenue retention","At least [90]%"],["Net revenue retention","At least [105]%"],["Renewals closed before renewal date","At least 95%"],["Value reviews completed for eligible accounts","At least 90%"]],"risks":[["Surprise churn","Early health review and save plans."],["Missing notice deadlines","Contract repository alerts and notice tracking."],["Habitual renewal discounting","Uplift policy and approval matrix."],["Pushy upselling damaging trust","Expansion based on documented customer value."]],"related":["Sales to Delivery Handoff","Weekly Pipeline Review and Forecast","Customer Health Monitoring","Proposal and Quotation"],"review":"Every 12 months, or after a quarter where retention falls below target"},{"id":"sales-commission-calculation","dept":"sales","title":"Sales Commission Calculation","summary":"Calculates, approves and pays sales commission accurately and on time according to the signed compensation plan.","tags":["commission","sales compensation","incentive","quota","payout","accelerators","clawback"],"purpose":"To pay sales staff the right commission on time, based on verified bookings and the plan they signed. Accurate, transparent calculation builds trust and keeps commission costs controlled.","scope":"Covers monthly or quarterly commission and bonus calculation for quota-carrying roles. It does not cover plan design, base salary reviews or non-sales bonuses.","definitions":[["Compensation plan","The signed document setting quota, rates, accelerators, clawbacks and payment timing for each rep."],["Commissionable booking","A closed won deal that meets plan rules, for example signed contract and, where required, payment received."],["Accelerator","A higher commission rate paid on bookings above quota."],["Clawback","Recovery of commission paid on a deal that later cancels or is not paid, within the period the plan states."]],"roles":[["RevOps Analyst","Extracts bookings, runs the calculation and prepares statements."],["Finance Lead","Reviews and approves totals, accrues cost and checks against invoices and payments."],["Sales Manager","Confirms deal credit splits and resolves rep queries."],["Payroll Administrator","Includes approved commission in payroll."],["Sales Rep","Reviews their statement and raises disputes on time."]],"prereqs":["Signed compensation plans for every eligible rep","Closed won bookings report from [CRM tool]","Invoice and payment data from [accounting tool]","Commission calculator or [commission tool]","Payroll calendar and cut-off dates"],"steps":[{"t":"Confirm plan acceptance","d":"RevOps Analyst confirms each eligible rep has a signed plan for the period. No commission is calculated on an unsigned plan without Finance Lead approval.","o":"RevOps Analyst"},{"t":"Close the bookings period","d":"RevOps Analyst locks the bookings report [3] business days after period end and extracts closed won deals with amounts and owners.","o":"RevOps Analyst"},{"t":"Verify bookings","d":"Finance Lead matches each deal to a signed contract and, where the plan requires, an invoice or payment, and flags exceptions.","o":"Finance Lead"},{"t":"Confirm credit splits","d":"Sales Manager confirms split credit between reps and any team or overlay credit in writing per the plan rules.","o":"Sales Manager"},{"t":"Calculate commission","d":"RevOps Analyst applies rates, tiers, accelerators, caps and any clawbacks from cancellations to produce each rep's total.","o":"RevOps Analyst"},{"t":"Second-person check","d":"A second person recalculates a sample of at least [20]% of statements, and every statement above [amount], before approval.","o":"Finance Lead"},{"t":"Approve totals","d":"Finance Lead approves total commission and records the accrual in the accounts.","o":"Finance Lead"},{"t":"Issue statements","d":"RevOps Analyst sends each rep a statement listing every deal, amount, rate and adjustment at least 5 business days before payroll cut-off.","o":"RevOps Analyst"},{"t":"Handle disputes","d":"Sales Rep raises disputes in writing within 5 business days of the statement. Sales Manager and RevOps Analyst resolve within 10 business days, with Finance Lead deciding unresolved cases.","o":"Sales Rep"},{"t":"Process payment","d":"Payroll Administrator includes approved commission in the next payroll and confirms payment to RevOps Analyst.","o":"Payroll Administrator"},{"t":"Archive records","d":"RevOps Analyst archives calculation files, approvals and statements for the period required by local law, at least [6] years.","o":"RevOps Analyst"}],"checks":["Every payout traceable to a signed contract and signed plan","Second-person recalculation completed before approval","Clawbacks applied consistently per plan rules","Statements delivered before payroll cut-off","Changes to calculation logic documented and approved by Finance Lead"],"kpis":[["Commission paid on schedule","100% of pay runs"],["Calculation errors found after payment","Under [1]% of statements"],["Disputes resolved within 10 business days","At least 95%"],["Commission cost as % of new bookings","Within plan budget of [x]%"]],"risks":[["Overpayment from incorrect bookings","Finance verification against contracts and invoices."],["Disputes harming morale","Transparent statements and clear dispute route."],["Gaming through deal timing or splits","Plan rules on timing and written split approvals."],["Key person dependency on one spreadsheet","Documented logic, version control and a trained backup."]],"related":["Weekly Pipeline Review and Forecast","Contract Negotiation and Closing","Compensation and Promotion Review","Payroll Processing"],"review":"Every 12 months at plan year start, or when the compensation plan changes"},{"id":"marketing-content-planning-publishing","dept":"marketing","title":"Content Planning and Publishing","summary":"Plans, drafts, reviews and publishes blog and long-form content on a predictable editorial calendar.","tags":["content calendar","editorial","blog","copywriting","publishing","content marketing"],"purpose":"To make sure [Company] publishes useful, accurate and on-brand content on a steady schedule. It links each piece to a business goal and a target audience so effort is not wasted.","scope":"Covers blog posts, guides, case studies and other long-form owned content from idea to publication and first distribution. It does not cover social-only posts, paid ad creative or press releases, which have their own SOPs.","definitions":[["Editorial calendar","The shared schedule listing every planned piece, owner, status and publish date."],["Content brief","A one-page outline stating audience, goal, keyword, angle, sources and call to action."],["SME","Subject matter expert who checks technical or factual accuracy."]],"roles":[["Content Lead","Owns the calendar, approves briefs and gives final publish sign-off."],["Writer","Researches and drafts the piece to the brief and fixes review comments."],["Editor","Edits for clarity, style guide compliance and grammar."],["SME","Confirms facts, figures and technical claims."],["Marketing Ops","Uploads, formats, tags and schedules content in the CMS."]],"prereqs":["Approved quarterly marketing goals and target personas","Brand style guide and tone of voice document","Access to [CMS] and the editorial calendar in [project tool]","Keyword research list from the latest SEO review"],"steps":[{"t":"Hold the monthly planning meeting","d":"In the last week of each month, review goals, SEO gaps and sales questions, and shortlist ideas for the next 4 to 6 weeks.","o":"Content Lead"},{"t":"Score and select ideas","d":"Score each idea 1 to 5 on audience fit, goal impact and effort, and add the top-scoring ones to the calendar with a publish date.","o":"Content Lead"},{"t":"Write the content brief","d":"Complete the brief template with audience, goal, primary keyword, outline, sources and call to action at least 10 business days before publish date.","o":"Content Lead"},{"t":"Draft the piece","d":"Write the first draft to the brief and word count, citing sources for every statistic. Submit at least 5 business days before publish date.","o":"Writer"},{"t":"Run SME fact check","d":"Send technical or regulated claims to the SME, who returns comments within 2 business days.","o":"SME"},{"t":"Edit for style and quality","d":"Edit against the style guide, check headings, links and readability, and run a plagiarism and grammar check.","o":"Editor"},{"t":"Prepare assets and metadata","d":"Add images with alt text and usage rights confirmed, meta title under 60 characters, meta description under 155 characters and internal links.","o":"Marketing Ops"},{"t":"Give final sign-off","d":"Review the staged page in preview, confirm the call to action works, and approve in the calendar.","o":"Content Lead"},{"t":"Schedule and publish","d":"Schedule in [CMS] for the agreed date and time, then check the live URL, mobile view and tracking tags within 1 hour of going live.","o":"Marketing Ops"},{"t":"Distribute","d":"Share to newsletter, social channels and sales team within 2 business days of publishing, using the distribution checklist.","o":"Content Lead"},{"t":"Review performance","d":"At 30 and 90 days, record traffic, engagement and conversions in the calendar and flag pieces to refresh or retire.","o":"Marketing Ops"}],"checks":["Every published piece has an approved brief on file","All statistics link to a credible, dated source","Images have confirmed licences and alt text","Meta title, description and canonical URL are set before publishing"],"kpis":[["On-time publishing","90% of pieces published on the scheduled date"],["Organic sessions per piece","[target] sessions within 90 days"],["Content-assisted conversions","[target] per month"],["Review cycle time","Draft to sign-off within 5 business days"]],"risks":[["Factual errors or outdated claims","Mandatory SME check for technical content and source dates within 24 months"],["Copyright infringement on images","Use only licensed or owned images and log the licence"],["Calendar slippage","Weekly status check and a 2-week buffer of ready drafts"]],"related":["Brand Asset and Copy Approval","Monthly SEO Review","Social Media Posting and Moderation","Brand Style Guide"],"review":"Every 12 months, or after a change of CMS or content strategy"},{"id":"marketing-social-media-posting-moderation","dept":"marketing","title":"Social Media Posting and Moderation","summary":"Keeps company social channels active, on-brand and safe, with clear rules for replies, moderation and escalation.","tags":["social media","community management","moderation","linkedin","instagram","posting schedule"],"purpose":"To publish consistent, approved posts on [Company] social channels and respond to the community quickly and appropriately. It also protects the brand by setting rules for harmful comments and sensitive topics.","scope":"Covers all official company accounts on [platforms], including scheduled posts, replies, direct messages and comment moderation. It does not cover employees' personal accounts (see Social Media Policy) or paid social ads.","definitions":[["Content queue","The scheduled list of approved posts in [scheduling tool]."],["Sensitive post","Any post on legal, safety, pricing changes, incidents, politics or tragedies."],["Hide vs delete","Hiding keeps a comment visible only to its author; deleting removes it permanently."]],"roles":[["Social Media Manager","Plans the queue, posts, monitors channels and moderates."],["Content Lead","Approves the weekly queue and any sensitive post."],["Support Team","Answers product and account questions routed from social."],["Communications Lead","Handles crises, media enquiries and legal-risk posts."]],"prereqs":["Admin access to each platform held under company-owned accounts with two-factor authentication","Scheduling tool such as [scheduling tool]","Brand guidelines and approved hashtags","Moderation guidelines and saved reply templates"],"steps":[{"t":"Build the weekly queue","d":"By Wednesday each week, draft the next week's posts with copy, visuals, links and platform-specific formats.","o":"Social Media Manager"},{"t":"Approve the queue","d":"Review and approve posts by Thursday close of business. Any sensitive post needs written approval from the Content Lead.","o":"Content Lead"},{"t":"Schedule posts","d":"Load approved posts into [scheduling tool] with UTM-tagged links and check previews on each platform.","o":"Social Media Manager"},{"t":"Monitor channels","d":"Check notifications, mentions and DMs at least 3 times per business day, and set alerts for brand keywords.","o":"Social Media Manager"},{"t":"Respond to comments and DMs","d":"Reply to genuine questions within 4 business hours using approved tone. Never share personal or account data publicly.","o":"Social Media Manager"},{"t":"Route support issues","d":"Move account, billing or bug issues to a private channel and create a support ticket within 1 hour, then reply publicly that the team is on it.","o":"Support Team"},{"t":"Moderate harmful content","d":"Hide spam, hate speech, threats or personal data immediately, screenshot it first, and block repeat offenders. Do not delete legitimate criticism.","o":"Social Media Manager"},{"t":"Escalate risk situations","d":"If a post goes viral negatively, involves a safety claim, legal threat or media, pause scheduled posts and alert the Communications Lead within 30 minutes.","o":"Social Media Manager"},{"t":"Handle crisis responses","d":"Agree a holding statement and response plan, and approve every public reply until the issue is closed.","o":"Communications Lead"},{"t":"Report monthly","d":"Report reach, engagement rate, follower growth, response time and top posts by the 5th business day of the month.","o":"Social Media Manager"}],"checks":["Every account is company-owned with two-factor authentication and at least 2 admins","Sensitive posts have documented approval","Moderation actions are logged with screenshots","Scheduled posts are paused during any active incident"],"kpis":[["Response time","90% of comments and DMs answered within 4 business hours"],["Engagement rate","[target]% per post on average"],["Posting consistency","100% of planned posts published"],["Escalations logged","100% of risk situations escalated within 30 minutes"]],"risks":[["Account takeover","Two-factor authentication, password manager and quarterly access review"],["Off-brand or insensitive post","Approval workflow and pause procedure during news events"],["Personal data shared publicly","Move all account conversations to private channels"],["Loss of access when staff leave","Remove access on the leaver's last day per offboarding checklist"]],"related":["Social Media Policy","Customer Complaint Handling","Press Release and Media Requests","Content Planning and Publishing"],"review":"Every 12 months, or after a social media incident or platform policy change"},{"id":"marketing-email-campaign-launch","dept":"marketing","title":"Email Campaign Launch","summary":"Builds, tests and sends marketing emails to the right consented audience with tracking and compliance checks.","tags":["email marketing","newsletter","campaign","eDM","mailchimp","unsubscribe"],"purpose":"To send effective marketing emails that reach only people who have agreed to receive them. It reduces errors such as broken links, wrong segments and missing unsubscribe links.","scope":"Covers one-off and recurring marketing emails and newsletters sent through [email platform]. It does not cover transactional emails such as receipts and password resets, or one-to-one sales emails.","definitions":[["Segment","A filtered group of contacts chosen to receive a send."],["Seed list","Internal test addresses that receive every send to confirm delivery."],["Suppression list","Contacts who must never be emailed, such as unsubscribes and hard bounces."],["A/B test","Sending two variants to small samples to pick the better performer."]],"roles":[["Email Marketing Manager","Plans, builds and schedules the campaign."],["Content Lead","Approves copy and offer."],["Marketing Ops","Builds segments, checks data and tracking."],["Reviewer","A second person who completes the pre-send checklist."]],"prereqs":["Campaign brief with goal, audience, offer and send date","Access to [email platform] with verified sending domain (SPF, DKIM, DMARC)","Approved email template and brand assets","Current consent and suppression lists"],"steps":[{"t":"Confirm the campaign brief","d":"Agree goal, audience, offer, key message, success metric and send date at least 7 business days ahead.","o":"Email Marketing Manager"},{"t":"Build the segment","d":"Filter contacts with valid marketing consent for this purpose, exclude suppressions, customers in active support escalations and anyone emailed in the last [x] days.","o":"Marketing Ops"},{"t":"Write and approve copy","d":"Draft subject line, preheader, body and call to action. Get approval for copy and offer terms 3 business days before send.","o":"Content Lead"},{"t":"Build the email","d":"Build in the approved template with plain-text version, alt text, physical address and a one-click unsubscribe link.","o":"Email Marketing Manager"},{"t":"Add tracking","d":"Add UTM parameters to all links and confirm the landing page and conversion events are live.","o":"Marketing Ops"},{"t":"Test rendering and links","d":"Send to the seed list, check major email clients and mobile, click every link and confirm personalisation fallbacks.","o":"Email Marketing Manager"},{"t":"Complete the pre-send checklist","d":"A second person checks segment size, sender name, subject, links, unsubscribe and send time, and signs off in the checklist.","o":"Reviewer"},{"t":"Run A/B test if planned","d":"Send variants to [10]% samples each and pick the winner after [4] hours based on the agreed metric.","o":"Email Marketing Manager"},{"t":"Schedule and send","d":"Schedule in the recipients' main time zone and monitor bounces and complaints for the first 2 hours. Pause if spam complaints exceed 0.1%.","o":"Email Marketing Manager"},{"t":"Report results","d":"Within 5 business days, report delivery, open, click, conversion and unsubscribe rates against the brief and record learnings.","o":"Marketing Ops"}],"checks":["Only contacts with valid consent are in the segment","Unsubscribe link and company address are present and working","Two-person pre-send sign-off is recorded","Seed list received the final version"],"kpis":[["Delivery rate","98% or higher"],["Spam complaint rate","Below 0.1%"],["Click-through rate","[target]% per campaign"],["Error-free sends","100% with no correction email needed"]],"risks":[["Emailing people without consent","Consent-based segments and suppression list sync; check local law such as GDPR or CAN-SPAM"],["Wrong audience or wrong merge data","Segment count check and personalisation fallbacks"],["Domain reputation damage","Authenticated domain, list hygiene and complaint monitoring"]],"related":["Brand Asset and Copy Approval","Customer Data Protection Policy","Product Launch Go-to-Market","Pre-send Checklist"],"review":"Every 12 months, or after a send error or deliverability issue"},{"id":"marketing-paid-ads-campaign-launch","dept":"marketing","title":"Paid Ads Campaign Launch","summary":"Launches paid search and social campaigns with approved budgets, correct tracking and daily spend controls.","tags":["paid ads","ppc","google ads","meta ads","paid social","media buying","budget"],"purpose":"To launch paid advertising that spends within budget, tracks conversions accurately and follows platform and advertising rules. It gives a repeatable way to test, optimise and stop campaigns.","scope":"Covers paid campaigns on [ad platforms] managed in-house or by an agency, from brief to post-campaign report. It does not cover sponsorships, influencer fees or print media buying.","definitions":[["CPA","Cost per acquisition: ad spend divided by conversions."],["ROAS","Return on ad spend: revenue divided by ad spend."],["Conversion event","The tracked action that counts as success, such as a sign-up or purchase."],["Kill criteria","Pre-agreed thresholds at which an ad set is paused."]],"roles":[["Performance Marketing Manager","Builds, launches and optimises campaigns."],["Head of Marketing","Approves budget, targets and kill criteria."],["Marketing Ops","Sets up and verifies tracking and attribution."],["Finance","Holds the ad budget, receives invoices and reconciles spend."],["Content Lead","Approves ad copy and creative."]],"prereqs":["Approved campaign brief with budget, CPA or ROAS target and dates","Company-owned ad accounts with billing set up and admin access for 2 staff","Conversion tracking and analytics in place","Approved creative in required sizes"],"steps":[{"t":"Approve brief and budget","d":"Agree objective, audience, total and daily budget, target CPA or ROAS and kill criteria in writing before any build.","o":"Head of Marketing"},{"t":"Verify tracking","d":"Test each conversion event end to end in the platform and analytics, and confirm values and deduplication.","o":"Marketing Ops"},{"t":"Build campaign structure","d":"Create campaigns and ad sets with clear naming convention [platform_objective_audience_date], audiences, exclusions and placements.","o":"Performance Marketing Manager"},{"t":"Load approved creative","d":"Upload only approved copy and creative with UTM-tagged URLs, and confirm claims meet platform ad policies.","o":"Content Lead"},{"t":"Set budget caps","d":"Set daily budgets and an account spending limit no higher than the approved total plus [5]%.","o":"Performance Marketing Manager"},{"t":"Peer review before launch","d":"A second person checks targeting, budgets, dates, URLs and tracking against the brief and signs the launch checklist.","o":"Marketing Ops"},{"t":"Launch and monitor","d":"Launch in the agreed window and check spend, delivery and disapprovals at 2 hours, 24 hours and then daily.","o":"Performance Marketing Manager"},{"t":"Optimise weekly","d":"Pause ad sets that hit kill criteria after [minimum spend], shift budget to winners and refresh creative when frequency exceeds [3].","o":"Performance Marketing Manager"},{"t":"Reconcile spend","d":"Match platform invoices to budget monthly and flag variances over 10% to the Head of Marketing.","o":"Finance"},{"t":"Close and report","d":"Within 5 business days of the end date, report spend, CPA, ROAS and learnings, and turn off all ads.","o":"Performance Marketing Manager"}],"checks":["Written budget approval exists before launch","Account spending limits are set","Launch checklist signed by a second person","Monthly spend reconciled to invoices"],"kpis":[["CPA vs target","At or below [target CPA]"],["Budget adherence","Spend within 5% of approved budget"],["Tracking accuracy","Platform conversions within 10% of analytics or CRM"],["Ad disapprovals","Fixed within 1 business day"]],"risks":[["Overspend","Daily budgets, account limits and daily monitoring"],["Broken tracking leading to bad decisions","End-to-end conversion test before launch and weekly check"],["Misleading ad claims","Copy approval and substantiation for every claim"],["Agency owning the account","All ad accounts owned by [Company], agency given partner access only"]],"related":["Brand Asset and Copy Approval","Product Launch Go-to-Market","Marketing Budget Policy","Vendor and Agency Management"],"review":"Every 12 months, or after an overspend or tracking failure"},{"id":"marketing-brand-asset-copy-approval","dept":"marketing","title":"Brand Asset and Copy Approval","summary":"Routes marketing copy and designs through a fast, tiered review so nothing off-brand, false or unlicensed goes out.","tags":["brand approval","copy review","creative review","legal review","brand guidelines","sign-off"],"purpose":"To make sure all external marketing material is on-brand, accurate and legally safe before it is published. Tiered approval keeps low-risk items fast and puts more checks on high-risk ones.","scope":"Covers copy, graphics, video, presentations and web pages produced by or for marketing, including agency work. It does not cover internal-only documents or customer support macros.","definitions":[["Tier 1","Low-risk item using existing approved messaging, such as a routine social post."],["Tier 2","New messaging, campaign creative or web page."],["Tier 3","Claims about performance, pricing, comparisons, testimonials, regulated topics or legal terms."],["Asset library","Central store of approved logos, templates and images in [DAM tool]."]],"roles":[["Requester","Submits the item with context and the required tier."],["Brand Manager","Checks brand, tone and visual identity and keeps the asset library."],["Content Lead","Checks messaging accuracy and clarity."],["Legal Reviewer","Reviews Tier 3 claims, comparisons, contests and testimonials."],["Head of Marketing","Resolves disputes and approves exceptions."]],"prereqs":["Brand guidelines and tone of voice guide","Approval request form or board in [project tool]","Claim substantiation file","Asset library with licence records"],"steps":[{"t":"Submit the request","d":"Submit the draft with audience, channel, go-live date and proposed tier, at least 2 business days before go-live for Tier 1 and 5 for Tier 2 or 3.","o":"Requester"},{"t":"Confirm the tier","d":"Check the tier against the definitions and raise it if the item contains claims, pricing or third-party content.","o":"Brand Manager"},{"t":"Brand review","d":"Check logo use, colours, typography, imagery and tone against brand guidelines and return comments within 1 business day.","o":"Brand Manager"},{"t":"Messaging review","d":"Check facts, product names, features and calls to action are correct and current within 1 business day.","o":"Content Lead"},{"t":"Substantiate claims","d":"For Tier 3, attach evidence for every factual or comparative claim, such as test data or a dated source.","o":"Requester"},{"t":"Legal review","d":"Review Tier 3 items for misleading claims, trademark use, testimonial consent and required disclaimers within 3 business days.","o":"Legal Reviewer"},{"t":"Check rights and licences","d":"Confirm licences for stock images, music and fonts and signed releases for any identifiable people.","o":"Brand Manager"},{"t":"Record approval","d":"Mark the item approved with date, approvers and version number. Any later change in copy or claim needs re-approval.","o":"Brand Manager"},{"t":"Resolve disagreements","d":"If reviewers disagree or a deadline is at risk, decide within 1 business day and record the reason.","o":"Head of Marketing"},{"t":"Archive the final","d":"Store the approved final file and evidence in the asset library for at least [3] years.","o":"Brand Manager"}],"checks":["Every published item has a recorded approval and version","Tier 3 items have claim evidence and legal sign-off","Licences and model releases are on file","Brand guidelines reviewed against live assets each quarter"],"kpis":[["Approval turnaround","Tier 1 in 1 day, Tier 2 in 3 days, Tier 3 in 5 days"],["Post-publication corrections","Fewer than [2] per quarter"],["Items published without approval","Zero"]],"risks":[["Misleading claims","Claim evidence and legal review for Tier 3"],["Copyright or trademark infringement","Licence records and use of the asset library only"],["Approval bottleneck","Tier-based routing, named backups and turnaround targets"]],"related":["Content Planning and Publishing","Paid Ads Campaign Launch","Brand Style Guide","Influencer and Partner Collaboration"],"review":"Every 12 months, or after a rebrand or a published error"},{"id":"marketing-product-launch-gtm","dept":"marketing","title":"Product Launch Go-to-Market","summary":"Coordinates marketing, sales and support so a new product or feature launches on time with clear messaging.","tags":["product launch","go-to-market","gtm","feature release","launch plan","positioning"],"purpose":"To bring new products and major features to market in a coordinated way. Everyone customer-facing should know what is launching, who it is for and how to talk about it before launch day.","scope":"Covers Tier 1 (major) and Tier 2 (notable) launches of products, features and pricing changes. Minor releases are handled through release notes only and are outside this SOP.","definitions":[["Launch tier","Size of the launch: Tier 1 needs full GTM, Tier 2 a reduced plan, Tier 3 release notes only."],["Positioning statement","Short statement of target customer, problem, solution and key difference."],["Launch readiness review","Go or no-go meeting held before launch day."]],"roles":[["Product Marketing Manager","Owns the GTM plan, positioning, messaging and launch timeline."],["Product Manager","Confirms scope, release date and feature readiness."],["Sales Lead","Prepares the sales team and pipeline targets."],["Support Lead","Prepares help content and trains support staff."],["Head of Marketing","Approves tier, budget and go or no-go decision."]],"prereqs":["Product requirements and confirmed release window","Customer research or beta feedback","Launch plan template and RACI","Pricing and packaging decision, if relevant"],"steps":[{"t":"Set the launch tier","d":"Agree the tier, launch date and goals at least 8 weeks ahead for Tier 1 and 4 weeks for Tier 2.","o":"Head of Marketing"},{"t":"Write positioning and messaging","d":"Draft positioning, key messages, proof points and FAQs, and validate them with 3 to 5 customers or sales staff.","o":"Product Marketing Manager"},{"t":"Build the launch plan","d":"List every deliverable, owner and due date across channels, sales enablement and support readiness.","o":"Product Marketing Manager"},{"t":"Confirm feature readiness","d":"Confirm the release date, known limitations and rollout approach, and flag any slip within 1 business day.","o":"Product Manager"},{"t":"Produce launch assets","d":"Create landing page, demo, blog, email, social and ad creative, all through the approval process, 2 weeks before launch.","o":"Product Marketing Manager"},{"t":"Enable sales","d":"Run a training session, share the pitch deck, battlecard and objection handling, and set pipeline targets 1 week before launch.","o":"Sales Lead"},{"t":"Prepare support","d":"Publish help articles, create macros and train agents 1 week before launch.","o":"Support Lead"},{"t":"Hold the readiness review","d":"Three business days before launch, check every deliverable and make a go, delay or reduced-launch decision.","o":"Head of Marketing"},{"t":"Launch","d":"Publish assets in the agreed order, monitor site, sign-ups, social and support queues, and post updates in [launch channel] through launch day.","o":"Product Marketing Manager"},{"t":"Run the 30-day review","d":"Report adoption, pipeline, revenue and feedback against goals and record lessons for the next launch.","o":"Product Marketing Manager"}],"checks":["Launch tier and goals approved in writing","All external assets approved before launch day","Sales and support trained before launch","Go or no-go decision recorded"],"kpis":[["Launch on planned date","90% of Tier 1 and 2 launches"],["Adoption","[target]% of active customers using the feature in 30 days"],["Launch pipeline","[target] value created in 30 days"],["Support readiness","Help articles live on launch day"]],"risks":[["Product slip after marketing commitments","Readiness review and avoiding public dates until 2 weeks before launch"],["Inconsistent messaging","Single messaging document used by all teams"],["Support overwhelmed","Macros, extra cover on launch week and staged rollout"]],"related":["Brand Asset and Copy Approval","Email Campaign Launch","Knowledge Base Article Updates","Sales Enablement Process"],"review":"Every 12 months, or after each Tier 1 launch retrospective"},{"id":"marketing-event-webinar-planning","dept":"marketing","title":"Event and Webinar Planning","summary":"Plans and runs webinars, in-person events and trade shows from goal setting to lead follow-up.","tags":["events","webinar","trade show","conference","virtual event","lead capture"],"purpose":"To run events that are well organised, on budget and produce measurable leads or customer value. It covers planning, promotion, delivery and follow-up so nothing is missed.","scope":"Covers company-hosted webinars, in-person events and exhibiting at third-party trade shows. It does not cover internal company events or staff travel policy.","definitions":[["Run of show","Minute-by-minute plan of the event with speakers and cues."],["Registrant","Person who signed up, whether or not they attend."],["Lead SLA","Agreed time for sales to follow up event leads."]],"roles":[["Event Manager","Owns the plan, budget, logistics and run of show."],["Speaker or Host","Prepares and delivers content and rehearses."],["Marketing Ops","Builds registration, tracking and lead upload."],["Sales Lead","Follows up leads within the agreed SLA."],["Head of Marketing","Approves event, goals and budget."]],"prereqs":["Event brief with goal, audience, date, budget and success metric","Webinar or registration platform such as [platform]","Venue or exhibitor contract, if in-person","Privacy notice for registrant data"],"steps":[{"t":"Approve the event brief","d":"Agree goal, audience, format, budget and target registrations 8 to 12 weeks ahead for in-person and 4 to 6 weeks for webinars.","o":"Head of Marketing"},{"t":"Book venue, platform and vendors","d":"Book and contract the venue or platform, catering, AV and booth, checking cancellation terms, insurance and accessibility.","o":"Event Manager"},{"t":"Confirm speakers and content","d":"Confirm speakers in writing, agree topic and slides due date, and collect bios and photos.","o":"Event Manager"},{"t":"Set up registration and tracking","d":"Build the registration page with consent wording, UTM tracking and automated confirmation and reminder emails.","o":"Marketing Ops"},{"t":"Promote the event","d":"Run promotion across email, social, partners and ads from 4 weeks out and track registrations weekly against target.","o":"Event Manager"},{"t":"Rehearse","d":"Hold a full technical rehearsal 2 to 3 business days before, testing audio, slides, polls, recording and backup host.","o":"Speaker or Host"},{"t":"Run the event","d":"Follow the run of show, start on time, capture questions and attendance, and record if agreed.","o":"Event Manager"},{"t":"Upload and grade leads","d":"Upload attendee and booth leads to [CRM] within 1 business day with source and engagement score.","o":"Marketing Ops"},{"t":"Follow up","d":"Send recording and thank-you emails within 2 business days, and sales contacts hot leads within 2 business days.","o":"Sales Lead"},{"t":"Close out","d":"Pay invoices, reconcile budget and report registrations, attendance, leads, pipeline and cost per lead within 10 business days.","o":"Event Manager"}],"checks":["Contracts reviewed for cancellation and liability terms","Registration form includes consent and privacy notice","Technical rehearsal completed","Leads uploaded within 1 business day"],"kpis":[["Registration to attendance","[40]% or higher for webinars"],["Cost per lead","At or below [target]"],["Lead follow-up","100% of hot leads contacted within 2 business days"],["Budget adherence","Within 10% of approved budget"]],"risks":[["Technical failure during webinar","Rehearsal, backup host and backup internet"],["Low attendance","Weekly registration tracking with promotion triggers"],["Cancellation costs","Check cancellation clauses and event insurance"],["Leads not followed up","Lead SLA and CRM task assignment"]],"related":["Email Campaign Launch","Paid Ads Campaign Launch","Lead Handoff and Qualification","Travel and Expenses Policy"],"review":"Every 12 months, or after a major event"},{"id":"marketing-monthly-seo-review","dept":"marketing","title":"Monthly SEO Review","summary":"Runs a monthly check of search rankings, technical health and content gaps, and turns findings into a prioritised action list.","tags":["seo","search engine optimisation","organic traffic","keywords","technical seo","site audit"],"purpose":"To protect and grow organic search traffic by catching technical problems early and finding content opportunities. It turns data into a short, prioritised list of actions each month.","scope":"Covers [Company] websites and blog on all major search engines. It does not cover paid search or app store optimisation.","definitions":[["Core Web Vitals","Search engine metrics for page loading, interactivity and visual stability."],["Indexation","Whether a page is included in a search engine's index."],["Striking distance keyword","A keyword where the site ranks in positions 4 to 20 and could move up with work."]],"roles":[["SEO Specialist","Runs the review, analyses data and writes the action list."],["Web Developer","Fixes technical issues raised."],["Content Lead","Prioritises and assigns content updates."],["Head of Marketing","Reviews results and approves priorities."]],"prereqs":["Access to [search console], [analytics] and [SEO tool]","Tracked keyword list","Previous month's SEO report","Site crawl tool"],"steps":[{"t":"Pull performance data","d":"In the first 3 business days of the month, export organic sessions, clicks, impressions, CTR and conversions compared to last month and last year.","o":"SEO Specialist"},{"t":"Review keyword rankings","d":"Check tracked keywords, note any drop of more than 5 positions and list striking distance keywords.","o":"SEO Specialist"},{"t":"Crawl the site","d":"Run a full crawl and log broken links, redirect chains, missing titles, duplicate content and noindex errors.","o":"SEO Specialist"},{"t":"Check indexation and coverage","d":"Review search console coverage and sitemap errors, and confirm key pages are indexed.","o":"SEO Specialist"},{"t":"Check page experience","d":"Review Core Web Vitals and mobile usability for top templates and flag failing pages.","o":"Web Developer"},{"t":"Find content opportunities","d":"Identify pages losing traffic, content gaps against competitors and pages to merge or refresh.","o":"SEO Specialist"},{"t":"Prioritise actions","d":"Score each action on impact and effort and pick the top [5 to 10] for the month.","o":"SEO Specialist"},{"t":"Approve and assign","d":"Approve the action list in the monthly meeting and assign owners and due dates.","o":"Head of Marketing"},{"t":"Fix technical issues","d":"Fix critical issues such as site-wide noindex or broken checkout links within 2 business days, and others in the next sprint.","o":"Web Developer"},{"t":"Update content","d":"Refresh or create assigned content through the content SOP and log changes with dates for later comparison.","o":"Content Lead"}],"checks":["Report delivered by the 5th business day","Critical technical issues logged and fixed within 2 business days","Changes logged with dates","Action list reviewed against last month's outcomes"],"kpis":[["Organic sessions","[target]% growth quarter on quarter"],["Organic conversions","[target] per month"],["Critical crawl errors","Zero open beyond 2 business days"],["Action completion","80% of monthly actions done on time"]],"risks":[["Traffic loss from site changes","SEO check in the release process for redirects and meta tags"],["Algorithm update drops","Monitor rankings weekly during known updates and focus on content quality"],["Wasted effort on low-value keywords","Prioritise by conversion intent, not volume alone"]],"related":["Content Planning and Publishing","Website Release Process","Paid Ads Campaign Launch"],"review":"Every 12 months, or after a site migration or major search algorithm update"},{"id":"marketing-press-release-media-requests","dept":"marketing","title":"Press Release and Media Requests","summary":"Manages press releases and journalist enquiries so the company speaks with one accurate, approved voice.","tags":["press release","pr","media relations","journalist","public relations","spokesperson"],"purpose":"To make sure all contact with the media is handled by approved people with accurate, approved messages. It protects [Company] from off-the-cuff comments and missed opportunities.","scope":"Covers drafting and distributing press releases and responding to any media, analyst or podcast request received by any employee. It does not cover routine social posts or customer reviews.","definitions":[["Spokesperson","An employee authorised to speak to the media on a topic."],["Embargo","An agreement that a journalist will not publish before a stated date and time."],["Holding statement","A short approved statement used while facts are confirmed."],["On background","Information that may be used but not attributed to a named person."]],"roles":[["Communications Lead","Owns media relations, drafts releases and routes all requests."],["Spokesperson","Gives interviews and quotes after briefing."],["CEO","Approves company-level announcements and quotes."],["Legal Reviewer","Checks releases for legal, financial or confidentiality risk."],["All Employees","Forward media enquiries without commenting."]],"prereqs":["List of approved spokespeople and topics","Press release template and boilerplate","Media contact list or distribution service","Company fact sheet and press kit"],"steps":[{"t":"Forward all media enquiries","d":"Any employee contacted by media replies only that someone will get back to them, and forwards details to [press email] within 1 hour.","o":"All Employees"},{"t":"Log and assess requests","d":"Log the outlet, deadline and topic, check the outlet and decide whether to respond, within 4 business hours.","o":"Communications Lead"},{"t":"Brief the spokesperson","d":"Prepare key messages, likely questions, facts and no-go topics, and brief the spokesperson before any interview.","o":"Communications Lead"},{"t":"Give the interview","d":"Stick to the key messages, avoid speculation, and say 'I will come back to you' when unsure. Never go off the record without agreement.","o":"Spokesperson"},{"t":"Draft the press release","d":"For announcements, draft a release with headline, dateline, key facts, quote and boilerplate at least 10 business days before release.","o":"Communications Lead"},{"t":"Review and approve","d":"Get factual sign-off from the owner, legal review for risk and final approval of quotes from the CEO.","o":"Legal Reviewer"},{"t":"Distribute","d":"Send to targeted journalists under embargo if agreed, publish on the newsroom page and share on social at release time.","o":"Communications Lead"},{"t":"Follow up and track coverage","d":"Follow up with key journalists within 2 business days and log coverage, reach and tone.","o":"Communications Lead"},{"t":"Correct errors","d":"If coverage contains a factual error, request a correction politely within 1 business day with evidence.","o":"Communications Lead"}],"checks":["Only approved spokespeople give comments","Every release has legal and CEO approval recorded","All enquiries logged with response outcome","Embargo times confirmed in writing"],"kpis":[["Enquiry response","100% acknowledged within 4 business hours"],["Coverage","[target] pieces per quarter in target outlets"],["Message pull-through","Key message present in [70]% of coverage"]],"risks":[["Unauthorised comment by staff","Media policy in induction and the forwarding rule"],["Disclosure of confidential information","Legal review and briefing on no-go topics"],["Embargo broken","Only share under embargo with trusted journalists and prepare for early publication"]],"related":["Media and Communications Policy","Service Outage Customer Communication","Social Media Posting and Moderation","Product Launch Go-to-Market"],"review":"Every 12 months, or after a media incident"},{"id":"marketing-influencer-partner-collaboration","dept":"marketing","title":"Influencer and Partner Collaboration","summary":"Selects, contracts and manages influencers and co-marketing partners with clear deliverables and disclosure rules.","tags":["influencer marketing","creators","co-marketing","partnerships","affiliate","sponsorship"],"purpose":"To work with influencers and partners in a way that is transparent, measurable and protects the brand. It sets checks on fit, contracts, disclosure and payment.","scope":"Covers paid and gifted influencer work, affiliate creators and co-marketing campaigns with other companies. It does not cover reseller or channel sales agreements, which belong to sales.","definitions":[["Disclosure","Clear statement that content is paid, gifted or sponsored, such as #ad."],["Deliverables","Agreed content items, formats, dates and usage rights."],["Usage rights","Permission for [Company] to reuse creator content and for how long."]],"roles":[["Partnerships Manager","Finds, vets and manages influencers and partners."],["Brand Manager","Reviews content for brand fit before posting."],["Legal Reviewer","Approves contracts and disclosure terms."],["Finance","Pays invoices against delivered work."],["Head of Marketing","Approves budget and partner selection over [threshold]."]],"prereqs":["Campaign brief with goal, budget and audience","Influencer and partner contract template","Disclosure guidelines for relevant markets","Tracking links or discount codes"],"steps":[{"t":"Define the brief","d":"Set goal, audience, budget, deliverables, timeline and success metrics before outreach.","o":"Partnerships Manager"},{"t":"Shortlist and vet","d":"Check audience fit, real engagement, past content and brand safety, and screen for fake followers and controversial history.","o":"Partnerships Manager"},{"t":"Approve selection","d":"Approve partners and fees, with Head of Marketing sign-off for any deal over [threshold].","o":"Head of Marketing"},{"t":"Agree contract","d":"Sign a contract covering deliverables, dates, fees, disclosure, usage rights, approval rights, exclusivity and termination before any work starts.","o":"Legal Reviewer"},{"t":"Share the creative brief","d":"Send key messages, do's and don'ts, mandatory disclosure and tracking links or codes.","o":"Partnerships Manager"},{"t":"Review content before posting","d":"Check draft content for accuracy, claims and visible disclosure within 2 business days of receipt.","o":"Brand Manager"},{"t":"Monitor live content","d":"Confirm posts went live as agreed with disclosure, and capture screenshots and links.","o":"Partnerships Manager"},{"t":"Pay against delivery","d":"Pay invoices only after deliverables are verified, within agreed payment terms.","o":"Finance"},{"t":"Measure and review","d":"Report reach, engagement, clicks, code use and conversions within 14 days and rate the partner for future work.","o":"Partnerships Manager"}],"checks":["Signed contract before any content is produced","Disclosure visible on every sponsored post","Payments matched to verified deliverables","Partner vetting record kept on file"],"kpis":[["Cost per acquisition via partners","At or below [target]"],["Disclosure compliance","100% of sponsored posts"],["On-time delivery","90% of deliverables on agreed dates"]],"risks":[["Undisclosed sponsorship","Contract clause, pre-posting review and live checks; check local advertising rules"],["Partner reputational issue","Vetting, morality clause and right to remove content"],["Paying for undelivered work","Payment on verified delivery or staged payments"],["Fake followers","Audience quality checks with [tool]"]],"related":["Brand Asset and Copy Approval","Vendor and Agency Management","Social Media Posting and Moderation","Contract Approval Policy"],"review":"Every 12 months, or after a change in advertising disclosure rules"},{"id":"support-ticket-triage","dept":"support","title":"Support Ticket Triage","summary":"Categorises, prioritises and routes every new support ticket so urgent issues get handled first.","tags":["ticket triage","helpdesk","priority","sla","routing","customer support"],"purpose":"To make sure every incoming request is read, classified and assigned quickly and consistently. Correct priority means critical problems are fixed first and SLAs are met.","scope":"Covers all tickets arriving by email, web form, chat transcripts and social handoff in [helpdesk tool]. It does not cover sales enquiries, which are routed to sales, or internal IT requests.","definitions":[["P1 Urgent","Service down or data loss for a customer, or a security issue. First response within 1 hour."],["P2 High","Major feature broken with no workaround. First response within 4 business hours."],["P3 Normal","Question or issue with a workaround. First response within 1 business day."],["P4 Low","Feedback, feature request or how-to. First response within 2 business days."]],"roles":[["Triage Agent","Reviews new tickets, sets category and priority, and assigns."],["Support Agent","Works assigned tickets to resolution."],["Support Lead","Sets the rota, monitors queue health and handles disputes on priority."],["On-call Engineer","Receives P1 technical issues out of hours."]],"prereqs":["[Helpdesk tool] with categories, priorities and SLA timers configured","Priority matrix and routing rules","Triage rota","Saved replies for acknowledgement"],"steps":[{"t":"Monitor the new queue","d":"Check unassigned tickets at least every 30 minutes during business hours. Aim for every ticket triaged within 1 hour of arrival.","o":"Triage Agent"},{"t":"Identify the customer","d":"Match the ticket to the customer account, plan and any VIP or at-risk flag, and merge duplicates.","o":"Triage Agent"},{"t":"Categorise","d":"Tag product area and type such as bug, how-to, billing, account access or feature request.","o":"Triage Agent"},{"t":"Set priority","d":"Use the priority matrix based on impact and urgency. Raise priority one level for enterprise plans or customers flagged at risk.","o":"Triage Agent"},{"t":"Escalate P1 immediately","d":"For P1, alert the on-call engineer and Support Lead in [incident channel] within 15 minutes and follow Ticket Escalation.","o":"Triage Agent"},{"t":"Route to the right queue","d":"Assign billing to billing, sales to sales, and technical issues to the matching skill group, balancing workload.","o":"Triage Agent"},{"t":"Acknowledge the customer","d":"Send acknowledgement with ticket number and expected response time if automation has not done so.","o":"Triage Agent"},{"t":"Close spam and non-actionable","d":"Close spam and auto-replies with the correct tag, and never delete tickets.","o":"Triage Agent"},{"t":"Review queue health","d":"Twice daily, check SLA breaches, aged tickets and mis-triaged items and rebalance assignments.","o":"Support Lead"},{"t":"Audit triage quality","d":"Weekly, sample 20 tickets for correct category and priority, and coach agents on errors.","o":"Support Lead"}],"checks":["No ticket unassigned for more than 1 business hour","P1 tickets have an incident alert logged","Weekly triage sample audited","Priority changes include a reason"],"kpis":[["Time to triage","95% within 1 business hour"],["First response SLA","95% met across priorities"],["Triage accuracy","90% correct in weekly sample"],["Reassignment rate","Below 10% of tickets"]],"risks":[["Urgent issue missed in queue","Keyword alerts for words like 'down' and 'security' and 30-minute checks"],["Priority inflation","Clear matrix and weekly audit"],["Out-of-hours P1 ignored","On-call rota and paging integration"]],"related":["Ticket Escalation","Live Chat and Phone Support","Service Outage Customer Communication","Support SLA Policy"],"review":"Every 12 months, or after a change in support tooling or SLAs"},{"id":"support-ticket-escalation","dept":"support","title":"Ticket Escalation","summary":"Moves tickets to senior support, engineering or management at the right time with full context and clear ownership.","tags":["escalation","tier 2","engineering handoff","bug report","sla breach","support"],"purpose":"To get complex, urgent or high-risk issues to the right people quickly without losing context. It keeps the customer informed and one owner accountable throughout.","scope":"Covers functional escalations (Tier 1 to Tier 2 to engineering) and hierarchical escalations (to management) for customer tickets. It does not cover major service outages, which follow the incident and outage SOPs.","definitions":[["Functional escalation","Moving a ticket to a team with more technical skill."],["Hierarchical escalation","Raising a ticket to a manager due to risk, value or dissatisfaction."],["Escalation note","Structured summary: issue, impact, steps to reproduce, what was tried, customer expectation."]],"roles":[["Tier 1 Agent","Raises the escalation with a complete note and stays the customer contact."],["Tier 2 Specialist","Investigates advanced issues and reproduces bugs."],["Engineering Liaison","Accepts bugs into the engineering backlog and gives estimates."],["Support Lead","Approves hierarchical escalations and monitors open escalations."],["Account Manager","Joins for key accounts and commercial issues."]],"prereqs":["Escalation note template in [helpdesk tool]","Link between helpdesk and [issue tracker]","Escalation criteria and contact list","Access to logs or admin tools for Tier 2"],"steps":[{"t":"Check escalation criteria","d":"Escalate if the issue is beyond Tier 1 knowledge, unresolved after [2] hours of work, a suspected bug, a security or data concern, or the customer asks for a manager.","o":"Tier 1 Agent"},{"t":"Write the escalation note","d":"Complete the template with steps to reproduce, screenshots, account ID, impact and what has been tried. Incomplete notes are returned.","o":"Tier 1 Agent"},{"t":"Tell the customer","d":"Explain that a specialist is reviewing and when the next update will come. Do not promise a fix date.","o":"Tier 1 Agent"},{"t":"Accept and investigate","d":"Accept within 4 business hours for P2 and 1 hour for P1, then investigate and reproduce.","o":"Tier 2 Specialist"},{"t":"Raise a bug if confirmed","d":"Create an issue in [issue tracker] linked to the ticket with severity, reproduction steps and affected customers count.","o":"Tier 2 Specialist"},{"t":"Triage the bug","d":"Confirm severity, assign to a team and give a target fix window within 2 business days, or 4 hours for P1.","o":"Engineering Liaison"},{"t":"Update the customer regularly","d":"Update at least every 24 hours for P1 and every 3 business days for P2, even when there is no news.","o":"Tier 1 Agent"},{"t":"Handle hierarchical escalations","d":"For complaints, legal threats or key accounts, inform the Support Lead and Account Manager within 1 business hour.","o":"Support Lead"},{"t":"Resolve and confirm","d":"Confirm the fix with the customer, close the ticket and link the release note.","o":"Tier 1 Agent"},{"t":"Review open escalations weekly","d":"Review all open escalations by age and value and unblock any older than 10 business days.","o":"Support Lead"}],"checks":["Every escalation has a complete note","Every confirmed bug is linked to its tickets","Customer update cadence met","Weekly escalation review recorded"],"kpis":[["Escalation rate","Below [15]% of tickets"],["Escalation acceptance time","95% within target"],["Update cadence compliance","95%"],["Escalations older than 10 days","Fewer than [5]"]],"risks":[["Context lost between teams","Mandatory template and linked records"],["Customer left without updates","Update reminders in helpdesk"],["Over-escalation of simple tickets","Coaching and knowledge base gaps logged"]],"related":["Support Ticket Triage","Customer Complaint Handling","Knowledge Base Article Updates","Incident Management"],"review":"Every 12 months, or after a change in team structure"},{"id":"support-refunds-returns","dept":"support","title":"Refunds and Returns","summary":"Handles refund and return requests fairly and consistently with clear eligibility checks and approval limits.","tags":["refund","returns","rma","chargeback","credit note","cancellation"],"purpose":"To process refunds and returns quickly and fairly while protecting [Company] from fraud and errors. It makes decisions consistent with the published refund policy.","scope":"Covers refunds for subscriptions and services and returns of physical goods requested by customers. It does not cover chargebacks already raised with a card issuer, which go to Finance, or supplier returns.","definitions":[["RMA","Return merchandise authorisation number issued before goods are sent back."],["Goodwill refund","A refund outside policy approved as an exception."],["Pro-rata refund","Refund for the unused part of a subscription period."]],"roles":[["Support Agent","Receives requests, checks eligibility and processes refunds within their limit."],["Support Lead","Approves refunds above the agent limit and goodwill exceptions."],["Finance","Approves refunds above [finance limit], reconciles and handles chargebacks."],["Warehouse Operative","Receives, inspects and restocks returned goods."]],"prereqs":["Published refund and returns policy","Access to [billing or payment system] with refund permissions by limit","Return label or RMA process","Refund log"],"steps":[{"t":"Log the request","d":"Record order or invoice number, reason code and requested amount in the ticket.","o":"Support Agent"},{"t":"Check eligibility","d":"Check the request against policy: time window, usage, condition of goods and previous refunds on the account.","o":"Support Agent"},{"t":"Try to resolve first","d":"Where the cause is a fixable issue, offer a fix or replacement, but never block a refund the customer is entitled to under policy or law.","o":"Support Agent"},{"t":"Get approval by limit","d":"Agents approve up to [agent limit], Support Lead up to [lead limit], Finance above that. Goodwill exceptions always need Support Lead approval.","o":"Support Lead"},{"t":"Issue RMA for physical goods","d":"Send the RMA number, return address and label with packing instructions within 1 business day.","o":"Support Agent"},{"t":"Inspect returned goods","d":"Inspect within 2 business days of receipt, record condition and photos, and restock, refurbish or write off.","o":"Warehouse Operative"},{"t":"Process the refund","d":"Refund to the original payment method within [5] business days of approval or receipt of goods.","o":"Support Agent"},{"t":"Confirm to customer","d":"Send confirmation with amount, method and expected bank timing, and close the ticket with a reason code.","o":"Support Agent"},{"t":"Reconcile monthly","d":"Match refunds in the payment system to the refund log and accounting records and investigate differences.","o":"Finance"},{"t":"Review reasons","d":"Monthly, report refund volume and top reasons to product and operations for root-cause fixes.","o":"Support Lead"}],"checks":["Every refund above agent limit has recorded approval","Refunds go only to the original payment method","Returned goods inspected before refund where policy requires","Monthly reconciliation signed off"],"kpis":[["Refund processing time","95% within 5 business days of approval"],["Refund rate","Below [x]% of revenue"],["Reconciliation errors","Zero unexplained differences"],["Chargeback rate","Below [0.5]% of transactions"]],"risks":[["Refund fraud or abuse","Account history check and approval limits"],["Refund to wrong account","Original payment method only and no manual bank details by email"],["Non-compliance with consumer law","Policy aligned with local consumer rights; check local law"]],"related":["Refund and Returns Policy","Customer Complaint Handling","Accounts Receivable and Credit Notes","Chargeback Handling"],"review":"Every 12 months, or after a policy or pricing change"},{"id":"support-customer-complaint-handling","dept":"support","title":"Customer Complaint Handling","summary":"Logs, investigates and resolves formal customer complaints fairly and on time, and feeds lessons back into the business.","tags":["complaints","customer dissatisfaction","grievance","service recovery","resolution","iso 10002"],"purpose":"To treat complaints as a chance to recover the relationship and improve the business. Every complaint should be acknowledged, investigated fairly, answered on time and analysed for root causes.","scope":"Covers expressions of dissatisfaction about products, service, staff or billing received through any channel. It does not cover simple support questions or legal claims already handled by lawyers.","definitions":[["Complaint","Any expression of dissatisfaction where a response or resolution is expected."],["Complaint register","Log of all complaints with dates, category, owner and outcome."],["Root cause","The underlying reason the problem happened, not just the symptom."]],"roles":[["Support Agent","Recognises, logs and acknowledges complaints."],["Complaint Owner","Investigates and responds; usually a senior agent or Support Lead."],["Support Lead","Assigns owners, approves remedies and reviews trends."],["Department Head","Provides input and fixes root causes in their area."]],"prereqs":["Complaints policy and published process for customers","Complaint register in [helpdesk tool] or spreadsheet","Remedy guidelines with approval limits","Response templates"],"steps":[{"t":"Recognise and log","d":"Log any complaint in the register on the same business day with channel, category and customer details, even if it was resolved on the spot.","o":"Support Agent"},{"t":"Acknowledge","d":"Acknowledge within 1 business day, thank the customer, name the owner and state when they will hear back.","o":"Support Agent"},{"t":"Assign an owner","d":"Assign an owner who was not involved in the original issue, within 1 business day.","o":"Support Lead"},{"t":"Investigate","d":"Review records, call logs and orders, talk to staff involved and, if needed, the customer, and record findings.","o":"Complaint Owner"},{"t":"Agree the remedy","d":"Choose a fair remedy such as fix, apology, credit or refund within guidelines, and get approval above [limit].","o":"Support Lead"},{"t":"Respond in writing","d":"Send a clear written response within 10 business days explaining findings, remedy and next steps. If it will take longer, update the customer with a new date.","o":"Complaint Owner"},{"t":"Offer a further route","d":"If the customer is not satisfied, offer review by a manager and any external body that applies.","o":"Complaint Owner"},{"t":"Fix the root cause","d":"Raise an action with the relevant Department Head to prevent recurrence, with a due date.","o":"Department Head"},{"t":"Close and confirm","d":"Close in the register once the remedy is delivered and record whether the customer accepted it.","o":"Complaint Owner"},{"t":"Review trends monthly","d":"Report volumes, categories, response times and root-cause actions to management monthly.","o":"Support Lead"}],"checks":["All complaints are in the register, including those resolved immediately","Acknowledgement and response deadlines tracked","Remedies above limit have approval","Root-cause actions tracked to completion"],"kpis":[["Acknowledgement time","100% within 1 business day"],["Resolution time","90% within 10 business days"],["Repeat complaints on same issue","Falling quarter on quarter"],["Post-complaint satisfaction","[target]% satisfied with handling"]],"risks":[["Complaint escalates publicly","Fast acknowledgement and empathetic response"],["Inconsistent remedies","Remedy guidelines and approval limits"],["Same problems recur","Root-cause action tracking"]],"related":["Ticket Escalation","Refunds and Returns","Customer Feedback and NPS Loop","Complaints Policy"],"review":"Every 12 months, or after a regulatory complaint or serious incident"},{"id":"support-new-customer-onboarding","dept":"support","title":"New Customer Onboarding","summary":"Guides new customers from signed contract to first value with a structured kickoff, setup plan and success check.","tags":["customer onboarding","implementation","kickoff","time to value","customer success","activation"],"purpose":"To help new customers set up correctly and reach their first meaningful result quickly. Good onboarding reduces early churn and support load.","scope":"Covers onboarding of new paying customers on [plans] from contract signature to the 90-day check. It does not cover self-serve free trials, which are handled by in-product onboarding.","definitions":[["Time to value","Days from signature to the customer's first agreed success milestone."],["Success plan","Shared document with goals, milestones, owners and dates."],["Handoff note","Sales summary of customer goals, stakeholders and commitments made."]],"roles":[["Customer Success Manager","Leads onboarding, owns the success plan and the relationship."],["Account Executive","Provides the sales handoff and attends kickoff."],["Implementation Specialist","Handles technical setup, integrations and data import."],["Customer Champion","Customer's lead contact who drives adoption internally."]],"prereqs":["Signed contract and sales handoff note","Onboarding plan template and kickoff deck","Customer account provisioned","Training materials and help centre links"],"steps":[{"t":"Complete sales handoff","d":"Within 2 business days of signature, hand over goals, stakeholders, commitments and risks in a 30-minute call and written note.","o":"Account Executive"},{"t":"Send welcome email","d":"Within 1 business day of handoff, introduce yourself, share next steps and book the kickoff.","o":"Customer Success Manager"},{"t":"Run the kickoff","d":"Within 5 business days, confirm goals, success criteria, timeline, roles and data or integration needs.","o":"Customer Success Manager"},{"t":"Agree the success plan","d":"Share the success plan with milestones and dates and get the customer champion to agree it.","o":"Customer Champion"},{"t":"Complete technical setup","d":"Configure the account, integrations, user access and data import, and confirm each item with the customer.","o":"Implementation Specialist"},{"t":"Train users","d":"Run role-based training sessions and share recordings and help articles.","o":"Customer Success Manager"},{"t":"Track adoption","d":"Check usage weekly against milestones and reach out within 2 business days if a milestone slips.","o":"Customer Success Manager"},{"t":"Confirm first value","d":"Confirm when the first success milestone is reached and record time to value.","o":"Customer Success Manager"},{"t":"Hold the 90-day review","d":"Review results against goals, gather feedback and agree next goals. Move the account to ongoing success management.","o":"Customer Success Manager"},{"t":"Collect onboarding feedback","d":"Send a short onboarding survey at completion and log improvement ideas.","o":"Customer Success Manager"}],"checks":["Handoff note completed before kickoff","Success plan agreed in writing","Setup items confirmed by the customer","Time to value recorded for every account"],"kpis":[["Time to value","Median under [30] days"],["Onboarding completion","90% complete within [60] days"],["Onboarding satisfaction","[target] average score"],["90-day retention","[target]% of new accounts active"]],"risks":[["Sales overpromised","Handoff note records commitments and gaps are raised at kickoff"],["Customer champion leaves","Identify a backup contact at kickoff"],["Stalled setup","Weekly milestone checks and escalation to sponsor"]],"related":["At-risk Account and Churn Prevention","Knowledge Base Article Updates","Sales to Success Handoff","Customer Feedback and NPS Loop"],"review":"Every 12 months, or after a major product or pricing change"},{"id":"support-knowledge-base-updates","dept":"support","title":"Knowledge Base Article Updates","summary":"Creates, reviews and retires help centre articles so customers and agents always find accurate answers.","tags":["knowledge base","help centre","faq","self-service","documentation","help articles"],"purpose":"To keep the help centre accurate, easy to search and aligned with the current product. Good articles reduce ticket volume and speed up agents.","scope":"Covers public help centre articles and internal agent knowledge articles. It does not cover developer API documentation or legal policies.","definitions":[["Article owner","Person responsible for keeping a given article accurate."],["Content gap","A common question with no article, found from tickets or searches with no results."],["Stale article","An article not reviewed within [6] months or affected by a product change."]],"roles":[["Knowledge Manager","Owns the knowledge base structure, standards and review schedule."],["Support Agent","Flags gaps and errors and drafts articles."],["Product Manager","Notifies upcoming changes and checks technical accuracy."],["Editor","Edits for clarity, style and format before publishing."]],"prereqs":["Help centre platform such as [KB tool]","Article template and writing style guide","Release calendar from product","Search and ticket tag reports"],"steps":[{"t":"Identify needs","d":"Weekly, review top ticket tags, failed searches and agent flags to list new or updated articles needed.","o":"Knowledge Manager"},{"t":"Get release notice","d":"Share upcoming product changes at least 5 business days before release, listing affected articles.","o":"Product Manager"},{"t":"Draft the article","d":"Write using the template: clear title as a question or task, short steps, screenshots and expected result.","o":"Support Agent"},{"t":"Check accuracy","d":"Confirm steps against the live or staging product within 2 business days.","o":"Product Manager"},{"t":"Edit and format","d":"Edit for plain language, consistent terms, accessibility and alt text, and add tags and related links.","o":"Editor"},{"t":"Publish","d":"Publish on release day for product changes, or within 5 business days for gaps, and link from relevant macros.","o":"Knowledge Manager"},{"t":"Fix flagged errors","d":"Correct errors flagged by customers or agents within 2 business days, or within 1 business day if the error causes data loss or billing problems.","o":"Knowledge Manager"},{"t":"Review stale articles","d":"Each month, review articles past their review date and update, merge or archive them.","o":"Knowledge Manager"},{"t":"Measure usefulness","d":"Monthly, check views, helpful votes and ticket deflection and rewrite low-rated articles.","o":"Knowledge Manager"}],"checks":["Every article has an owner and review date","Product releases have matching article updates on release day","Screenshots match the current interface","Archived articles redirect to a replacement"],"kpis":[["Self-service ratio","[target]% of help centre visits without a ticket"],["Article helpfulness","[75]% positive votes"],["Stale articles","Fewer than 5% past review date"],["Error fix time","95% within 2 business days"]],"risks":[["Outdated articles cause wrong actions","Release-linked updates and review schedule"],["Duplicate or conflicting articles","Single owner per topic and search before creating"],["Internal information published publicly","Separate internal and public spaces and editor check"]],"related":["Product Launch Go-to-Market","Support Ticket Triage","Ticket Escalation","Writing Style Guide"],"review":"Every 12 months, or after a help centre platform change"},{"id":"support-churn-prevention","dept":"support","title":"At-risk Account and Churn Prevention","summary":"Spots accounts likely to cancel early and runs a structured save plan to keep them.","tags":["churn","retention","health score","at-risk","customer success","renewal","save plan"],"purpose":"To identify customers at risk of leaving early enough to act. A consistent save process improves retention and reveals why customers leave.","scope":"Covers paying accounts managed by customer success, from risk detection to save or exit. It does not cover involuntary churn from failed payments, which follows the dunning process.","definitions":[["Health score","Combined score from usage, support tickets, NPS, payment and engagement signals."],["At-risk account","An account with a health score below [threshold] or a direct churn signal."],["Save plan","Agreed actions and timeline to address the customer's concerns."],["Churn reason code","Standard category recorded for every cancellation."]],"roles":[["Customer Success Manager","Monitors health, runs save plans and records outcomes."],["Head of Customer Success","Approves commercial concessions and reviews at-risk list weekly."],["Account Executive","Joins for commercial discussions and renewals."],["Product Manager","Reviews product-related churn reasons and feedback."]],"prereqs":["Health score model in [CS platform or CRM]","At-risk playbook and concession limits","Renewal dates for all accounts","Cancellation survey"],"steps":[{"t":"Monitor health weekly","d":"Review health scores and risk signals each week: usage drop over 30%, champion leaving, low NPS, repeat P1 tickets or late payment.","o":"Customer Success Manager"},{"t":"Flag at-risk accounts","d":"Flag the account in [CRM] with reason and renewal date within 1 business day of the signal.","o":"Customer Success Manager"},{"t":"Contact the customer","d":"Reach out within 3 business days to understand their situation, using a call rather than email where possible.","o":"Customer Success Manager"},{"t":"Diagnose the root cause","d":"Classify the cause as product gap, poor adoption, budget, change of stakeholder, service issue or competitor.","o":"Customer Success Manager"},{"t":"Agree a save plan","d":"Agree actions with the customer, such as retraining, a technical fix, executive call or plan change, with dates.","o":"Customer Success Manager"},{"t":"Approve concessions","d":"Approve any discount, credit or term change above [limit] and record it.","o":"Head of Customer Success"},{"t":"Review weekly","d":"Review all at-risk accounts by revenue and renewal date each week and assign help where needed.","o":"Head of Customer Success"},{"t":"Handle renewal","d":"Start renewal talks at least 90 days before renewal for at-risk accounts.","o":"Account Executive"},{"t":"Record the outcome","d":"Mark saved, downgraded or churned, with reason code, and run an exit survey for churned customers.","o":"Customer Success Manager"},{"t":"Share churn insights","d":"Quarterly, share churn reasons and revenue impact with product and leadership.","o":"Product Manager"}],"checks":["All at-risk accounts have an owner and save plan","Concessions are approved and recorded","Every churn has a reason code","Weekly at-risk review held"],"kpis":[["Gross revenue retention","[target]% annually"],["Save rate","[target]% of at-risk accounts retained"],["Time to contact","90% within 3 business days of flag"],["Logo churn","Below [x]% per month"]],"risks":[["Late detection","Automated alerts on health score drops"],["Discounting becomes default","Concession limits and approval"],["Same reasons repeat","Quarterly churn review with product"]],"related":["New Customer Onboarding","Customer Feedback and NPS Loop","Renewals Process","Failed Payment and Dunning"],"review":"Every 12 months, or after a change to the health score model"},{"id":"support-live-chat-phone","dept":"support","title":"Live Chat and Phone Support","summary":"Runs real-time chat and phone support with clear staffing, greeting, verification and wrap-up standards.","tags":["live chat","phone support","call centre","contact centre","real-time support","customer service"],"purpose":"To give customers fast, friendly and secure help over live channels. It sets standards for availability, identity checks, call handling and recording.","scope":"Covers inbound live chat and phone support during published hours. It does not cover outbound sales calls or email-only support.","definitions":[["ASA","Average speed of answer: average time a customer waits before an agent responds."],["AHT","Average handle time including talk and wrap-up."],["Identity verification","Checks to confirm the person is an authorised account user before sharing account details."],["Wrap-up","After-contact work: notes, tags and follow-ups."]],"roles":[["Support Agent","Handles chats and calls to standard."],["Shift Lead","Manages staffing, queue and live escalations during a shift."],["Workforce Planner","Forecasts volume and builds rotas."],["Quality Analyst","Scores sample interactions and coaches."]],"prereqs":["Chat and telephony tools integrated with [helpdesk tool]","Published support hours and out-of-hours message","Identity verification checklist","Call recording notice where recording is used"],"steps":[{"t":"Forecast and staff","d":"Build weekly rotas from forecast volume so that at least [80]% of chats are answered within 60 seconds and calls within [2] minutes.","o":"Workforce Planner"},{"t":"Start the shift","d":"Log in on time, check open handovers and known issues, and confirm status in the tool.","o":"Support Agent"},{"t":"Greet and identify","d":"Greet using the standard opening, get the customer's name and reason for contact.","o":"Support Agent"},{"t":"Verify identity","d":"Before discussing account details, verify using [2] approved factors. Never ask for full passwords or full card numbers.","o":"Support Agent"},{"t":"Resolve or route","d":"Resolve on the contact where possible. If not, create a ticket, set expectations and route using triage rules.","o":"Support Agent"},{"t":"Manage the queue live","d":"Monitor queue and wait times. If waits exceed target for 15 minutes, move agents from email or switch on callback and wait messages.","o":"Shift Lead"},{"t":"Handle difficult contacts","d":"Stay calm, acknowledge feelings and offer options. Agents may end abusive contacts after one warning and must log it.","o":"Support Agent"},{"t":"Wrap up","d":"Complete notes, tags and follow-ups within [2] minutes of the contact ending.","o":"Support Agent"},{"t":"Hand over at shift end","d":"Record open issues and pending callbacks in the handover log.","o":"Shift Lead"},{"t":"Review quality","d":"Score at least [4] interactions per agent per month and give feedback within 5 business days.","o":"Quality Analyst"}],"checks":["Identity verified before account details are shared","Call recording notice played where recording is used","Every contact has notes and tags","Shift handover log completed"],"kpis":[["Chat ASA","Under 60 seconds"],["Call answer rate","[90]% within [2] minutes"],["First contact resolution","[70]% or higher"],["CSAT","[90]% satisfied"],["Quality score","[85]% average"]],"risks":[["Social engineering","Strict identity verification and no exceptions under pressure"],["Long waits at peaks","Forecasting, callbacks and flexible staffing"],["Agent burnout","Breaks scheduled, abuse policy and wellbeing check-ins"],["Recording without notice","Notices and retention rules; check local law"]],"related":["Support Ticket Triage","Ticket Escalation","Customer Complaint Handling","Data Protection Policy"],"review":"Every 12 months, or after a change of telephony or chat tool"},{"id":"support-customer-feedback-nps-loop","dept":"support","title":"Customer Feedback and NPS Loop","summary":"Collects NPS and customer feedback, follows up with responders and turns themes into product and service actions.","tags":["nps","csat","customer feedback","voice of customer","surveys","close the loop"],"purpose":"To listen to customers in a structured way and act on what they say. Closing the loop with responders builds trust and gives product and leadership clear priorities.","scope":"Covers relationship NPS surveys, transactional CSAT surveys and feature feedback from all channels. It does not cover market research with non-customers.","definitions":[["NPS","Net Promoter Score: percentage of promoters (9 to 10) minus percentage of detractors (0 to 6)."],["CSAT","Customer satisfaction score after a specific interaction."],["Close the loop","Contacting a responder to thank them, learn more or explain what will happen."],["Feedback theme","A grouped topic across many pieces of feedback."]],"roles":[["Customer Insights Owner","Runs surveys, analyses feedback and reports themes."],["Customer Success Manager","Follows up with detractors and promoters on their accounts."],["Product Manager","Reviews themes and decides product actions."],["Head of Customer Success","Owns the programme and presents results to leadership."]],"prereqs":["Survey tool such as [survey tool] connected to [CRM]","Survey schedule and contact rules to avoid over-surveying","Feedback tagging taxonomy","Consent for contacting customers"],"steps":[{"t":"Plan the survey schedule","d":"Send relationship NPS every [6] months per contact and CSAT after resolved tickets, with no contact surveyed more than once in [30] days.","o":"Customer Insights Owner"},{"t":"Send the survey","d":"Send from a recognised sender with a short question set and an open comment box.","o":"Customer Insights Owner"},{"t":"Alert on detractors","d":"Route detractor and very low CSAT responses to the account owner automatically on the same day.","o":"Customer Insights Owner"},{"t":"Close the loop with detractors","d":"Contact detractors within 2 business days to understand and address their issue, and log the outcome.","o":"Customer Success Manager"},{"t":"Engage promoters","d":"Thank promoters within 5 business days and, where appropriate, invite them to reviews, case studies or referrals.","o":"Customer Success Manager"},{"t":"Tag and analyse feedback","d":"Tag all comments by theme weekly and quantify by volume and revenue affected.","o":"Customer Insights Owner"},{"t":"Review themes with product","d":"Monthly, present top themes and agree actions, owners and dates.","o":"Product Manager"},{"t":"Tell customers what changed","d":"Publish 'you asked, we did' updates in release notes or newsletters at least quarterly.","o":"Customer Insights Owner"},{"t":"Report to leadership","d":"Report NPS, CSAT, response rates, themes and actions quarterly.","o":"Head of Customer Success"}],"checks":["Detractors contacted within 2 business days","Survey frequency rules followed","All comments tagged","Actions from themes tracked to completion"],"kpis":[["NPS","[target] or improving quarter on quarter"],["Survey response rate","[20]% or higher"],["Detractor follow-up","100% within 2 business days"],["Actions completed","[75]% of agreed actions on time"]],"risks":[["Survey fatigue","Contact frequency rules and short surveys"],["Feedback collected but not acted on","Monthly product review and published updates"],["Score gaming by staff","Do not tie individual pay to scores alone and never ask for a particular score"]],"related":["Customer Complaint Handling","At-risk Account and Churn Prevention","Product Roadmap Process","New Customer Onboarding"],"review":"Every 12 months, or after a change of survey tool or method"},{"id":"support-service-outage-communication","dept":"support","title":"Service Outage Customer Communication","summary":"Keeps customers informed during outages and incidents with fast, honest, regular updates and a clear follow-up.","tags":["outage","incident communication","status page","downtime","service disruption","post-incident"],"purpose":"To keep customers informed quickly and honestly when the service is down or degraded. Clear updates reduce ticket volume, protect trust and support contractual obligations.","scope":"Covers customer-facing communication for unplanned outages, degraded performance, security incidents affecting service, and planned maintenance. Technical incident response is covered by the Incident Management SOP; regulated breach notices need legal input.","definitions":[["Status page","Public page showing current service status and incident updates."],["SEV1","Full outage or major function unavailable for most customers."],["SEV2","Partial outage or serious degradation for some customers."],["Post-incident report","Customer-facing summary of what happened, impact, cause and prevention."]],"roles":[["Incident Commander","Leads the technical response and confirms facts for updates."],["Communications Owner","Writes and publishes all customer updates during the incident."],["Support Lead","Manages ticket volume, macros and direct contact with key accounts."],["Account Manager","Calls key or contractually covered customers."],["Head of Customer Success","Approves the post-incident report and any service credits."]],"prereqs":["Status page tool such as [status page tool] with subscriber notifications","Pre-approved update templates for each severity","List of key accounts and SLA commitments","Incident channel in [chat tool]"],"steps":[{"t":"Confirm the incident","d":"Declare severity and assign a Communications Owner within 10 minutes of confirming a SEV1 or SEV2.","o":"Incident Commander"},{"t":"Post the first update","d":"Publish an 'investigating' notice on the status page within 15 minutes for SEV1 and 30 minutes for SEV2, using the template.","o":"Communications Owner"},{"t":"Prepare support","d":"Create a macro and banner for inbound tickets and tag related tickets to the incident so they can be updated in bulk.","o":"Support Lead"},{"t":"Contact key accounts","d":"Call or message key accounts and customers with SLA commitments within 1 hour for SEV1.","o":"Account Manager"},{"t":"Update on a fixed cadence","d":"Update at least every 30 minutes for SEV1 and every 60 minutes for SEV2, even if there is no new information. State facts only, no blame and no guessed fix times.","o":"Communications Owner"},{"t":"Announce resolution","d":"Post 'resolved' once the Incident Commander confirms recovery, and keep monitoring status for at least 1 hour.","o":"Communications Owner"},{"t":"Close related tickets","d":"Send a bulk update to tagged tickets and close them once confirmed, inviting customers to reply if still affected.","o":"Support Lead"},{"t":"Publish the post-incident report","d":"For SEV1, publish a summary of impact, timeline, root cause and prevention steps within 5 business days.","o":"Head of Customer Success"},{"t":"Apply service credits","d":"Calculate and apply SLA credits as per contract within the next billing cycle, proactively where possible.","o":"Head of Customer Success"},{"t":"Review communications","d":"In the incident review, assess timing and clarity of updates and update templates.","o":"Communications Owner"}],"checks":["First update posted within target time","Update cadence met throughout the incident","Key accounts contacted for SEV1","Post-incident report published for every SEV1","Legal consulted for incidents involving personal data"],"kpis":[["Time to first update","SEV1 within 15 minutes, SEV2 within 30 minutes"],["Update cadence compliance","100%"],["Post-incident report on time","100% within 5 business days"],["Incident-related ticket volume","Falling as status page subscribers grow"]],"risks":[["Silence or late updates","Pre-approved templates and named Communications Owner"],["Inaccurate statements","Only facts confirmed by the Incident Commander are published"],["Missed contractual or legal notice","Key accounts list with SLA terms and legal check for data incidents; check local law"],["Status page hosted on same infrastructure","Use an independent status page provider"]],"related":["Incident Management","Ticket Escalation","Press Release and Media Requests","Service Level Agreement Policy","Data Breach Response"],"review":"Every 12 months, or after every SEV1 incident"},{"id":"finance-customer-invoicing-billing","dept":"finance","title":"Customer Invoicing and Billing","summary":"Ensures every billable sale is invoiced accurately, on time and in the right format so cash arrives when expected.","tags":["invoicing","billing","accounts receivable","invoice","revenue","customer billing"],"purpose":"To make sure every delivered product or service is billed correctly and promptly. Accurate invoices reduce disputes, shorten payment times and keep revenue records reliable.","scope":"Covers one-off, milestone and recurring invoices issued to customers by [Company], including credit notes. It does not cover chasing overdue invoices, which is handled by the Collections and Overdue Invoices SOP.","definitions":[["Billing trigger","The event that makes an amount billable, such as delivery, milestone sign-off or subscription renewal date."],["Credit note","A document that reduces or cancels an amount already invoiced."],["Payment terms","The agreed number of days after the invoice date by which the customer must pay, e.g. Net 30."],["PO number","The customer's purchase order reference, which many customers require on the invoice before they will pay."]],"roles":[["Billing Specialist","Prepares, checks and sends invoices and credit notes."],["Account Owner","Confirms the billing trigger has occurred and resolves customer questions on scope."],["Finance Manager","Approves non-standard invoices, credit notes and changes to terms."],["Customer","Receives the invoice and confirms receipt where required."]],"prereqs":["Signed contract, order form or accepted quote with pricing and payment terms","Customer master record with legal name, billing address, tax ID and billing contact","Access to [accounting system] and invoice templates","Customer PO number where the customer requires one","Current tax rates for the customer's location"],"steps":[{"t":"Confirm the billing trigger","d":"Check that delivery, milestone acceptance or the renewal date has occurred and obtain written evidence such as a signed delivery note or acceptance email. Do this within 1 business day of the trigger.","o":"Account Owner"},{"t":"Verify customer master data","d":"Confirm legal entity name, billing address, tax ID and billing email in [accounting system] match the contract. Correct any mismatch before raising the invoice.","o":"Billing Specialist"},{"t":"Draft the invoice","d":"Create the invoice from the approved template with unique sequential number, invoice date, due date, line descriptions, quantities, unit prices and the customer PO number.","o":"Billing Specialist"},{"t":"Apply tax correctly","d":"Apply the tax rate for the customer's location and status, and record any exemption certificate or reverse-charge wording. Check local law if the customer is in a new jurisdiction.","o":"Billing Specialist"},{"t":"Reconcile to the contract","d":"Compare every line against the contract or order form. Any price, discount or term that differs requires Finance Manager approval before sending.","o":"Billing Specialist"},{"t":"Approve non-standard invoices","d":"Review and approve invoices above [amount, e.g. 10,000], invoices with manual discounts, and any first invoice to a new customer.","o":"Finance Manager"},{"t":"Send the invoice","d":"Send the invoice by the customer's required channel (email, portal or e-invoicing network) within 2 business days of the billing trigger. Attach supporting documents such as timesheets or delivery notes.","o":"Billing Specialist"},{"t":"Confirm receipt for large invoices","d":"For invoices above [amount] or customers using a supplier portal, confirm the invoice has been received and accepted into their payables queue within 5 business days.","o":"Account Owner"},{"t":"Record and post","d":"Ensure the invoice is posted to the correct revenue account, customer and period in [accounting system], and that deferred revenue is set up for amounts billed in advance.","o":"Billing Specialist"},{"t":"Handle corrections with credit notes","d":"Never edit or delete a sent invoice. Issue a credit note referencing the original invoice number, approved by the Finance Manager, then reissue if needed.","o":"Finance Manager"},{"t":"Run recurring billing check","d":"On the [day] of each month, compare the recurring billing run to the active contracts list so that new, upgraded, downgraded and cancelled customers are billed correctly.","o":"Billing Specialist"},{"t":"Archive records","d":"Store the invoice, supporting evidence and approvals in [document system] against the customer record for at least [retention period, check local law].","o":"Billing Specialist"}],"checks":["Invoice numbers are sequential with no gaps or duplicates","Every invoice has a matching billing trigger and contract reference","Credit notes above [amount] carry Finance Manager approval","Monthly list of uninvoiced delivered work is reviewed and cleared before close"],"kpis":[["Invoice timeliness","95% of invoices sent within 2 business days of billing trigger"],["Invoice accuracy","Fewer than 2% of invoices credited or reissued due to error"],["Days sales outstanding (DSO)","At or below [target, e.g. 40] days"],["Unbilled revenue at month-end","Below [amount or % of monthly revenue]"]],"risks":[["Delivered work never invoiced (revenue leakage)","Monthly reconciliation of delivery or usage records to invoices raised"],["Incorrect tax charged","Tax rate table reviewed quarterly and new jurisdictions checked with an adviser"],["Invoice rejected for missing PO number","PO number is a mandatory field for customers flagged as PO-required"],["Fraudulent change of company bank details on invoices","Bank details locked in template; any change approved by two finance signatories"]],"related":["Collections and Overdue Invoices","Month-end Close","Sales Tax and GST/VAT Filing","Customer Credit Policy"],"review":"Every 12 months, or after a change to accounting system, pricing model or tax registration"},{"id":"finance-accounts-payable-supplier-payments","dept":"finance","title":"Accounts Payable and Supplier Payments","summary":"Pays only valid, approved supplier invoices, accurately and on time, with controls that stop duplicate and fraudulent payments.","tags":["accounts payable","ap","supplier payments","vendor invoices","payment run","three-way match"],"purpose":"To process supplier invoices from receipt to payment in a controlled way. It protects cash, keeps suppliers paid on agreed terms and prevents duplicate, unauthorised or fraudulent payments.","scope":"Covers all supplier invoices and payments made by bank transfer, card or direct debit by [Company]. It does not cover payroll, employee expenses or petty cash, which have their own SOPs.","definitions":[["Three-way match","Checking that the purchase order, goods or service receipt and supplier invoice agree on item, quantity and price."],["Payment run","A scheduled batch of approved supplier payments released together."],["Supplier master file","The approved record of each supplier's legal details, tax ID and bank account."],["Tolerance","The allowed difference between PO and invoice values before an exception is raised."]],"roles":[["AP Clerk","Receives, codes, matches and schedules invoices for payment."],["Budget Holder","Confirms goods or services were received and approves invoices without a PO."],["Finance Manager","Reviews and approves the payment run and resolves exceptions."],["Payment Authoriser","Second signatory who releases payments in the banking platform."]],"prereqs":["Approved supplier record in [accounting system] with verified bank details","Purchase order for PO-backed spend","Goods received note or service confirmation","Access to [AP inbox] and [banking platform] with dual authorisation enabled","Current Spend Approval Limits matrix"],"steps":[{"t":"Receive invoices centrally","d":"Require all suppliers to send invoices to [AP inbox] only. Log each invoice in [accounting system] within 1 business day of receipt, rejecting any addressed to the wrong legal entity.","o":"AP Clerk"},{"t":"Check for duplicates","d":"Search by supplier, invoice number, date and amount before entering. Flag any invoice that matches an existing record on two or more fields.","o":"AP Clerk"},{"t":"Perform three-way match","d":"Match the invoice to the PO and goods received note. Differences within tolerance of [e.g. 2% or 100] may proceed; anything larger goes to the Budget Holder as an exception.","o":"AP Clerk"},{"t":"Approve non-PO invoices","d":"For invoices without a PO, route to the Budget Holder for approval within 3 business days, following the Spend Approval Limits matrix.","o":"Budget Holder"},{"t":"Code the invoice","d":"Assign the general ledger account, cost centre, tax code and accounting period. Prepayments above [amount] are coded to the balance sheet and released over the service period.","o":"AP Clerk"},{"t":"Verify bank detail changes","d":"Treat any request to change supplier bank details as high risk. Call the supplier on a phone number already held on file, not one in the request, and record the call before updating.","o":"Finance Manager"},{"t":"Prepare the payment run","d":"Every [day of week], select approved invoices due before the next run, taking early-payment discounts where worthwhile. Produce a payment proposal report.","o":"AP Clerk"},{"t":"Review the payment proposal","d":"Review the proposal for unusual payees, round amounts, new suppliers and changed bank details. Approve or remove items and sign the report.","o":"Finance Manager"},{"t":"Release payments with dual authorisation","d":"Upload the approved batch to [banking platform]. A second authoriser who did not prepare the batch releases it. Payments above [amount] require two senior signatories.","o":"Payment Authoriser"},{"t":"Send remittance advice","d":"Send remittance advice to suppliers on the day of payment, listing invoices paid, so they can allocate cash correctly.","o":"AP Clerk"},{"t":"Reconcile supplier statements","d":"Monthly, reconcile statements from the top [e.g. 20] suppliers by spend to the AP ledger and investigate differences within 5 business days.","o":"AP Clerk"},{"t":"File and retain","d":"Attach invoice, PO, receipt evidence and approval trail to the transaction and retain for [retention period, check local law].","o":"AP Clerk"}],"checks":["No individual can both create a supplier and approve its payment","Every payment run is approved by someone other than the preparer","Bank detail changes have a recorded call-back verification","Aged payables report reviewed monthly for disputed or stuck invoices"],"kpis":[["On-time payment","95% of invoices paid within agreed terms"],["Invoice processing time","Median under 5 business days from receipt to approval"],["Duplicate payments","Zero per quarter"],["Touchless match rate","At least [e.g. 70%] of PO invoices auto-matched"]],"risks":[["Invoice or bank-detail fraud","Call-back verification on a known number and dual authorisation of payments"],["Duplicate payment","System duplicate check plus manual review of the payment proposal"],["Late payment damaging supplier relationships","Weekly runs and aged payables review"],["Paying for goods not received","Three-way match and Budget Holder confirmation"]],"related":["Purchase Requests and Purchase Orders","Vendor Onboarding and Due Diligence","Spend Approval Limits","Month-end Close"],"review":"Every 12 months, or after any payment fraud attempt or banking platform change"},{"id":"finance-collections-overdue-invoices","dept":"finance","title":"Collections and Overdue Invoices","summary":"Gives a firm, polite and escalating routine for collecting overdue customer invoices while protecting the relationship.","tags":["collections","overdue invoices","debt recovery","dunning","credit control","accounts receivable"],"purpose":"To turn overdue receivables into cash quickly and consistently. A clear escalation path reduces bad debt and avoids ad hoc, inconsistent chasing.","scope":"Covers all customer invoices past their due date, from first reminder to referral to an external agency or write-off. It does not cover issuing invoices or setting credit limits for new customers.","definitions":[["Dunning","A structured sequence of reminders sent as an invoice becomes more overdue."],["Aged receivables report","A report grouping unpaid invoices by days overdue, e.g. 1-30, 31-60, 61-90, 90+."],["Payment plan","A written agreement letting a customer clear a balance in instalments."],["Bad debt provision","An accounting allowance for receivables unlikely to be collected."]],"roles":[["Credit Controller","Runs the reminder schedule, logs contact and agrees promises to pay."],["Account Owner","Uses the customer relationship to resolve disputes and unblock payment."],["Finance Manager","Approves payment plans, service holds, agency referral and write-offs."],["Founder or CEO","Approves legal action and write-offs above [amount]."]],"prereqs":["Up-to-date aged receivables report from [accounting system]","Customer contacts for accounts payable, not only the project contact","Signed contract showing payment terms and late payment clause","Reminder email templates for each stage","Collections log in [CRM or spreadsheet]"],"steps":[{"t":"Send a pre-due reminder","d":"For invoices above [amount], send a friendly reminder 5 days before the due date confirming the amount, due date and payment details.","o":"Credit Controller"},{"t":"Send the first overdue reminder","d":"On day 1 overdue, email the customer's AP contact with a copy of the invoice and ask for an expected payment date.","o":"Credit Controller"},{"t":"Call at 7 days overdue","d":"Phone the AP contact, ask whether the invoice is approved and when it is scheduled for payment, and record the promise to pay with a date.","o":"Credit Controller"},{"t":"Resolve disputes quickly","d":"If the customer raises a dispute, log the reason and pass it to the Account Owner, who must respond within 3 business days. Pursue the undisputed part separately.","o":"Account Owner"},{"t":"Escalate at 15 days overdue","d":"Send a formal reminder copying the customer's budget holder, noting the contractual late payment terms. Inform the Account Owner.","o":"Credit Controller"},{"t":"Agree a payment plan where justified","d":"If the customer cannot pay in full, agree a written plan with dates and amounts. Plans longer than [e.g. 3 months] need Finance Manager approval.","o":"Finance Manager"},{"t":"Place account on hold at 30 days","d":"With Finance Manager approval and notice to the Account Owner, pause new orders or service changes, giving the customer 5 business days' written notice where the contract allows.","o":"Finance Manager"},{"t":"Issue a final notice at 45 days","d":"Send a final written demand stating the amount, interest or fees where contractually allowed, and the date after which the debt will be referred externally.","o":"Credit Controller"},{"t":"Refer to agency or legal at 60 days","d":"Decide whether to refer to a collection agency or solicitor, weighing amount, cost and relationship. Check local law on debt recovery procedures.","o":"Founder or CEO"},{"t":"Review the bad debt provision","d":"At each month-end, provide for invoices over 90 days or with known customer insolvency, and propose write-offs for approval.","o":"Finance Manager"},{"t":"Report weekly","d":"Share a weekly overdue summary with the top 10 overdue accounts, promises to pay and actions, with Account Owners and leadership.","o":"Credit Controller"}],"checks":["Every overdue invoice has a logged contact within the last 7 days","Promises to pay are followed up the day after the promised date","Service holds and write-offs carry documented approval","Disputes are tracked to closure with root cause recorded"],"kpis":[["Days sales outstanding (DSO)","At or below [target] days"],["Overdue over 60 days","Less than 5% of total receivables"],["Promise-to-pay kept rate","At least 80%"],["Bad debt write-off","Below [e.g. 0.5%] of annual revenue"]],"risks":[["Damaging a key customer relationship","Account Owner involved from day 15 and tone set by approved templates"],["Chasing the wrong contact","Maintain AP contact separately from project contact"],["Unlawful collection practice","Use only contractual remedies and check local law before charging interest or referring"],["Disputes left unresolved","3-business-day response target and weekly dispute review"]],"related":["Customer Invoicing and Billing","Customer Credit Policy","Month-end Close","Payment Plan Agreement Form"],"review":"Every 12 months, or when DSO exceeds target for two consecutive months"},{"id":"finance-month-end-close","dept":"finance","title":"Month-end Close","summary":"Closes the books within a set number of working days with reconciled balances and reliable management accounts.","tags":["month end","financial close","management accounts","reconciliation","accruals","reporting"],"purpose":"To produce accurate, timely monthly financial statements that leadership can rely on for decisions. A fixed calendar and checklist make the close repeatable and auditable.","scope":"Covers the monthly close of all ledgers and entities of [Company], from cut-off to delivery of management accounts. Year-end statutory accounts and audit preparation follow an extended version of this process.","definitions":[["Working day (WD)","A business day counted from month-end, e.g. WD3 is the third working day of the new month."],["Accrual","An expense recorded in the month incurred even though the invoice has not yet arrived."],["Prepayment","An amount paid in advance and released to expense over the period it covers."],["Balance sheet reconciliation","Proving a ledger balance against independent evidence such as a bank statement or sub-ledger."]],"roles":[["Accountant","Posts journals, prepares reconciliations and drafts the accounts."],["Finance Manager","Owns the close calendar, reviews journals and reconciliations and signs off."],["Budget Holders","Confirm accruals, report unbilled work and explain variances."],["Founder or CEO","Reviews management accounts and approves for circulation."]],"prereqs":["Close calendar with WD deadlines for the year","Month-end checklist in [task tool or spreadsheet]","Bank statements and sub-ledger reports for the month","Payroll report and expense claims for the month","Prior month's reconciliations and budget for variance analysis"],"steps":[{"t":"Announce cut-off","d":"On WD-3, remind all teams that invoices, expense claims and sales orders must be submitted by the last day of the month to be included.","o":"Finance Manager"},{"t":"Close sub-ledgers","d":"On WD1, complete sales invoicing, post all supplier invoices received and approve outstanding expense claims, then lock AR and AP for the period.","o":"Accountant"},{"t":"Reconcile bank and cash","d":"By WD2, reconcile every bank, card and payment-provider account to statements, with all reconciling items explained.","o":"Accountant"},{"t":"Post payroll journals","d":"By WD2, post payroll, employer taxes and pension costs from the payroll report and reconcile liabilities to the payroll provider.","o":"Accountant"},{"t":"Collect and post accruals","d":"By WD2, ask Budget Holders for goods and services received but not invoiced above [amount], then post accruals with supporting notes.","o":"Budget Holders"},{"t":"Post prepayments, depreciation and deferrals","d":"By WD3, release prepayments, run depreciation and adjust deferred revenue using the schedules, keeping each schedule tied to the ledger.","o":"Accountant"},{"t":"Reconcile balance sheet accounts","d":"By WD4, reconcile every balance sheet account above [materiality, e.g. 1,000]. Items older than 60 days are escalated.","o":"Accountant"},{"t":"Review journals","d":"Review all manual journals above [amount] for support and approval. No one approves their own journal.","o":"Finance Manager"},{"t":"Analyse variances","d":"Compare actuals to budget and last month. Obtain explanations from Budget Holders for variances above [e.g. 10% and 2,000] within 1 working day.","o":"Finance Manager"},{"t":"Prepare management accounts","d":"By WD5, produce profit and loss, balance sheet, cash flow, cash runway and KPI pack with commentary.","o":"Accountant"},{"t":"Sign off and lock the period","d":"Finance Manager signs off the checklist and reconciliations, then locks the period in [accounting system] to prevent back-posting.","o":"Finance Manager"},{"t":"Present and run a retrospective","d":"Present the pack to leadership by WD6. Record any delays or errors and agree one improvement for next month.","o":"Founder or CEO"}],"checks":["Every balance sheet account has a signed reconciliation","Suspense and clearing accounts are zero or fully explained","Period is locked after sign-off","Revenue cut-off tested against delivery records for the last 3 days of the month"],"kpis":[["Days to close","Management accounts delivered by WD[5]"],["Post-close adjustments","Zero material adjustments after sign-off"],["Reconciliation completion","100% of balance sheet accounts reconciled by WD4"],["Unexplained variance items","None above materiality"]],"risks":[["Late or missing accruals understate costs","Accrual request to Budget Holders with nil-return required"],["Errors hidden in manual journals","Independent review of journals above threshold"],["Back-dated postings change reported results","Period lock with restricted override rights"],["Key-person dependency","Documented checklist and cross-training of a second preparer"]],"related":["Bank Reconciliation","Accounts Payable and Supplier Payments","Payroll Processing","Annual Budget and Rolling Forecast"],"review":"Every 12 months, or after a missed close deadline or change of accounting system"},{"id":"finance-employee-expense-reimbursement","dept":"finance","title":"Employee Expense Reimbursement","summary":"Reimburses genuine business expenses quickly while keeping spending within policy and supported by valid receipts.","tags":["expenses","expense claims","reimbursement","receipts","travel expenses","out of pocket"],"purpose":"To reimburse employees fairly and promptly for business costs they pay personally. It also ensures claims are within policy, correctly coded and supported for tax purposes.","scope":"Covers out-of-pocket expenses and company card transactions for all employees and contractors with expense rights. It does not cover supplier invoices, petty cash or relocation packages, which follow separate processes.","definitions":[["Expense policy","The rules on what can be claimed, spending limits and required evidence."],["Valid receipt","An itemised receipt showing supplier, date, items, amount and tax, not only a card slip."],["Per diem","A fixed daily allowance for meals or incidentals where policy allows it."],["Taxable benefit","A reimbursed item that tax authorities treat as employee income; check local law."]],"roles":[["Claimant","Submits complete claims with receipts within the deadline."],["Line Manager","Approves claims for business purpose and policy compliance."],["Finance Reviewer","Checks receipts, coding and tax, and queries exceptions."],["Payroll or AP Lead","Pays approved claims in the scheduled run."]],"prereqs":["Published expense policy with limits per category","Account in [expense tool] for every eligible employee","Employee bank details verified in [HRIS or payroll]","Pre-approval for travel or single items above [amount]"],"steps":[{"t":"Capture receipts at the time of spend","d":"Photograph or forward the itemised receipt into [expense tool] within 7 days of the expense, noting the business purpose and attendees for meals.","o":"Claimant"},{"t":"Submit the claim","d":"Submit claims at least monthly and no later than [30] days after the expense. Claims older than [90] days are rejected unless the Finance Manager agrees.","o":"Claimant"},{"t":"Attach pre-approval where needed","d":"For travel, conferences or single items above [amount], attach the written pre-approval.","o":"Claimant"},{"t":"Approve for business purpose","d":"Review each line for genuine business purpose and policy limits within 3 business days. Managers cannot approve their own claims or those of their own manager.","o":"Line Manager"},{"t":"Check receipts and coding","d":"Confirm each receipt is valid and matches the amount, check category, cost centre and tax code, and verify mileage against a route planner.","o":"Finance Reviewer"},{"t":"Query or reject exceptions","d":"Return claims with missing receipts or out-of-policy items, stating the reason. Missing receipts above [amount] require a signed declaration.","o":"Finance Reviewer"},{"t":"Flag taxable items","d":"Identify items that may be taxable benefits, such as gifts or home office equipment, and pass them to payroll for reporting. Check local law.","o":"Finance Reviewer"},{"t":"Pay approved claims","d":"Pay approved claims in the next [weekly or fortnightly] reimbursement run, or through payroll, and notify the claimant.","o":"Payroll or AP Lead"},{"t":"Reconcile company cards","d":"Monthly, ensure every company card transaction has a receipt and approval. Unsupported spend after 30 days is recovered from the cardholder per policy.","o":"Finance Reviewer"},{"t":"Audit a sample","d":"Each quarter, audit a random 5% of claims plus all claims above [amount] for duplicates, split receipts and policy breaches.","o":"Finance Reviewer"}],"checks":["No self-approval of claims","Duplicate receipt detection enabled in [expense tool]","Quarterly sample audit completed and findings recorded","Card transactions without receipts escalated after 30 days"],"kpis":[["Reimbursement time","90% paid within 10 business days of submission"],["Policy compliance","At least 95% of claims approved without query"],["Card receipt match rate","98% of card transactions with receipts by month-end"]],"risks":[["Fraudulent or duplicate claims","Duplicate detection, receipt image checks and sample audits"],["Unreported taxable benefits","Finance flags taxable categories for payroll"],["Late claims distorting month-end costs","Submission deadline and month-end reminder"],["Staff out of pocket for long periods","Fixed payment run schedule and approval SLA"]],"related":["Expense Policy","Spend Approval Limits","Payroll Processing","Business Travel Policy"],"review":"Every 12 months, or after a change in tax rules on benefits or the expense tool"},{"id":"finance-payroll-processing","dept":"finance","title":"Payroll Processing","summary":"Pays every employee the right amount on the right day with correct deductions and filings, and no unauthorised changes.","tags":["payroll","salaries","wages","pay run","payslips","payroll taxes"],"purpose":"To run each payroll accurately, on time and in line with employment and tax law. It controls changes to pay data so that errors and fraud are caught before money leaves the bank.","scope":"Covers regular and off-cycle payroll for employees of [Company] in each country where it runs payroll, whether in-house or through a provider. Contractor payments are handled through Accounts Payable.","definitions":[["Pay cut-off","The last date changes can be included in the current pay run."],["Gross-to-net","The calculation from gross pay through tax and deductions to net pay."],["Payroll variance report","A comparison of this period's pay with last period, by employee."],["Off-cycle payment","A payment made outside the normal schedule, such as a correction or final pay."]],"roles":[["Payroll Administrator","Collects changes, processes the pay run and produces reports."],["HR Manager","Provides authorised starters, leavers and pay changes from [HRIS]."],["Finance Manager","Reviews the variance report and approves the pay run."],["Payment Authoriser","Releases net pay and tax payments as second signatory."]],"prereqs":["Payroll calendar with cut-off, approval and pay dates","Access to [payroll system or provider] and [HRIS]","Signed change forms for new starters, leavers and pay changes","Current tax codes, statutory rates and pension or benefit settings","Approved timesheets, overtime and commission schedules"],"steps":[{"t":"Collect authorised changes","d":"By cut-off, export starters, leavers, salary changes and benefit updates from [HRIS]. Each change must carry HR approval and, for pay rises, approval per the Spend Approval Limits.","o":"HR Manager"},{"t":"Collect variable pay","d":"By cut-off, obtain approved overtime, commission, bonuses and unpaid leave. Commission must be signed off by the Sales leader and Finance Manager.","o":"Payroll Administrator"},{"t":"Update the payroll system","d":"Enter changes in [payroll system] and keep the change log. Bank detail changes require verification directly with the employee through a known channel.","o":"Payroll Administrator"},{"t":"Run the draft payroll","d":"Run gross-to-net at least 5 business days before pay date and produce the payslip preview, variance report and payroll summary.","o":"Payroll Administrator"},{"t":"Investigate variances","d":"Explain every employee whose net pay changes by more than [e.g. 5% or 200] versus last period, and confirm starters and leavers are correct.","o":"Payroll Administrator"},{"t":"Review and approve","d":"Review the variance report, headcount reconciliation to [HRIS] and total cost against budget. Approve in writing at least 3 business days before pay date.","o":"Finance Manager"},{"t":"Fund and release net pay","d":"Ensure the payroll account is funded, then release the net pay file in [banking platform] with dual authorisation, allowing for bank processing times.","o":"Payment Authoriser"},{"t":"Distribute payslips","d":"Publish payslips through [payroll portal] on or before pay date. Never send payslips to personal email without encryption.","o":"Payroll Administrator"},{"t":"Pay and file statutory deductions","d":"Pay income tax, social security and pension contributions and submit required filings by the statutory deadlines. Check local law for each country.","o":"Payroll Administrator"},{"t":"Post payroll journals","d":"Send the payroll journal to finance and reconcile payroll liability accounts to zero after payments clear.","o":"Payroll Administrator"},{"t":"Handle errors with off-cycle runs","d":"If an underpayment is found, pay the difference within 2 business days via an approved off-cycle run. Recover overpayments only with written agreement and per local law.","o":"Finance Manager"}],"checks":["Headcount on payroll reconciles to [HRIS] active employees","No individual can both add an employee and approve the pay run","Bank detail changes have documented verification","Payroll liability accounts reconciled monthly"],"kpis":[["On-time pay","100% of employees paid on pay date"],["Payroll accuracy","Fewer than [1] correction per 100 payslips"],["Statutory filings","100% submitted by deadline, zero penalties"],["Approval lead time","Pay run approved at least 3 business days before pay date"]],"risks":[["Ghost employees or unauthorised pay changes","Segregation of duties and headcount reconciliation each run"],["Late tax payments and penalties","Payroll calendar with filing deadlines and reminders"],["Data breach of salary information","Restricted access, encrypted payslips and access reviews"],["Payroll provider failure","Documented provider escalation contacts and an emergency manual payment procedure"]],"related":["Month-end Close","Employee Onboarding","Employee Offboarding","Employee Expense Reimbursement"],"review":"Every 12 months, after any change of payroll provider, or when operating in a new country"},{"id":"finance-annual-budget-rolling-forecast","dept":"finance","title":"Annual Budget and Rolling Forecast","summary":"Builds an agreed annual budget and keeps a rolling forecast so leaders can see cash runway and adjust spending early.","tags":["budget","forecast","financial planning","fp&a","cash runway","rolling forecast"],"purpose":"To translate company goals into an agreed financial plan and keep it current. Regular reforecasting gives early warning on cash, hiring and revenue shortfalls.","scope":"Covers the annual budget cycle and the [monthly or quarterly] rolling forecast for all departments of [Company]. It does not cover fundraising models prepared for investors, although these should reconcile to the forecast.","definitions":[["Budget","The approved annual financial plan used as the baseline for performance."],["Rolling forecast","An updated projection that always looks [12 or 18] months ahead."],["Driver","An operational input that determines a financial number, e.g. headcount, conversion rate, average order value."],["Cash runway","The number of months the company can operate with current cash at the forecast burn rate."]],"roles":[["Finance Manager","Owns the model, timeline and consolidation."],["Department Heads","Submit headcount, spend and revenue drivers for their area."],["Founder or CEO","Sets targets and priorities and approves the final budget."],["Board","Reviews and approves the annual budget where required."]],"prereqs":["Strategic goals and targets for the year","Prior year actuals and current year-to-date results","Budget template and driver assumptions","Hiring plan and salary bands","Budget calendar with submission and review dates"],"steps":[{"t":"Set targets and guardrails","d":"At least [10] weeks before year start, agree revenue target, minimum cash runway (e.g. 18 months) and maximum burn with leadership.","o":"Founder or CEO"},{"t":"Issue templates and assumptions","d":"Send Department Heads the template with shared assumptions: salary inflation, benefits load, tax rates, exchange rates and price changes.","o":"Finance Manager"},{"t":"Build driver-based submissions","d":"Submit headcount by month, programme spend and revenue drivers with a short justification linked to goals, within 2 weeks of the request.","o":"Department Heads"},{"t":"Consolidate the first draft","d":"Combine submissions into profit and loss, cash flow and headcount views and compare against targets and runway guardrails.","o":"Finance Manager"},{"t":"Challenge and prioritise","d":"Hold review sessions with each department to cut or phase spend where the draft breaches guardrails, recording decisions.","o":"Founder or CEO"},{"t":"Model scenarios","d":"Prepare base, downside and upside cases, with a list of pre-agreed cost actions to trigger if the downside occurs.","o":"Finance Manager"},{"t":"Approve the budget","d":"Present the final budget to leadership and, where required, the Board for approval before the start of the year. Lock the approved version.","o":"Board"},{"t":"Load and communicate budgets","d":"Load approved budgets by cost centre into [accounting or planning tool] and give each Department Head their budget and spending authority.","o":"Finance Manager"},{"t":"Report actuals against budget monthly","d":"After each month-end close, share budget versus actual and forecast by department and request explanations for material variances.","o":"Finance Manager"},{"t":"Update the rolling forecast","d":"Each [month or quarter], update drivers with Department Heads, roll the forecast forward and recalculate cash runway.","o":"Department Heads"},{"t":"Trigger corrective actions","d":"If forecast runway falls below the agreed guardrail, convene leadership within 5 business days to apply pre-agreed cost or revenue actions.","o":"Founder or CEO"}],"checks":["Forecast cash flow reconciles to the opening bank balance","Headcount plan ties to the hiring plan and HR records","Each version of the budget and forecast is saved and dated","Key assumptions documented with owner and source"],"kpis":[["Forecast accuracy","Revenue and costs within 10% of actual for the next quarter"],["Budget delivered on time","Approved before the financial year starts"],["Variance explanations","100% of material variances explained within 5 working days of close"],["Cash runway","At or above [e.g. 18] months"]],"risks":[["Overly optimistic revenue assumptions","Scenario modelling and comparison to historic conversion rates"],["Budget ignored after approval","Monthly variance reviews with Department Heads"],["Model errors","Version control, peer review and check totals in the model"],["Cash shortfall found too late","Rolling 13-week cash forecast alongside the main forecast"]],"related":["Month-end Close","Spend Approval Limits","Headcount Planning and Hiring Approval","Board Reporting"],"review":"Every 12 months before the budget cycle starts, or after a funding event or major strategy change"},{"id":"finance-petty-cash","dept":"finance","title":"Petty Cash","summary":"Controls a small cash float for minor purchases so every amount is authorised, receipted and reconciled.","tags":["petty cash","cash float","imprest","cash handling","small purchases"],"purpose":"To allow small, urgent purchases in cash without losing control of the money. A fixed float with regular counts makes shortages visible quickly.","scope":"Covers petty cash floats held at any [Company] office, site or store. It does not cover customer cash takings, which follow the cash handling procedure, or employee expense claims.","definitions":[["Imprest system","A fixed float that is topped up only by the amount spent, so cash plus receipts always equals the float."],["Petty cash voucher","A form recording each payout, signed by the recipient and approver."],["Float","The set amount of cash held, e.g. [200]."],["Cash count","A physical count of cash and vouchers against the float."]],"roles":[["Petty Cash Custodian","Holds the key, makes payouts and keeps the log."],["Approver","Authorises payouts above [amount] and signs top-up requests."],["Finance Reviewer","Performs surprise counts and posts transactions."],["Employee","Requests cash and provides receipts and change."]],"prereqs":["Lockable cash box stored in a locked drawer or safe","Pre-numbered petty cash vouchers or a log in [system]","Approved float amount and list of permitted purchases","Named custodian and deputy"],"steps":[{"t":"Set the float","d":"Agree a float sized to about one month of typical spend, normally no more than [e.g. 200]. Record the float amount and custodian.","o":"Finance Reviewer"},{"t":"Request a payout","d":"The employee completes a voucher with date, amount, purpose and cost centre. Purchases above [amount, e.g. 50] are not paid from petty cash.","o":"Employee"},{"t":"Approve and pay","d":"The custodian checks the purchase is permitted, obtains approval for items above [amount, e.g. 25], pays out and has the employee sign.","o":"Petty Cash Custodian"},{"t":"Collect receipt and change","d":"Within 2 business days, the employee returns the itemised receipt and any change, which the custodian attaches to the voucher.","o":"Employee"},{"t":"Keep cash secure","d":"Lock the cash box after each transaction and store it in the safe out of hours. Only the custodian and deputy hold keys.","o":"Petty Cash Custodian"},{"t":"Count weekly","d":"Each week, count cash and add receipts. The total must equal the float. Record the count and sign it.","o":"Petty Cash Custodian"},{"t":"Request a top-up","d":"When cash falls below [e.g. 25%] of the float, submit the vouchers with a top-up request for the exact amount spent.","o":"Petty Cash Custodian"},{"t":"Approve and post the top-up","d":"Check vouchers and receipts, post expenses to the correct accounts and approve the top-up withdrawal.","o":"Approver"},{"t":"Perform surprise counts","d":"At least quarterly, carry out an unannounced count with the custodian present and record the result.","o":"Finance Reviewer"},{"t":"Investigate differences","d":"Report any shortage or surplus above [e.g. 5] to the Finance Manager the same day and record the outcome.","o":"Finance Reviewer"}],"checks":["Cash plus receipts equals the float at every count","Vouchers are pre-numbered with no gaps","Custodian does not approve their own payouts","Keys and safe codes changed when the custodian changes"],"kpis":[["Count variance","Zero unexplained differences"],["Receipt compliance","100% of payouts supported by receipts"],["Top-up frequency","No more than [2] per month, otherwise review float size"]],"risks":[["Theft or loss of cash","Low float, locked storage and surprise counts"],["Personal use or IOUs","IOUs prohibited and checked at each count"],["Avoiding purchase controls by splitting payments","Payout limit and review of vouchers for repeated items"]],"related":["Employee Expense Reimbursement","Month-end Close","Cash Handling Procedure"],"review":"Every 12 months, or after any cash shortage or change of custodian"},{"id":"finance-sales-tax-gst-vat-filing","dept":"finance","title":"Sales Tax and GST/VAT Filing","summary":"Prepares, reviews and files indirect tax returns accurately and on time, with records that stand up to audit.","tags":["vat","gst","sales tax","tax return","indirect tax","compliance"],"purpose":"To meet indirect tax obligations in every place [Company] is registered. Accurate returns avoid penalties, interest and lost input tax recovery.","scope":"Covers VAT, GST and sales tax returns, payments and records for all registrations held by [Company]. It does not cover corporate income tax or payroll taxes.","definitions":[["Output tax","Tax charged on sales to customers."],["Input tax","Tax paid on purchases that may be reclaimable."],["Reverse charge","A rule under which the customer, not the supplier, accounts for the tax on certain transactions."],["Nexus or registration threshold","The level of sales or presence that creates an obligation to register; check local law."]],"roles":[["Tax Preparer","Extracts data, reconciles and drafts each return."],["Finance Manager","Reviews, approves and submits returns and payments."],["External Tax Adviser","Advises on new jurisdictions, complex transactions and registrations."],["Billing Specialist","Applies correct tax codes on invoices."]],"prereqs":["Register of tax registrations with numbers, periods and deadlines","Tax code mapping in [accounting system]","Closed month or period in the ledger","Access to tax authority portals with two named users","Exemption and reverse-charge evidence from customers"],"steps":[{"t":"Maintain the filing calendar","d":"Keep a calendar of every return and payment deadline by jurisdiction with reminders 10 business days before each.","o":"Finance Manager"},{"t":"Monitor registration thresholds","d":"Quarterly, review sales by country or state against registration thresholds and ask the adviser about any jurisdiction above [e.g. 80%] of a threshold.","o":"Tax Preparer"},{"t":"Close the period first","d":"Prepare the return only after month-end close for the relevant period so that sales and purchase ledgers are complete.","o":"Tax Preparer"},{"t":"Run the tax reports","d":"Extract output and input tax reports by tax code and reconcile them to the tax control accounts in the general ledger.","o":"Tax Preparer"},{"t":"Review exceptions","d":"Check zero-rated, exempt and reverse-charge transactions for supporting evidence, and review input tax claims for valid tax invoices.","o":"Tax Preparer"},{"t":"Draft the return","d":"Complete the return in the required format, with a working file linking each box to the ledger report.","o":"Tax Preparer"},{"t":"Review and approve","d":"Review the working file, compare to previous periods and investigate movements above [e.g. 20%]. Approve before submission.","o":"Finance Manager"},{"t":"Submit and pay","d":"Submit the return and pay any amount due at least 2 business days before the deadline, keeping submission receipts.","o":"Finance Manager"},{"t":"Post and reconcile","d":"Post the payment or refund and confirm the tax control account balance is zero or explained.","o":"Tax Preparer"},{"t":"Correct prior errors","d":"If an error is found, assess materiality and correct it in the next return or by voluntary disclosure on the adviser's advice. Check local law.","o":"External Tax Adviser"},{"t":"Retain records","d":"Keep returns, workings and invoices for the statutory period, which varies by country. Check local law.","o":"Tax Preparer"}],"checks":["Tax control account reconciled every period","Return figures tie to ledger reports","Preparer and approver are different people","Filing calendar reviewed monthly for missed deadlines"],"kpis":[["On-time filing","100% of returns and payments by deadline"],["Penalties and interest","Zero"],["Post-filing corrections","No material corrections per year"],["Input tax recovery","All valid input tax claimed within the period"]],"risks":[["Missed registration in a new market","Quarterly threshold monitoring and adviser review"],["Wrong tax codes on invoices","Tax code review for new products and customer types"],["Portal access lost when a person leaves","At least two authorised users per portal"],["Unsupported input tax claims","Valid invoice check before claiming"]],"related":["Customer Invoicing and Billing","Month-end Close","Accounts Payable and Supplier Payments","Tax Registration Register"],"review":"Every 12 months, or on entering a new country or state, or after a tax rule change"},{"id":"finance-bank-reconciliation","dept":"finance","title":"Bank Reconciliation","summary":"Matches every bank, card and payment-provider transaction to the ledger so cash balances are accurate and errors surface fast.","tags":["bank reconciliation","cash","bank rec","statement matching","payment providers"],"purpose":"To confirm that cash in the accounts matches the bank. Frequent reconciliation catches errors, missing entries and fraud early.","scope":"Covers all bank accounts, credit cards, payment gateways and wallets held by [Company]. Customer receivable and supplier statement reconciliations are covered in their own SOPs.","definitions":[["Reconciling item","A valid timing difference between bank and ledger, such as an uncleared payment."],["Unreconciled item","A difference without explanation, which must be investigated."],["Bank feed","An automatic import of bank transactions into [accounting system]."],["Clearing account","A temporary ledger account used for payment-provider settlements."]],"roles":[["Accountant","Matches transactions and prepares the reconciliation."],["Finance Manager","Reviews and signs off reconciliations and approves write-offs."],["AP Clerk","Resolves supplier payment differences."],["Credit Controller","Allocates unidentified customer receipts."]],"prereqs":["Read-only bank access or bank feeds for every account","Statements or settlement reports for each account and provider","List of all accounts with owner and purpose","Reconciliation template or module in [accounting system]"],"steps":[{"t":"Import transactions","d":"Import or confirm bank feed data for every account at least [weekly] and check the feed balance against the bank portal.","o":"Accountant"},{"t":"Match routine transactions","d":"Match receipts to invoices and payments to bills. Use bank rules only for fixed recurring items such as rent and subscriptions.","o":"Accountant"},{"t":"Allocate unidentified receipts","d":"Send unidentified receipts to the Credit Controller, who must allocate them within 3 business days or record them in a suspense account.","o":"Credit Controller"},{"t":"Reconcile payment providers","d":"Reconcile gateway settlements to the gross sales, fees, refunds and chargebacks in the clearing account, so only net payouts hit the bank.","o":"Accountant"},{"t":"Investigate unknown payments","d":"Query any payment not recognised the same day with the AP Clerk. Treat unrecognised debits as possible fraud until explained.","o":"AP Clerk"},{"t":"Prepare the month-end reconciliation","d":"By WD2, produce a reconciliation from statement balance to ledger balance listing every reconciling item with date and explanation.","o":"Accountant"},{"t":"Clear old items","d":"Investigate reconciling items older than 30 days and correct or escalate them. Do not carry them forward without a note.","o":"Accountant"},{"t":"Review and sign off","d":"Review each reconciliation, check the statement balance against an original bank statement, and sign and date it.","o":"Finance Manager"},{"t":"Approve adjustments","d":"Approve any write-off or correcting journal above [amount] with documentation.","o":"Finance Manager"},{"t":"Store evidence","d":"Save statements and signed reconciliations in [document system] for each month.","o":"Accountant"}],"checks":["Every account on the account list has a reconciliation each month","Statement balance verified against an original statement","No unreconciled items over 30 days without escalation","Preparer and reviewer are different people"],"kpis":[["Reconciliation timeliness","100% completed by WD2"],["Aged reconciling items","None older than 30 days"],["Unidentified receipts","Allocated within 3 business days"]],"risks":[["Fraudulent payments unnoticed","Daily review of debits and independent reviewer"],["Forgotten or dormant accounts","Account register reviewed quarterly and dormant accounts closed"],["Bank feed errors or duplicates","Feed balance checked against bank portal"],["Payment-provider fees and chargebacks missed","Gross-to-net settlement reconciliation"]],"related":["Month-end Close","Accounts Payable and Supplier Payments","Collections and Overdue Invoices","Petty Cash"],"review":"Every 12 months, or after opening a new bank or payment-provider account"},{"id":"finance-spend-approval-limits","dept":"finance","title":"Spend Approval Limits","summary":"Sets who can approve which commitments and payments, so spending decisions are made at the right level with an audit trail.","tags":["delegation of authority","approval matrix","signing authority","spend control","doa","authorisation"],"purpose":"To define clear limits for approving spending, contracts and payments. A documented matrix speeds up routine decisions and keeps large or unusual commitments with senior leaders.","scope":"Covers purchases, contracts, hires, pay changes, write-offs and payments made on behalf of [Company]. It does not replace legal sign-off requirements set by the company's constitution or local law.","definitions":[["Delegation of Authority (DoA) matrix","A table listing types of commitment and the approval required at each value band."],["Total contract value","The full value over the contract term, including renewals and one-off fees, not the monthly amount."],["Split purchase","Dividing one purchase into smaller ones to stay under an approval limit, which is prohibited."],["Budgeted spend","Spend included in the approved budget for that cost centre."]],"roles":[["Finance Manager","Maintains the matrix and configures limits in systems."],["Founder or CEO","Approves the matrix and high-value commitments."],["Budget Holders","Approve spend within their limit and budget."],["Board","Approves items reserved to it, such as large contracts or borrowing."]],"prereqs":["Approved annual budget by cost centre","Org chart with named Budget Holders","Company constitution and any investor consent rights","Systems where limits can be configured, e.g. [expense tool], [purchasing tool], [banking platform]"],"steps":[{"t":"Draft value bands","d":"Set bands that fit the company size, for example: up to [1,000] Budget Holder; up to [10,000] Department Head plus Finance; up to [50,000] CEO; above that Board.","o":"Finance Manager"},{"t":"Define commitment types","d":"List categories with their own rules: new hires, pay changes, software contracts, capital spend, legal settlements, refunds, write-offs and borrowing.","o":"Finance Manager"},{"t":"Apply total contract value","d":"State that limits apply to total contract value over the full term, including auto-renewals.","o":"Finance Manager"},{"t":"Set rules for unbudgeted spend","d":"Require one level higher approval for any unbudgeted spend, and Finance Manager review for all unbudgeted items above [amount].","o":"Finance Manager"},{"t":"Reserve Board and investor matters","d":"Mark items requiring Board or investor consent under the shareholders' agreement, such as new debt or acquisitions.","o":"Board"},{"t":"Approve and publish","d":"The CEO approves the matrix; publish it on [intranet] and brief all Budget Holders.","o":"Founder or CEO"},{"t":"Configure systems","d":"Set approval workflows in purchasing, expense and banking tools to match the matrix, and restrict bank signatories accordingly.","o":"Finance Manager"},{"t":"Approve within limits","d":"Approve only within your own limit and budget, checking for split purchases and conflicts of interest. Declare any conflict and pass to the next level.","o":"Budget Holders"},{"t":"Handle absence","d":"Nominate a delegate at the same or higher level during absence, recorded in the approval tool. Delegation to a lower level is not allowed.","o":"Budget Holders"},{"t":"Monitor compliance","d":"Quarterly, sample approvals for compliance and report breaches to the CEO, including any split purchases.","o":"Finance Manager"},{"t":"Review limits","d":"Update the matrix after funding rounds, reorganisations or role changes, and remove leavers' approval rights within 1 business day of leaving.","o":"Finance Manager"}],"checks":["System approval rules match the published matrix","Leavers removed from approval and bank rights within 1 business day","Quarterly sample shows no split purchases","Matrix version and approval date recorded"],"kpis":[["Approval compliance","At least 98% of sampled transactions approved at the correct level"],["Approval turnaround","90% of approvals within 2 business days"],["Matrix currency","Reviewed within 30 days of any reorganisation"]],"risks":[["Commitments made without authority","System-enforced workflows and contract signatory list"],["Purchases split to avoid limits","Analytics on repeated supplier spend just below limits"],["Bottlenecks slowing the business","Sensible low-value limits and named delegates"],["Approver with a conflict of interest","Conflict declaration and escalation rule"]],"related":["Purchase Requests and Purchase Orders","Accounts Payable and Supplier Payments","Annual Budget and Rolling Forecast","Conflict of Interest Policy"],"review":"Every 12 months, or after a funding round, reorganisation or control breach"},{"id":"ops-purchase-requests-purchase-orders","dept":"ops","title":"Purchase Requests and Purchase Orders","summary":"Turns internal buying needs into approved purchase orders so spend is authorised, budgeted and traceable before suppliers deliver.","tags":["purchase order","po","purchase request","procurement","requisition","buying"],"purpose":"To control what [Company] buys, from whom and at what price. Raising an approved PO before ordering prevents unauthorised commitments and makes invoice matching simple.","scope":"Covers goods and services above [PO threshold, e.g. 500] bought from external suppliers. It does not cover payroll, taxes, utilities or items bought through expense claims.","definitions":[["Purchase request (PR)","An internal request to buy, stating need, quantity, budget and preferred supplier."],["Purchase order (PO)","A formal order to a supplier with agreed price, quantity, delivery and terms."],["Preferred supplier","A supplier already approved with negotiated terms for a category."],["Competitive quotes","Comparable written quotes from different suppliers for the same requirement."]],"roles":[["Requester","Raises the PR with a clear specification and business reason."],["Budget Holder","Approves the PR against budget and need."],["Procurement Lead","Sources suppliers, obtains quotes, negotiates and issues POs."],["Finance Manager","Approves high-value or unbudgeted spend and checks coding."]],"prereqs":["Spend Approval Limits matrix","Approved supplier list","PR form or workflow in [purchasing tool]","Budget by cost centre","Standard PO terms and conditions"],"steps":[{"t":"Raise a purchase request","d":"Submit a PR in [purchasing tool] with specification, quantity, required date, cost centre, estimated cost and business reason. Raise it at least [10] business days before needed.","o":"Requester"},{"t":"Check budget and need","d":"Confirm the spend is needed and within budget, and approve or reject within 2 business days.","o":"Budget Holder"},{"t":"Select sourcing route","d":"Use a preferred supplier where available. Otherwise obtain [2] quotes above [e.g. 5,000] and [3] quotes above [e.g. 25,000], or document why a single source is justified.","o":"Procurement Lead"},{"t":"Compare and negotiate","d":"Compare quotes on total cost, delivery, quality, support and supplier risk, and negotiate price or terms where volume allows.","o":"Procurement Lead"},{"t":"Onboard new suppliers","d":"If the supplier is new, complete Vendor Onboarding and Due Diligence before the PO is issued.","o":"Procurement Lead"},{"t":"Obtain final approval","d":"Route the PR with the selected quote for approval at the level required by the Spend Approval Limits, based on total contract value.","o":"Finance Manager"},{"t":"Issue the PO","d":"Issue a numbered PO with price, quantity, delivery address and date, payment terms and standard terms attached. Ask the supplier to quote the PO number on all invoices.","o":"Procurement Lead"},{"t":"Obtain supplier acknowledgement","d":"Get written acceptance of the PO within 3 business days and update the expected delivery date.","o":"Procurement Lead"},{"t":"Receipt goods or services","d":"On delivery, check quantity and condition against the PO and record a goods received note in [purchasing tool] within 1 business day.","o":"Requester"},{"t":"Manage changes","d":"Any change to price, quantity or scope requires a PO amendment with the same approval as the original value change.","o":"Procurement Lead"},{"t":"Close the PO","d":"Close POs once fully invoiced and received. Review open POs older than 90 days monthly and close or chase them.","o":"Procurement Lead"}],"checks":["No supplier invoice above threshold paid without a PO except approved exceptions","Quotes on file for spend above quote thresholds","PO approvals match the Spend Approval Limits","Open PO list reviewed monthly"],"kpis":[["PO compliance","At least 90% of eligible spend under a PO"],["PR-to-PO cycle time","Median under 5 business days"],["Retrospective POs","Less than 5% of POs raised after the invoice"],["Savings from negotiation","Tracked against first quote, target [e.g. 5%]"]],"risks":[["Maverick buying without approval","Communicated no-PO-no-pay rule with AP enforcement"],["Paying above market price","Quote thresholds and periodic price benchmarking"],["Conflict of interest in supplier choice","Conflict declarations and Procurement review of single-source requests"],["Delivery delays","Required dates captured and supplier acknowledgement chased"]],"related":["Spend Approval Limits","Vendor Onboarding and Due Diligence","Accounts Payable and Supplier Payments","Inventory and Stock Control"],"review":"Every 12 months, or after a change of purchasing tool or approval limits"},{"id":"ops-vendor-onboarding-due-diligence","dept":"ops","title":"Vendor Onboarding and Due Diligence","summary":"Checks and sets up new suppliers so the company only works with legitimate, capable and compliant vendors.","tags":["vendor onboarding","supplier onboarding","due diligence","kyc","third-party risk","supplier setup"],"purpose":"To confirm that new suppliers are who they say they are and can deliver safely and securely. Proper onboarding reduces fraud, data and supply risks.","scope":"Covers every new supplier, contractor agency and software vendor before the first order or contract. It does not cover customers or individual freelancers engaged through HR.","definitions":[["Risk tier","A low, medium or high rating based on spend, data access and business criticality, which sets the depth of checks."],["Sanctions screening","Checking the supplier and its owners against government sanctions lists."],["Data processing agreement (DPA)","A contract setting how a vendor handles personal data, required under laws such as GDPR."],["Supplier master record","The approved record of supplier legal name, tax ID, address and bank details."]],"roles":[["Requester","Explains the need and the data or systems the vendor will access."],["Procurement Lead","Runs the onboarding checklist and risk tiering."],["Security or IT Lead","Assesses information security for vendors handling data or system access."],["Finance Manager","Verifies bank details and creates the supplier master record."],["Legal Reviewer","Reviews contract terms, DPA and liability."]],"prereqs":["Vendor request form","Supplier questionnaire for each risk tier","Sanctions and adverse media screening tool or service","Standard contract and DPA templates","Access to [accounting system] for supplier creation"],"steps":[{"t":"Submit the vendor request","d":"Complete the request form describing the service, estimated annual spend, data involved and system access. Confirm no existing supplier already provides it.","o":"Requester"},{"t":"Assign a risk tier","d":"Rate the vendor low, medium or high. High applies to spend above [e.g. 50,000], access to personal or confidential data, or services critical to operations.","o":"Procurement Lead"},{"t":"Collect company information","d":"Obtain legal name, registration number, tax ID, address, ownership, insurance certificates and references, and verify against the official company registry.","o":"Procurement Lead"},{"t":"Screen for sanctions and adverse media","d":"Screen the company and named owners or directors, and record the results. Any match is escalated to the Legal Reviewer before proceeding.","o":"Procurement Lead"},{"t":"Assess information security","d":"For medium and high tiers with data access, review the security questionnaire and certificates such as ISO 27001 or SOC 2 reports, and record any gaps and agreed actions.","o":"Security or IT Lead"},{"t":"Check financial stability","d":"For high-tier vendors, review recent accounts or a credit report and consider dependency risk.","o":"Finance Manager"},{"t":"Agree contract terms","d":"Negotiate and sign the contract, including service levels, liability, termination, confidentiality and DPA where personal data is processed.","o":"Legal Reviewer"},{"t":"Verify bank details","d":"Obtain bank details on supplier letterhead or through the supplier portal and confirm them by phone using an independently sourced number before entry.","o":"Finance Manager"},{"t":"Create the supplier record","d":"Create the supplier in [accounting system] with a different person approving the record than the one who entered it.","o":"Finance Manager"},{"t":"Record in the vendor register","d":"Add the vendor to the register with owner, tier, contract dates, renewal notice period and review date.","o":"Procurement Lead"},{"t":"Set up access","d":"Grant only the minimum system access needed, with named accounts and an end date matching the contract.","o":"Security or IT Lead"}],"checks":["No supplier created without a completed checklist for its tier","Bank details verified by independent call-back","High-tier vendors have security and financial reviews on file","Vendor register includes owner and renewal date for each vendor"],"kpis":[["Onboarding cycle time","Low tier within 5 business days, high tier within 20"],["Checklist completeness","100% of new suppliers"],["Vendors without owner","Zero"]],"risks":[["Fake supplier or invoice fraud","Registry checks, call-back verification and segregated supplier creation"],["Data breach through a vendor","Security assessment, DPA and least-privilege access"],["Sanctions breach","Screening at onboarding and on renewal"],["Over-reliance on a fragile supplier","Financial review and contingency supplier for critical services"]],"related":["Purchase Requests and Purchase Orders","Quarterly Vendor Performance Review","Accounts Payable and Supplier Payments","Information Security Policy"],"review":"Every 12 months, or after a supplier-related incident or new data protection requirement"},{"id":"ops-quarterly-vendor-performance-review","dept":"ops","title":"Quarterly Vendor Performance Review","summary":"Scores key suppliers each quarter on delivery, quality, cost and service, and agrees actions to fix or replace weak ones.","tags":["vendor review","supplier performance","scorecard","qbr","supplier management","sla review"],"purpose":"To make sure important suppliers deliver what they promised and continue to offer value. Regular, evidence-based reviews catch problems before they disrupt the business.","scope":"Covers all high-tier and medium-tier suppliers in the vendor register, and any supplier with an open non-conformance. Low-tier suppliers are reviewed annually or at renewal.","definitions":[["Supplier scorecard","A standard rating of a supplier across delivery, quality, cost, service and risk."],["SLA","Service level agreement: measurable commitments in the contract."],["OTIF","On time in full: orders delivered by the agreed date in the agreed quantity."],["Improvement plan","Agreed actions, owners and dates to close performance gaps."]],"roles":[["Vendor Owner","The internal person accountable for the supplier relationship."],["Procurement Lead","Runs the review cycle and consolidates scorecards."],["Finance Manager","Provides spend data and checks pricing against contract."],["Supplier Account Manager","Attends the review and commits to improvement actions."]],"prereqs":["Vendor register with tiers and owners","Contract SLAs and pricing schedules","Quarterly spend, delivery and quality data","Open non-conformance and incident records","Scorecard template"],"steps":[{"t":"Select suppliers for review","d":"In the first week of the quarter, list suppliers due for review and confirm owners.","o":"Procurement Lead"},{"t":"Gather performance data","d":"Collect OTIF, defect or incident rates, SLA results, ticket response times and spend versus budget for the last quarter.","o":"Vendor Owner"},{"t":"Check invoices against contract","d":"Compare invoiced prices and fees to the contract and flag any overcharging or unapproved increases.","o":"Finance Manager"},{"t":"Score the supplier","d":"Rate each area 1 to 5 against the scorecard definitions, using data rather than opinion, and calculate a weighted score.","o":"Vendor Owner"},{"t":"Collect internal feedback","d":"Ask the main internal users for a short rating and comments within 5 business days.","o":"Vendor Owner"},{"t":"Hold the review meeting","d":"Meet the Supplier Account Manager, share the scorecard in advance, and discuss results, root causes and upcoming needs.","o":"Vendor Owner"},{"t":"Agree improvement actions","d":"For any area scored 2 or below, agree a written improvement plan with dates within 2 weeks of the meeting.","o":"Supplier Account Manager"},{"t":"Escalate persistent issues","d":"If a supplier scores below [e.g. 3.0] for two quarters, escalate to leadership and start contingency sourcing.","o":"Procurement Lead"},{"t":"Recheck risk status","d":"Refresh sanctions screening, insurance certificates and security attestations if due, and update the risk tier.","o":"Procurement Lead"},{"t":"Plan renewals","d":"Flag contracts renewing within 6 months and decide to renew, renegotiate or exit, respecting notice periods.","o":"Vendor Owner"},{"t":"Publish the summary","d":"Share a quarterly supplier summary with leadership listing scores, trends, actions and renewal decisions.","o":"Procurement Lead"}],"checks":["Every in-scope supplier has a dated scorecard","Improvement plans tracked to closure","Renewal notice dates captured with reminders","Pricing checked against contract each quarter"],"kpis":[["Reviews completed","100% of in-scope suppliers each quarter"],["Supplier OTIF","At least [95%] across key suppliers"],["Improvement actions closed on time","At least 85%"],["Unplanned auto-renewals","Zero"]],"risks":[["Reviews become box-ticking","Data-based scoring and a required action for low scores"],["Missed termination notice windows","Renewal calendar with 6-month alerts"],["Single-source dependency","Contingency supplier identified for critical categories"],["Overcharging unnoticed","Quarterly invoice-to-contract price check"]],"related":["Vendor Onboarding and Due Diligence","Supplier Non-conformance and Corrective Action (CAPA)","Purchase Requests and Purchase Orders","Contract Management Policy"],"review":"Every 12 months, or after a major supplier failure"},{"id":"ops-inventory-stock-control","dept":"ops","title":"Inventory and Stock Control","summary":"Keeps stock records accurate and stock levels right-sized, avoiding stockouts, overstock, loss and expiry.","tags":["inventory","stock control","warehouse","cycle count","stocktake","reorder point"],"purpose":"To make sure the right stock is available when needed while minimising cash tied up in inventory. Accurate records support reliable ordering, fulfilment and financial reporting.","scope":"Covers raw materials, finished goods, packaging and consumables held at [Company] warehouses, stores or third-party logistics sites. It does not cover company fixed assets such as laptops, which follow Company Asset Management.","definitions":[["SKU","Stock keeping unit: a unique code for each item variant."],["Reorder point","The stock level that triggers a new purchase, based on lead time demand plus safety stock."],["Cycle count","Counting a subset of stock on a rolling schedule instead of all at once."],["FIFO or FEFO","First in first out, or first expired first out, picking rules."]],"roles":[["Inventory Controller","Maintains stock records, reorder levels and counts."],["Warehouse Operative","Receives, stores, picks and moves stock and records each movement."],["Procurement Lead","Raises purchase orders when reorder points are hit."],["Finance Manager","Reviews stock valuation, write-offs and count variances."]],"prereqs":["Inventory or warehouse management system [system] with SKU master data","Labelled bin or shelf locations","Barcode scanners or count sheets","Reorder points and safety stock per SKU","Approved write-off thresholds"],"steps":[{"t":"Receive stock","d":"Check deliveries against the PO for quantity, SKU and damage, record batch or expiry where relevant, and book in within 4 hours of arrival.","o":"Warehouse Operative"},{"t":"Put away to a recorded location","d":"Store each item in its assigned location and scan the location so the system shows exactly where it is.","o":"Warehouse Operative"},{"t":"Record every movement","d":"Scan or log every pick, transfer, return and adjustment at the time it happens. No stock moves without a system record.","o":"Warehouse Operative"},{"t":"Apply picking rules","d":"Pick using FIFO, or FEFO for dated goods, so older stock leaves first.","o":"Warehouse Operative"},{"t":"Classify stock by value","d":"Classify SKUs as A, B or C by annual value: A items counted monthly, B quarterly, C twice a year.","o":"Inventory Controller"},{"t":"Run cycle counts","d":"Complete scheduled blind counts, where the counter does not see the system quantity, and record results the same day.","o":"Inventory Controller"},{"t":"Investigate variances","d":"Recount any variance above [e.g. 2% or 100 in value] and investigate the cause before adjusting.","o":"Inventory Controller"},{"t":"Approve adjustments","d":"Approve stock adjustments above [amount] and review trends monthly.","o":"Finance Manager"},{"t":"Reorder at the reorder point","d":"Review the reorder report [daily or weekly] and raise POs for SKUs at or below the reorder point.","o":"Procurement Lead"},{"t":"Manage slow-moving and expiring stock","d":"Monthly, list stock with no movement for [90] days or expiring within [60] days and agree action: promote, return, transfer or write off.","o":"Inventory Controller"},{"t":"Quarantine damaged stock","d":"Move damaged, returned or suspect stock to a marked quarantine area and block it in the system until inspected.","o":"Warehouse Operative"},{"t":"Perform the year-end count","d":"Carry out a full count or validated cycle-count evidence at financial year-end with Finance observing.","o":"Finance Manager"}],"checks":["Counts are blind and performed by someone other than the person who handles that stock day to day where possible","Adjustments carry approval and reason code","Quarantine stock blocked from picking","Reorder points reviewed quarterly against actual demand"],"kpis":[["Inventory record accuracy","At least 98% of counted locations correct"],["Stockout rate","Below 2% of order lines"],["Inventory turnover","At or above [target] turns per year"],["Write-offs","Below [e.g. 1%] of inventory value"]],"risks":[["Theft or shrinkage","Restricted access, CCTV where appropriate and frequent counts of high-value items"],["Stockouts losing sales","Reorder points with safety stock and supplier lead-time tracking"],["Expired or obsolete stock","FEFO picking and monthly slow-mover review"],["Inaccurate valuation in accounts","Approved adjustments and year-end count"]],"related":["Purchase Requests and Purchase Orders","Order Fulfilment and Shipping","Quality Control Inspection","Month-end Close"],"review":"Every 12 months, or after a stock count variance above tolerance or a system change"},{"id":"ops-order-fulfilment-shipping","dept":"ops","title":"Order Fulfilment and Shipping","summary":"Moves customer orders from payment to doorstep accurately and within the promised dispatch time, with tracking and clear exceptions.","tags":["order fulfilment","shipping","dispatch","pick pack ship","ecommerce","logistics"],"purpose":"To deliver every customer order correctly, safely and on time. A consistent pick, pack and ship routine reduces errors, returns and customer contacts.","scope":"Covers B2C and B2B orders shipped from [Company] sites or a third-party logistics partner. It does not cover returns processing or international customs classification beyond the documents listed.","definitions":[["Dispatch SLA","The promised time between order and handover to the carrier, e.g. same day for orders before 2 pm."],["Pick list","The document or screen listing items and locations to collect for an order."],["Order hold","A status that stops fulfilment pending payment, fraud or address checks."],["Proof of delivery (POD)","Carrier evidence that the parcel was delivered."]],"roles":[["Fulfilment Lead","Plans daily workload, manages exceptions and carrier performance."],["Picker Packer","Picks, checks, packs and labels orders."],["Customer Support Agent","Updates customers on delays and handles delivery queries."],["Inventory Controller","Resolves stock discrepancies found during picking."]],"prereqs":["Order management system [OMS] connected to the sales channels","Carrier accounts and label printing","Packaging materials by product size","Packing standards and fragile item guidelines","Customs documents for international orders"],"steps":[{"t":"Release orders for fulfilment","d":"At set times each day, release paid orders that pass fraud and address checks. Hold orders with mismatched addresses or high fraud scores for review within 4 hours.","o":"Fulfilment Lead"},{"t":"Prioritise the queue","d":"Sort orders by service level: express first, then oldest standard orders, then pre-orders and backorders.","o":"Fulfilment Lead"},{"t":"Pick items","d":"Pick using the pick list and scan each item barcode. Report any short pick immediately so stock can be checked.","o":"Picker Packer"},{"t":"Resolve short picks","d":"Check alternate locations and stock records within 1 hour. If stock is unavailable, split or cancel the line and trigger a customer update.","o":"Inventory Controller"},{"t":"Check and pack","d":"Scan items again at packing to confirm SKU and quantity, use the right-size packaging, protect fragile items and include the packing slip and any required inserts.","o":"Picker Packer"},{"t":"Weigh and label","d":"Weigh the parcel, select the carrier service and print the label. Attach customs forms and commercial invoice for international parcels.","o":"Picker Packer"},{"t":"Hand over to carrier","d":"Stage parcels by carrier, scan them onto the manifest and get a signed or scanned collection record before the cut-off time.","o":"Fulfilment Lead"},{"t":"Send tracking","d":"Ensure the customer receives dispatch confirmation with tracking within 1 hour of carrier scan.","o":"Customer Support Agent"},{"t":"Monitor exceptions","d":"Each morning, review carrier exception reports for delays, failed deliveries and damage, and contact affected customers proactively.","o":"Customer Support Agent"},{"t":"Handle lost or damaged parcels","d":"Open a carrier claim within the carrier's deadline, and send a replacement or refund per policy without waiting for the claim outcome for orders below [amount].","o":"Fulfilment Lead"},{"t":"Review daily performance","d":"At end of day, record orders shipped, SLA misses, pick errors and backlog, and agree staffing for the next day.","o":"Fulfilment Lead"}],"checks":["Double scan at pick and pack","Orders on hold reviewed within 4 hours","Carrier manifest reconciled to parcels collected","Weekly sample of packed orders audited for presentation and accuracy"],"kpis":[["Dispatch on time","At least 98% within dispatch SLA"],["Order accuracy","At least 99.5% of orders shipped without error"],["Damage rate","Below 0.5% of parcels"],["Cost per order","At or below [target]"]],"risks":[["Wrong item shipped","Barcode scanning at pick and pack"],["Peak volume backlog","Forecast peak periods and pre-agreed temporary staff"],["Carrier failure","Secondary carrier account set up and tested"],["Fraudulent orders","Fraud screening and hold review before dispatch"]],"related":["Inventory and Stock Control","Customer Returns and Refunds","Quality Control Inspection","Customer Complaint Handling"],"review":"Every 12 months, or before peak season, or after a carrier change"},{"id":"ops-company-asset-management","dept":"ops","title":"Company Asset Management","summary":"Tracks company equipment from purchase to disposal so every asset is assigned, secured, maintained and recovered.","tags":["asset management","it assets","equipment","laptops","asset register","disposal"],"purpose":"To know what equipment [Company] owns, where it is and who is responsible for it. Good asset control reduces loss, protects data and supports accurate accounts.","scope":"Covers laptops, phones, monitors, tools, vehicles, furniture and other equipment above [e.g. 200] value or holding company data, whether bought or leased. It does not cover inventory held for sale.","definitions":[["Asset register","The master list of assets with tag, description, owner, location, cost and status."],["Asset tag","A unique label or serial number fixed to each asset."],["Capitalisation threshold","The value above which an asset is recorded on the balance sheet and depreciated."],["Secure data wipe","Erasure of data to a recognised standard before reuse or disposal."]],"roles":[["Asset Administrator","Maintains the register, tags assets and manages issue and return."],["Employee","Looks after assigned assets and reports loss or damage promptly."],["IT Lead","Configures devices, enforces security and wipes data."],["Finance Manager","Records capital assets, depreciation and disposals."],["Line Manager","Confirms asset needs for new starters and returns for leavers."]],"prereqs":["Asset register in [asset tool or spreadsheet]","Asset tags or labels","Device management tool [MDM] for laptops and phones","Asset acknowledgement form","Approved disposal and recycling providers"],"steps":[{"t":"Approve the purchase","d":"Buy assets through the Purchase Requests and Purchase Orders SOP, using standard models where possible.","o":"Line Manager"},{"t":"Tag and register on arrival","d":"Within 2 business days of delivery, tag the asset and record serial number, cost, supplier, warranty end date and location.","o":"Asset Administrator"},{"t":"Configure and secure","d":"Enrol devices in [MDM], enable disk encryption, screen lock and remote wipe, and install standard software.","o":"IT Lead"},{"t":"Issue to the employee","d":"Issue the asset with a signed or e-signed acknowledgement of responsibility and update the register owner.","o":"Asset Administrator"},{"t":"Record capital assets","d":"Capitalise assets above the threshold, set the depreciation life and reconcile the fixed asset ledger to the register monthly.","o":"Finance Manager"},{"t":"Report loss or damage","d":"Report lost, stolen or damaged assets to the Asset Administrator and IT Lead within 4 hours, and to police where theft is suspected.","o":"Employee"},{"t":"Respond to loss","d":"Remotely lock or wipe lost devices immediately, assess any data breach through the incident process and update the register.","o":"IT Lead"},{"t":"Maintain and repair","d":"Track warranty, servicing and inspections, such as electrical safety testing or vehicle servicing, with reminders 30 days before due.","o":"Asset Administrator"},{"t":"Recover assets from leavers","d":"Collect all assets on or before the last working day, check condition against the register and confirm return in the leaver checklist.","o":"Line Manager"},{"t":"Audit the register","d":"Twice a year, reconcile the register to MDM data and a physical or self-attestation check, and investigate missing items.","o":"Asset Administrator"},{"t":"Dispose securely","d":"Wipe or destroy storage to a recognised standard, keep the certificate, dispose through an approved recycler and record the disposal with Finance.","o":"IT Lead"}],"checks":["Every device holding data is enrolled in MDM with encryption","Register reconciled to fixed asset ledger monthly","Leaver asset returns confirmed before final pay where local law allows","Data destruction certificates kept for disposed devices"],"kpis":[["Register accuracy","At least 98% of assets found where recorded at audit"],["Leaver recovery","100% of assets returned within 5 business days of leaving"],["Lost or stolen assets","Below [number] per year"],["Encryption coverage","100% of laptops and phones"]],"risks":[["Data breach from a lost device","Encryption, MDM and remote wipe"],["Assets not returned by leavers","Line Manager checklist and courier return kits for remote staff"],["Ghost assets in accounts","Twice-yearly audit and ledger reconciliation"],["Unsafe equipment","Scheduled safety inspections with records"]],"related":["Purchase Requests and Purchase Orders","Employee Onboarding","Employee Offboarding","Information Security Policy"],"review":"Every 12 months, or after a data incident involving a device"},{"id":"ops-business-continuity-dr-activation","dept":"ops","title":"Business Continuity and Disaster Recovery Plan Activation","summary":"Activates the continuity plan quickly after a major disruption so critical services resume within agreed recovery times.","tags":["business continuity","disaster recovery","bcp","crisis management","incident response","resilience"],"purpose":"To give a clear sequence for declaring a disruption and restoring critical operations. A practised activation process limits harm to people, customers and revenue.","scope":"Covers events that stop or seriously degrade critical services, such as loss of premises, major IT or cloud outage, key supplier failure, cyber attack or severe weather. Routine IT incidents are handled by the normal incident process unless they meet the activation criteria.","definitions":[["Recovery time objective (RTO)","The maximum acceptable time to restore a service after disruption."],["Recovery point objective (RPO)","The maximum acceptable amount of data loss, measured in time."],["Crisis Management Team (CMT)","The small group authorised to declare a disruption and direct the response."],["Critical service","A process whose loss would cause severe harm within the RTO, listed in the business impact analysis."]],"roles":[["Crisis Lead","Decides on activation, chairs the CMT and approves key decisions."],["Recovery Lead","Coordinates technical and operational recovery against RTOs."],["Communications Lead","Manages messages to staff, customers, partners and media."],["People Safety Lead","Accounts for staff safety and wellbeing."],["Department Leads","Run their recovery procedures and report status."]],"prereqs":["Approved business continuity plan with business impact analysis, RTOs and RPOs","Up-to-date contact lists held offline and in a secondary location","Tested backups and alternate work arrangements","Pre-approved communication templates","Emergency spending authority for the Crisis Lead"],"steps":[{"t":"Raise the alert","d":"Anyone who sees a potentially major disruption reports it immediately to the on-call manager or Crisis Lead, with what, where, when and who is affected.","o":"Department Leads"},{"t":"Assess against activation criteria","d":"Within 30 minutes, the Crisis Lead checks whether a critical service will exceed its RTO or there is risk to life, data or reputation, and decides whether to activate.","o":"Crisis Lead"},{"t":"Protect people first","d":"Confirm everyone's safety, follow emergency services instructions, and complete a staff accountability check within 1 hour.","o":"People Safety Lead"},{"t":"Convene the CMT","d":"Open the crisis bridge or channel, assign roles, start a decision and action log with timestamps, and agree the next update time.","o":"Crisis Lead"},{"t":"Contain the incident","d":"Take immediate steps to stop the damage spreading, such as isolating systems in a cyber attack or securing a damaged site.","o":"Recovery Lead"},{"t":"Invoke recovery procedures","d":"Start the recovery runbooks for affected critical services in priority order, such as failover to backup systems or moving staff to remote work.","o":"Recovery Lead"},{"t":"Communicate internally","d":"Inform staff within 1 hour of activation what has happened, what they should do and when the next update will come.","o":"Communications Lead"},{"t":"Communicate externally","d":"Notify affected customers, key suppliers, insurers and, where required, regulators within required timelines. Check local law for breach notification deadlines.","o":"Communications Lead"},{"t":"Track recovery against RTOs","d":"Each department reports status at agreed intervals, at least every [2] hours during the acute phase, and the CMT reprioritises resources.","o":"Department Leads"},{"t":"Approve emergency spending","d":"Use pre-approved emergency spending authority up to [amount] and record every commitment.","o":"Crisis Lead"},{"t":"Return to normal","d":"When services meet normal levels, confirm data integrity, formally stand down the CMT and inform all stakeholders.","o":"Crisis Lead"},{"t":"Hold a post-incident review","d":"Within 10 business days, review what worked and what failed, update the plan and assign improvement actions with owners.","o":"Recovery Lead"}],"checks":["Contact lists verified quarterly","Backups restore-tested at least twice a year","Plan exercised at least annually with a tabletop or live test","Decision log maintained for every activation"],"kpis":[["Activation decision time","Within 30 minutes of alert"],["Staff accounted for","100% within 1 hour"],["Critical services restored within RTO","100%"],["Post-incident actions closed","At least 90% by due date"]],"risks":[["Plan unavailable when systems are down","Offline and printed copies with key leaders"],["Untested recovery steps fail","Annual exercises and restore tests"],["Mixed or late messages to customers","Single Communications Lead and pre-approved templates"],["Key person unavailable","Named deputies for every CMT role"]],"related":["IT Incident Response","Data Breach Response","Office or Workspace Opening and Closing","Backup and Restore Procedure"],"review":"Every 12 months, after each activation or exercise, or after a major change to systems or premises"},{"id":"ops-quality-control-inspection","dept":"ops","title":"Quality Control Inspection","summary":"Inspects incoming materials, in-process work and finished products against clear criteria so defects are caught before customers see them.","tags":["quality control","qc","inspection","aql","quality assurance","iso 9001"],"purpose":"To verify that products meet defined specifications at each key stage. Consistent inspection protects customers, reduces rework cost and supports quality standards such as ISO 9001.","scope":"Covers incoming goods inspection, in-process checks and final inspection for products made, assembled or packed by or for [Company]. Supplier failures found here are handled through the Supplier Non-conformance and Corrective Action (CAPA) SOP.","definitions":[["Specification","The documented requirements a product must meet, such as dimensions, materials, appearance and function."],["AQL","Acceptable quality limit: the maximum defect rate accepted in a sampling plan."],["Critical, major and minor defect","Defect classes by impact: safety or legal, function, and cosmetic."],["Hold tag","A label showing an item is awaiting a quality decision and must not be used or shipped."]],"roles":[["QC Inspector","Performs inspections, records results and applies status tags."],["Quality Manager","Owns specifications, sampling plans and release decisions."],["Production or Warehouse Lead","Provides items for inspection and segregates rejected stock."],["Procurement Lead","Communicates incoming rejections to suppliers."]],"prereqs":["Approved product specifications and reference samples","Sampling plan per product, e.g. based on ISO 2859-1","Calibrated measuring equipment with valid calibration labels","Inspection checklists or forms in [QMS tool]","Marked quarantine area and hold tags"],"steps":[{"t":"Plan the inspection","d":"Identify the batch, product, specification revision and sampling plan before starting.","o":"QC Inspector"},{"t":"Check equipment","d":"Confirm measuring tools are calibrated and in date. Do not use equipment with expired calibration.","o":"QC Inspector"},{"t":"Draw the sample","d":"Take the number of samples set by the plan at random from across the batch, not just the top of the pallet.","o":"QC Inspector"},{"t":"Inspect against the checklist","d":"Check each sample for dimensions, function, appearance, labelling and packaging, and classify any defect as critical, major or minor.","o":"QC Inspector"},{"t":"Record results","d":"Record measurements, defects and photos in [QMS tool] at the time of inspection, linked to the batch or PO number.","o":"QC Inspector"},{"t":"Decide accept or reject","d":"Accept if defects are within the AQL. Any critical defect rejects the batch. Reject or escalate if major or minor defects exceed the limits.","o":"Quality Manager"},{"t":"Tag and segregate","d":"Apply accepted, hold or rejected tags, move rejected items to quarantine and block them in the system within 1 hour.","o":"Production or Warehouse Lead"},{"t":"Decide disposition","d":"For rejected batches, decide within 2 business days to return, rework, sort 100%, use with concession or scrap, recording who approved.","o":"Quality Manager"},{"t":"Notify the supplier","d":"For incoming rejections, notify the supplier within 1 business day with evidence and open a non-conformance.","o":"Procurement Lead"},{"t":"Release accepted product","d":"Release accepted batches in the system so they can be used or shipped.","o":"Quality Manager"},{"t":"Review quality trends","d":"Monthly, review defect rates by product, supplier and line, and start corrective action for repeat issues.","o":"Quality Manager"}],"checks":["Sampling plan followed and documented for every batch","All measuring equipment within calibration date","No shipment of items on hold or rejected","Concessions signed by the Quality Manager"],"kpis":[["First pass yield","At least [e.g. 97%]"],["Customer-reported defects","Below [e.g. 500] parts per million"],["Inspection on time","95% of incoming batches inspected within 1 business day"],["Supplier rejection rate","Tracked monthly per supplier"]],"risks":[["Defective product reaches customers","Final inspection, hold tags and system blocks"],["Inconsistent judgement between inspectors","Reference samples and periodic inspector calibration"],["Measurement errors","Calibration programme"],["Inspection delays slowing production","Planned inspection slots and trained backup inspectors"]],"related":["Supplier Non-conformance and Corrective Action (CAPA)","Inventory and Stock Control","Order Fulfilment and Shipping","Calibration Procedure"],"review":"Every 12 months, or after a customer quality complaint or specification change"},{"id":"ops-supplier-nonconformance-capa","dept":"ops","title":"Supplier Non-conformance and Corrective Action (CAPA)","summary":"Records supplier quality or delivery failures, contains the impact and drives root-cause fixes so problems do not recur.","tags":["capa","non-conformance","corrective action","ncr","root cause","supplier quality"],"purpose":"To deal with supplier failures in a structured way, from containment to verified correction. It turns repeated problems into lasting improvements and gives evidence for supplier decisions.","scope":"Covers non-conforming goods, services or deliveries from external suppliers, whether found at receipt, in production or by customers. Internal process failures follow the internal CAPA procedure, which uses the same method.","definitions":[["Non-conformance report (NCR)","The record of a failure to meet a requirement, with evidence."],["Containment","Immediate action to stop the problem affecting more product or customers."],["Root cause analysis","Finding the underlying reason for a failure, e.g. using 5 Whys or a fishbone diagram."],["Effectiveness check","Verification after a set time that the corrective action has stopped recurrence."]],"roles":[["Quality Manager","Owns the NCR and CAPA process and approves closure."],["Procurement Lead","Communicates with the supplier and manages commercial recovery."],["Supplier Quality Contact","Investigates root cause and implements corrective actions at the supplier."],["Production or Warehouse Lead","Carries out containment on site."]],"prereqs":["NCR and CAPA form or module in [QMS tool]","Evidence: photos, measurements, batch numbers, delivery notes","Supplier contract or quality agreement","Defect severity criteria"],"steps":[{"t":"Raise the NCR","d":"Open an NCR within 1 business day of finding the issue, with description, batch, quantity affected, evidence and severity.","o":"Quality Manager"},{"t":"Contain the problem","d":"Quarantine affected stock, check other batches and work in progress, and stop shipments if needed, within 4 hours for critical issues.","o":"Production or Warehouse Lead"},{"t":"Assess customer impact","d":"Determine whether affected product has reached customers and decide on customer notification or recall with leadership.","o":"Quality Manager"},{"t":"Notify the supplier","d":"Send the NCR to the supplier within 1 business day, requesting acknowledgement within 2 business days and containment at their site.","o":"Procurement Lead"},{"t":"Require root cause analysis","d":"Ask the supplier for a root cause analysis and corrective action plan, for example in 8D format, within 10 business days.","o":"Supplier Quality Contact"},{"t":"Review the response","d":"Check that the root cause is supported by evidence, not just 'operator error', and that actions address both occurrence and detection.","o":"Quality Manager"},{"t":"Agree disposition and recovery","d":"Agree return, rework, replacement or credit, and recover costs such as sorting and expedited freight where the contract allows.","o":"Procurement Lead"},{"t":"Increase inspection temporarily","d":"Apply tightened inspection on the next [e.g. 3] deliveries from the supplier until the fix is proven.","o":"Quality Manager"},{"t":"Verify effectiveness","d":"After the agreed period, typically 60 to 90 days, confirm the defect has not recurred before closing the CAPA.","o":"Quality Manager"},{"t":"Close and record","d":"Close the NCR and CAPA with evidence, and update the supplier's scorecard.","o":"Quality Manager"},{"t":"Escalate repeat offenders","d":"If the same issue recurs or a supplier has [3] NCRs in a quarter, escalate to leadership for a supplier development plan or exit.","o":"Procurement Lead"}],"checks":["Every NCR has documented containment","Root causes supported by evidence before approval","Effectiveness check completed before closure","Overdue CAPAs reviewed weekly"],"kpis":[["NCR acknowledgement","100% acknowledged by supplier within 2 business days"],["CAPA closure","At least 80% closed within 60 days"],["Repeat non-conformances","Zero repeats of the same root cause within 12 months"],["Cost of poor supplier quality","Tracked and recovered where contractually possible"]],"risks":[["Superficial root cause leads to repeat failures","Evidence-based review and effectiveness check"],["Affected product shipped during investigation","Immediate containment and system blocks"],["Supplier slow to respond","Contractual response times and escalation"],["Lost cost recovery","Track costs per NCR and claim within contract deadlines"]],"related":["Quality Control Inspection","Quarterly Vendor Performance Review","Product Recall Procedure","Customer Complaint Handling"],"review":"Every 12 months, or after a product recall or major supplier failure"},{"id":"ops-office-workspace-opening-closing","dept":"ops","title":"Office or Workspace Opening and Closing","summary":"Opens and closes the premises safely and securely each day, with checks on alarms, utilities, hazards and sensitive information.","tags":["office opening","closing checklist","premises security","facilities","lock up","workplace safety"],"purpose":"To make sure the workplace is safe and ready at the start of each day and secure at the end. Consistent checks reduce the risk of theft, fire, water damage and data exposure.","scope":"Covers offices, studios, shops, warehouses and shared workspaces used by [Company]. It does not cover emergency evacuation, which follows the fire and emergency procedure.","definitions":[["Key holder","A named person authorised to open, close and respond to alarms at the premises."],["Lone working","Working alone on the premises without direct supervision, which needs extra safety measures."],["Clear desk","Leaving no confidential papers or unlocked devices on desks at the end of the day."],["Opening log","A record of who opened or closed the site, when, and any issues found."]],"roles":[["Key Holder","Opens and closes the premises and completes the checklist."],["Office or Facilities Manager","Maintains the checklist, key register and alarm codes, and resolves issues."],["Staff","Follow clear desk rules and report hazards."],["Security or Alarm Provider","Monitors alarms and contacts key holders on activation."]],"prereqs":["Named key holders and a key and access card register","Alarm codes issued individually, not shared","Opening and closing checklist on paper or in [facilities app]","Emergency contacts for building management, alarm company and utilities","Lone working arrangements where staff open or close alone"],"steps":[{"t":"Check before entering","d":"On arrival, look for signs of forced entry or damage. If found, do not enter: move to a safe place and call the police and Facilities Manager.","o":"Key Holder"},{"t":"Disarm the alarm and log entry","d":"Disarm using your personal code within the entry delay and record opening time in the log.","o":"Key Holder"},{"t":"Walk through for hazards","d":"Check for leaks, smells of gas or burning, blocked fire exits, trip hazards and faulty equipment, and fix or report them before others start work.","o":"Key Holder"},{"t":"Turn on services","d":"Switch on lights, heating or cooling and shared equipment, and confirm internet and phones work.","o":"Key Holder"},{"t":"Confirm lone working check-in","d":"If working alone, check in with the nominated contact per the lone working arrangement, and again on leaving.","o":"Key Holder"},{"t":"Report issues","d":"Log any defects or security concerns in [facilities app] the same day, and escalate urgent risks to the Facilities Manager immediately.","o":"Staff"},{"t":"Apply clear desk at end of day","d":"Lock away confidential papers, lock or shut down devices, and remove personal items from shared spaces.","o":"Staff"},{"t":"Check all areas before closing","d":"Confirm all staff and visitors have left, including toilets and meeting rooms, and that windows and internal fire doors are closed.","o":"Key Holder"},{"t":"Shut down equipment","d":"Switch off non-essential electrical equipment, kitchen appliances and heaters, leaving servers and fridges on as listed.","o":"Key Holder"},{"t":"Secure cash and valuables","d":"Lock cash, stock and high-value equipment in the safe or secure room.","o":"Key Holder"},{"t":"Arm the alarm and lock up","d":"Set the alarm, lock all external doors and check them, then record closing time and any issues in the log.","o":"Key Holder"},{"t":"Review logs and access","d":"Weekly, review opening logs and open issues. Monthly, reconcile the key and card register and remove leavers' access within 1 business day of leaving.","o":"Office or Facilities Manager"}],"checks":["Opening and closing logs complete for every working day","Alarm codes are individual and changed when a key holder leaves","Fire exits checked clear at opening","Key register reconciled monthly"],"kpis":[["Checklist completion","100% of days"],["Security incidents","Zero caused by unlocked doors or unset alarms"],["Facility issues resolved","Urgent within 24 hours, routine within 5 business days"]],"risks":[["Break-in or theft","Alarm, individual codes, lock checks and secure storage"],["Fire or flood out of hours","Equipment shutdown and walk-through for hazards"],["Lone worker injury","Lone working check-in and emergency contacts"],["Data exposure","Clear desk and device locking"]],"related":["Company Asset Management","Business Continuity and Disaster Recovery Plan Activation","Fire and Emergency Evacuation Procedure","Visitor Management"],"review":"Every 12 months, or after a security incident or change of premises"},{"id":"it-new-user-access-provisioning","dept":"it","title":"New User Access Provisioning","summary":"Gives every new starter the right accounts and permissions, ready on day one, with least-privilege access recorded and approved.","tags":["access request","account creation","joiner","permissions","onboarding","least privilege"],"purpose":"To make sure new staff, contractors and interns can work from their first day with exactly the access their role needs. It also creates an auditable record of who approved each permission.","scope":"Covers creation of identity accounts, email, SaaS applications, shared drives and system roles for all new joiners and role changes. It does not cover physical building access or the laptop build, which have their own SOPs.","definitions":[["Identity provider (IdP)","The central system, e.g. [IdP tool], that holds user accounts and single sign-on."],["Role profile","A pre-approved bundle of applications and permissions for a job family."],["Least privilege","Granting only the minimum access needed to do the job."],["Privileged access","Admin, finance, production or customer-data permissions that carry higher risk."]],"roles":[["Hiring Manager","Submits the access request and confirms the role profile."],["HR Coordinator","Confirms start date, job title and contract type in [HRIS tool]."],["IT Administrator","Creates accounts, assigns groups and records the work in the ticket."],["System Owner","Approves privileged or non-standard access to their application."],["Security Lead","Reviews role profiles and spot-checks provisioning quarterly."]],"prereqs":["Signed contract or engagement letter recorded in [HRIS tool]","Access request ticket in [ticketing tool] using the joiner form","Current role profile matrix","Admin access to [IdP tool] and key SaaS consoles","Naming convention for usernames and email addresses"],"steps":[{"t":"Trigger the joiner ticket","d":"HR creates the joiner ticket as soon as the contract is signed and at least 5 business days before the start date, including name, title, manager, start date and employment type.","o":"HR Coordinator"},{"t":"Confirm the role profile","d":"The manager selects the matching role profile and lists any extra access with a business reason within 1 business day of the ticket opening.","o":"Hiring Manager"},{"t":"Obtain approvals for privileged access","d":"Any access outside the role profile, or any admin, finance or customer-data permission, is approved in the ticket by the named System Owner. Verbal approvals are not accepted.","o":"System Owner"},{"t":"Create the core identity","d":"Create the account in [IdP tool] using the naming convention, set the account to activate on the start date and assign the department and manager attributes.","o":"IT Administrator"},{"t":"Assign groups and applications","d":"Add the user to the role-profile groups so SaaS apps provision through single sign-on. Create any manual accounts only where SSO is not available and note them in the ticket.","o":"IT Administrator"},{"t":"Set expiry for temporary staff","d":"For contractors and interns, set an account expiry date equal to the contract end date. No temporary account may exceed [90] days without renewal.","o":"IT Administrator"},{"t":"Enforce MFA enrolment","d":"Require multi-factor enrolment at first sign-in. Accounts that have not enrolled within 48 hours of activation are suspended automatically.","o":"IT Administrator"},{"t":"Send credentials securely","d":"Send the activation link to the personal email on file or deliver it in person on day one. Never send passwords in the same channel as the username.","o":"IT Administrator"},{"t":"Verify access on day one","d":"On the first morning, confirm the starter can sign in to email, chat and their top 3 role apps. Fix any gap before noon.","o":"Hiring Manager"},{"t":"Close and record","d":"Attach the final list of granted access to the ticket and close it. The ticket is the access record for audit.","o":"IT Administrator"},{"t":"Review role profiles quarterly","d":"Each quarter, sample 10% of new joiners and compare granted access with the role profile. Correct drift and update profiles where needed.","o":"Security Lead"}],"checks":["No account is active before the contract start date","Every privileged permission has a named written approval","Temporary accounts all carry an expiry date","MFA enrolled for 100% of active users","Manual (non-SSO) accounts are listed in the ticket"],"kpis":[["Day-one readiness","95% of joiners have full role access by 10:00 on day one"],["Provisioning lead time","Tickets completed at least 1 business day before start"],["Access exceptions","Less than 10% of joiners need access outside their role profile"],["Audit sample accuracy","100% of sampled grants match approvals"]],"risks":[["Excessive access granted by copying another user","Never clone users; provision only from role profiles"],["Accounts created for hires who do not start","Activate on start date and disable if HR marks a no-show"],["Credentials intercepted","Use one-time activation links and separate channels"],["Shadow accounts outside SSO","Record every manual account and include it in leaver checks"]],"related":["Access Removal for Leavers","Laptop and Device Setup","Password and Multi-factor Authentication","Employee Onboarding","Access Control Policy"],"review":"Every 12 months, or after a new core system is introduced or an access-related audit finding"},{"id":"it-access-removal-leavers","dept":"it","title":"Access Removal for Leavers","summary":"Removes all system, data and physical access for departing staff on time, and recovers company devices and data.","tags":["offboarding","leaver","deprovisioning","termination","account disable","exit"],"purpose":"To protect company systems and data by removing a leaver's access no later than their last working moment. It also ensures company data and devices are recovered and handed over.","scope":"Covers employees, contractors, interns and agency staff leaving voluntarily or involuntarily, and role changes that remove access. It does not cover final pay, benefits or exit interviews, which HR handles separately.","definitions":[["Leaver date","The final working day and time agreed by HR."],["Immediate removal","Disabling access within 1 hour, used for involuntary or high-risk exits."],["Data handover","Transfer of files, mailboxes and ownership of shared assets to a named successor."]],"roles":[["HR Coordinator","Notifies IT of the leaver and exit type, and confirms the leaver date."],["Line Manager","Names the successor for data and confirms which assets must be transferred."],["IT Administrator","Disables accounts, revokes tokens, transfers data and recovers devices."],["System Owner","Removes access in applications not connected to SSO."],["Security Lead","Handles high-risk exits and reviews logs where misuse is suspected."]],"prereqs":["Leaver ticket in [ticketing tool] with exit type","Asset register showing devices assigned to the person","List of non-SSO applications and their owners","Admin access to [IdP tool], email and device management"],"steps":[{"t":"Notify IT of the leaver","d":"HR opens the leaver ticket as soon as notice is given, and within 1 hour of a decision for involuntary exits. Mark the exit as standard or high risk.","o":"HR Coordinator"},{"t":"Plan the handover","d":"The manager names a successor for files, mailbox and shared documents, and lists any shared credentials the person knew, at least 3 business days before the leaver date where possible.","o":"Line Manager"},{"t":"Schedule the disable","d":"For standard exits, schedule the account disable for the agreed end time on the leaver date. For high-risk exits, disable immediately while the person is in the exit meeting.","o":"IT Administrator"},{"t":"Disable identity and revoke sessions","d":"Disable the account in [IdP tool], sign out all sessions, revoke OAuth and API tokens and reset the password. Remove MFA devices.","o":"IT Administrator"},{"t":"Remove non-SSO access","d":"Each System Owner removes the person from applications outside SSO, including finance, banking and cloud consoles, within 4 business hours and confirms in the ticket.","o":"System Owner"},{"t":"Rotate shared secrets","d":"Rotate any shared passwords, API keys, Wi-Fi keys or door codes the leaver knew within 1 business day.","o":"IT Administrator"},{"t":"Transfer data ownership","d":"Transfer drive files and shared documents to the successor and convert the mailbox to a shared mailbox or set an auto-reply and forward for [30] days.","o":"IT Administrator"},{"t":"Recover devices","d":"Collect laptop, phone, tokens and badges on the last day or arrange prepaid courier return within 5 business days. Remote-lock devices not returned by then.","o":"IT Administrator"},{"t":"Wipe and reassign devices","d":"Back up any required data, securely wipe returned devices and update the asset register status.","o":"IT Administrator"},{"t":"Review activity for high-risk exits","d":"For high-risk exits, review the last 30 days of download, export and forwarding activity and record findings.","o":"Security Lead"},{"t":"Delete or archive the account","d":"Keep the account disabled for [30] days, then delete or archive in line with the data retention policy.","o":"IT Administrator"}],"checks":["Account disabled at or before the leaver time","All non-SSO systems confirmed removed in the ticket","Shared secrets rotated and logged","All assigned devices returned or remotely locked","Mail forwarding rules set by the leaver have been removed"],"kpis":[["Timely disable","100% of accounts disabled by the leaver time"],["Non-SSO removal","100% within 4 business hours"],["Device recovery","95% of devices returned within 5 business days"],["Orphan accounts found in audit","Zero per quarter"]],"risks":[["Former staff keep access to cloud apps","Monthly reconciliation of HR leaver list against all app user lists"],["Data taken before departure","Activity review for high-risk exits and data loss controls"],["Business data lost when mailbox is deleted","Successor transfer and retention period before deletion"],["Devices not returned","Remote lock, wipe and deduction from final settlement where local law allows"]],"related":["New User Access Provisioning","Employee Offboarding","Asset Management Policy","Data Retention Policy"],"review":"Every 12 months, or after any leaver-related security incident"},{"id":"it-password-mfa","dept":"it","title":"Password and Multi-factor Authentication","summary":"Sets and enforces password, password manager and MFA standards across all company accounts, including resets and lost devices.","tags":["password policy","mfa","2fa","two-factor","password manager","account reset"],"purpose":"To reduce account takeover by enforcing strong, unique passwords and multi-factor authentication for every user and system. It also defines a safe process for resets and lost authenticators.","scope":"Covers all staff and contractor accounts on company systems, shared and service accounts, and admin accounts. It does not cover customer passwords inside the company's own product, which are governed by product security standards.","definitions":[["MFA","Signing in with two or more factors, such as a password plus an authenticator app or security key."],["Phishing-resistant MFA","Hardware security keys or passkeys that cannot be replayed on a fake site."],["Password manager","The approved vault, [password manager], for storing and sharing credentials."],["Service account","A non-human account used by a system or integration."]],"roles":[["IT Administrator","Configures policies, handles resets and monitors compliance."],["Security Lead","Owns the standard and approves exceptions."],["Employee","Uses the password manager, keeps MFA devices secure and reports loss."],["Line Manager","Confirms the identity of team members requesting resets when needed."]],"prereqs":["Identity provider with enforceable password and MFA policies","Company licence for [password manager]","Security keys for admin users","Identity verification checklist for help desk resets"],"steps":[{"t":"Set the password standard","d":"Configure a minimum length of 14 characters for user accounts and 20 for admin and service accounts, block known breached passwords and disable forced periodic expiry unless compromise is suspected.","o":"Security Lead"},{"t":"Enforce MFA everywhere","d":"Require MFA for SSO, email, VPN, cloud consoles and any app holding company data. Disable SMS as a factor where an app or key is available.","o":"IT Administrator"},{"t":"Issue phishing-resistant keys to admins","d":"Give every admin and finance approver two hardware keys or passkeys, one primary and one stored securely as backup.","o":"IT Administrator"},{"t":"Roll out the password manager","d":"Provision every user in [password manager] on day one. Shared team credentials live only in shared vaults with named members.","o":"IT Administrator"},{"t":"Use the password manager daily","d":"Generate unique passwords for every work account and never reuse a work password elsewhere or store it in browsers, documents or chat.","o":"Employee"},{"t":"Verify identity before any reset","d":"For reset requests, verify the person by video call or in person plus one known fact, or by manager confirmation. Never reset based on an email or chat message alone.","o":"IT Administrator"},{"t":"Handle lost MFA devices","d":"When a user reports a lost phone or key, revoke that factor immediately, issue a temporary access code valid for no more than 24 hours and require re-enrolment.","o":"IT Administrator"},{"t":"Manage service account credentials","d":"Store service credentials in the vault or a secrets manager, rotate them every [12] months and on any staff departure who knew them.","o":"IT Administrator"},{"t":"Approve and log exceptions","d":"Any system that cannot support MFA needs a written exception with a compensating control and an expiry date no longer than 6 months.","o":"Security Lead"},{"t":"Monitor compliance monthly","d":"Run the MFA and password manager adoption report monthly and chase any non-compliant user within 2 business days.","o":"IT Administrator"}],"checks":["MFA enforced, not just enabled, at the IdP","Every admin has a backup phishing-resistant factor","No credentials found in shared drives or chat during quarterly scan","All exceptions have an owner and expiry date"],"kpis":[["MFA coverage","100% of user and admin accounts"],["Password manager adoption","95% of users active monthly"],["Reset identity verification","100% of resets have a recorded verification method"],["Open exceptions past expiry","Zero"]],"risks":[["Help desk social engineering","Strict identity verification and manager confirmation for resets"],["MFA fatigue push attacks","Use number matching and phishing-resistant factors for admins"],["Shared credentials leaking","Shared vaults with rotation on leaver events"],["Lockout of admin accounts","Backup keys and two break-glass accounts stored offline"]],"related":["New User Access Provisioning","Access Removal for Leavers","Phishing Report Handling","Information Security Policy"],"review":"Every 12 months, or after an account compromise or change of identity provider"},{"id":"it-backup-restore-testing","dept":"it","title":"Data Backup and Restore Testing","summary":"Keeps reliable, protected backups of critical data and proves they can be restored within agreed recovery targets.","tags":["backup","restore test","disaster recovery","rpo","rto","data protection"],"purpose":"To make sure critical business data can be recovered after deletion, ransomware, outage or error. Regular restore tests prove backups work rather than assuming they do.","scope":"Covers production databases, file storage, SaaS data such as email and documents, and critical configuration. It does not cover individual laptops beyond synced folders, or full site failover planning, which sits in the Business Continuity Plan.","definitions":[["RPO","Recovery Point Objective: the maximum acceptable data loss measured in time."],["RTO","Recovery Time Objective: the maximum acceptable time to restore service."],["Immutable backup","A copy that cannot be changed or deleted for a set period, even by an admin."],["3-2-1 rule","Three copies of data on two types of storage with one copy off-site or in a separate account."]],"roles":[["IT Administrator","Configures backup jobs, monitors results and runs restore tests."],["System Owner","Sets RPO and RTO for their system and validates restored data."],["Security Lead","Ensures backups are encrypted, immutable and access-restricted."],["Operations Manager","Receives test reports and approves remediation timelines."]],"prereqs":["Inventory of critical systems with RPO and RTO","Backup tool or service, e.g. [backup tool]","Separate backup storage account with restricted credentials","Restore test log template"],"steps":[{"t":"Classify systems and targets","d":"List each critical system with its owner, RPO and RTO. Typical targets: production database RPO 1 hour, RTO 4 hours; file storage RPO 24 hours, RTO 1 business day.","o":"System Owner"},{"t":"Configure backup jobs","d":"Set schedules that meet each RPO, enable encryption at rest and in transit and store copies in a separate account or region.","o":"IT Administrator"},{"t":"Protect the backups","d":"Enable immutability or object lock for at least [30] days, restrict backup deletion to two named admins and require MFA for the backup console.","o":"Security Lead"},{"t":"Back up SaaS data","d":"Use a SaaS backup service for email, documents and key business apps, since vendor recycle bins are not backups.","o":"IT Administrator"},{"t":"Monitor job results daily","d":"Review the backup dashboard every business day. Investigate any failed or partial job the same day and rerun within 24 hours.","o":"IT Administrator"},{"t":"Run monthly file-level restore tests","d":"Each month restore a random sample of at least 5 files or records from different systems to an isolated location and confirm they open correctly.","o":"IT Administrator"},{"t":"Run quarterly full restore tests","d":"Each quarter restore one critical system in full to a test environment, time the restore against the RTO and record the result.","o":"IT Administrator"},{"t":"Validate restored data","d":"The System Owner checks record counts, recent transactions and application behaviour on the restored copy and signs off in the test log.","o":"System Owner"},{"t":"Report and remediate gaps","d":"Report any test that misses RPO or RTO to the Operations Manager within 2 business days with a fix plan and date.","o":"Operations Manager"},{"t":"Update the inventory","d":"Add new systems to the backup inventory before go-live and remove retired ones after their retention period.","o":"IT Administrator"}],"checks":["Every critical system appears in the inventory with RPO and RTO","Backups stored in a separate account with immutability","Restore test log signed by the System Owner","Failed jobs investigated within one business day"],"kpis":[["Backup job success rate","99% per month"],["Restore tests completed","100% of scheduled monthly and quarterly tests"],["RTO achieved in tests","100% of quarterly tests within RTO"],["Systems without backup","Zero critical systems"]],"risks":[["Ransomware encrypts backups","Immutable, separately credentialed backup storage"],["Backups silently failing","Daily monitoring and alerting on failed jobs"],["Restore takes longer than expected","Timed quarterly full restores and documented runbooks"],["New systems missed","Backup check in the go-live and change process"]],"related":["Security Incident Response","IT Change Management","Business Continuity Plan","Data Retention Policy"],"review":"Every 12 months, or after a failed restore test or real recovery event"},{"id":"it-security-incident-response","dept":"it","title":"Security Incident Response","summary":"Detects, contains, investigates and recovers from security incidents in a controlled way, with clear severity levels and communication.","tags":["incident response","cyber attack","breach","malware","ransomware","compromise","csirt"],"purpose":"To limit the damage and recovery time of security incidents such as account compromise, malware or unauthorised access. It sets out who leads, how decisions are made and how evidence is preserved.","scope":"Covers suspected or confirmed security incidents affecting company systems, devices, accounts or data, including at suppliers that hold company data. It does not cover production outages without a security cause, which follow the Production Incident and On-call SOP.","definitions":[["Security incident","An event that threatens the confidentiality, integrity or availability of systems or data."],["Incident Lead","The person with authority to direct the response until closure."],["Containment","Actions that stop an incident spreading, such as isolating a device or disabling an account."],["Severity","SEV1 critical (active attack or data exposure), SEV2 high, SEV3 contained or low impact."]],"roles":[["Incident Lead","Declares severity, directs actions and approves closure."],["IT Administrator","Performs containment, evidence collection and recovery actions."],["Communications Owner","Handles internal updates and any customer or partner messages."],["Executive Sponsor","Approves major decisions such as shutting systems or engaging outside help."],["Data Protection Lead","Assesses whether personal data is involved and triggers breach notification."]],"prereqs":["Incident contact list with out-of-hours numbers","Incident log template and dedicated chat channel","Contracts or contacts for external forensic support and cyber insurer","Admin access to IdP, endpoint management and logging tools"],"steps":[{"t":"Report and log","d":"Anyone who suspects an incident reports it to [security email or channel] immediately. The first responder opens an incident log with time, reporter and what was seen.","o":"IT Administrator"},{"t":"Triage and assign severity","d":"Within 30 minutes, assess scope and assign SEV1 to SEV3. SEV1 incidents page the Incident Lead and Executive Sponsor at any hour.","o":"Incident Lead"},{"t":"Open the response channel","d":"Create a private incident channel and bridge, invite only those needed and record all decisions with timestamps in the log.","o":"Incident Lead"},{"t":"Contain the threat","d":"Isolate affected devices from the network, disable compromised accounts, revoke sessions and tokens and block malicious domains. For SEV1, aim to contain within 4 hours.","o":"IT Administrator"},{"t":"Preserve evidence","d":"Before wiping anything, export relevant logs, take disk or memory images where feasible and record hashes. Keep evidence in restricted storage.","o":"IT Administrator"},{"t":"Assess data impact","d":"Determine whether personal or confidential data was accessed or exfiltrated. If personal data may be involved, start the Personal Data Breach Notification SOP immediately.","o":"Data Protection Lead"},{"t":"Decide on outside help","d":"For SEV1 or where in-house skills are insufficient, the Executive Sponsor decides within 4 hours whether to engage forensic responders and notify the cyber insurer.","o":"Executive Sponsor"},{"t":"Eradicate the cause","d":"Remove malware, close the exploited weakness, patch systems and reset all credentials that may be exposed.","o":"IT Administrator"},{"t":"Recover services","d":"Restore from clean backups where needed, monitor closely for 72 hours for signs of return and confirm normal operation with system owners.","o":"IT Administrator"},{"t":"Communicate","d":"Send internal updates at least every 4 hours for SEV1 and daily for SEV2. Customer or partner messages are approved by the Incident Lead and Executive Sponsor before sending.","o":"Communications Owner"},{"t":"Close and review","d":"Close the incident when contained, eradicated and recovered. Hold a blameless review within 10 business days and track actions to completion.","o":"Incident Lead"}],"checks":["Incident log has timestamps for detection, containment and recovery","Evidence preserved before systems are rebuilt","Data protection assessment recorded for every incident","Post-incident actions have owners and due dates"],"kpis":[["Time to triage","Within 30 minutes for 95% of reports"],["Time to contain SEV1","Within 4 hours"],["Review completion","100% of SEV1 and SEV2 reviewed within 10 business days"],["Repeat incidents from same cause","Zero within 12 months"]],"risks":[["Evidence destroyed during cleanup","Mandatory evidence step before eradication"],["Attacker monitoring company chat or email","Use an out-of-band channel for SEV1 incidents"],["Regulatory deadlines missed","Early involvement of the Data Protection Lead"],["Confusion over who is in charge","Single named Incident Lead per incident"]],"related":["Personal Data Breach Notification","Phishing Report Handling","Data Backup and Restore Testing","Blameless Post-mortem","Information Security Policy"],"review":"Every 12 months, after every SEV1 incident, or after an annual tabletop exercise"},{"id":"it-software-patching","dept":"it","title":"Software Patching and Updates","summary":"Applies security and software updates to devices, servers and applications within set timeframes based on severity.","tags":["patch management","updates","vulnerability","security patches","os updates","cve"],"purpose":"To close known security weaknesses quickly and keep systems supported and stable. Patching timeframes are tied to risk so critical issues are fixed first.","scope":"Covers operating systems, browsers, office software, network devices, servers and third-party applications on company-managed devices. It does not cover application code dependencies in the product, which follow the Third-party API and Dependency Updates SOP.","definitions":[["Critical patch","A fix for a vulnerability rated critical or known to be actively exploited."],["Patch window","The agreed time when updates may restart devices or services."],["Pilot group","A small set of users or servers that receive updates first to catch problems."],["End of life (EOL)","Software no longer receiving security updates from its vendor."]],"roles":[["IT Administrator","Approves, deploys and monitors patches."],["Security Lead","Rates vulnerability severity and approves deferrals."],["System Owner","Tests critical business systems after patches."],["Employee","Restarts devices when prompted and reports issues."]],"prereqs":["Device management tool, e.g. [MDM tool], covering all company devices","Asset inventory with OS and software versions","Vendor security advisory subscriptions","Defined patch windows and pilot group"],"steps":[{"t":"Monitor advisories","d":"Check vendor advisories and the vulnerability scanner at least weekly, and daily for products flagged as actively exploited.","o":"Security Lead"},{"t":"Rate and set deadlines","d":"Assign each patch a deadline: actively exploited or critical within 72 hours, high within 14 days, medium within 30 days, low at next routine cycle.","o":"Security Lead"},{"t":"Test with the pilot group","d":"Deploy non-emergency patches to the pilot group first and wait 2 business days for issues before wider rollout.","o":"IT Administrator"},{"t":"Deploy to all devices","d":"Push updates through [MDM tool] with automatic install and a forced restart deadline of 48 hours after release to users.","o":"IT Administrator"},{"t":"Restart when prompted","d":"Save work and restart within the deadline. Report any application failure after an update to the help desk.","o":"Employee"},{"t":"Patch servers and network devices","d":"Apply server and network updates during the agreed patch window after a fresh backup or snapshot, and check services afterwards.","o":"IT Administrator"},{"t":"Verify critical business systems","d":"After patching systems that support finance, sales or production, the System Owner runs a short functional check and confirms within 1 business day.","o":"System Owner"},{"t":"Chase non-compliant devices","d":"Report devices missing patches beyond the deadline weekly. Devices more than 14 days overdue on a critical patch lose access to company apps until updated.","o":"IT Administrator"},{"t":"Approve deferrals","d":"Any patch delayed past its deadline needs a written deferral with reason, compensating control and new date, approved by the Security Lead.","o":"Security Lead"},{"t":"Plan end-of-life replacements","d":"Review the inventory quarterly for software or hardware reaching end of life within 6 months and raise replacement requests.","o":"IT Administrator"}],"checks":["All devices enrolled in device management","Critical patches deployed within 72 hours","Deferrals documented and approved","No end-of-life operating systems in use without an approved exception"],"kpis":[["Critical patch compliance","95% of devices within 72 hours"],["High patch compliance","95% within 14 days"],["Unmanaged devices","Zero"],["Patch-related outages","Fewer than 1 per quarter"]],"risks":[["Exploit of an unpatched system","Severity-based deadlines and access blocking for overdue devices"],["Update breaks a business system","Pilot group, snapshots and rollback plan"],["Unknown devices not patched","Inventory reconciliation against network and SSO logs"],["Users postponing restarts indefinitely","Forced restart deadline"]],"related":["IT Change Management","Laptop and Device Setup","Data Backup and Restore Testing","Vulnerability Management Policy"],"review":"Every 12 months, or after an incident caused by a missing or faulty patch"},{"id":"it-laptop-device-setup","dept":"it","title":"Laptop and Device Setup","summary":"Prepares, secures and hands over company laptops and phones to a consistent standard, and tracks them in the asset register.","tags":["laptop setup","device provisioning","mdm","hardware","asset register","new starter"],"purpose":"To give every user a secure, working device that meets the company security baseline from the moment they receive it. It also keeps an accurate record of who holds which asset.","scope":"Covers company-owned laptops, desktops, tablets and phones for staff and contractors, whether issued in office or shipped. It does not cover personal devices used for work, which follow the Bring Your Own Device Policy.","definitions":[["Baseline","The minimum security configuration every device must meet."],["Zero-touch enrolment","Automatic device management enrolment when the device first connects to the internet."],["Asset tag","A unique ID recorded in the asset register and labelled on the device."]],"roles":[["IT Administrator","Orders, configures, ships and records devices."],["Hiring Manager","Requests the device type and confirms delivery address in time."],["Employee","Signs for the device, completes first sign-in and looks after it."],["Finance Officer","Approves purchases above [amount] and records the asset for depreciation."]],"prereqs":["Approved hardware catalogue by role","Device management tool with zero-touch enrolment","Security baseline checklist","Asset register and acceptable use policy"],"steps":[{"t":"Request the device","d":"The manager selects the standard device for the role from the catalogue at least 10 business days before the start date. Non-standard requests include a business reason.","o":"Hiring Manager"},{"t":"Approve and order","d":"Order from approved suppliers. Purchases above [amount] or outside the catalogue need Finance approval before ordering.","o":"Finance Officer"},{"t":"Register the asset","d":"On receipt, record serial number, model, cost, purchase date and asset tag in the register and assign it to the user.","o":"IT Administrator"},{"t":"Enrol in device management","d":"Enrol via zero-touch or manually so the device is managed before first user sign-in.","o":"IT Administrator"},{"t":"Apply the security baseline","d":"Confirm full-disk encryption, screen lock after 5 minutes, firewall, endpoint protection, automatic updates and no local admin rights for standard users.","o":"IT Administrator"},{"t":"Install standard software","d":"Deploy the role's standard applications through device management. Do not install unlicensed or personal software.","o":"IT Administrator"},{"t":"Test before handover","d":"Sign in with a test account, confirm Wi-Fi, VPN, camera, microphone and printing work, and check the baseline report shows compliant.","o":"IT Administrator"},{"t":"Ship or hand over securely","d":"Ship with tracking and signature on delivery to arrive 2 business days before start, or hand over in person. Send the activation details separately.","o":"IT Administrator"},{"t":"Accept and complete first sign-in","d":"The employee signs the device acceptance form, completes first sign-in and MFA setup and reports any damage within 1 business day.","o":"Employee"},{"t":"Reconcile the register","d":"Each quarter, compare the asset register with device management and chase devices that have not checked in for 30 days.","o":"IT Administrator"}],"checks":["Device encrypted and compliant before handover","User has no local admin rights unless approved","Signed acceptance form on file","Asset register matches device management records"],"kpis":[["Device ready on day one","98% of starters"],["Baseline compliance","100% of active devices"],["Register accuracy","99% match in quarterly reconciliation"],["Lost or stolen devices unencrypted","Zero"]],"risks":[["Lost device exposes data","Encryption, remote lock and remote wipe"],["Shipping theft or misdelivery","Tracked, signed delivery and activation details sent separately"],["Untracked assets","Quarterly reconciliation and check-in monitoring"],["Users installing risky software","No local admin and an app approval process"]],"related":["New User Access Provisioning","Software Patching and Updates","Access Removal for Leavers","Acceptable Use Policy"],"review":"Every 12 months, or after a device loss incident or change of device management tool"},{"id":"it-phishing-report-handling","dept":"it","title":"Phishing Report Handling","summary":"Handles staff reports of suspicious emails and messages quickly, removes threats from all inboxes and supports anyone who clicked.","tags":["phishing","suspicious email","spam","social engineering","email security","report phish"],"purpose":"To turn staff reports of suspicious messages into fast action that protects the whole company. It also makes sure people who clicked a link feel safe to report it straight away.","scope":"Covers suspicious emails, text messages, chat messages and calls received by staff on company accounts or about company business. It does not cover customer-reported scams impersonating the company, which go to the Communications Owner and Security Incident Response.","definitions":[["Phishing","A message designed to trick someone into giving credentials, money or access, or opening malware."],["Business email compromise","A scam impersonating an executive or supplier to redirect payments."],["Indicator","A sender address, domain, link or attachment hash linked to a phishing attempt."]],"roles":[["Employee","Reports suspicious messages using the report button and does not forward them to colleagues."],["IT Administrator","Analyses reports, purges messages and blocks indicators."],["Security Lead","Escalates confirmed compromise and runs awareness training."],["Finance Officer","Verifies any payment or bank detail change by phone using known contacts."]],"prereqs":["Report-phish button or [phishing mailbox] set up in the email client","Admin rights to search and purge mail across the tenant","Blocklist access on email gateway and web filter","Response templates for reporters"],"steps":[{"t":"Report the message","d":"Use the report button or forward as an attachment to [phishing mailbox]. Do not click links, reply or forward to colleagues.","o":"Employee"},{"t":"Tell IT immediately if you interacted","d":"If you clicked a link, entered a password, opened an attachment or approved an MFA prompt, call or message IT straight away. There is no blame for reporting.","o":"Employee"},{"t":"Triage within 1 business hour","d":"Classify each report as phishing, spam, simulation or legitimate. Prioritise reports where someone interacted.","o":"IT Administrator"},{"t":"Search and purge","d":"For confirmed phishing, search all mailboxes for the same sender, subject or link and remove every copy within 2 hours.","o":"IT Administrator"},{"t":"Block indicators","d":"Add sender domains, URLs and attachment hashes to the email gateway and web filter blocklists.","o":"IT Administrator"},{"t":"Secure affected accounts","d":"For anyone who entered credentials, reset the password, revoke sessions, check for new mail forwarding rules and review sign-in logs for the past 7 days.","o":"IT Administrator"},{"t":"Check payment fraud attempts","d":"If the message requested a payment or bank detail change, Finance verifies with the supplier using a previously known phone number before any action.","o":"Finance Officer"},{"t":"Escalate confirmed compromise","d":"If any account or device is confirmed compromised, open a security incident under the Security Incident Response SOP.","o":"Security Lead"},{"t":"Respond to the reporter","d":"Thank the reporter and tell them the outcome within 1 business day to encourage future reporting.","o":"IT Administrator"},{"t":"Review trends and train","d":"Monthly, review report volumes and themes and share a short awareness note. Run phishing simulations at least quarterly.","o":"Security Lead"}],"checks":["Reports with user interaction handled within 1 hour","All copies of confirmed phishing purged","Mail forwarding rules checked on any compromised account","Payment change requests verified by phone"],"kpis":[["Triage time","90% of reports within 1 business hour"],["Report rate in simulations","Above 60% of recipients report"],["Click rate in simulations","Below 5%"],["Payment fraud losses","Zero"]],"risks":[["Staff hide clicks out of fear","No-blame reporting culture and quick, supportive response"],["Same phish reaches many inboxes","Tenant-wide search and purge"],["Fraudulent supplier bank change","Mandatory call-back verification"],["Report fatigue","Feedback to reporters and simple one-click reporting"]],"related":["Security Incident Response","Password and Multi-factor Authentication","Supplier Bank Detail Change","Security Awareness Training"],"review":"Every 12 months, or after a successful phishing attack"},{"id":"it-personal-data-breach-notification","dept":"it","title":"Personal Data Breach Notification","summary":"Assesses personal data breaches and notifies regulators and affected people within legal deadlines, with a full record kept.","tags":["data breach","gdpr","privacy","breach notification","regulator","personal data","dpo"],"purpose":"To meet legal obligations when personal data is lost, stolen, exposed or altered without authorisation. It ensures a consistent risk assessment and timely, accurate notifications.","scope":"Covers breaches of personal data about customers, staff, candidates and other individuals, whether caused internally, by attackers or by suppliers processing data for the company. It does not cover the technical investigation itself, which follows Security Incident Response.","definitions":[["Personal data breach","A security incident leading to accidental or unlawful destruction, loss, alteration, disclosure of or access to personal data."],["Awareness","The point the company has a reasonable degree of certainty a breach has occurred; many laws, such as GDPR, start the clock here."],["Supervisory authority","The data protection regulator for the relevant jurisdiction."],["High risk","A breach likely to cause significant harm to individuals, such as fraud, discrimination or distress."]],"roles":[["Data Protection Lead","Owns the assessment, notification decision and breach register."],["Incident Lead","Provides technical facts on what data, how many people and current status."],["Legal Adviser","Advises on legal obligations across jurisdictions and reviews notices."],["Executive Sponsor","Approves notifications and external statements."],["Communications Owner","Prepares and sends notices to affected individuals and handles enquiries."]],"prereqs":["Breach register and assessment template","Contact details and online forms for relevant supervisory authorities","Records of processing showing data categories and locations","Supplier contracts with breach notice clauses","Notice templates for regulators and individuals"],"steps":[{"t":"Record awareness time","d":"As soon as a possible personal data breach is reported, log the date and time of awareness in the breach register. This starts any legal clock.","o":"Data Protection Lead"},{"t":"Gather the facts","d":"Within 24 hours, establish what data types, how many individuals and records, which countries, cause, whether data was encrypted and whether it is contained.","o":"Incident Lead"},{"t":"Assess the risk to individuals","d":"Score likelihood and severity of harm, considering sensitivity, volume, identifiability and the ability to misuse the data. Record the reasoning.","o":"Data Protection Lead"},{"t":"Confirm legal obligations","d":"Identify which laws apply based on where affected people live. Check local law for deadlines; for example GDPR requires regulator notice within 72 hours of awareness where there is a risk.","o":"Legal Adviser"},{"t":"Decide on regulator notification","d":"If notification is required, prepare it with the facts known so far. Do not delay to wait for complete information; send updates in phases if needed.","o":"Data Protection Lead"},{"t":"Approve and submit","d":"The Executive Sponsor approves the regulator notice and the Data Protection Lead submits it before the deadline, saving the confirmation.","o":"Executive Sponsor"},{"t":"Notify affected individuals","d":"Where risk is high, send clear notices without undue delay describing what happened, likely consequences, what the company is doing and steps people can take.","o":"Communications Owner"},{"t":"Notify business customers if a processor","d":"Where the company processes data on behalf of a client, notify the client within the contract timeframe, typically 24 to 48 hours, so they can meet their own duties.","o":"Data Protection Lead"},{"t":"Handle enquiries","d":"Set up a dedicated contact route and scripted answers for individuals and journalists. Log all enquiries.","o":"Communications Owner"},{"t":"Close and record lessons","d":"Record the final facts, decisions, notifications and remedial actions in the breach register, including breaches that were not notified and why.","o":"Data Protection Lead"}],"checks":["Awareness time recorded for every breach","Risk assessment reasoning documented, including for non-notified breaches","Regulator notices sent within the applicable deadline","Individual notices reviewed by legal before sending"],"kpis":[["Notifications on time","100% within legal deadlines"],["Initial assessment completed","Within 24 hours of awareness"],["Register completeness","100% of breaches recorded"],["Repeat breaches from same cause","Zero within 12 months"]],"risks":[["Missing the legal deadline","Awareness time logged immediately and a phased notification approach"],["Over or under-stating the breach","Fact-based notices with updates as investigation progresses"],["Supplier breach not reported to the company","Contract clauses and supplier contact checks"],["Inconsistent messages","Single approved statement and enquiry script"]],"related":["Security Incident Response","Data Protection Policy","Records of Processing Activities","Supplier Due Diligence"],"review":"Every 12 months, after any notified breach, or when data protection law changes"},{"id":"it-change-management","dept":"it","title":"IT Change Management","summary":"Plans, approves, schedules and records changes to IT systems so they happen safely with minimal disruption.","tags":["change control","change request","cab","maintenance window","it operations","configuration change"],"purpose":"To reduce outages and security gaps caused by uncontrolled changes to infrastructure and business systems. It balances speed with a level of review that matches the risk.","scope":"Covers changes to networks, servers, cloud infrastructure, identity, email, security tooling and configuration of business SaaS systems. It does not cover product code releases, which follow the Product Release SOP, or routine standard changes listed in the pre-approved catalogue.","definitions":[["Standard change","A low-risk, repeatable change with a pre-approved procedure."],["Normal change","A change that needs assessment and approval before it is made."],["Emergency change","A change needed urgently to restore service or close a serious security gap."],["Change Advisory Board (CAB)","The small group that reviews normal changes, usually weekly."]],"roles":[["Change Requester","Raises the change with plan, risk and rollback."],["Change Manager","Reviews requests, chairs CAB and keeps the change calendar."],["Approver","System Owner or manager who approves the change for their area."],["Implementer","Carries out and verifies the change."]],"prereqs":["Change request form in [ticketing tool]","Change calendar and freeze periods","Standard change catalogue","Current backups or snapshots for affected systems"],"steps":[{"t":"Raise the change request","d":"Describe what, why, systems affected, implementation steps, test plan, rollback plan and proposed time. Submit normal changes at least 3 business days before the date.","o":"Change Requester"},{"t":"Classify the change","d":"Classify as standard, normal or emergency and rate risk as low, medium or high based on impact and likelihood of failure.","o":"Change Manager"},{"t":"Assess and approve","d":"Low-risk normal changes need one Approver. Medium and high-risk changes go to the weekly CAB and need Approver plus Change Manager sign-off.","o":"Approver"},{"t":"Check the calendar","d":"Confirm no conflict with other changes, business peaks or freeze periods such as month-end close. Notify affected users at least 2 business days ahead.","o":"Change Manager"},{"t":"Prepare and back up","d":"Take a backup or snapshot, confirm access and have the rollback steps ready before the window opens.","o":"Implementer"},{"t":"Implement in the window","d":"Make the change during the approved window, following the plan. Stop and roll back if a step fails or the window is exceeded by more than 30 minutes.","o":"Implementer"},{"t":"Verify the outcome","d":"Run the test plan, check monitoring and confirm with a user or System Owner that the service works.","o":"Implementer"},{"t":"Handle emergency changes","d":"For emergencies, get verbal approval from the Change Manager or on-call manager, implement, then raise the retrospective record within 1 business day.","o":"Change Requester"},{"t":"Close and record","d":"Update the ticket with actual steps, result and any issues, and update configuration documentation.","o":"Implementer"},{"t":"Review failed changes","d":"Review any change that caused an incident or was rolled back at the next CAB and capture lessons.","o":"Change Manager"}],"checks":["Every normal change has a rollback plan before approval","No changes during freeze periods without Executive approval","Emergency changes have a retrospective record within 1 business day","Configuration documentation updated on closure"],"kpis":[["Change success rate","95% without incident or rollback"],["Unauthorised changes found","Zero per quarter"],["Emergency change share","Below 10% of all changes"],["Change-caused incidents","Fewer than 2 per quarter"]],"risks":[["Change causes an outage","Risk rating, testing, backups and rollback plans"],["Bypassing the process","Admin activity logs reviewed against approved changes"],["Conflicting changes","Shared change calendar"],["Process too slow for small fixes","Standard change catalogue for repeatable work"]],"related":["Software Patching and Updates","Product Release","Data Backup and Restore Testing","Security Incident Response"],"review":"Every 12 months, or after a major change-related outage"},{"id":"it-saas-software-approval","dept":"it","title":"New Software and SaaS Approval","summary":"Evaluates and approves new software and SaaS tools for security, privacy, cost and fit before anyone signs up or shares data.","tags":["saas approval","software request","vendor security","shadow it","procurement","tool evaluation"],"purpose":"To prevent unmanaged tools from exposing company data, duplicating spend or creating compliance gaps. It gives teams a clear, fast route to get the tools they need.","scope":"Covers new paid or free software, SaaS subscriptions, browser extensions, AI tools and integrations that handle company data or connect to company systems. It does not cover renewals of already approved tools, except where data use or terms change materially.","definitions":[["Shadow IT","Software used for company work without approval or IT knowledge."],["Data classification","Public, internal, confidential or restricted, based on sensitivity."],["Security review","A check of vendor controls, certifications such as SOC 2 or ISO 27001, and data handling terms."],["DPA","Data Processing Agreement setting out how a vendor handles personal data."]],"roles":[["Requester","Submits the request with business need, data involved and budget."],["IT Administrator","Checks for overlap, SSO support and integration needs."],["Security Lead","Performs the security and privacy review based on data classification."],["Finance Officer","Confirms budget and contract terms."],["Budget Owner","Approves spend and accepts residual risk for their team."]],"prereqs":["Software request form in [ticketing tool]","Approved software list","Vendor security questionnaire","Data classification policy"],"steps":[{"t":"Check the approved list","d":"Before requesting, check whether an approved tool already meets the need. If so, request access to that tool instead.","o":"Requester"},{"t":"Submit the request","d":"Describe the business need, number of users, data the tool will hold or access, integrations needed, cost and the alternatives considered.","o":"Requester"},{"t":"Check overlap and fit","d":"Within 2 business days, confirm whether it duplicates an existing tool, supports SSO and MFA, and can be centrally administered.","o":"IT Administrator"},{"t":"Classify the data and set review depth","d":"Public or internal data needs a light review. Confidential, personal or restricted data needs a full security review and DPA.","o":"Security Lead"},{"t":"Review vendor security and privacy","d":"Review certifications, questionnaire answers, data location, sub-processors, retention and breach notice terms. Complete within 5 business days for full reviews.","o":"Security Lead"},{"t":"Review commercial terms","d":"Check price, auto-renewal, notice periods, liability and data export on exit. Contracts above [amount] or longer than 12 months need Finance sign-off.","o":"Finance Officer"},{"t":"Approve or reject","d":"The Budget Owner approves with the review findings attached. Rejections include a reason and any approved alternative.","o":"Budget Owner"},{"t":"Set up centrally","d":"Purchase on a company account, connect to SSO, assign an internal owner and add the tool to the approved list with its data classification.","o":"IT Administrator"},{"t":"Schedule renewal review","d":"Add the renewal date to the calendar with a 60-day reminder to review usage, cost and security status.","o":"Finance Officer"},{"t":"Detect unapproved tools","d":"Quarterly, review expense claims, SSO logs and browser extension reports for unapproved tools and bring them through this process or remove them.","o":"IT Administrator"}],"checks":["Every tool holding confidential data has a completed security review and DPA","All approved tools use company accounts and SSO where available","Approved list shows owner, data class and renewal date","Expense claims for software matched to approved list"],"kpis":[["Request turnaround","Light reviews within 3 business days, full within 10"],["Tools on SSO","90% of approved tools"],["Unapproved tools found per quarter","Decreasing trend"],["Unused licences","Below 10% of paid seats"]],"risks":[["Data shared with an insecure vendor","Risk-based security review before any data is uploaded"],["Duplicate tools and wasted spend","Overlap check and approved list"],["Auto-renewal surprises","Renewal calendar with 60-day reminders"],["Slow process drives shadow IT","Clear turnaround targets and light review path"]],"related":["Vendor Onboarding","Supplier Due Diligence","Data Protection Policy","Third-party API and Dependency Updates"],"review":"Every 12 months, or after a supplier-related security incident"},{"id":"product-release","dept":"product","title":"Product Release","summary":"Moves a tested product version into production in a controlled, communicated way with a clear go or no-go decision.","tags":["release","deployment","go live","launch","release notes","ship"],"purpose":"To ship product changes to customers reliably and predictably. It makes sure every release is tested, approved, monitored and communicated.","scope":"Covers scheduled releases of web, mobile and API products to production, including feature flags and staged rollouts. It does not cover emergency hotfixes during an incident, which follow Production Incident and On-call, or infrastructure changes, which follow IT Change Management.","definitions":[["Release candidate","The build intended for production after passing tests."],["Feature flag","A switch that turns a feature on or off without redeploying."],["Staged rollout","Releasing to a small percentage of users first, then expanding."],["Go or no-go","The final decision meeting or check before release."]],"roles":[["Release Manager","Coordinates the release, runs the go or no-go check and owns the release record."],["Engineering Lead","Confirms code quality, tests and deployment readiness."],["QA Lead","Confirms test results and known issues."],["Product Manager","Confirms scope, writes release notes and approves customer messaging."],["Support Lead","Prepares the support team for changes and monitors tickets after release."]],"prereqs":["Release candidate built from the main branch","Passing automated test suite and QA sign-off","Release notes draft","Rollback plan and monitoring dashboards","Release calendar showing freeze dates"],"steps":[{"t":"Freeze the scope","d":"Lock the release scope at least 2 business days before the release date. Anything not merged and tested by then moves to the next release.","o":"Product Manager"},{"t":"Cut the release candidate","d":"Create the release branch or tag from main and deploy it to staging.","o":"Engineering Lead"},{"t":"Run regression and acceptance tests","d":"Run the full automated suite plus manual tests on critical user journeys such as sign-up, login, payment and core workflows. Record results.","o":"QA Lead"},{"t":"Review known issues","d":"List open defects in the release. Any critical or high-severity defect blocks release unless the Product Manager accepts it in writing with a workaround.","o":"QA Lead"},{"t":"Prepare support and customers","d":"Share release notes and a short briefing with support at least 1 business day before. Draft customer-facing notes for changes users will notice.","o":"Support Lead"},{"t":"Hold the go or no-go check","d":"Confirm tests passed, rollback plan ready, on-call engineer available and no clash with business events. Record the decision and approvers.","o":"Release Manager"},{"t":"Deploy with a staged rollout","d":"Deploy during the agreed window, avoiding Fridays and late afternoons, and release to 5 to 10% of users or behind a flag first where possible.","o":"Engineering Lead"},{"t":"Monitor and expand","d":"Watch error rate, latency and key business metrics for at least 30 minutes. Expand to 100% only if metrics stay within normal ranges.","o":"Engineering Lead"},{"t":"Roll back if thresholds breach","d":"If error rate rises above [threshold] or a critical journey fails, roll back under the Deployment Rollback SOP without waiting for further approval.","o":"Release Manager"},{"t":"Publish release notes","d":"Publish the changelog or customer notes and tell internal teams the release is complete.","o":"Product Manager"},{"t":"Watch support signals","d":"Monitor support tickets and feedback for 48 hours and flag any spike linked to the release.","o":"Support Lead"},{"t":"Close the release record","d":"Record version, date, scope, approvers, issues found and any follow-up actions.","o":"Release Manager"}],"checks":["No critical defects open without written acceptance","Rollback tested or confirmed possible before deploy","On-call engineer named for 24 hours after release","Release notes published within 1 business day"],"kpis":[["Change failure rate","Below 15% of releases need rollback or hotfix"],["Release on schedule","90% of releases on planned date"],["Post-release critical bugs","Fewer than 1 per release"],["Time to restore after bad release","Under 1 hour"]],"risks":[["Bad release reaches all users","Staged rollout and feature flags"],["Support unprepared for changes","Briefing and notes before release"],["Scope creep delays release","Scope freeze 2 business days before"],["Release during low staffing","Release windows that avoid Fridays and holidays"]],"related":["Deployment Rollback","Code Review and Merge","Production Incident and On-call","Product Requirements Sign-off"],"review":"Every 12 months, or after a release causes a SEV1 incident"},{"id":"product-code-review-merge","dept":"product","title":"Code Review and Merge","summary":"Ensures every code change is reviewed, tested and merged consistently so quality, security and knowledge-sharing improve.","tags":["code review","pull request","merge request","peer review","branch protection","git"],"purpose":"To catch defects and security issues before they reach production and to spread knowledge of the codebase. It sets clear expectations for authors and reviewers so reviews are fast and useful.","scope":"Covers all changes to product code, infrastructure as code and configuration stored in version control. It does not cover experimental branches never merged to main, or data changes made directly in production.","definitions":[["Pull request (PR)","A proposed change submitted for review before merging."],["Branch protection","Repository rules that block merging without approvals and passing checks."],["CODEOWNERS","A file naming who must review changes to specific areas."],["CI","Continuous integration: automated build, test and scan on each change."]],"roles":[["Author","Writes the change, tests it and responds to feedback."],["Reviewer","Reviews the change for correctness, design, security and readability."],["Code Owner","Approves changes to sensitive areas such as payments, auth or data models."],["Engineering Lead","Sets review standards and resolves disagreements."]],"prereqs":["Repository with branch protection on main","CI pipeline running tests, linting and dependency scans","PR template with description, testing and risk sections","CODEOWNERS file for sensitive areas"],"steps":[{"t":"Keep changes small","d":"Aim for PRs under about 400 changed lines with one purpose. Split large work behind feature flags.","o":"Author"},{"t":"Self-review and test","d":"Run tests locally, add or update tests for new behaviour, and read your own diff before requesting review.","o":"Author"},{"t":"Write a clear description","d":"Use the PR template: what changed, why, linked ticket, how it was tested, screenshots for UI changes and any risk or migration notes.","o":"Author"},{"t":"Pass automated checks","d":"Request review only after CI passes, including tests, linting, secret scanning and dependency checks.","o":"Author"},{"t":"Assign reviewers","d":"Request at least one reviewer. Changes to areas listed in CODEOWNERS automatically require the Code Owner.","o":"Author"},{"t":"Review within 1 business day","d":"Start the review within 1 business day. Check correctness, tests, security (input validation, auth, secrets), performance and readability.","o":"Reviewer"},{"t":"Give clear, labelled feedback","d":"Mark comments as blocking or optional. Explain the reason and suggest an alternative where possible. Keep comments about the code, not the person.","o":"Reviewer"},{"t":"Approve sensitive changes","d":"Changes to authentication, payments, permissions or personal data handling need Code Owner approval in addition to a peer review.","o":"Code Owner"},{"t":"Resolve feedback","d":"Address every blocking comment or reply with reasoning. Escalate disagreements that last more than 2 rounds to the Engineering Lead.","o":"Author"},{"t":"Merge and clean up","d":"Merge using the agreed strategy, such as squash merge, once approved and checks pass. Delete the branch and update the ticket.","o":"Author"},{"t":"Audit review practice","d":"Monthly, review metrics on review time and PR size and sample merged PRs to confirm standards are followed.","o":"Engineering Lead"}],"checks":["Main branch cannot be merged without approval and passing CI","No self-approval of own changes","Secrets scanning passes on every PR","Sensitive areas approved by a Code Owner"],"kpis":[["Time to first review","Median under 1 business day"],["PR size","80% of PRs under 400 changed lines"],["Escaped defects","Decreasing trend quarter on quarter"],["Merges bypassing review","Zero"]],"risks":[["Rubber-stamp approvals","Monthly sampling and review checklist"],["Review bottleneck on one person","Rotate reviewers and grow Code Owner pool"],["Secrets committed to repo","Automated secret scanning and immediate rotation"],["Large PRs hide defects","Size guidance and feature flags"]],"related":["Product Release","Third-party API and Dependency Updates","Bug Triage","Secure Development Policy"],"review":"Every 12 months, or after a production incident traced to a reviewed change"},{"id":"product-bug-triage","dept":"product","title":"Bug Triage","summary":"Captures, prioritises and assigns reported bugs consistently so the most harmful issues are fixed first.","tags":["bug triage","defect","issue tracking","severity","priority","qa"],"purpose":"To make sure every reported bug is reviewed, reproduced and prioritised by its real impact on users and the business. It prevents important issues being lost and stops low-value work crowding the backlog.","scope":"Covers bugs reported by customers, support, internal staff, QA and monitoring tools in the product. It does not cover feature requests, which follow Feature Request Intake, or live outages, which follow Production Incident and On-call.","definitions":[["Severity","Technical impact: S1 critical (data loss, security, core flow down), S2 major, S3 minor, S4 cosmetic."],["Priority","Order of fixing, P1 to P4, based on severity, users affected and business impact."],["Reproduction steps","The exact steps, environment and data needed to see the bug."]],"roles":[["Triage Lead","Runs triage sessions and confirms severity and priority."],["Support Lead","Logs customer-reported bugs with evidence and customer impact."],["QA Lead","Reproduces bugs and adds technical detail."],["Engineering Lead","Assigns bugs to engineers and protects capacity for fixes."],["Product Manager","Weighs business impact and decides on lower-priority trade-offs."]],"prereqs":["Issue tracker, e.g. [issue tracker], with a bug template","Severity and priority definitions published to all teams","Access to logs and test environments","Agreed bug fix capacity per sprint, e.g. 20%"],"steps":[{"t":"Log the bug","d":"Use the bug template: summary, steps to reproduce, expected and actual result, environment, screenshots or logs, number of users or accounts affected.","o":"Support Lead"},{"t":"Check for duplicates","d":"Search existing issues and link duplicates to the original, adding new customer references to show impact.","o":"QA Lead"},{"t":"Reproduce","d":"Attempt to reproduce within 1 business day. If not reproducible, request more information and set a 5 business day follow-up before closing.","o":"QA Lead"},{"t":"Escalate S1 bugs immediately","d":"Any bug causing data loss, security exposure or a broken core journey for many users is raised to on-call straight away, not left for the next triage session.","o":"Triage Lead"},{"t":"Set severity and priority","d":"In triage, at least twice weekly, confirm severity and assign priority using the matrix of impact and number of users.","o":"Triage Lead"},{"t":"Apply fix targets","d":"Target times: P1 within 2 business days, P2 within the current or next sprint, P3 within the quarter, P4 when convenient or close as won't fix.","o":"Product Manager"},{"t":"Assign an owner","d":"Assign P1 and P2 bugs to a named engineer with a target date. Keep P3 and P4 in the prioritised backlog.","o":"Engineering Lead"},{"t":"Update reporters","d":"Tell support the priority and target date so they can update customers. Update again when fixed.","o":"Support Lead"},{"t":"Verify the fix","d":"Confirm the fix in staging against the original steps and add a regression test where practical before closing.","o":"QA Lead"},{"t":"Review the backlog monthly","d":"Close bugs older than 6 months with no new reports unless still relevant, and look for patterns pointing to deeper problems.","o":"Product Manager"}],"checks":["Every bug has severity, priority and an owner or backlog position","S1 bugs escalated to on-call within 1 hour","Fixed bugs verified against original reproduction steps","Customers updated through support when bugs they reported are fixed"],"kpis":[["Time to triage","90% of new bugs triaged within 2 business days"],["P1 fix time","90% within 2 business days"],["Bug reopen rate","Below 5%"],["Open P1 and P2 bugs older than 30 days","Zero"]],"risks":[["Critical bug sits in the queue","Immediate S1 escalation outside triage sessions"],["Backlog grows without limit","Monthly cleanup and won't-fix decisions"],["Bugs crowd out roadmap work","Agreed bug capacity per sprint"],["Poor reports waste engineering time","Mandatory template and QA reproduction"]],"related":["Production Incident and On-call","Feature Request Intake","Sprint Planning","Customer Support Ticket Escalation"],"review":"Every 12 months, or when bug volume or reopen rate rises sharply"},{"id":"product-incident-on-call","dept":"product","title":"Production Incident and On-call","summary":"Runs a clear on-call rota and incident process so production outages are detected, fixed and communicated fast.","tags":["on-call","incident management","outage","pager","sev1","status page","sre"],"purpose":"To restore service quickly when the product is down or degraded and keep customers and colleagues informed. It also makes on-call fair and sustainable for engineers.","scope":"Covers outages, degraded performance and failed critical journeys in production services. It does not cover security incidents, which follow Security Incident Response, though both may run together.","definitions":[["SEV1","Product unavailable or a core journey broken for most users, or data at risk."],["SEV2","Major feature broken or serious degradation for a subset of users."],["SEV3","Minor issue with workaround and limited impact."],["Incident Commander","The person coordinating the response, not necessarily the one fixing it."]],"roles":[["On-call Engineer","Responds to alerts, triages and starts the fix."],["Incident Commander","Coordinates people, decisions and timeline for SEV1 and SEV2."],["Communications Owner","Updates the status page, support team and stakeholders."],["Engineering Lead","Maintains the rota, runbooks and escalation paths."],["Subject Matter Expert","Joins on request to fix a specific component."]],"prereqs":["On-call rota with primary and secondary in [paging tool]","Alerts tied to user-facing symptoms with runbook links","Status page and incident channel template","Access for on-call engineers to production logs, dashboards and deploy tools"],"steps":[{"t":"Maintain a fair rota","d":"Run weekly rotations with a primary and secondary, at least 4 people per rota where possible, with hand-over notes and compensation or time off per company policy.","o":"Engineering Lead"},{"t":"Acknowledge alerts","d":"Acknowledge pages within 5 minutes for SEV1 and 15 minutes for SEV2. If the primary does not acknowledge, the page escalates to the secondary automatically.","o":"On-call Engineer"},{"t":"Assess and declare severity","d":"Check dashboards and confirm user impact. Declare an incident and severity in the incident channel within 15 minutes of acknowledging.","o":"On-call Engineer"},{"t":"Appoint an Incident Commander","d":"For SEV1 and SEV2, appoint an Incident Commander separate from the main fixer where people are available.","o":"On-call Engineer"},{"t":"Stabilise first","d":"Prioritise restoring service over finding root cause: roll back recent deploys, disable feature flags, scale up or fail over.","o":"On-call Engineer"},{"t":"Bring in experts","d":"Page subject matter experts as needed and keep the channel focused. Record key actions and times as you go.","o":"Incident Commander"},{"t":"Communicate status","d":"Post a status page update within 30 minutes of a SEV1 and every 30 to 60 minutes after. Brief support with customer-facing wording.","o":"Communications Owner"},{"t":"Confirm resolution","d":"Confirm metrics are back to normal for at least 30 minutes and critical journeys work before declaring resolved.","o":"Incident Commander"},{"t":"Post the resolved notice","d":"Update the status page and internal channels with a short summary and any customer action required.","o":"Communications Owner"},{"t":"Hand off and schedule review","d":"Record a timeline summary and schedule a blameless post-mortem within 5 business days for SEV1 and SEV2.","o":"Incident Commander"},{"t":"Improve alerts and runbooks","d":"After each incident, fix noisy or missing alerts and update the runbook that should have helped.","o":"Engineering Lead"}],"checks":["Every page acknowledged or escalated automatically","Status page updated for every SEV1","Incident timeline recorded","Post-mortem scheduled for every SEV1 and SEV2"],"kpis":[["Time to acknowledge SEV1","Under 5 minutes"],["Mean time to restore SEV1","Under 1 hour"],["Monthly uptime","[99.9]% or the published SLA"],["Out-of-hours pages per on-call week","Fewer than 2"]],"risks":[["Alert fatigue causes missed pages","Alert on user-facing symptoms and remove noisy alerts"],["One person holds all knowledge","Runbooks and rotating experts"],["Customers learn of outages before the company","Synthetic monitoring and fast status updates"],["On-call burnout","Fair rota, compensation and limits on out-of-hours pages"]],"related":["Deployment Rollback","Blameless Post-mortem","Security Incident Response","Bug Triage"],"review":"Every 12 months, or after any SEV1 that missed response targets"},{"id":"product-deployment-rollback","dept":"product","title":"Deployment Rollback","summary":"Reverts a faulty deployment safely and quickly, including database and feature flag considerations, to restore a known-good state.","tags":["rollback","revert","bad deploy","release failure","recovery","hotfix"],"purpose":"To restore a stable product quickly when a deployment causes errors or harms users. It defines when to roll back, who decides and how to handle data changes safely.","scope":"Covers rollback of application deployments, configuration changes and feature flag releases in production. It does not cover infrastructure rebuilds or data restores from backup, which follow Data Backup and Restore Testing.","definitions":[["Rollback","Redeploying the previous known-good version."],["Roll forward","Fixing the issue with a new deployment instead of reverting."],["Backward-compatible migration","A database change that works with both old and new application versions."],["Kill switch","A feature flag used to turn off a feature instantly."]],"roles":[["On-call Engineer","Decides on and performs the rollback during or after a release."],["Release Manager","Coordinates communication and records the rollback."],["Engineering Lead","Approves roll forward instead of rollback and owns follow-up fixes."],["QA Lead","Verifies the restored version."]],"prereqs":["Previous release artefact available and deployable","Deploy tool with one-step rollback","Migration notes showing whether database changes are reversible","Dashboards for error rate, latency and key journeys"],"steps":[{"t":"Recognise rollback triggers","d":"Roll back when error rate exceeds [threshold], latency doubles for 10 minutes, a critical journey fails or data corruption is suspected.","o":"On-call Engineer"},{"t":"Decide fast","d":"Default to rollback. Roll forward only if the fix is known, small and can ship within 30 minutes, with Engineering Lead agreement.","o":"Engineering Lead"},{"t":"Try the kill switch first","d":"If the fault is in a flagged feature, turn the flag off and confirm recovery before redeploying.","o":"On-call Engineer"},{"t":"Check database compatibility","d":"Confirm the previous version works with the current schema. If a migration is not backward-compatible, do not roll back the schema without a tested down-migration.","o":"On-call Engineer"},{"t":"Announce the rollback","d":"Post in the release and incident channels that a rollback is starting, with the version numbers.","o":"Release Manager"},{"t":"Execute the rollback","d":"Redeploy the last known-good version using the deploy tool. Do not make manual changes on servers.","o":"On-call Engineer"},{"t":"Verify recovery","d":"Confirm error rates and latency return to baseline and run smoke tests on critical journeys within 15 minutes.","o":"QA Lead"},{"t":"Handle affected data","d":"Identify records created or changed by the faulty version and plan corrections with the Engineering Lead. Do not edit production data without a reviewed script.","o":"Engineering Lead"},{"t":"Block re-release","d":"Mark the faulty version as blocked in the release record until a fix has passed review and testing.","o":"Release Manager"},{"t":"Review and prevent","d":"Hold a short review or post-mortem and add tests or checks that would have caught the fault.","o":"Engineering Lead"}],"checks":["Rollback path confirmed before every release","Smoke tests pass after rollback","Faulty version blocked from redeploy","Data impact assessed and recorded"],"kpis":[["Time from trigger to rollback complete","Under 15 minutes"],["Rollback success rate","100% of rollbacks restore service"],["Releases with irreversible migrations without plan","Zero"]],"risks":[["Rollback breaks due to schema change","Backward-compatible migrations and expand-then-contract pattern"],["Delay while debating roll forward","Default to rollback rule and 30-minute limit"],["Data written by faulty version left wrong","Data impact step and reviewed correction scripts"],["Manual fixes create drift","Rollback only through the deploy tool"]],"related":["Product Release","Production Incident and On-call","Blameless Post-mortem","IT Change Management"],"review":"Every 12 months, or after a rollback that failed or took longer than 30 minutes"},{"id":"product-sprint-planning","dept":"product","title":"Sprint Planning","summary":"Plans each sprint with a clear goal, realistic capacity and ready backlog items so the team commits to work it can finish.","tags":["sprint planning","agile","scrum","backlog","iteration","capacity"],"purpose":"To give the team a focused, achievable plan for each sprint that supports product goals. It balances new features, bugs and technical work against real capacity.","scope":"Covers planning for product and engineering teams working in sprints of 1 to 3 weeks. It does not cover quarterly roadmap planning or teams working purely in a continuous flow model.","definitions":[["Sprint goal","One or two sentences describing what the sprint will achieve."],["Definition of ready","Criteria a backlog item must meet before it can be planned."],["Capacity","Available working days or points after leave, meetings and on-call."],["Velocity","Average work completed in recent sprints, used as a guide not a target."]],"roles":[["Product Manager","Brings a prioritised backlog and proposes the sprint goal."],["Engineering Lead","Confirms capacity, technical work and risks."],["Delivery Lead","Facilitates the session and keeps the board up to date."],["Team Member","Estimates work, raises concerns and commits to the plan."]],"prereqs":["Prioritised backlog with top items meeting the definition of ready","Team leave and on-call calendar","Velocity from the last 3 sprints","Outcomes from the previous sprint review and retrospective"],"steps":[{"t":"Refine the backlog beforehand","d":"Hold refinement at least 2 business days before planning so the top items have acceptance criteria, designs and estimates.","o":"Product Manager"},{"t":"Calculate capacity","d":"Work out available days per person after leave, holidays, on-call and fixed meetings. Plan to no more than 80% of the result.","o":"Engineering Lead"},{"t":"Reserve capacity for bugs and tech work","d":"Set aside an agreed share, e.g. 20%, for bugs and technical improvements before adding features.","o":"Engineering Lead"},{"t":"Propose the sprint goal","d":"State the goal and the outcome it supports. Keep it to one or two clear objectives.","o":"Product Manager"},{"t":"Select items","d":"Pull ready items in priority order until capacity is reached. Items not meeting the definition of ready stay in the backlog.","o":"Delivery Lead"},{"t":"Break down and estimate","d":"Split items into tasks no larger than 2 days and confirm estimates as a team. Flag dependencies on other teams or vendors.","o":"Team Member"},{"t":"Identify risks","d":"Note risks such as unclear requirements, external dependencies or key-person absence, and agree how to handle them.","o":"Engineering Lead"},{"t":"Commit to the plan","d":"Confirm as a team that the goal and selected items are achievable. Adjust scope rather than over-commit.","o":"Team Member"},{"t":"Publish the sprint","d":"Update the board, share the sprint goal with stakeholders and keep the session within 2 hours for a 2-week sprint.","o":"Delivery Lead"},{"t":"Manage mid-sprint changes","d":"New urgent work replaces existing work of similar size, agreed by the Product Manager. Do not add work without removing work.","o":"Product Manager"}],"checks":["Sprint goal written and shared","Planned work within 80% of capacity","All planned items meet the definition of ready","Bug and tech work allocation honoured"],"kpis":[["Sprint goal achievement","80% of sprints meet their goal"],["Planned vs completed work","Between 80% and 100%"],["Mid-sprint scope changes","Fewer than 2 per sprint"],["Carry-over items","Below 15% of planned items"]],"risks":[["Chronic over-commitment","Plan to 80% capacity and use recent velocity"],["Unclear items stall work","Definition of ready and pre-planning refinement"],["Constant interruptions","Swap rule for urgent work"],["Technical debt grows","Reserved capacity each sprint"]],"related":["Feature Request Intake","Bug Triage","Product Requirements Sign-off","Product Release"],"review":"Every 6 months, or when sprint goal achievement falls below 60% for 3 sprints"},{"id":"product-blameless-postmortem","dept":"product","title":"Blameless Post-mortem","summary":"Reviews incidents without blame to find root causes and contributing factors, and tracks actions that prevent repeats.","tags":["post-mortem","postmortem","incident review","root cause analysis","rca","lessons learned"],"purpose":"To learn from incidents and near misses so they do not happen again. A blameless approach encourages honest detail about what happened and why decisions made sense at the time.","scope":"Covers all SEV1 and SEV2 production and security incidents, and selected SEV3 incidents or near misses with learning value. It does not cover individual performance management, which is handled separately and never through this process.","definitions":[["Blameless","Focusing on systems and conditions rather than individual fault."],["Contributing factor","A condition that made the incident more likely or worse."],["Root cause","The underlying reason that, if fixed, would prevent recurrence."],["Action item","A specific, owned and dated change resulting from the review."]],"roles":[["Post-mortem Owner","Drafts the document, schedules the meeting and tracks actions."],["Facilitator","Runs the meeting neutrally and keeps it blameless."],["Incident Participants","Provide facts, timelines and context."],["Engineering Lead","Prioritises action items and reviews completion."]],"prereqs":["Incident timeline, chat logs and monitoring graphs","Post-mortem template","Action tracker in [issue tracker]","List of incident participants"],"steps":[{"t":"Assign an owner","d":"Within 1 business day of resolution, assign a Post-mortem Owner, ideally someone involved but not the Incident Commander.","o":"Engineering Lead"},{"t":"Build the timeline","d":"Reconstruct events from detection to resolution with timestamps from logs, alerts and chat. Note what people knew at each point.","o":"Post-mortem Owner"},{"t":"Quantify the impact","d":"Record duration, users or accounts affected, failed transactions, revenue impact and SLA breaches.","o":"Post-mortem Owner"},{"t":"Gather participant input","d":"Ask participants to add context to the draft before the meeting, including what was confusing or what helped.","o":"Incident Participants"},{"t":"Hold the review meeting","d":"Within 5 business days, run a 45 to 60 minute meeting. Open by restating the blameless principle and walk through the timeline.","o":"Facilitator"},{"t":"Analyse causes","d":"Use '5 whys' or a contributing factors approach to identify root causes in systems, processes, tooling and communication.","o":"Facilitator"},{"t":"Agree action items","d":"Agree 3 to 7 specific actions, each with an owner, priority and due date. Prefer fixes that prevent or detect, not just 'be more careful'.","o":"Engineering Lead"},{"t":"Publish the post-mortem","d":"Share the final document with engineering and relevant teams within 10 business days, removing customer personal data.","o":"Post-mortem Owner"},{"t":"Track actions to completion","d":"Review open post-mortem actions in a regular engineering meeting. High-priority actions should close within 30 days.","o":"Engineering Lead"},{"t":"Share learning across incidents","d":"Quarterly, review all post-mortems for recurring themes and report them to leadership.","o":"Post-mortem Owner"}],"checks":["No individual named as the cause of an incident","Every action has an owner and due date","Document published within 10 business days","Customer-facing summary prepared where an SLA was breached"],"kpis":[["Post-mortem completion","100% of SEV1 and SEV2 within 10 business days"],["Action completion","80% of actions closed by their due date"],["Repeat incidents","Zero repeat SEV1 from the same root cause within 12 months"]],"risks":[["People hide mistakes","Blameless principle stated and enforced by facilitator"],["Actions never completed","Tracker with regular review"],["Shallow analysis","Structured cause analysis and focus on systems"],["Sensitive data in documents","Redaction before publishing"]],"related":["Production Incident and On-call","Security Incident Response","Deployment Rollback","Bug Triage"],"review":"Every 12 months, or if action completion falls below target for 2 quarters"},{"id":"product-feature-request-intake","dept":"product","title":"Feature Request Intake","summary":"Collects, deduplicates and evaluates feature requests from customers and teams, and closes the loop with requesters.","tags":["feature request","product feedback","customer feedback","idea intake","roadmap","prioritisation"],"purpose":"To turn scattered ideas and customer asks into structured evidence that informs product decisions. It also makes sure requesters get a clear answer rather than silence.","scope":"Covers feature requests and improvement ideas from customers, prospects, sales, support, partners and staff. It does not cover bugs, which follow Bug Triage, or custom paid development, which follows a separate commercial process.","definitions":[["Request","A single customer or internal ask for new or changed functionality."],["Opportunity","A grouped problem area combining many related requests."],["RICE","A scoring model: Reach, Impact, Confidence, Effort."],["Closing the loop","Telling requesters the outcome or status."]],"roles":[["Product Manager","Owns the intake board, evaluates opportunities and decides outcomes."],["Support Lead","Logs requests raised in support conversations."],["Account Manager","Logs requests from customers and prospects with deal or revenue context."],["Product Operations","Tags, deduplicates and maintains the feedback system."]],"prereqs":["Feedback tool or board, e.g. [feedback tool]","Request form with required fields","Product strategy and current roadmap themes","Customer data such as plan, revenue and segment"],"steps":[{"t":"Capture the request","d":"Log each request with the customer's problem in their words, who asked, account details, plan, revenue and urgency. Record the problem, not just the proposed solution.","o":"Support Lead"},{"t":"Log sales and account requests","d":"Record requests from prospects and customers with deal size and whether they are blocking a sale or renewal. Do not promise delivery dates.","o":"Account Manager"},{"t":"Deduplicate and tag","d":"Within 5 business days, merge duplicates into existing requests and tag by product area, segment and theme.","o":"Product Operations"},{"t":"Group into opportunities","d":"Monthly, group related requests into opportunities that describe the underlying user problem.","o":"Product Manager"},{"t":"Evaluate and score","d":"Score opportunities using RICE or the agreed model, considering strategy fit, number of accounts, revenue and effort estimates from engineering.","o":"Product Manager"},{"t":"Decide the outcome","d":"Classify as planned, under consideration, not now or will not do, with a short reason.","o":"Product Manager"},{"t":"Close the loop","d":"Update requesters on the outcome within 10 business days of the decision. Use templates that are honest and avoid committing to dates.","o":"Support Lead"},{"t":"Notify on delivery","d":"When a requested feature ships, notify every linked customer and account owner.","o":"Product Operations"},{"t":"Report trends","d":"Quarterly, share the top requested opportunities and decisions with leadership, sales and support.","o":"Product Manager"}],"checks":["Every request linked to a customer or source","No delivery dates promised outside the roadmap","Duplicate requests merged rather than counted separately","Requesters notified when features ship"],"kpis":[["Requests processed","90% tagged within 5 business days"],["Loop closure","80% of requesters receive an outcome"],["Roadmap items backed by request data","70% or more"]],"risks":[["Loudest customer drives the roadmap","Scoring model and segment weighting"],["Sales promises unbuilt features","No-commitment rule and approved responses"],["Feedback lost in chats and emails","Single intake tool and required logging"],["Requesters feel ignored","Loop closure templates and delivery notifications"]],"related":["Product Requirements Sign-off","Sprint Planning","Bug Triage","Customer Feedback Collection"],"review":"Every 12 months, or when the product strategy changes"},{"id":"product-requirements-sign-off","dept":"product","title":"Product Requirements Sign-off","summary":"Gets product requirements documented, reviewed and approved by the right people before engineering commits to build.","tags":["prd","requirements","specification","sign-off","acceptance criteria","product spec"],"purpose":"To make sure the team builds the right thing with shared understanding of goals, scope and success measures. Clear sign-off reduces rework and late changes.","scope":"Covers new features, significant changes to existing features and new products that need more than about 1 week of engineering effort. It does not cover small improvements or bug fixes, which can go straight to the backlog with acceptance criteria.","definitions":[["PRD","Product Requirements Document describing the problem, goals, scope and requirements."],["Acceptance criteria","Testable conditions that must be true for the work to be accepted."],["Non-goals","Things explicitly out of scope for this work."],["Success metric","The measurable outcome that shows the feature worked."]],"roles":[["Product Manager","Writes the PRD and drives it to sign-off."],["Engineering Lead","Reviews feasibility, estimates effort and flags technical risk."],["Design Lead","Provides user flows and designs and confirms usability."],["Stakeholder Approver","Business owner, e.g. head of sales or operations, who confirms the business need is met."],["Security Lead","Reviews requirements that touch personal data, authentication or payments."]],"prereqs":["PRD template","Evidence from user research, feedback or data","Roadmap context and target timeline","Design system and existing analytics"],"steps":[{"t":"Define the problem","d":"Write the problem statement, target users, evidence and why it matters now. Get informal agreement on the problem before detailing solutions.","o":"Product Manager"},{"t":"Set goals and success metrics","d":"State 1 to 3 measurable goals, e.g. raise onboarding completion from 60% to 75% within 90 days, and how they will be tracked.","o":"Product Manager"},{"t":"Write scope and non-goals","d":"List what is in scope, what is not and assumptions. Use user stories with acceptance criteria for each requirement.","o":"Product Manager"},{"t":"Add designs and flows","d":"Attach user flows, wireframes or prototypes for key journeys, including empty, error and edge states.","o":"Design Lead"},{"t":"Review technical feasibility","d":"Engineering reviews within 5 business days, adds a rough estimate, dependencies and risks, and proposes scope cuts if needed.","o":"Engineering Lead"},{"t":"Review security and privacy","d":"Where the feature handles personal data, permissions or payments, complete a privacy and security review and add required controls as requirements.","o":"Security Lead"},{"t":"Hold the review meeting","d":"Walk through the PRD with reviewers, resolve open questions and record decisions in the document.","o":"Product Manager"},{"t":"Obtain sign-off","d":"Approvers sign off in the document or tool with name and date. Sign-off means the scope is agreed, not that the plan cannot change.","o":"Stakeholder Approver"},{"t":"Control changes after sign-off","d":"Material scope changes are recorded in a change log in the PRD and re-approved by the same approvers.","o":"Product Manager"},{"t":"Confirm acceptance at delivery","d":"Before release, check the delivered work against acceptance criteria and record any accepted gaps.","o":"Product Manager"}],"checks":["Success metrics are measurable and tracked","Every requirement has acceptance criteria","Engineering and design reviewed before sign-off","Scope changes logged and re-approved"],"kpis":[["Time from draft to sign-off","Under 10 business days"],["Post-sign-off scope changes","Fewer than 2 material changes per project"],["Features meeting success metric","60% or more within 90 days of release"]],"risks":[["Building the wrong thing","Problem validation and evidence before solutions"],["Late privacy or security issues","Mandatory review for sensitive features"],["Endless review cycles","Fixed review window and named approvers"],["Scope creep after sign-off","Change log and re-approval"]],"related":["Feature Request Intake","Sprint Planning","Product Release","Data Protection Policy"],"review":"Every 12 months, or when the product development process changes"},{"id":"product-dependency-api-updates","dept":"product","title":"Third-party API and Dependency Updates","summary":"Keeps open-source libraries and third-party APIs up to date, secure and supported, with tested upgrades and deprecation tracking.","tags":["dependency updates","open source","library upgrade","api deprecation","sca","vulnerability","sbom"],"purpose":"To reduce security vulnerabilities and avoid outages caused by outdated libraries or retired third-party APIs. Regular, small updates are cheaper and safer than rare large ones.","scope":"Covers open-source and commercial libraries, frameworks, container base images and external APIs used by the product. It does not cover operating system patching of staff devices or servers, which follows Software Patching and Updates.","definitions":[["Dependency","Any external code or service the product relies on."],["SCA","Software composition analysis: tools that detect known vulnerabilities and licences in dependencies."],["Deprecation","A vendor notice that an API version or feature will be removed."],["Lockfile","A file pinning exact dependency versions for repeatable builds."]],"roles":[["Dependency Owner","Engineer responsible for a service's dependencies on rotation."],["Engineering Lead","Sets update cadence and approves major upgrades."],["Security Lead","Rates vulnerability severity and approves exceptions."],["Reviewer","Reviews upgrade pull requests and test results."]],"prereqs":["SCA or automated update tool, e.g. [dependency tool], enabled on all repositories","Lockfiles committed for every project","Register of third-party APIs with version, owner and contact","Automated test suite with good coverage of integrations"],"steps":[{"t":"Keep an inventory","d":"Maintain a list of third-party APIs and key libraries with current version, owner and support end date. Update it whenever a new dependency is added.","o":"Dependency Owner"},{"t":"Vet new dependencies","d":"Before adding a library, check maintenance activity, licence compatibility, known vulnerabilities and whether an existing dependency already covers the need.","o":"Reviewer"},{"t":"Automate update PRs","d":"Let the update tool open grouped pull requests weekly for minor and patch updates, with CI running full tests.","o":"Dependency Owner"},{"t":"Apply security fixes by severity","d":"Fix critical vulnerabilities within 7 days, high within 30 days and medium within 90 days, unless the vulnerable code path is confirmed unreachable and recorded.","o":"Security Lead"},{"t":"Review and merge routine updates","d":"Review changelogs for breaking changes, confirm tests pass and merge routine updates within 1 week of the PR opening.","o":"Reviewer"},{"t":"Plan major upgrades","d":"Treat major framework or library upgrades as planned work with a ticket, estimate and test plan, and schedule them in sprint planning.","o":"Engineering Lead"},{"t":"Track API deprecations","d":"Subscribe to changelogs of every external API. Log deprecation notices with the retirement date and plan migration at least 60 days before it.","o":"Dependency Owner"},{"t":"Test integrations","d":"Run contract or integration tests against vendor sandboxes before switching API versions, and use feature flags to switch over gradually.","o":"Dependency Owner"},{"t":"Record exceptions","d":"Where an update cannot be applied in time, record the reason, compensating control and new date, approved by the Security Lead.","o":"Security Lead"},{"t":"Review dependency health quarterly","d":"Quarterly, review outdated packages, unmaintained libraries and licence issues, and agree a reduction plan.","o":"Engineering Lead"}],"checks":["SCA scanning enabled on every repository","No critical vulnerabilities older than 7 days without approved exception","All external APIs listed with owner and version","Lockfiles committed and builds reproducible"],"kpis":[["Critical vulnerability fix time","100% within 7 days"],["Dependencies more than one major version behind","Below 10%"],["API deprecation migrations completed before cut-off","100%"],["Outages caused by third-party changes","Zero per quarter"]],"risks":[["Supply chain attack via a compromised package","Lockfiles, vetting and SCA alerts"],["Vendor retires an API without the team noticing","Changelog subscriptions and deprecation log"],["Upgrade breaks production","Test suite, staged rollout and feature flags"],["Licence conflict","Licence check on new dependencies"]],"related":["Code Review and Merge","Software Patching and Updates","New Software and SaaS Approval","Product Release"],"review":"Every 12 months, or after a dependency-related incident"},{"id":"legal-contract-review-approval","dept":"legal","title":"Contract Review and Approval","summary":"Every contract is risk-reviewed, approved at the right level and signed only by authorised people before it binds the company.","tags":["contract","agreement","legal review","signature","approval matrix","msa","redlines"],"purpose":"To make sure no contract is signed without a proportionate legal and commercial review. It protects [Company] from unfavourable terms, unauthorised commitments and lost contract records.","scope":"Covers all customer, supplier, partner and service contracts, including renewals and amendments, at any value. It does not cover employment contracts (see HR) or standard click-through terms below [low-value threshold], which follow the low-risk fast track.","definitions":[["Contract owner","The employee who requested the contract and is accountable for the commercial relationship."],["Approval matrix","The table that sets who may approve and sign contracts by value, term and risk level."],["Redline","A tracked-changes markup of proposed edits to the other party's draft."],["Fallback position","A pre-agreed alternative clause the reviewer may accept without escalation."]],"roles":[["Contract Owner","Raises the request, provides commercial context and manages the counterparty."],["Legal Reviewer","Reviews terms against the playbook, redlines and assigns a risk rating."],["Finance Approver","Confirms budget, payment terms, pricing and tax treatment."],["Authorised Signatory","Signs on behalf of [Company] within their delegated authority."],["Contract Administrator","Logs the contract, stores the executed copy and sets renewal reminders."]],"prereqs":["Contract request form completed in [contract tool]","Counterparty draft or [Company] template","Current approval matrix and contract playbook","Budget approval or purchase request where money is spent","Counterparty legal name, registration number and address"],"steps":[{"t":"Submit the request","d":"Contract Owner submits the request form with the draft, value, term, purpose and deadline. Requests need at least 5 business days before the required signing date unless marked urgent with a reason.","o":"Contract Owner"},{"t":"Triage and assign risk tier","d":"Within 1 business day, classify the contract as low, medium or high risk using value, data access, liability, exclusivity and term. Low-risk contracts on [Company] paper with no changes may skip to approval.","o":"Legal Reviewer"},{"t":"Check the counterparty","d":"Verify the counterparty's legal name and registration and screen it against sanctions lists where required. Record any red flags before review continues.","o":"Contract Administrator"},{"t":"Review against the playbook","d":"Compare each key clause (liability cap, indemnities, IP, data protection, termination, governing law, payment) with the playbook. Medium risk: within 3 business days; high risk: within 5 business days.","o":"Legal Reviewer"},{"t":"Prepare redlines and a summary","d":"Mark up the draft using fallback positions and write a one-page summary of open issues, deviations and recommended stance for the Contract Owner.","o":"Legal Reviewer"},{"t":"Negotiate open points","d":"Contract Owner shares redlines with the counterparty and leads commercial talks; Legal joins calls for high-risk points. Any deviation beyond the fallback must be escalated before agreeing.","o":"Contract Owner"},{"t":"Confirm financial terms","d":"Check pricing, payment terms, currency, tax clauses and that spend is within budget. Contracts above [finance threshold] need written Finance sign-off.","o":"Finance Approver"},{"t":"Obtain approval per the matrix","d":"Route the final draft and summary through the approval matrix in [contract tool]. No signatory may approve a contract outside their limit, and two approvals are required above [dual-approval limit].","o":"Contract Administrator"},{"t":"Execute the contract","d":"Send for e-signature with [Company] signing last where possible, so the agreed version cannot be altered. Check that the signed version matches the approved version before countersigning.","o":"Authorised Signatory"},{"t":"File and record metadata","d":"Within 2 business days of signature, store the executed copy in the contract repository and record parties, value, start and end dates, notice period and owner.","o":"Contract Administrator"},{"t":"Set obligation and renewal reminders","d":"Create reminders at 90 and 30 days before the renewal or notice deadline and log key obligations (SLAs, reporting, insurance) with their owners.","o":"Contract Administrator"},{"t":"Hand over to the business","d":"Contract Owner briefs the team that will deliver or manage the contract on key obligations and restrictions within 5 business days.","o":"Contract Owner"}],"checks":["No contract is signed without a recorded approval matching the matrix","Executed version compared with approved version before countersignature","Every executed contract has complete metadata in the repository","High-risk deviations have documented escalation sign-off","Renewal reminders exist for every contract with an auto-renewal clause"],"kpis":[["Review turnaround","90% of medium-risk contracts reviewed within 3 business days"],["Repository completeness","100% of executed contracts stored with metadata within 2 business days"],["Unauthorised signatures","Zero contracts signed outside delegated authority"],["Missed renewal deadlines","Zero auto-renewals missed per year"]],"risks":[["Employee signs without authority","Publish the approval matrix, restrict e-signature accounts to authorised signatories, and audit quarterly."],["Unfavourable liability or indemnity terms","Playbook with fallback positions and mandatory escalation for uncapped liability."],["Version mismatch at signing","Lock the final PDF and compare against the approved draft before signing."],["Lost or unfindable contracts","Single central repository with mandatory metadata fields."]],"related":["Delegation of Authority Policy","Contract Playbook","NDA Request and Signing","Vendor Onboarding","Document Retention and Disposal"],"review":"Every 12 months, or after a change in the approval matrix or a material contract dispute"},{"id":"legal-nda-request-signing","dept":"legal","title":"NDA Request and Signing","summary":"Non-disclosure agreements are issued on approved templates and signed before any confidential information is shared.","tags":["nda","non-disclosure","confidentiality agreement","mutual nda","cda","confidential information"],"purpose":"To protect [Company]'s confidential information by making sure an appropriate NDA is in place before discussions with third parties. It also keeps NDA turnaround fast so deals are not delayed.","scope":"Covers mutual and one-way NDAs with prospects, partners, suppliers, investors and candidates for sensitive roles. It does not cover confidentiality clauses inside wider commercial contracts, which follow Contract Review and Approval.","definitions":[["Mutual NDA","An agreement where both parties disclose and protect each other's confidential information."],["One-way NDA","An agreement where only one party discloses information and the other protects it."],["Standard template","The [Company] NDA approved by Legal that may be signed without further review if unchanged."]],"roles":[["Requester","Identifies the need for an NDA and provides counterparty details."],["Legal Reviewer","Reviews non-standard or counterparty-paper NDAs."],["Authorised Signatory","Signs NDAs on behalf of [Company]."],["Contract Administrator","Issues templates, tracks status and stores executed NDAs."]],"prereqs":["NDA request form in [contract tool]","Current mutual and one-way NDA templates","Counterparty legal name, address and signatory details","Description of the information to be shared and purpose"],"steps":[{"t":"Check for an existing NDA","d":"Before requesting, search the repository for a current NDA with the counterparty that covers the same purpose. Reuse it if it is still in force.","o":"Requester"},{"t":"Submit the request","d":"Submit the form with counterparty details, purpose, direction of disclosure and the date information must be shared.","o":"Requester"},{"t":"Select the right template","d":"Choose mutual or one-way based on who discloses. Issue the standard template within 1 business day with counterparty details filled in.","o":"Contract Administrator"},{"t":"Handle counterparty paper","d":"If the other party insists on its own NDA, route it to Legal. Check term, definition of confidential information, residuals clause, non-solicit and governing law; review within 2 business days.","o":"Legal Reviewer"},{"t":"Approve any changes","d":"Accept edits within the NDA playbook fallbacks. Reject non-compete, exclusivity or IP assignment terms hidden in an NDA unless separately approved.","o":"Legal Reviewer"},{"t":"Send for signature","d":"Send via e-signature to the counterparty first, then to the Authorised Signatory. Confirm the counterparty signatory has authority to sign.","o":"Contract Administrator"},{"t":"Countersign","d":"Check the document is the approved version and sign within 1 business day of counterparty signature.","o":"Authorised Signatory"},{"t":"Confirm and release","d":"Notify the Requester that the NDA is fully signed. No confidential information may be shared until this confirmation.","o":"Contract Administrator"},{"t":"Store and set expiry reminder","d":"File the executed NDA with metadata (parties, type, effective date, term, purpose) and set a reminder 30 days before expiry.","o":"Contract Administrator"},{"t":"Mark shared information","d":"When sharing, label documents 'Confidential' and keep a simple log of what was shared and when.","o":"Requester"}],"checks":["No confidential material shared before a fully signed NDA is confirmed","Unchanged templates used for at least [80%] of NDAs","Non-standard terms reviewed and approved by Legal","Every executed NDA stored with expiry date"],"kpis":[["Standard NDA turnaround","90% fully signed within 3 business days"],["Template usage rate","80% or more on [Company] paper"],["Repository completeness","100% of signed NDAs filed within 1 business day"]],"risks":[["Information shared before signing","Requester training and a release confirmation email before data rooms or demos are opened."],["Hidden restrictive terms in counterparty NDA","Legal review of all counterparty paper using a checklist."],["Duplicate or conflicting NDAs","Search the repository before each new request."]],"related":["Contract Review and Approval","Information Classification Policy","Fundraising Data Room Preparation"],"review":"Every 12 months, or after a confidentiality breach"},{"id":"legal-data-subject-requests","dept":"legal","title":"Data Subject Access and Deletion Requests","summary":"Requests from individuals to access, correct or delete their personal data are verified, fulfilled and recorded within legal deadlines.","tags":["dsar","subject access request","right to erasure","gdpr","privacy request","data deletion","personal data"],"purpose":"To handle privacy rights requests lawfully, consistently and on time. It reduces regulatory risk and builds trust with customers, employees and other individuals.","scope":"Covers access, rectification, erasure, restriction, portability and objection requests from any individual whose personal data [Company] holds. It does not cover requests made on behalf of a corporate customer as data controller, which follow the customer contract, or law enforcement requests.","definitions":[["Data subject","The identifiable living person the personal data relates to."],["DSAR","Data subject access request: a request to see the personal data held about the person."],["Statutory deadline","The legal response time, often one month under GDPR with possible extension; check local law."],["Data map","The record of systems that store personal data and what categories they hold."]],"roles":[["Privacy Lead","Owns the process, decides on exemptions and signs off responses."],["Request Handler","Logs, verifies and coordinates the request day to day."],["System Owners","Search, export or delete data in their systems when asked."],["Legal Counsel","Advises on complex cases, exemptions and refusals."]],"prereqs":["Privacy request log or ticket queue","Current data map listing systems holding personal data","Identity verification method approved by the Privacy Lead","Response templates for each request type"],"steps":[{"t":"Log the request","d":"Record every request on receipt, whatever channel it arrives through, with date received, requester, request type and deadline. Acknowledge within 2 business days.","o":"Request Handler"},{"t":"Verify identity","d":"Confirm identity using proportionate checks, such as replying from the registered email or account login. Do not ask for more ID than needed; the deadline may pause while waiting, if local law allows.","o":"Request Handler"},{"t":"Clarify scope","d":"If the request is unclear or very broad, ask the requester to clarify within 5 business days. Record the clarification.","o":"Request Handler"},{"t":"Identify systems","d":"Use the data map to list every system likely to hold the person's data, including email, CRM, support tool, backups and processors.","o":"Privacy Lead"},{"t":"Issue search or deletion tasks","d":"Send tasks to System Owners with a due date no later than 10 business days before the deadline.","o":"Request Handler"},{"t":"Search, extract or delete","d":"System Owners complete the action and confirm in writing what was found or deleted, with screenshots or export files.","o":"System Owners"},{"t":"Assess exemptions and third-party data","d":"Redact other people's personal data and assess legal holds, retention obligations or other exemptions before release or deletion.","o":"Legal Counsel"},{"t":"Instruct processors","d":"For erasure, notify relevant processors and any recipients of the data to delete or correct it, and record their confirmations.","o":"Request Handler"},{"t":"Prepare the response","d":"Compile the data in a commonly used electronic format with the required information about purposes, recipients, retention and sources.","o":"Request Handler"},{"t":"Approve and send","d":"Privacy Lead reviews completeness and redactions, then sends via a secure channel before the deadline.","o":"Privacy Lead"},{"t":"Close and record","d":"Record the outcome, date sent, any refusal reasons and evidence in the log. Keep the log for [retention period].","o":"Request Handler"}],"checks":["Every request logged within 1 business day of receipt","Identity verified before any data is disclosed","Third-party data redacted in all access responses","Erasure confirmed by every listed system and processor","Refusals and extensions documented with reasons"],"kpis":[["Requests completed on time","100% within statutory deadline"],["Acknowledgement time","95% within 2 business days"],["Disclosure errors","Zero responses sent to the wrong person or with unredacted third-party data"]],"risks":[["Disclosure to an impostor","Identity verification before release and secure delivery."],["Missed deadline","Deadline tracking in the log with reminders at 50% and 80% of the period."],["Data missed in shadow systems","Keep the data map current and include email and shared drives in every search."],["Deleting data under legal hold","Legal check for holds and retention obligations before erasure."]],"related":["Privacy Policy","Data Map and Record of Processing","Document Retention and Disposal","Data Breach Response"],"review":"Every 12 months, or after a regulator enquiry or a missed deadline"},{"id":"legal-document-retention-disposal","dept":"legal","title":"Document Retention and Disposal","summary":"Records are kept for the required period, protected while held and destroyed securely and provably when no longer needed.","tags":["records management","retention schedule","data disposal","shredding","archiving","legal hold"],"purpose":"To keep business records for as long as law and business need require, and no longer. It reduces storage costs, privacy risk and the burden of searching old data in disputes.","scope":"Covers paper and electronic records in all departments, including email, shared drives, SaaS tools and archives. It does not cover source code version history or system logs governed by the IT Logging Standard.","definitions":[["Retention schedule","The table setting how long each record type is kept and the trigger date for the period."],["Legal hold","An instruction to preserve records relevant to actual or expected litigation or investigation, overriding the schedule."],["Record owner","The department responsible for a record type."],["Certificate of destruction","Evidence from a disposal provider that media or paper was destroyed."]],"roles":[["Records Manager","Maintains the schedule, runs the annual disposal cycle and keeps disposal logs."],["Record Owners","Classify their records, apply retention and approve disposal."],["Legal Counsel","Sets retention periods, issues and lifts legal holds."],["IT Administrator","Configures retention rules in systems and securely deletes electronic data."]],"prereqs":["Approved retention schedule","Inventory of systems and storage locations holding records","Active legal hold register","Contract with a certified shredding or disposal provider"],"steps":[{"t":"Maintain the retention schedule","d":"Review the schedule yearly with Legal so each record type has a period and trigger, checking local law for tax, employment and health and safety records.","o":"Records Manager"},{"t":"Classify records at creation","d":"Store records in the designated location for their type, so retention can be applied automatically where possible.","o":"Record Owners"},{"t":"Configure system retention rules","d":"Set retention and deletion policies in email, file storage and key SaaS tools to match the schedule. Test that holds override deletion.","o":"IT Administrator"},{"t":"Apply legal holds immediately","d":"On notice of a dispute or investigation, Legal issues a hold notice within 1 business day naming custodians and record types. Suspend deletion for those records.","o":"Legal Counsel"},{"t":"Run the disposal review","d":"Each [quarter], generate a list of records past their retention date and send it to Record Owners.","o":"Records Manager"},{"t":"Approve disposal","d":"Record Owners confirm within 10 business days that listed records have no ongoing business need. Check the list against the legal hold register.","o":"Record Owners"},{"t":"Destroy paper records securely","d":"Place paper in locked confidential bins for cross-cut shredding by the provider. Obtain a certificate of destruction for each collection.","o":"Records Manager"},{"t":"Delete electronic records","d":"Delete approved records from live systems and confirm that backups expire within the backup rotation period. Wipe or destroy retired devices to a recognised standard.","o":"IT Administrator"},{"t":"Log the disposal","d":"Record what was destroyed, by whom, when, under which approval and the certificate reference. Keep the log permanently.","o":"Records Manager"},{"t":"Lift holds when cleared","d":"Legal releases holds in writing when the matter closes, and records resume normal retention.","o":"Legal Counsel"}],"checks":["No disposal proceeds without checking the legal hold register","Each disposal batch has a named approver and log entry","Certificates of destruction filed for all paper and media disposals","System retention settings tested at least yearly"],"kpis":[["Disposal cycle completion","100% of overdue records reviewed each quarter"],["Holds issued promptly","100% within 1 business day of notice"],["Records past retention","Less than [5%] of records held beyond their period without reason"]],"risks":[["Destroying evidence under legal hold","Hold register check before every disposal and system-level hold settings."],["Keeping personal data too long","Automated retention rules and quarterly disposal reviews."],["Insecure disposal leaks data","Certified disposal provider and locked confidential bins."]],"related":["Retention Schedule","Data Subject Access and Deletion Requests","IT Asset Disposal","Information Security Policy"],"review":"Every 12 months, or after a change in law or a new system that stores records"},{"id":"legal-gifts-hospitality-antibribery","dept":"legal","title":"Gifts, Hospitality and Anti-bribery","summary":"Gifts and hospitality given or received are within limits, approved where needed and recorded, preventing bribery.","tags":["anti-bribery","anti-corruption","gifts register","hospitality","entertainment","facilitation payments"],"purpose":"To prevent bribery and the appearance of improper influence in [Company]'s business dealings. It gives staff clear limits and a simple way to record and approve gifts and hospitality.","scope":"Covers all employees, contractors and agents giving or receiving gifts, meals, travel, entertainment or donations connected to [Company] business. It does not cover normal staff rewards paid by [Company] to its own employees.","definitions":[["Gift","Anything of value given or received without payment, including vouchers, goods, tickets and discounts."],["Hospitality","Meals, events, travel or accommodation provided in a business context."],["Public official","Anyone employed by or acting for a government, public body, state-owned company or public international organisation."],["Facilitation payment","A small unofficial payment to speed up a routine government action. Prohibited."]],"roles":[["Employee","Follows limits, seeks approval and records gifts and hospitality."],["Line Manager","Approves items within the manager limit and challenges unusual patterns."],["Compliance Officer","Maintains the register, approves high-value or sensitive items and investigates concerns."],["Finance Team","Checks expense claims against the register before reimbursement."]],"prereqs":["Anti-bribery policy with value limits","Gifts and hospitality register in [register tool]","Approval form","Annual anti-bribery training completion"],"steps":[{"t":"Check the limits before acting","d":"Before offering or accepting anything, check it against the limits: up to [low limit] per person may be accepted without approval, above it needs approval, and cash or cash equivalents are never allowed.","o":"Employee"},{"t":"Apply extra rules for public officials","d":"Any gift or hospitality to a public official needs prior written approval from the Compliance Officer regardless of value. Check local law, as some jurisdictions ban it entirely.","o":"Employee"},{"t":"Watch timing and frequency","d":"Decline anything offered during a live tender, contract negotiation or regulatory decision, and anything from the same party more than [3] times in 12 months.","o":"Employee"},{"t":"Request approval","d":"Submit the approval form before the event or, for unsolicited gifts, within 5 business days of receipt, with giver, recipient, value and business reason.","o":"Employee"},{"t":"Approve or decline","d":"Line Manager approves items between [low limit] and [manager limit]. Compliance Officer approves above [manager limit] and all public official items within 3 business days.","o":"Line Manager"},{"t":"Return or hand over refused gifts","d":"Return gifts that are not approved with a polite note citing policy, or hand them to the Compliance Officer for donation or a staff raffle.","o":"Employee"},{"t":"Record in the register","d":"Log every item above [low limit], whether accepted, declined, given or returned, within 5 business days.","o":"Employee"},{"t":"Reconcile expenses","d":"Finance checks that client entertainment and gift expense claims above [low limit] have a matching register entry before reimbursement.","o":"Finance Team"},{"t":"Review the register","d":"Review the register quarterly for patterns, repeat givers or suppliers in active tenders, and follow up any concerns.","o":"Compliance Officer"},{"t":"Report suspected bribery","d":"Report any request for or offer of a bribe immediately to the Compliance Officer or the whistleblowing channel. Retaliation against reporters is prohibited.","o":"Employee"}],"checks":["No cash or cash-equivalent gifts given or accepted","All public official items have prior written approval","Expense claims matched to register entries","Quarterly register review documented"],"kpis":[["Register completeness","100% of expense claims for gifts or entertainment matched to an entry"],["Training completion","100% of staff trained yearly"],["Approval turnaround","95% within 3 business days"]],"risks":[["Gift used to influence a contract award","Ban on gifts during tenders and negotiations, and register review."],["Unrecorded hospitality","Finance reconciliation of expenses against the register."],["Agents paying bribes on our behalf","Due diligence on third-party agents and anti-bribery clauses in contracts."]],"related":["Anti-bribery and Corruption Policy","Whistleblowing Policy","Conflict of Interest Declaration","Expense Claims"],"review":"Every 12 months, or after a reported incident or change in law"},{"id":"legal-compliance-audit-preparation","dept":"legal","title":"Compliance Audit Preparation","summary":"The company enters every external or internal compliance audit with complete evidence, briefed staff and a tracked remediation plan.","tags":["audit readiness","soc 2","iso 27001","external audit","evidence collection","certification"],"purpose":"To make compliance audits efficient and predictable by preparing evidence and people in advance. It reduces findings caused by missing documents rather than real control gaps.","scope":"Covers planned certification, regulatory, customer and internal audits against frameworks such as ISO 9001, ISO 27001, SOC 2 or PCI DSS. It does not cover financial statement audits, which follow the Year-end Close process.","definitions":[["Control","A policy, procedure or technical measure that meets a framework requirement."],["Evidence","Records that prove a control operated, such as logs, tickets, approvals or screenshots."],["Finding","An auditor's observation of a gap, rated as major, minor or observation."],["Audit period","The time window the auditor tests, for example the last 6 or 12 months."]],"roles":[["Audit Lead","Owns the plan, timeline and auditor relationship."],["Control Owners","Produce evidence and explain how their controls work."],["Executive Sponsor","Provides resources and accepts residual risk."],["Audit Coordinator","Manages the evidence tracker, scheduling and document requests."]],"prereqs":["Audit scope, standard and dates agreed with the auditor","Control list mapped to the framework","Previous audit report and remediation status","Evidence tracker and secure sharing folder"],"steps":[{"t":"Confirm scope and timeline","d":"At least 12 weeks before fieldwork, confirm the framework, in-scope entities, systems, locations and audit period with the auditor.","o":"Audit Lead"},{"t":"Map controls to owners","d":"List every in-scope control with its owner and expected evidence in the tracker within 1 week.","o":"Audit Coordinator"},{"t":"Run a gap assessment","d":"Control Owners self-assess each control against the requirement and flag gaps by 10 weeks before fieldwork.","o":"Control Owners"},{"t":"Remediate gaps","d":"Create tickets for each gap with owner and due date, prioritising gaps likely to be major findings. Review progress weekly.","o":"Audit Lead"},{"t":"Collect evidence","d":"Gather evidence covering the full audit period, named consistently by control ID, and upload to the secure folder at least 3 weeks before fieldwork.","o":"Control Owners"},{"t":"Quality-check evidence","d":"Check that each item is dated, complete, within the audit period and free of unnecessary personal data. Return weak evidence within 2 business days.","o":"Audit Coordinator"},{"t":"Update policies","d":"Confirm policies are approved, versioned and reviewed within the last 12 months.","o":"Control Owners"},{"t":"Brief interviewees","d":"Hold a 30-minute briefing for people the auditor will interview: answer honestly, stick to facts, do not guess, and offer to follow up.","o":"Audit Lead"},{"t":"Run fieldwork logistics","d":"Schedule interviews, provide a single request inbox and respond to auditor requests within 1 business day.","o":"Audit Coordinator"},{"t":"Review draft findings","d":"Check draft findings for factual accuracy and provide context or extra evidence within the auditor's deadline.","o":"Audit Lead"},{"t":"Agree the remediation plan","d":"Assign each finding an owner, action and due date, and get Executive Sponsor sign-off within 2 weeks of the final report.","o":"Executive Sponsor"},{"t":"Track to closure","d":"Review remediation monthly and keep evidence of fixes for the next audit.","o":"Audit Lead"}],"checks":["Every in-scope control has an owner and evidence before fieldwork","Evidence covers the whole audit period","Auditor requests answered within 1 business day","All findings have an owner and due date"],"kpis":[["Evidence ready before fieldwork","100% of controls 3 weeks before fieldwork"],["Major findings","Zero"],["Remediation on time","90% of findings closed by due date"]],"risks":[["Missing evidence for part of the period","Continuous evidence collection through the year, not only before audits."],["Staff give inaccurate answers","Interview briefings and Control Owners present for their areas."],["Over-sharing confidential data with auditors","Share via a controlled folder and redact unnecessary personal data."]],"related":["Information Security Policy","Risk and Issue Log Review","Document Retention and Disposal","Internal Audit Plan"],"review":"Every 12 months, or after each audit cycle"},{"id":"legal-conflict-of-interest-declaration","dept":"legal","title":"Conflict of Interest Declaration","summary":"Personal interests that could affect business decisions are declared, assessed and managed openly.","tags":["conflict of interest","coi","declaration","related party","outside employment","ethics"],"purpose":"To protect [Company] decisions from bias caused by personal, financial or family interests. It gives staff a safe, simple way to declare interests and shows how they are managed.","scope":"Covers all employees, directors, contractors and advisers. It covers financial interests, outside work, family relationships, board seats and personal relationships at work. It does not replace the gifts process, which is covered by Gifts, Hospitality and Anti-bribery.","definitions":[["Conflict of interest","A situation where personal interests could, or could appear to, influence a person's judgement on behalf of [Company]."],["Related party","A close family member, partner or a business in which the person has a significant interest."],["Management plan","The agreed measures, such as recusal or reassignment, that control a declared conflict."]],"roles":[["Declarant","Declares interests honestly and on time and follows the management plan."],["Line Manager","Makes the first assessment and agrees practical controls."],["Compliance Officer","Keeps the register, decides on significant conflicts and runs the annual declaration."],["Board Chair","Handles conflicts involving directors or the CEO."]],"prereqs":["Conflict of interest policy","Declaration form in [HRIS tool]","Conflicts register","Examples guide for common conflicts"],"steps":[{"t":"Declare at onboarding","d":"New joiners complete a declaration, even if 'none', within their first 5 business days.","o":"Declarant"},{"t":"Declare new conflicts promptly","d":"Declare any new or changed interest within 10 business days of becoming aware, and before taking part in any related decision.","o":"Declarant"},{"t":"Assess the declaration","d":"Line Manager reviews within 5 business days and rates it as no conflict, manageable or significant.","o":"Line Manager"},{"t":"Escalate significant conflicts","d":"Send significant conflicts, those involving suppliers or customers above [value], and any director or CEO conflict to the Compliance Officer or Board Chair.","o":"Line Manager"},{"t":"Agree a management plan","d":"Agree controls such as stepping out of decisions, removing access, second approver on transactions or ending the outside role. Record the plan in writing.","o":"Compliance Officer"},{"t":"Record in the register","d":"Log the declaration, rating, plan and review date. Restrict register access to those who need it.","o":"Compliance Officer"},{"t":"Recuse in meetings","d":"Declarant states the conflict at the start of any relevant meeting and leaves the decision; the minutes record the recusal.","o":"Declarant"},{"t":"Run the annual declaration","d":"Every [month], all staff confirm or update their declarations. Chase non-responders after 10 business days.","o":"Compliance Officer"},{"t":"Monitor compliance","d":"Check sample supplier payments and hiring decisions against the register yearly for undeclared conflicts.","o":"Compliance Officer"}],"checks":["Every employee has a current declaration on file","Each declared conflict has a written plan","Recusals recorded in meeting minutes","Annual declaration completion tracked"],"kpis":[["Annual declaration completion","100% within 30 days of launch"],["Assessment time","95% within 5 business days"],["Undeclared conflicts found in audit","Zero"]],"risks":[["Staff do not declare out of fear","Clear guidance that declaring is expected and not a disciplinary matter, with examples."],["Plan not followed","Technical controls such as approval routing and periodic checks."],["Director conflicts handled by subordinates","Route all director and CEO conflicts to the Board Chair."]],"related":["Code of Conduct","Gifts, Hospitality and Anti-bribery","Vendor Onboarding","Recruitment and Hiring"],"review":"Every 12 months, or after a breach of the policy"},{"id":"safety-workplace-inspection","dept":"safety","title":"Workplace Safety Inspection","summary":"Regular documented inspections find and fix workplace hazards before they cause harm.","tags":["safety inspection","hazard check","walkthrough","health and safety","osha","workplace audit"],"purpose":"To identify hazards in the workplace systematically and make sure they are corrected on time. It also provides evidence that [Company] meets its health and safety duties.","scope":"Covers all offices, warehouses, stores and other premises operated by [Company], including shared areas we control. It does not cover client sites, which follow the client's own rules, or specialist inspections such as lifts and pressure systems done by certified contractors.","definitions":[["Hazard","Anything with potential to cause harm, such as a trailing cable or blocked exit."],["Risk rating","Likelihood multiplied by severity, scored low, medium or high."],["Corrective action","A task to remove or control a hazard, with an owner and due date."]],"roles":[["Safety Lead","Owns the inspection schedule, checklist and action tracker."],["Inspector","Carries out the inspection and records findings."],["Site Manager","Assigns and completes corrective actions at the site."],["Employees","Report hazards between inspections and follow controls."]],"prereqs":["Site inspection checklist","Previous inspection report and open actions","Camera or phone for photos","Access to all areas, including plant and storage rooms"],"steps":[{"t":"Schedule inspections","d":"Set a schedule: offices [monthly], warehouses and stores [weekly], and after any refit or layout change.","o":"Safety Lead"},{"t":"Review previous actions","d":"Before the walk, review open actions from the last inspection so they can be checked on site.","o":"Inspector"},{"t":"Walk the whole site","d":"Follow the checklist route covering exits, fire equipment, electrics, floors, storage, workstations, kitchens, first aid and signage. Allow 45 to 90 minutes depending on site size.","o":"Inspector"},{"t":"Record findings with evidence","d":"Record each hazard with location, photo and description. Note good practice too.","o":"Inspector"},{"t":"Rate each hazard","d":"Assign a risk rating and due date: high within 24 hours, medium within 7 days, low within 30 days.","o":"Inspector"},{"t":"Make high risks safe immediately","d":"For high risks, isolate the area or stop the activity on the spot and inform the Site Manager before leaving.","o":"Inspector"},{"t":"Issue the report","d":"Send the report with actions to the Site Manager and Safety Lead within 2 business days.","o":"Inspector"},{"t":"Complete corrective actions","d":"Assign each action to a named person and record completion with a photo.","o":"Site Manager"},{"t":"Verify closure","d":"Check that high and medium actions are effectively closed, not just marked done, and escalate overdue ones to leadership.","o":"Safety Lead"},{"t":"Share learning","d":"Brief staff on recurring issues at the next team meeting and update the checklist if new hazard types appear.","o":"Safety Lead"}],"checks":["Inspections completed on schedule for every site","High-risk hazards made safe the same day","Photo evidence for closed actions","Overdue actions escalated weekly"],"kpis":[["Inspections on schedule","100%"],["High-risk actions closed","100% within 24 hours"],["Overall actions closed on time","90% or more"],["Repeat findings","Downward trend quarter on quarter"]],"risks":[["Inspections become tick-box","Rotate inspectors and include a spot check by the Safety Lead."],["Actions left open","Weekly overdue report to the Site Manager and leadership."],["Areas skipped","Checklist lists every room and zone and requires a sign-off per area."]],"related":["Accident and Near-miss Reporting","Fire Evacuation and Drills","Health and Safety Policy","Risk Assessment Procedure"],"review":"Every 12 months, or after a serious incident or site change"},{"id":"safety-accident-near-miss-reporting","dept":"safety","title":"Accident and Near-miss Reporting","summary":"Accidents and near misses are reported quickly, investigated proportionately and used to prevent repeats.","tags":["incident report","accident","near miss","injury","riddor","osha recordable","investigation"],"purpose":"To make sure people who are hurt get help, incidents are reported to authorities when required, and causes are fixed. Near misses are captured so problems are fixed before anyone is injured.","scope":"Covers injuries, ill health, dangerous occurrences and near misses involving employees, contractors, visitors or customers on [Company] premises or during work. It does not cover IT security incidents or customer complaints, which have their own processes.","definitions":[["Accident","An unplanned event that results in injury, ill health or damage."],["Near miss","An unplanned event that could have caused harm but did not."],["Reportable incident","An incident that local law requires to be reported to a regulator, for example under RIDDOR or OSHA rules; check local law."],["Root cause","The underlying reason the incident happened, beyond the immediate trigger."]],"roles":[["Person Involved or Witness","Reports the incident and gives an account."],["Supervisor","Makes the area safe, ensures first aid, and completes the initial report."],["Safety Lead","Classifies the incident, leads investigations and handles regulator reporting."],["HR Partner","Supports injured staff, absence and return to work."]],"prereqs":["Incident report form in [incident tool]","Accident book or log","Investigation template","Contact details for regulators and insurers"],"steps":[{"t":"Make safe and give first aid","d":"Stop the activity, make the area safe and call a first aider or emergency services. Wellbeing comes before paperwork.","o":"Supervisor"},{"t":"Report immediately","d":"Report the incident or near miss to the Supervisor as soon as possible and within the same shift.","o":"Person Involved or Witness"},{"t":"Complete the initial report","d":"Within 24 hours, record what happened, where, when, who, injuries, witnesses and immediate actions, with photos if safe.","o":"Supervisor"},{"t":"Preserve the scene","d":"For serious incidents, keep the scene undisturbed, except to make safe, until the Safety Lead agrees.","o":"Supervisor"},{"t":"Classify severity","d":"Classify within 1 business day as near miss, minor, lost time or major, and decide the investigation level.","o":"Safety Lead"},{"t":"Notify regulators and insurers","d":"Check whether the incident is reportable under local law and report within the legal deadline. Notify the insurer for injuries and damage.","o":"Safety Lead"},{"t":"Investigate","d":"For lost-time and major incidents, interview people, review evidence and use a method such as 5 Whys to find root causes within 10 business days.","o":"Safety Lead"},{"t":"Agree corrective actions","d":"Set actions that address root causes, not just the person, with owners and due dates.","o":"Safety Lead"},{"t":"Support the injured person","d":"Keep in contact, manage absence and plan any adjustments for return to work.","o":"HR Partner"},{"t":"Close and share lessons","d":"Close the incident once actions are verified and share an anonymised summary with staff within 30 days.","o":"Safety Lead"}],"checks":["Every incident logged within 24 hours","Reportable incidents reported within the legal deadline","Investigations find root causes, not only blame","Actions verified before closure"],"kpis":[["Report timeliness","95% within 24 hours"],["Near-miss to accident ratio","Rising ratio, showing healthy reporting"],["Investigation completion","90% within 10 business days"],["Lost time injury frequency","Below [target]"]],"risks":[["Under-reporting","No-blame reporting message, easy mobile form and recognition for near-miss reports."],["Missed regulator deadline","Classification within 1 business day with a reportability checklist."],["Blaming individuals","Root cause method focused on systems and conditions."]],"related":["First Aid Response","Workplace Safety Inspection","Return to Work Procedure","Hazardous Materials Handling"],"review":"Every 12 months, or after a major incident"},{"id":"safety-fire-evacuation-drills","dept":"safety","title":"Fire Evacuation and Drills","summary":"Everyone on site can evacuate safely in a fire or emergency, and drills prove it at least twice a year.","tags":["fire drill","evacuation","fire warden","assembly point","emergency","fire safety"],"purpose":"To make sure staff and visitors leave the building quickly and safely in a fire or other emergency. Regular drills test the plan and build habits.","scope":"Covers all [Company] premises and everyone present, including visitors and contractors. Shared buildings follow the landlord's plan, with this SOP covering [Company]'s own wardens and roll call. It does not cover fire equipment servicing, which is done by certified contractors.","definitions":[["Fire warden","A trained employee who sweeps an area and guides people out."],["Assembly point","The safe location outside where people gather for roll call."],["PEEP","Personal emergency evacuation plan for someone who needs help to evacuate."]],"roles":[["Fire Safety Lead","Owns the evacuation plan, warden rota and drill schedule."],["Fire Wardens","Sweep their zone, guide people out and report to the Roll Call Officer."],["Roll Call Officer","Takes roll call at the assembly point and briefs emergency services."],["All Staff","Know the routes, leave immediately and follow wardens."]],"prereqs":["Current fire risk assessment","Floor plans with escape routes and assembly point","Warden rota with cover for absence","Sign-in records for visitors and contractors","PEEPs for anyone who needs them"],"steps":[{"t":"Maintain the warden rota","d":"Keep at least [1 warden per 20 people] per floor on every shift, with trained deputies. Review monthly.","o":"Fire Safety Lead"},{"t":"Raise the alarm","d":"Anyone discovering a fire activates the nearest call point and calls emergency services. Do not fight a fire unless trained and it is small and safe to do so.","o":"All Staff"},{"t":"Evacuate immediately","d":"Leave by the nearest safe exit without collecting belongings and without using lifts.","o":"All Staff"},{"t":"Sweep the zone","d":"Wardens check toilets, meeting rooms and quiet areas, close doors, and assist anyone with a PEEP.","o":"Fire Wardens"},{"t":"Take roll call","d":"Use the staff list and visitor sign-in to account for everyone within [10] minutes. Report missing people to emergency services, never re-enter.","o":"Roll Call Officer"},{"t":"Brief emergency services","d":"Give the fire service the location of the fire, missing persons and any hazards such as gas cylinders.","o":"Roll Call Officer"},{"t":"Wait for the all clear","d":"Only re-enter when the fire service or Fire Safety Lead gives the all clear.","o":"Fire Safety Lead"},{"t":"Run drills twice yearly","d":"Hold unannounced drills at least every 6 months and for each shift, timing the full evacuation.","o":"Fire Safety Lead"},{"t":"Debrief and improve","d":"Within 5 business days, record evacuation time, issues such as blocked exits or slow areas, and actions.","o":"Fire Safety Lead"},{"t":"Induct new starters","d":"Show every new starter the exits, call points and assembly point on day one.","o":"Fire Safety Lead"}],"checks":["Evacuation completed within target time","Roll call accounts for 100% including visitors","Escape routes and exits clear at every inspection","PEEPs tested in drills"],"kpis":[["Drills held","At least 2 per site per year"],["Evacuation time","Under [4] minutes"],["Warden coverage","100% of shifts"]],"risks":[["Unaccounted visitors","Mandatory sign-in and digital visitor list available at the assembly point."],["Warden absent","Named deputies and a daily warden check at shift start."],["Blocked exits","Daily opening check and weekly inspections."]],"related":["Visitor Sign-in and Escort","Workplace Safety Inspection","Fire Risk Assessment","Crisis Management"],"review":"Every 12 months, after each drill debrief, or after any change to the building"},{"id":"safety-first-aid-response","dept":"safety","title":"First Aid Response","summary":"Anyone injured or taken ill at work gets prompt, competent first aid and onward care, with every case recorded.","tags":["first aid","first aider","injury","medical emergency","aed","first aid kit"],"purpose":"To make sure trained first aiders and equipment are available and that the response to injury or illness is quick and consistent. It supports legal first aid duties.","scope":"Covers all [Company] premises and working hours, for employees, contractors and visitors. It does not cover medical treatment beyond first aid, occupational health assessments or travel medical cover.","definitions":[["First aider","An employee holding a current first aid certificate from an approved provider."],["Appointed person","Someone who takes charge of first aid arrangements and calls emergency services when no first aider is present."],["AED","Automated external defibrillator."]],"roles":[["First Aider","Responds, gives first aid within their training and records treatment."],["Safety Lead","Assesses first aid needs, keeps the rota and training current."],["Supervisor","Calls for help, manages the scene and follows up."],["Kit Checker","Checks and restocks first aid kits and AED."]],"prereqs":["First aid needs assessment","List of first aiders on display with contact details","Stocked first aid kits and AED where provided","Treatment log"],"steps":[{"t":"Assess first aid needs","d":"Determine the number of first aiders per site and shift based on headcount and hazards, at minimum [1 per 50 staff] and more for higher-risk work.","o":"Safety Lead"},{"t":"Keep certificates current","d":"Track certificate expiry and book refresher training at least 60 days before expiry.","o":"Safety Lead"},{"t":"Call for help","d":"When someone is hurt or unwell, call the nearest first aider and, for serious cases, emergency services immediately. Do not wait for the first aider to call.","o":"Supervisor"},{"t":"Check for danger and assess","d":"Make sure the area is safe, then assess the casualty following training (for example, airway, breathing, circulation).","o":"First Aider"},{"t":"Give first aid within training","d":"Treat within your competence. Use the AED for anyone unresponsive and not breathing normally, following its voice prompts.","o":"First Aider"},{"t":"Arrange onward care","d":"Decide whether the person needs emergency services, a doctor or to go home. Never send someone who may be seriously hurt home alone.","o":"First Aider"},{"t":"Inform contacts","d":"With consent, contact the person's emergency contact for anything beyond minor treatment.","o":"Supervisor"},{"t":"Record the treatment","d":"Within the same shift, record date, time, name, injury, treatment and outcome in the treatment log. Store it confidentially.","o":"First Aider"},{"t":"Report as an incident","d":"Raise an incident report for any work-related injury so it can be investigated.","o":"Supervisor"},{"t":"Restock kits","d":"Replace used items within 1 business day and check all kits and the AED monthly, including expiry dates and pads.","o":"Kit Checker"}],"checks":["First aider available on every shift","Kits checked monthly with a signed record","AED readiness indicator checked weekly","Treatment log kept confidentially"],"kpis":[["Shift coverage","100% of shifts have a first aider"],["Kit compliance","100% of monthly checks completed"],["Certificate currency","Zero expired certificates"]],"risks":[["No first aider present","Rota with deputies and appointed persons for small sites."],["Expired supplies or AED pads","Monthly check with expiry tracking."],["Confidential health data exposed","Store treatment logs securely with restricted access."]],"related":["Accident and Near-miss Reporting","Fire Evacuation and Drills","Health and Safety Policy"],"review":"Every 12 months, or after a serious medical incident"},{"id":"safety-visitor-signin-escort","dept":"safety","title":"Visitor Sign-in and Escort","summary":"Every visitor is expected, signed in, badged, escorted where needed and signed out, protecting people and information.","tags":["visitor management","reception","guest","badge","site security","contractor access"],"purpose":"To know who is on site at all times for safety and security reasons, and to protect confidential areas and information. It also gives visitors a professional welcome.","scope":"Covers all visitors, including candidates, clients, suppliers, contractors and family members, at every [Company] site. It does not cover employees, who use their own access badges, or delivery drivers who stay at the loading bay.","definitions":[["Host","The employee responsible for a visitor while on site."],["Restricted area","An area such as server rooms or finance where visitors need an escort and approval."],["Visitor badge","A dated, visible badge marking the wearer as a visitor."]],"roles":[["Host","Pre-registers, meets, escorts and signs out their visitor."],["Receptionist","Checks in visitors, issues badges and keeps the visitor log."],["Facilities Manager","Owns the process, visitor system and restricted area rules."],["Security Officer","Handles unescorted or suspicious visitors, where present."]],"prereqs":["Visitor management system or sign-in book","Visitor badges and lanyards","Visitor safety and confidentiality briefing card","Pre-registration form"],"steps":[{"t":"Pre-register the visitor","d":"Host registers visitors in [visitor system] at least 1 business day ahead with name, company, purpose, time and areas to be visited.","o":"Host"},{"t":"Approve restricted access","d":"Requests to enter restricted areas need approval from the area owner before the visit.","o":"Facilities Manager"},{"t":"Check in on arrival","d":"Confirm identity against the registration, record arrival time and ask the visitor to accept the confidentiality and safety notice.","o":"Receptionist"},{"t":"Issue a badge","d":"Give a dated visitor badge to be worn visibly at all times. Contractors also receive a site safety briefing.","o":"Receptionist"},{"t":"Collect the visitor","d":"Host meets the visitor at reception within 10 minutes. Visitors do not wander unaccompanied.","o":"Host"},{"t":"Escort throughout","d":"Keep visitors with you or in a designated meeting room. Keep screens locked and confidential papers away.","o":"Host"},{"t":"Handle unknown people","d":"Any employee who sees an unbadged person politely offers help and escorts them to reception, or calls security if they refuse.","o":"Security Officer"},{"t":"Sign out and return the badge","d":"Host takes the visitor to reception to sign out and return the badge. Reception records departure.","o":"Host"},{"t":"Reconcile the log","d":"At close of day, check that all visitors have signed out and follow up any open entries with the host.","o":"Receptionist"},{"t":"Retain and purge records","d":"Keep the visitor log for [retention period] and then delete it, in line with privacy rules.","o":"Facilities Manager"}],"checks":["Every visitor in the log has arrival and departure times","Badges issued and returned for every visit","Restricted area visits pre-approved","Visitor list available for fire roll call"],"kpis":[["Pre-registration rate","90% of visitors"],["Open sign-outs at end of day","Zero"],["Badge return rate","100%"]],"risks":[["Visitor unaccounted for in an emergency","Live visitor list available to the Roll Call Officer."],["Confidential information seen","Escort rule, clear desk and locked screens."],["Tailgating","Staff trained to challenge and reception positioned at the entry point."]],"related":["Fire Evacuation and Drills","Physical Security Policy","NDA Request and Signing","Contractor Management"],"review":"Every 12 months, or after a security incident"},{"id":"safety-hazardous-materials-handling","dept":"safety","title":"Hazardous Materials Handling","summary":"Hazardous substances are bought, stored, used and disposed of safely, with exposure controlled and spills handled correctly.","tags":["hazardous substances","chemicals","coshh","sds","spill response","dangerous goods","msds"],"purpose":"To protect people and the environment from harm caused by chemicals and other hazardous materials. It ensures risk assessments, safety data sheets, correct storage and disposal are in place.","scope":"Covers all chemicals, cleaning products, solvents, gases, batteries and other hazardous materials used or stored by [Company]. It does not cover the transport of dangerous goods by carriers, which follows carrier and regulatory rules.","definitions":[["SDS","Safety data sheet from the supplier describing hazards and controls."],["Substance risk assessment","Assessment of how a substance is used, who could be exposed and the controls needed, for example under COSHH."],["PPE","Personal protective equipment such as gloves, goggles and respirators."],["Spill kit","Kit with absorbents, PPE and bags for containing spills."]],"roles":[["Safety Lead","Approves new substances and maintains the chemical register."],["Area Supervisor","Makes sure controls, PPE and storage are used correctly."],["Trained Handler","Uses substances in line with assessment and training."],["Purchasing","Only buys approved substances and obtains SDS."]],"prereqs":["Chemical register","Current SDS for each substance","Substance risk assessments","Correct storage cabinets, PPE and spill kits","Licensed waste disposal contractor"],"steps":[{"t":"Approve before purchase","d":"Request approval for any new substance. The Safety Lead checks the SDS and whether a less hazardous alternative exists.","o":"Safety Lead"},{"t":"Obtain the SDS","d":"Purchasing obtains the current SDS before the first delivery and adds it to the register.","o":"Purchasing"},{"t":"Assess the risk","d":"Complete a substance risk assessment covering exposure routes, quantities, controls and PPE before first use.","o":"Safety Lead"},{"t":"Store correctly","d":"Store in labelled original containers, segregated by compatibility (for example flammables away from oxidisers) in suitable cabinets, below eye level.","o":"Area Supervisor"},{"t":"Train handlers","d":"Train users on hazards, controls, PPE and spill response before they handle the substance. Record training.","o":"Area Supervisor"},{"t":"Use with controls","d":"Use the minimum quantity, ventilation and PPE as stated in the assessment. Never decant into unlabelled containers.","o":"Trained Handler"},{"t":"Respond to spills","d":"Evacuate if needed, wear PPE, contain with the spill kit, ventilate and report. Call emergency services for large or toxic releases.","o":"Trained Handler"},{"t":"Dispose through licensed contractors","d":"Collect hazardous waste in labelled containers and dispose only via a licensed contractor, keeping transfer notes.","o":"Area Supervisor"},{"t":"Inspect storage monthly","d":"Check containers, labels, quantities, cabinet condition and spill kits monthly and record results.","o":"Area Supervisor"},{"t":"Review the register","d":"Review the register and assessments yearly and remove substances no longer used.","o":"Safety Lead"}],"checks":["Every substance on site is in the register with a current SDS","Risk assessment completed before first use","All containers labelled","Waste transfer notes kept"],"kpis":[["SDS coverage","100% of substances"],["Training coverage","100% of handlers trained before use"],["Spills reported","100%, with zero unreported exposures"]],"risks":[["Exposure causing ill health","Substitution, ventilation, PPE and health surveillance where required."],["Incompatible storage causing reaction","Segregation rules and monthly storage inspection."],["Illegal disposal","Licensed contractors only and retained transfer notes."]],"related":["Accident and Near-miss Reporting","Workplace Safety Inspection","PPE Issue and Use","Environmental Policy"],"review":"Every 12 months, or when a new substance or process is introduced"},{"id":"leadership-weekly-leadership-meeting","dept":"leadership","title":"Weekly Leadership Meeting","summary":"A focused weekly leadership meeting reviews metrics, resolves key issues and ends with clear owned actions.","tags":["leadership meeting","exec meeting","staff meeting","weekly sync","management team","agenda"],"purpose":"To give the leadership team a reliable weekly rhythm for reviewing performance, making decisions and staying aligned. It replaces ad hoc updates with a consistent agenda and action log.","scope":"Covers the weekly meeting of [Company]'s leadership team. It does not cover board meetings, quarterly planning or one-to-ones.","definitions":[["Scorecard","A set of 5 to 15 weekly metrics with owners and targets."],["Issues list","Topics needing discussion or a decision, ranked by importance."],["Action item","A task agreed in the meeting with one owner and a due date, normally within 7 days."]],"roles":[["Chair","Runs the meeting to time, keeps discussion on track and drives decisions."],["Meeting Coordinator","Prepares the agenda pack, takes notes and maintains the action log."],["Leadership Members","Update their metrics, raise issues and complete actions."],["Metric Owners","Enter scorecard numbers before the deadline."]],"prereqs":["Shared scorecard","Issues list","Action log","Fixed recurring 60 to 90 minute slot"],"steps":[{"t":"Update the scorecard","d":"Metric Owners enter last week's numbers by [day and time], at least 24 hours before the meeting, with a one-line note on any miss.","o":"Metric Owners"},{"t":"Add issues","d":"Leadership Members add issues to the list by the same deadline with a one-sentence statement of what is needed: decision, input or information.","o":"Leadership Members"},{"t":"Circulate the pack","d":"Send the agenda, scorecard, action log and issues list 24 hours ahead.","o":"Meeting Coordinator"},{"t":"Start on time with a check-in","d":"Open on time with a 5-minute round of headline good news or blockers.","o":"Chair"},{"t":"Review the scorecard","d":"Spend no more than 10 minutes. Each owner says on or off track; off-track items move to the issues list rather than being debated now.","o":"Chair"},{"t":"Review previous actions","d":"Confirm each action as done or not done. Undone actions get a new date once, then become an issue.","o":"Meeting Coordinator"},{"t":"Prioritise and solve issues","d":"Pick the top 3 issues and work through them one at a time: identify the root cause, discuss, decide and assign actions.","o":"Chair"},{"t":"Record decisions","d":"Note each decision, the rationale and who will communicate it.","o":"Meeting Coordinator"},{"t":"Agree communication","d":"In the last 5 minutes, agree what is shared with teams and by whom, and what stays confidential.","o":"Chair"},{"t":"Publish notes","d":"Share decisions and actions within 4 business hours of the meeting.","o":"Meeting Coordinator"},{"t":"Rate the meeting","d":"Each member scores the meeting 1 to 10; discuss any score below 8 briefly and adjust the format.","o":"Chair"}],"checks":["Scorecard complete before the meeting","Every action has a single owner and date","Decisions documented with rationale","Notes published within 4 business hours"],"kpis":[["Scorecard completion","100% before deadline"],["Action completion rate","85% or more by due date"],["Meeting rating","Average 8 or above"],["Start on time","95% of meetings"]],"risks":[["Meeting turns into status updates","Pre-read scorecard and time limits; only issues get discussion time."],["Decisions not followed through","Action log reviewed every week."],["Confidential topics leak","Agree explicitly what is shared."]],"related":["Quarterly OKR Setting","Quarterly Business Review","Weekly Status Reporting"],"review":"Every 6 months, or when the leadership team changes"},{"id":"leadership-quarterly-okr-setting","dept":"leadership","title":"Quarterly OKR Setting","summary":"Company and team OKRs are drafted, aligned, published and tracked each quarter so everyone knows what matters most.","tags":["okr","objectives and key results","goals","quarterly planning","priorities","alignment"],"purpose":"To set a small number of measurable priorities each quarter and align teams behind them. It creates focus and a fair basis for reviewing progress.","scope":"Covers company-level and team-level OKRs for all teams. It does not cover individual performance objectives, budgets or headcount planning, which are linked but run separately.","definitions":[["Objective","A qualitative, inspiring statement of what we want to achieve."],["Key result","A measurable outcome with a baseline and target that shows the objective is met."],["Committed vs aspirational","Committed OKRs are expected to be fully met; aspirational ones are stretch targets where 70% is good."],["Confidence score","An owner's weekly estimate, 0 to 10, of reaching a key result."]],"roles":[["CEO","Sets company objectives and makes final trade-off decisions."],["OKR Coordinator","Runs the timeline, templates, tool and quality checks."],["Team Leads","Draft team OKRs that support company OKRs."],["Key Result Owners","Track and update progress weekly."]],"prereqs":["Previous quarter OKR scores and retrospective","Company strategy and annual goals","Current metrics baseline","OKR tool or shared template"],"steps":[{"t":"Score last quarter","d":"In the last week of the quarter, owners score each key result 0.0 to 1.0 with a short comment on what was learned.","o":"Key Result Owners"},{"t":"Draft company OKRs","d":"Draft 3 to 5 company objectives with 2 to 4 key results each, 4 weeks before quarter start.","o":"CEO"},{"t":"Review with leadership","d":"Discuss drafts in a 2-hour session, test each key result for measurability and cut anything that is not a top priority.","o":"CEO"},{"t":"Share company draft","d":"Publish draft company OKRs to Team Leads 3 weeks before quarter start.","o":"OKR Coordinator"},{"t":"Draft team OKRs","d":"Team Leads draft up to 3 objectives that contribute to company OKRs, including dependencies on other teams, within 1 week.","o":"Team Leads"},{"t":"Check quality","d":"Check that key results are outcomes, not tasks, with baseline, target and single owner. Return weak drafts with comments within 2 business days.","o":"OKR Coordinator"},{"t":"Resolve dependencies","d":"Hold a cross-team session to agree dependencies and resolve conflicts in capacity or priority.","o":"Team Leads"},{"t":"Finalise and publish","d":"CEO approves final OKRs and they are published to all staff before day 1 of the quarter.","o":"CEO"},{"t":"Track weekly","d":"Owners update progress and confidence score weekly. Key results below confidence 5 are raised at the leadership meeting.","o":"Key Result Owners"},{"t":"Run a mid-quarter check","d":"At week 6, review progress and agree whether to adjust, drop or add effort. Changes are recorded, not hidden.","o":"OKR Coordinator"}],"checks":["No more than 5 company objectives","Every key result has a baseline, target and owner","Team OKRs link to at least one company OKR","Weekly updates recorded"],"kpis":[["OKRs published on time","100% before quarter start"],["Weekly update rate","90% of key results updated each week"],["Average committed OKR score","0.9 or above"],["Average aspirational OKR score","0.6 to 0.7"]],"risks":[["Too many priorities","Hard limits on number of objectives and key results."],["Key results are activities","Quality check against outcome criteria."],["OKRs forgotten after setting","Weekly confidence updates in the leadership meeting."]],"related":["Weekly Leadership Meeting","Quarterly Business Review","Performance Review Cycle","Annual Budgeting"],"review":"Every 12 months, or after a quarterly retrospective"},{"id":"leadership-quarterly-business-review","dept":"leadership","title":"Quarterly Business Review","summary":"Each quarter, leadership reviews results against plan, understands the reasons and agrees decisions for the next quarter.","tags":["qbr","quarterly review","business review","performance review","quarter end","results"],"purpose":"To review the quarter's performance honestly with data and turn the lessons into decisions. It connects financial results, OKRs and operational health in one place.","scope":"Covers the internal quarterly business review for the leadership team and department heads. It does not cover customer-facing QBRs run by account managers or board meetings.","definitions":[["Plan vs actual","Comparison of budgeted figures with achieved results."],["Variance","The difference between plan and actual, in value and percentage."],["Department pack","A short standard set of slides each department submits."]],"roles":[["CEO","Chairs the review and owns final decisions."],["Finance Lead","Provides financial results and variance analysis."],["Department Heads","Prepare department packs and explain results."],["Chief of Staff","Coordinates the timeline, template and follow-up actions."]],"prereqs":["Closed management accounts for the quarter","OKR scores","Department KPI dashboards","Standard QBR template"],"steps":[{"t":"Schedule the review","d":"Book a half-day session within 15 business days after quarter end, once the books are closed.","o":"Chief of Staff"},{"t":"Issue the template","d":"Send the department pack template with a deadline 5 business days before the review: results, wins, misses, root causes, risks and asks.","o":"Chief of Staff"},{"t":"Close the numbers","d":"Prepare revenue, gross margin, operating costs, cash and runway against plan, with explanations for variances above [10%].","o":"Finance Lead"},{"t":"Prepare department packs","d":"Each department submits up to [6] slides focused on outcomes and causes, not activity lists.","o":"Department Heads"},{"t":"Circulate a pre-read","d":"Combine and send the pack 3 business days before the session so time is spent on discussion.","o":"Chief of Staff"},{"t":"Review company performance","d":"Open with financials and company OKRs, then customer and people metrics.","o":"CEO"},{"t":"Run department reviews","d":"Each department gets a fixed slot: 5 minutes highlights, the rest questions and challenges.","o":"Department Heads"},{"t":"Identify cross-cutting themes","d":"Capture recurring problems and opportunities across departments on a shared board.","o":"Chief of Staff"},{"t":"Make decisions","d":"Agree decisions on priorities, budget reallocation, hiring and stopping work, each with an owner.","o":"CEO"},{"t":"Communicate outcomes","d":"Share a summary with all staff within 5 business days, and feed decisions into next quarter's OKRs.","o":"Chief of Staff"}],"checks":["Pack circulated 3 business days ahead","Variances above threshold explained","Every decision has an owner and date","Staff summary shared within 5 business days"],"kpis":[["QBR held on time","Within 15 business days of quarter end"],["Pre-read on time","100% of packs"],["Decision follow-through","90% of actions done by next QBR"]],"risks":[["Review becomes presentation theatre","Pre-read and time limits favour discussion."],["Numbers not reliable","Hold QBR only after the month-end close."],["No change after review","Track decisions in the leadership action log."]],"related":["Quarterly OKR Setting","Board Meeting Preparation","Month-end Close","Weekly Leadership Meeting"],"review":"Every 12 months"},{"id":"leadership-board-meeting-preparation","dept":"leadership","title":"Board Meeting Preparation","summary":"Board meetings are scheduled, prepared and minuted properly, with papers sent on time and resolutions recorded.","tags":["board meeting","board pack","directors","investor update","minutes","governance","resolutions"],"purpose":"To make board meetings productive and well-governed by preparing a clear board pack and accurate records. It helps directors make informed decisions and meet their legal duties.","scope":"Covers regular and special meetings of [Company]'s board of directors and its committees. It does not cover shareholder general meetings, which follow the company's constitution and local law.","definitions":[["Board pack","The agenda, reports and papers sent to directors before the meeting."],["Quorum","The minimum number of directors required for decisions to be valid, as set in the constitution."],["Resolution","A formal decision of the board, recorded in the minutes or by written consent."],["Company Secretary","The person responsible for governance records; may be a director or an external provider."]],"roles":[["CEO","Sets the agenda with the Chair and presents the business update."],["Board Chair","Approves the agenda and runs the meeting."],["Company Secretary","Issues notice, compiles the pack, records minutes and maintains statutory records."],["Finance Lead","Prepares financial statements, forecast and cash position."],["Paper Authors","Write papers on specific decisions or topics."]],"prereqs":["Annual board calendar","Constitution and shareholders' agreement (notice and quorum rules)","Previous minutes and action log","Secure board portal or shared folder"],"steps":[{"t":"Set the annual calendar","d":"Schedule all regular board meetings for the year in advance, typically [quarterly].","o":"Company Secretary"},{"t":"Agree the agenda","d":"Four weeks before, CEO and Chair agree the agenda, separating items for decision, discussion and noting.","o":"CEO"},{"t":"Commission papers","d":"Ask Paper Authors for papers using the standard cover sheet (purpose, recommendation, options, risks) with a deadline 10 business days before.","o":"Company Secretary"},{"t":"Prepare financials","d":"Produce financial results, KPIs, cash runway and forecast vs budget with commentary.","o":"Finance Lead"},{"t":"Write the CEO update","d":"Write a 2 to 4 page update on performance, strategy, key risks, people and asks of the board.","o":"CEO"},{"t":"Review the pack","d":"CEO reviews all papers for consistency and clarity 8 business days before.","o":"CEO"},{"t":"Issue notice and pack","d":"Send notice and the full pack through the secure portal at least [7] calendar days before, or as the constitution requires.","o":"Company Secretary"},{"t":"Collect conflicts and apologies","d":"Ask directors to confirm attendance and declare conflicts on agenda items before the meeting. Confirm quorum.","o":"Company Secretary"},{"t":"Hold the meeting","d":"Chair runs to the agenda, records conflicts, and ensures each decision item ends in a clear resolution.","o":"Board Chair"},{"t":"Draft minutes","d":"Circulate draft minutes and the action list to the Chair within 5 business days.","o":"Company Secretary"},{"t":"Approve and file","d":"Approve minutes at or before the next meeting, sign them and file statutory changes with the registry within the legal deadline.","o":"Company Secretary"},{"t":"Track actions","d":"Track board actions and report status at the start of the next meeting.","o":"CEO"}],"checks":["Notice period and quorum met","Every decision item has a recommendation","Conflicts recorded","Signed minutes filed","Statutory filings made on time"],"kpis":[["Pack sent on time","100% at least [7] days before"],["Minutes drafted","100% within 5 business days"],["Board actions completed","90% by next meeting"]],"risks":[["Invalid decisions due to notice or quorum failures","Check constitution rules in the pre-meeting checklist."],["Confidential pack leaks","Secure portal with access controls, no email attachments."],["Directors surprised by bad news","CEO informs the Chair of material issues before the pack."]],"related":["Quarterly Business Review","Conflict of Interest Declaration","Fundraising Data Room Preparation","Delegation of Authority Policy"],"review":"Every 12 months, or after a change in board composition or constitution"},{"id":"leadership-crisis-management","dept":"leadership","title":"Crisis Management","summary":"A crisis team is activated quickly, makes decisions with clear authority and communicates accurately until recovery.","tags":["crisis","emergency response","incident management","business continuity","crisis communications","reputation"],"purpose":"To protect people, customers, assets and reputation when a serious event threatens the business. It sets who leads, how decisions are made and how [Company] communicates under pressure.","scope":"Covers events with major impact, such as serious injury, major data breach, extended outage, loss of a key site, fraud, legal action or reputational attack. It does not replace the specific technical runbooks used to fix the underlying problem.","definitions":[["Crisis","An event that threatens people's safety, business continuity, finances or reputation and needs leadership response beyond normal operations."],["Crisis Management Team (CMT)","The small leadership group that takes control during a crisis."],["Holding statement","A short, approved first message acknowledging the situation while facts are confirmed."],["Severity level","Level 1 (major), 2 (serious) or 3 (contained), defined by impact criteria."]],"roles":[["Crisis Lead","Usually the CEO; chairs the CMT and makes final decisions."],["Communications Lead","Owns internal, customer, media and social messages."],["Operations Lead","Coordinates the operational response and business continuity."],["Legal Counsel","Advises on legal duties, regulator notification and liability."],["Crisis Coordinator","Keeps the decision log, schedules updates and tracks actions."]],"prereqs":["Crisis contact list with backups, held offline too","Severity criteria","Pre-approved holding statement templates","Business continuity plans","Dedicated communication channel for the CMT"],"steps":[{"t":"Escalate the event","d":"Anyone aware of a possible crisis informs their manager and the Crisis Lead immediately. Do not wait for full facts.","o":"Operations Lead"},{"t":"Assess and declare","d":"Within 30 minutes, Crisis Lead assesses severity against the criteria and declares a crisis, activating the CMT for Level 1 or 2.","o":"Crisis Lead"},{"t":"Convene the CMT","d":"Assemble the CMT on the dedicated channel within 1 hour. Assign roles and backups if anyone is unavailable.","o":"Crisis Coordinator"},{"t":"Protect people first","d":"Confirm everyone's safety and take immediate steps to stop further harm.","o":"Operations Lead"},{"t":"Establish the facts","d":"Gather what is known, unknown and assumed. Record it on a single shared status page.","o":"Crisis Coordinator"},{"t":"Check legal obligations","d":"Identify notification duties (regulators, data protection authority, insurers, police) and their deadlines.","o":"Legal Counsel"},{"t":"Issue a holding statement","d":"Send an approved holding statement to staff and affected stakeholders within [2] hours. Staff must not comment publicly.","o":"Communications Lead"},{"t":"Decide and log","d":"Make decisions with the information available. Record each decision, reason, owner and time in the decision log.","o":"Crisis Lead"},{"t":"Run an update rhythm","d":"Hold CMT updates at fixed intervals (for example every 2 to 4 hours) and update stakeholders on a published schedule.","o":"Crisis Coordinator"},{"t":"Activate continuity plans","d":"Invoke business continuity plans to keep critical services running.","o":"Operations Lead"},{"t":"Stand down","d":"Crisis Lead declares the end when the situation is stable and communicates it to everyone involved.","o":"Crisis Lead"},{"t":"Review and improve","d":"Within 10 business days, hold a blameless review and update plans, contacts and templates.","o":"Crisis Coordinator"}],"checks":["Severity assessed within 30 minutes","Decision log maintained throughout","Regulatory notifications made within deadlines","One approved voice for external communications","Post-crisis review completed"],"kpis":[["CMT activation time","Within 1 hour"],["Holding statement time","Within 2 hours"],["Crisis exercises","At least 1 tabletop per year"],["Review completion","100% within 10 business days"]],"risks":[["Key people unreachable","Named backups and contact list kept offline."],["Inconsistent or inaccurate messaging","Single Communications Lead and approved templates."],["Missed legal notification","Legal Counsel on CMT with a notification checklist."]],"related":["Fire Evacuation and Drills","Data Breach Response","Business Continuity Plan","Board Meeting Preparation"],"review":"Every 12 months, after every crisis or tabletop exercise"},{"id":"leadership-fundraising-data-room","dept":"leadership","title":"Fundraising Data Room Preparation","summary":"A complete, organised and secure data room is ready before investor due diligence starts.","tags":["data room","due diligence","fundraising","investors","vdr","series a","seed round"],"purpose":"To speed up investor due diligence and reduce deal risk by preparing accurate documents in advance. It also controls who sees confidential information and when.","scope":"Covers equity fundraising rounds and similar transactions, such as debt facilities or strategic investment. It does not cover the pitch deck or investor outreach process, or a full sale of the company, which needs specialist advisers.","definitions":[["Virtual data room (VDR)","A secure online repository with access controls and activity tracking."],["Cap table","The record of all shares, options and convertible instruments and who holds them."],["Due diligence request list","The investor's list of documents and questions."],["Staged access","Releasing more sensitive folders only as investors progress."]],"roles":[["CEO","Owns the fundraising process and investor relationships."],["Finance Lead","Prepares financial statements, model, cap table and metrics."],["Legal Counsel","Prepares corporate, contract and IP documents and advises on disclosure."],["Data Room Administrator","Builds the structure, uploads files and manages permissions."],["Department Owners","Provide documents for their area."]],"prereqs":["Data room platform","Standard folder index","Signed NDAs with each investor before access","Current cap table and financial statements"],"steps":[{"t":"Create the index","d":"Build a numbered folder structure: corporate, cap table, financials, commercial, customers, product and technology, IP, people, legal and compliance.","o":"Data Room Administrator"},{"t":"Assign document owners","d":"Allocate each folder to an owner with a deadline at least 4 weeks before investor meetings.","o":"CEO"},{"t":"Clean up the cap table","d":"Reconcile cap table with share registers, option grants and convertibles. Fix discrepancies before upload.","o":"Finance Lead"},{"t":"Prepare financials","d":"Upload historical financials, monthly management accounts, the model with assumptions, and key SaaS or business metrics with definitions.","o":"Finance Lead"},{"t":"Gather legal documents","d":"Collect constitution, board minutes, material contracts, IP assignments from founders, staff and contractors, and any litigation details.","o":"Legal Counsel"},{"t":"Fix gaps found","d":"Address gaps such as unsigned IP assignments or missing board approvals before investors find them.","o":"Legal Counsel"},{"t":"Redact sensitive data","d":"Remove personal data and anonymise customer names where contracts or privacy rules require. Do not upload individual salary data until late-stage.","o":"Data Room Administrator"},{"t":"Set staged permissions","d":"Grant view-only, watermarked access per investor after NDA signing. Release sensitive folders only at term sheet stage.","o":"Data Room Administrator"},{"t":"Answer questions through a log","d":"Track investor questions in a Q&A log and answer within 2 business days, with Legal reviewing anything contractual.","o":"CEO"},{"t":"Monitor activity","d":"Review access reports weekly to see which investors are engaged and which documents attract attention.","o":"CEO"},{"t":"Close and archive","d":"At closing, revoke all external access and archive a full copy of the data room as disclosed.","o":"Data Room Administrator"}],"checks":["Every folder has an owner and is complete before launch","Cap table reconciled","NDA in place before access","Personal data redacted","Access revoked at close"],"kpis":[["Data room readiness","100% of index complete before first meeting"],["Q&A response time","90% within 2 business days"],["Due diligence duration","Under [6] weeks"]],"risks":[["Inconsistent numbers across documents","Single source for metrics and a final consistency review."],["Leak of confidential information","Watermarking, view-only access and staged release."],["Undisclosed issues damage trust","Proactive disclosure of known issues with context."]],"related":["NDA Request and Signing","Board Meeting Preparation","Document Retention and Disposal","Contract Review and Approval"],"review":"Before each fundraising round, or every 12 months"},{"id":"retail-store-opening","dept":"retail","title":"Store Opening","summary":"The store opens on time, safe, clean, stocked and with a verified till float, every trading day.","tags":["store opening","opening checklist","shop","retail operations","till float","morning routine"],"purpose":"To make sure every store opens to customers on time in a safe, presentable and ready state. A consistent routine also protects cash and stock at the most vulnerable time of day.","scope":"Covers the daily opening routine for all [Company] retail stores and cafes. It does not cover new store launches or refits, which follow the project process.","definitions":[["Float","The fixed amount of cash placed in each till at opening, for example [float amount]."],["Two-person opening","Rule that two staff are present when the store is unlocked, for safety."],["Opening checklist","The daily form recording each opening task and who did it."]],"roles":[["Opening Manager","Leads the opening, holds keys and alarm codes, verifies cash."],["Store Associate","Completes assigned floor, stock and cleaning tasks."],["Area Manager","Reviews checklists and follows up exceptions."]],"prereqs":["Keys and alarm code","Opening checklist","Safe with counted floats","Rota showing opening staff"],"steps":[{"t":"Arrive and check the exterior","d":"Arrive [30 to 45] minutes before opening. Check doors, windows and shutters for damage or forced entry before unlocking. If anything looks wrong, do not enter and call security or police.","o":"Opening Manager"},{"t":"Enter with two people","d":"Unlock with a second staff member present, disarm the alarm within the entry time and relock the door behind you.","o":"Opening Manager"},{"t":"Walk the store","d":"Check for leaks, damage, temperature of fridges and freezers, and that fire exits are clear. Record fridge temperatures on the log.","o":"Store Associate"},{"t":"Prepare tills","d":"Take floats from the safe, count them with a second person and record the amount. Log in to tills and test card terminals.","o":"Opening Manager"},{"t":"Power up systems","d":"Turn on lighting, music, digital signage and point of sale; check stock and price updates have downloaded.","o":"Store Associate"},{"t":"Replenish and face up","d":"Fill gaps on shelves from the stockroom, face up products and check promotional pricing matches the system.","o":"Store Associate"},{"t":"Clean customer areas","d":"Clean entrance, floors, counters and fitting rooms or seating to standard.","o":"Store Associate"},{"t":"Hold a team huddle","d":"Brief the team for 5 minutes on sales targets, promotions, deliveries and any issues.","o":"Opening Manager"},{"t":"Complete the checklist","d":"Sign off every checklist item and note exceptions with action taken.","o":"Opening Manager"},{"t":"Open the doors on time","d":"Unlock customer doors at the exact opening time and greet the first customers.","o":"Opening Manager"}],"checks":["Float counted by two people and recorded","Fridge temperatures logged before trading","Fire exits clear","Checklist signed daily"],"kpis":[["On-time opening","100% of trading days"],["Checklist completion","100% daily"],["Float discrepancies","Zero"]],"risks":[["Opening alone exposes staff to robbery","Two-person opening rule and exterior check."],["Wrong prices displayed","Daily price check against system before opening."],["Temperature failures unnoticed","Log fridge temperatures before trading and escalate out-of-range readings."]],"related":["Store Closing and Cash-up","Food Safety and Hygiene (HACCP-based)","Stocktake","Cash Handling Policy"],"review":"Every 12 months, or after a security incident"},{"id":"retail-store-closing-cash-up","dept":"retail","title":"Store Closing and Cash-up","summary":"The store closes securely each day with tills reconciled, cash banked and premises locked and alarmed.","tags":["store closing","cash up","till reconciliation","end of day","banking","z report"],"purpose":"To close stores safely and account for every sale and every unit of cash each day. It detects errors and theft early and protects staff.","scope":"Covers the daily close and cash reconciliation for all stores. It does not cover month-end accounting, which uses the daily figures produced here.","definitions":[["Z report","End-of-day till report showing total sales by payment type, which resets the till."],["Variance","The difference between counted cash and expected cash from the Z report."],["Banking","Cash deposited in the bank or collected by a cash-in-transit service."],["Variance tolerance","The acceptable difference before investigation, for example [plus or minus small amount]."]],"roles":[["Closing Manager","Leads the close, reconciles tills and secures cash and premises."],["Store Associate","Completes closing floor and cleaning tasks."],["Finance Team","Checks daily reports, banking and follows up variances."],["Area Manager","Investigates repeated variances."]],"prereqs":["Closing checklist","Cash-up sheet or POS reconciliation screen","Safe and banking bags","Alarm code"],"steps":[{"t":"Announce closing","d":"Announce closing 15 minutes and 5 minutes before time, then lock the door at closing time and let remaining customers out through one door.","o":"Closing Manager"},{"t":"Sweep the store","d":"Check fitting rooms, toilets and stockroom to make sure no customers remain.","o":"Store Associate"},{"t":"Run the Z report","d":"Close each till and print or save the Z report.","o":"Closing Manager"},{"t":"Count cash with a witness","d":"Count each till away from the shop window with a second person. Remove the float and record notes, coins and card totals on the cash-up sheet.","o":"Closing Manager"},{"t":"Reconcile and record variances","d":"Compare counted cash with the Z report. Variances above [tolerance] must be recounted, explained in writing and reported to the Area Manager the same day.","o":"Closing Manager"},{"t":"Reconcile card terminals","d":"Run end-of-day batch on card terminals and check totals match the POS card figure.","o":"Closing Manager"},{"t":"Prepare banking","d":"Place takings in a sealed, numbered banking bag, record the bag number and store in the safe until banking or collection.","o":"Closing Manager"},{"t":"Clean and tidy","d":"Clean floors, counters and equipment, empty bins and recover the shop floor for the next day.","o":"Store Associate"},{"t":"Secure the premises","d":"Turn off non-essential equipment, check doors, windows and fire exits are secure, set the alarm and leave together.","o":"Closing Manager"},{"t":"Submit daily figures","d":"Upload the cash-up sheet and Z report to [finance system] by [time] the next morning.","o":"Closing Manager"},{"t":"Review daily reports","d":"Finance reviews sales, variances and banking by 12:00 the next business day and queries anything missing.","o":"Finance Team"}],"checks":["Two people present for cash count","Variances above tolerance explained in writing","Banking bag numbers recorded","Alarm set and logged"],"kpis":[["Cash variance","Within [tolerance] on 98% of days"],["Banking on time","100% within [1 business day]"],["Daily report submission","100% by [time]"]],"risks":[["Theft of cash","Two-person counts, sealed bags, minimal cash on premises and regular collection."],["Staff safety at close","Leave together and avoid counting in view of windows."],["Customer locked in or hidden","Full store sweep before alarming."]],"related":["Store Opening","Cash Handling Policy","Stocktake","Month-end Close"],"review":"Every 12 months, or after a cash loss incident"},{"id":"retail-food-safety-haccp","dept":"retail","title":"Food Safety and Hygiene (HACCP-based)","summary":"Food is prepared, stored and served safely through monitored critical control points, hygiene rules and records.","tags":["food safety","haccp","hygiene","temperature log","allergens","kitchen","critical control point"],"purpose":"To prevent food from making customers ill by controlling hazards at every stage from delivery to service. It provides the daily records that inspectors expect.","scope":"Covers all food handling at [Company] cafes, kitchens, food stores and catering operations. It does not replace the site's full HACCP plan, which this SOP puts into daily practice, and food safety law varies, so check local requirements.","definitions":[["HACCP","Hazard Analysis and Critical Control Points: a system for identifying and controlling food hazards."],["Critical control point (CCP)","A step where control is essential to prevent or remove a hazard, such as cooking temperature."],["Critical limit","The value that must be met at a CCP, for example core temperature of [75°C] or as local guidance requires."],["Corrective action","What staff must do when a critical limit is not met."]],"roles":[["Food Safety Lead","Owns the HACCP plan, training and record review."],["Shift Supervisor","Makes sure daily checks are completed and corrective actions taken."],["Food Handlers","Follow hygiene rules and record CCP checks."],["Receiving Staff","Check deliveries against acceptance criteria."]],"prereqs":["Site HACCP plan","Calibrated probe thermometer","Daily temperature and cleaning logs","Allergen matrix for all menu items","Food handler training records"],"steps":[{"t":"Check staff fitness to work","d":"At the start of each shift, staff confirm they have had no vomiting or diarrhoea in the last 48 hours and cover any cuts with blue plasters.","o":"Shift Supervisor"},{"t":"Wash hands and wear clean clothing","d":"Wash hands on entry, after breaks, after handling raw food and after touching waste.","o":"Food Handlers"},{"t":"Receive deliveries","d":"Check chilled goods at or below [5°C] and frozen at or below [-18°C], packaging intact and in date. Reject and record failures.","o":"Receiving Staff"},{"t":"Store food correctly","d":"Store raw below ready-to-eat food, label all opened and prepared items with date, and rotate first in, first out.","o":"Food Handlers"},{"t":"Monitor fridges and freezers","d":"Record temperatures at least twice daily. Out-of-range readings trigger moving food and a supervisor check.","o":"Food Handlers"},{"t":"Cook to critical limits","d":"Probe the thickest part of high-risk foods and record core temperature. Continue cooking if below the limit.","o":"Food Handlers"},{"t":"Cool and reheat safely","d":"Cool cooked food to below [8°C] within [90 minutes] and reheat to the critical limit once only.","o":"Food Handlers"},{"t":"Control allergens","d":"Use the allergen matrix to answer every customer allergy question, use separate utensils and never guess.","o":"Shift Supervisor"},{"t":"Clean to schedule","d":"Follow the cleaning schedule with the correct dilution and contact time for sanitiser, and sign it off.","o":"Food Handlers"},{"t":"Take corrective action","d":"When a critical limit is missed, follow the plan (discard, re-cook or quarantine), record what was done and inform the supervisor.","o":"Shift Supervisor"},{"t":"Calibrate thermometers","d":"Check probes weekly in iced water and boiling water and replace any outside [plus or minus 1°C].","o":"Food Safety Lead"},{"t":"Review records weekly","d":"Review all logs weekly, address gaps and keep records for [retention period] for inspections.","o":"Food Safety Lead"}],"checks":["Every CCP has a record for each shift","Corrective actions recorded for every deviation","Allergen matrix updated for each menu change","All handlers trained before handling food"],"kpis":[["Temperature log completion","100% of required checks"],["Inspection rating","Highest local rating"],["Food safety incidents","Zero customer illnesses or allergen incidents"]],"risks":[["Allergen cross-contamination","Allergen matrix, separate equipment and staff training."],["Incomplete records","Supervisor sign-off each shift and weekly review."],["Faulty thermometer giving false readings","Weekly calibration checks."]],"related":["Store Opening","Supplier Approval","Accident and Near-miss Reporting","Cleaning Schedule"],"review":"Every 12 months, or after a menu change, new equipment or food safety incident"},{"id":"retail-ecommerce-order-processing","dept":"retail","title":"Ecommerce Order Processing","summary":"Online orders are checked, picked, packed and shipped accurately within the promised dispatch time.","tags":["ecommerce","order fulfilment","pick and pack","shipping","online orders","dispatch","warehouse"],"purpose":"To deliver online orders accurately and on time while stopping fraudulent orders. It sets clear cut-off times and quality checks for the fulfilment team.","scope":"Covers all orders placed on [Company]'s web store and marketplaces and fulfilled from our own stock. It does not cover returns or drop-shipped orders fulfilled by suppliers.","definitions":[["Cut-off time","The latest order time for same-day dispatch, for example [14:00]."],["Pick list","The list of items and bin locations for an order or batch."],["Order hold","An order paused for fraud, address or stock checks."],["Dispatch SLA","The promised time from order to handover to the carrier."]],"roles":[["Order Processor","Reviews new orders, handles holds and customer contact."],["Picker","Picks items accurately from locations."],["Packer","Checks, packs and labels orders."],["Fulfilment Manager","Owns SLAs, carrier relations and exception handling."]],"prereqs":["Order management system","Barcode scanners","Packaging materials and inserts","Carrier accounts and label printer","Fraud screening rules"],"steps":[{"t":"Import orders","d":"Sync orders from all sales channels at least every [30 minutes] so none are missed.","o":"Order Processor"},{"t":"Screen for fraud","d":"Review orders flagged by the fraud tool (for example billing and shipping mismatch, high value, rush delivery). Place on hold and verify with the customer within 4 business hours.","o":"Order Processor"},{"t":"Check address and stock","d":"Validate incomplete addresses and confirm stock is available. Contact the customer the same day if anything is wrong.","o":"Order Processor"},{"t":"Batch and print pick lists","d":"Release orders before the cut-off into pick batches sorted by location route.","o":"Fulfilment Manager"},{"t":"Pick by scanning","d":"Scan each item's barcode at the location. Report shortages immediately rather than substituting.","o":"Picker"},{"t":"Verify at packing","d":"Scan every item again against the order and check for damage. Mismatches go back to the picker.","o":"Packer"},{"t":"Pack to standard","d":"Use the right box size, protective fill and inserts. Fragile items get extra protection and labels.","o":"Packer"},{"t":"Label and manifest","d":"Print the carrier label, apply it to the top face and add the parcel to the carrier manifest.","o":"Packer"},{"t":"Hand over to the carrier","d":"Scan parcels at handover and get the driver's signature or scan confirmation on the manifest.","o":"Fulfilment Manager"},{"t":"Notify the customer","d":"Send the dispatch email with tracking automatically within 1 hour of handover.","o":"Order Processor"},{"t":"Manage exceptions","d":"Review unshipped orders past SLA daily and contact affected customers proactively.","o":"Fulfilment Manager"}],"checks":["Every item scanned at pick and pack","Fraud-flagged orders verified before release","Carrier handover confirmed","Late orders reviewed daily"],"kpis":[["On-time dispatch","98% of orders within SLA"],["Order accuracy","99.5% or higher"],["Chargeback rate","Below [0.5%]"],["Damage in transit","Below [0.5%]"]],"risks":[["Wrong item shipped","Scan-to-verify at pick and pack."],["Fraudulent orders","Fraud rules and manual verification before dispatch."],["Missed carrier collection","Fixed collection times and a backup carrier."]],"related":["Returns and Refunds","New Product Listing","Stocktake","Customer Complaint Handling"],"review":"Every 12 months, or after a new channel or carrier"},{"id":"retail-new-product-listing","dept":"retail","title":"New Product Listing","summary":"New products go live online and in-store with accurate data, compliant content, correct pricing and stock in place.","tags":["product listing","catalogue","sku","product data","merchandising","pim","new product"],"purpose":"To make sure every new product is listed accurately and consistently across all channels. Good product data drives sales and reduces returns and complaints.","scope":"Covers adding new products and variants to [Company]'s web store, marketplaces and point of sale. It does not cover supplier selection or price changes on existing products.","definitions":[["SKU","Stock keeping unit: a unique code for each product variant."],["PIM","Product information management system holding master product data."],["Listing checklist","Required data fields and checks that must pass before go-live."]],"roles":[["Buyer","Approves the product, cost, retail price and launch date."],["Catalogue Coordinator","Creates SKUs and enters product data."],["Content Creator","Produces images and descriptions."],["Compliance Reviewer","Checks claims, labelling and safety information."],["Ecommerce Manager","Approves go-live and monitors performance."]],"prereqs":["Supplier product information and specifications","Approved cost and retail price","Product samples for photography","Listing checklist and style guide"],"steps":[{"t":"Approve the product","d":"Buyer confirms the product, cost, margin, retail price and launch date and opens a listing request.","o":"Buyer"},{"t":"Create the SKU","d":"Create SKUs and variants using the naming convention and assign barcodes. Check for duplicates first.","o":"Catalogue Coordinator"},{"t":"Enter product data","d":"Enter title, attributes, dimensions, weight, materials, care instructions, country of origin and tax code in the PIM.","o":"Catalogue Coordinator"},{"t":"Photograph the product","d":"Shoot images to the style guide: plain background main image plus at least [3] detail or lifestyle images.","o":"Content Creator"},{"t":"Write the description","d":"Write a clear description with benefits, specifications and search keywords, avoiding unverified claims.","o":"Content Creator"},{"t":"Check compliance","d":"Check claims, allergen or ingredient information, safety warnings and age restrictions against local rules.","o":"Compliance Reviewer"},{"t":"Set price and promotions","d":"Load the retail price and any launch promotion in all channels and check it displays correctly.","o":"Catalogue Coordinator"},{"t":"Confirm stock is received","d":"Only go live when stock is booked into inventory, unless a pre-order is approved.","o":"Catalogue Coordinator"},{"t":"Run the go-live check","d":"Check the listing on desktop and mobile for every channel against the checklist.","o":"Ecommerce Manager"},{"t":"Publish and announce","d":"Publish and inform marketing and store teams of the launch.","o":"Ecommerce Manager"},{"t":"Review performance","d":"Review views, conversion, returns and reviews after 30 days and improve content as needed.","o":"Ecommerce Manager"}],"checks":["No duplicate SKUs","All mandatory fields complete before go-live","Claims and safety information approved","Price matches across channels"],"kpis":[["Time to list","Within [5] business days of stock receipt"],["Listing error rate","Below 2% of listings"],["Returns due to wrong description","Below [1%]"]],"risks":[["Misleading product claims","Compliance review before publication."],["Selling stock you do not have","Go-live only after stock is booked in."],["Price errors","Price checks in all channels before launch."]],"related":["Ecommerce Order Processing","Stocktake","Pricing Policy","Supplier Onboarding"],"review":"Every 12 months, or after adding a new sales channel"},{"id":"retail-stocktake","dept":"retail","title":"Stocktake","summary":"Physical stock is counted accurately, reconciled with the system and variances investigated and posted.","tags":["stocktake","inventory count","cycle count","shrinkage","stock reconciliation","inventory audit"],"purpose":"To confirm that inventory records match physical stock, so that financial reports, reorders and online availability are correct. It also measures shrinkage and its causes.","scope":"Covers full annual or periodic stocktakes and regular cycle counts in stores and warehouses. It does not cover stock valuation policy, which is set by Finance.","definitions":[["Full stocktake","A count of all stock at one point in time, usually with trading or movements stopped."],["Cycle count","Counting a subset of locations on a rolling schedule."],["Shrinkage","Stock loss from theft, damage, admin error or supplier fraud."],["Blind count","Counting without seeing the expected system quantity."]],"roles":[["Stocktake Lead","Plans and controls the count and approves results."],["Counters","Count stock accurately in assigned zones."],["Checkers","Recount samples and investigate differences."],["Finance Team","Reviews variances and posts adjustments."]],"prereqs":["Location map and zone allocation","Handheld scanners or count sheets","Cut-off for deliveries, sales and transfers","Pre-count tidy and labelled locations"],"steps":[{"t":"Plan the count","d":"Set the date, zones, team and cut-off at least 2 weeks ahead. Schedule outside trading hours where possible.","o":"Stocktake Lead"},{"t":"Prepare locations","d":"Tidy stock, process all receipts, returns and transfers, and label every location. Separate damaged stock.","o":"Stocktake Lead"},{"t":"Freeze movements","d":"At cut-off, stop deliveries and transfers and record the last document numbers.","o":"Stocktake Lead"},{"t":"Brief counters","d":"Brief the team on zones, units of measure, how to count packs and how to record damaged items.","o":"Stocktake Lead"},{"t":"Count blind","d":"Counters scan or count each location without seeing system quantities and mark zones as complete.","o":"Counters"},{"t":"Check samples","d":"Recount at least [10%] of locations and all high-value items. Differences above [threshold] trigger a full recount of that zone.","o":"Checkers"},{"t":"Compare with the system","d":"Generate the variance report once all zones are complete.","o":"Stocktake Lead"},{"t":"Investigate significant variances","d":"Check variances above [value threshold] for unprocessed paperwork, mis-located stock or unit errors before accepting.","o":"Checkers"},{"t":"Approve and post adjustments","d":"Stocktake Lead and Finance approve adjustments; Finance posts them with a reference.","o":"Finance Team"},{"t":"Report shrinkage","d":"Report shrinkage by category and cause and agree actions, such as security or process changes, within 10 business days.","o":"Stocktake Lead"},{"t":"Run cycle counts","d":"Between full counts, count high-value or fast-moving SKUs [weekly] and others on a rotating schedule.","o":"Stocktake Lead"}],"checks":["Movements frozen during the count","Blind counts used","High-value items double counted","Adjustments approved by two people"],"kpis":[["Inventory accuracy","98% or higher at location level"],["Shrinkage","Below [1%] of sales"],["Cycle count completion","100% of schedule"]],"risks":[["Counting errors","Blind counts, check counts and recounts above threshold."],["Manipulating results to hide theft","Two-person approval of adjustments and independent checkers."],["Cut-off errors","Freeze movements and record last document numbers."]],"related":["Store Closing and Cash-up","Ecommerce Order Processing","Goods Receiving","Month-end Close"],"review":"Every 12 months, or after a shrinkage spike"},{"id":"pm-project-kickoff","dept":"pm","title":"Project Kickoff","summary":"Every project starts with agreed objectives, scope, roles, plan and governance, documented in a charter.","tags":["project kickoff","project charter","initiation","project start","stakeholders","raci"],"purpose":"To start projects with a shared understanding of goals, scope, responsibilities and ways of working. A good kickoff prevents most later scope disputes and delays.","scope":"Covers internal and client projects above [effort threshold, e.g. 20 person-days]. It does not cover small tasks or business-as-usual work managed in team boards.","definitions":[["Project charter","A document authorising the project, stating objectives, scope, budget, timeline and roles."],["RACI","Matrix showing who is Responsible, Accountable, Consulted and Informed for each deliverable."],["Sponsor","The senior person who owns the business case and makes key decisions."],["Baseline","The approved scope, schedule and budget against which changes are measured."]],"roles":[["Project Sponsor","Approves the charter, provides resources and resolves escalations."],["Project Manager","Prepares the charter, runs the kickoff and sets up governance."],["Project Team","Contributes to planning and commits to deliverables."],["Key Stakeholders","Confirm requirements and acceptance criteria."]],"prereqs":["Approved business case, statement of work or contract","Charter template","Initial resource availability","Project workspace in [PM tool]"],"steps":[{"t":"Confirm authorisation","d":"Confirm the project is approved and funded, with a named Sponsor, before scheduling the kickoff.","o":"Project Manager"},{"t":"Draft the charter","d":"Write objectives, success measures, in-scope and out-of-scope items, key milestones, budget, assumptions and constraints.","o":"Project Manager"},{"t":"Map stakeholders","d":"List stakeholders with their interest, influence and how they will be engaged.","o":"Project Manager"},{"t":"Build the RACI","d":"Agree who is responsible and accountable for each major deliverable. Only one Accountable per deliverable.","o":"Project Manager"},{"t":"Agree charter with the Sponsor","d":"Review the draft with the Sponsor and resolve open points at least 3 business days before the kickoff.","o":"Project Sponsor"},{"t":"Run the kickoff meeting","d":"Hold a 60 to 90 minute kickoff to walk through goals, scope, plan, roles, risks and ways of working, with time for questions.","o":"Project Manager"},{"t":"Capture initial risks","d":"Run a 15-minute risk brainstorm in the kickoff and log the top risks with owners.","o":"Project Team"},{"t":"Set up governance","d":"Agree status reporting frequency, steering meeting cadence, decision and change rules, and escalation path.","o":"Project Manager"},{"t":"Set up tools","d":"Create the project workspace, plan, RAID log, document folder and communication channel, and give access.","o":"Project Manager"},{"t":"Baseline the plan","d":"Within 5 business days of kickoff, finalise the schedule with the team and get Sponsor sign-off to baseline it.","o":"Project Sponsor"},{"t":"Circulate the pack","d":"Share the signed charter, kickoff notes and plan with all stakeholders within 2 business days.","o":"Project Manager"}],"checks":["Charter signed by the Sponsor","Out-of-scope items written down","Every deliverable has one Accountable person","Baseline approved within 5 business days"],"kpis":[["Charter sign-off before work starts","100% of projects"],["Baseline approved","Within 5 business days of kickoff"],["Kickoff attendance of key stakeholders","90% or more"]],"risks":[["Unclear scope leads to disputes","Explicit out-of-scope list and change control from day one."],["Missing stakeholder discovered late","Stakeholder mapping before kickoff."],["Team over-allocated","Confirm resource availability with line managers before baseline."]],"related":["Change Request Control","Risk and Issue Log Review","Weekly Status Reporting","Resource Allocation and Capacity Planning"],"review":"Every 12 months, or after a project closure review identifies kickoff gaps"},{"id":"pm-change-request-control","dept":"pm","title":"Change Request Control","summary":"Changes to project scope, schedule or budget are assessed and approved before work starts on them.","tags":["change control","change request","scope creep","variation","change order","baseline"],"purpose":"To control scope creep by making the impact of every change visible and agreed. It keeps the baseline meaningful and protects margins on client work.","scope":"Covers changes to the approved scope, deliverables, schedule, budget or quality criteria of any baselined project. It does not cover IT production changes, which follow IT change management.","definitions":[["Change request (CR)","A formal request to change the project baseline."],["Impact assessment","Analysis of the change's effect on scope, schedule, cost, quality, resources and risk."],["Change board","The people authorised to approve changes, set by size of impact."],["Change log","Register of all change requests and their status."]],"roles":[["Requester","Raises the change and explains the reason and value."],["Project Manager","Logs, coordinates impact assessment and implements approved changes."],["Project Team","Estimates effort and identifies technical impacts."],["Change Board","Approves, rejects or defers changes within its authority."],["Account Manager","For client projects, agrees commercial terms and gets client signature."]],"prereqs":["Baselined project plan and budget","Change request form","Change log","Approval thresholds"],"steps":[{"t":"Raise the change","d":"Requester submits a CR describing the change, reason, priority and desired date. Verbal requests are logged by the Project Manager.","o":"Requester"},{"t":"Log and acknowledge","d":"Log the CR with a unique number and acknowledge within 1 business day. No work starts on unapproved changes.","o":"Project Manager"},{"t":"Triage","d":"Decide if it is a change, a defect or already in scope. Close requests that are already covered with an explanation.","o":"Project Manager"},{"t":"Assess impact","d":"Team estimates effort, schedule, cost, risk and dependencies within 3 business days for normal changes.","o":"Project Team"},{"t":"Prepare options","d":"Present options such as accept, defer to a later phase, or trade off against another item.","o":"Project Manager"},{"t":"Agree commercials","d":"For client projects, prepare a change order with price and timeline and obtain client written approval.","o":"Account Manager"},{"t":"Decide","d":"Change Board decides within its thresholds: Project Manager up to [small limit], Sponsor up to [larger limit], steering committee above that.","o":"Change Board"},{"t":"Update the baseline","d":"For approved changes, update scope, plan, budget and RAID log and record the new baseline version.","o":"Project Manager"},{"t":"Communicate the decision","d":"Inform the Requester and team of the decision and its effect within 1 business day.","o":"Project Manager"},{"t":"Report change status","d":"Include open, approved and rejected changes and cumulative impact in status reports.","o":"Project Manager"}],"checks":["No work on changes before approval","Every CR has an impact assessment","Client changes have written approval","Baseline version updated after each approval"],"kpis":[["Changes assessed on time","90% within 3 business days"],["Unapproved scope work","Zero hours logged against unapproved changes"],["Revenue recovered on client changes","100% of chargeable changes invoiced"]],"risks":[["Scope creep through informal requests","All requests logged, team trained to redirect requests to the PM."],["Slow decisions delay the project","Thresholds with delegated authority and decision deadlines."],["Unpaid extra work on client projects","Signed change order before work starts."]],"related":["Project Kickoff","Weekly Status Reporting","Client Deliverable Sign-off","Contract Review and Approval"],"review":"Every 12 months"},{"id":"pm-risk-issue-log-review","dept":"pm","title":"Risk and Issue Log Review","summary":"Project risks and issues are logged, scored, owned and reviewed regularly so they are acted on early.","tags":["raid log","risk register","issue log","risk management","mitigation","escalation"],"purpose":"To identify and manage threats to project success before they cause damage, and resolve issues quickly. A regular review keeps the log useful rather than a forgotten spreadsheet.","scope":"Covers risks and issues for all projects with a baseline. It does not cover the company-wide enterprise risk register, though high project risks may be escalated to it.","definitions":[["Risk","An uncertain event that may affect objectives if it happens."],["Issue","A problem that is happening now and needs action."],["Risk score","Probability multiplied by impact, each rated 1 to 5."],["Response","Avoid, reduce, transfer or accept, with specific actions."]],"roles":[["Project Manager","Maintains the log and runs the review."],["Risk Owners","Monitor their risks and carry out responses."],["Project Team","Raises new risks and issues."],["Project Sponsor","Decides on escalated risks and issues."]],"prereqs":["RAID log with scoring guide","Current project plan","Escalation thresholds"],"steps":[{"t":"Log new items promptly","d":"Anyone can raise a risk or issue; the Project Manager logs it within 1 business day with description, cause and effect.","o":"Project Team"},{"t":"Score each risk","d":"Rate probability and impact 1 to 5 and calculate the score. Scores of 15 or more are high.","o":"Project Manager"},{"t":"Assign an owner","d":"Give every risk and issue one owner who can act on it.","o":"Project Manager"},{"t":"Plan responses","d":"Owner sets specific response actions with dates within 3 business days, and for issues a resolution target date.","o":"Risk Owners"},{"t":"Review weekly","d":"Hold a 20 to 30 minute weekly review: new items, changes in score, overdue actions and closure.","o":"Project Manager"},{"t":"Escalate high items","d":"Escalate high risks and issues that threaten a milestone or budget beyond tolerance to the Sponsor within 1 business day.","o":"Project Manager"},{"t":"Sponsor decides","d":"Sponsor decides on escalated items within 3 business days or asks the steering committee.","o":"Project Sponsor"},{"t":"Convert risks to issues","d":"When a risk happens, close it as a risk and open an issue linked to it.","o":"Project Manager"},{"t":"Close items","d":"Close risks when they can no longer happen and issues when resolved, recording the outcome.","o":"Risk Owners"},{"t":"Report the top risks","d":"Include the top 5 risks and open issues in the weekly status report.","o":"Project Manager"}],"checks":["Every item has an owner and next action date","High items escalated within 1 business day","Log reviewed weekly with a date stamp","Closed items have outcomes recorded"],"kpis":[["Log freshness","Reviewed weekly on 100% of active projects"],["Overdue response actions","Below 10%"],["Issue resolution","80% by target date"]],"risks":[["Log becomes stale","Weekly review in the team rhythm and freshness check in status reports."],["Risks owned by nobody","Mandatory owner field."],["Optimistic scoring","Team scoring and Sponsor challenge on top risks."]],"related":["Project Kickoff","Weekly Status Reporting","Change Request Control","Crisis Management"],"review":"Every 12 months"},{"id":"pm-weekly-status-reporting","dept":"pm","title":"Weekly Status Reporting","summary":"Each active project publishes a concise, honest weekly status report with RAG rating, progress, risks and asks.","tags":["status report","rag status","project update","progress report","stakeholder update","weekly report"],"purpose":"To give sponsors and stakeholders a reliable weekly view of project health so they can act early. Consistent format makes reports quick to write and read.","scope":"Covers all active baselined projects. It does not cover daily stand-ups or quarterly portfolio reviews.","definitions":[["RAG","Red, amber, green rating of project health against agreed criteria."],["Green","On track for scope, schedule and budget within tolerance."],["Amber","At risk; recovery possible within the team's control."],["Red","Off track; needs Sponsor decision or help."]],"roles":[["Project Manager","Writes and publishes the report."],["Workstream Leads","Provide updates on their areas."],["Project Sponsor","Reads, challenges and acts on asks."],["PMO Lead","Maintains the template and portfolio view."]],"prereqs":["Status report template","Up-to-date plan, RAID log and budget tracker","Distribution list"],"steps":[{"t":"Collect updates","d":"Workstream Leads send progress, next week's plan and blockers by [day and time].","o":"Workstream Leads"},{"t":"Check against the baseline","d":"Compare milestones, spend to date and forecast against the baseline.","o":"Project Manager"},{"t":"Set the RAG rating","d":"Rate overall, schedule, budget, scope and quality using the agreed criteria, for example schedule amber if a milestone slips up to [5] days, red beyond.","o":"Project Manager"},{"t":"Write the summary","d":"Write a 3 to 5 line executive summary stating status, key change since last week and what is needed.","o":"Project Manager"},{"t":"List progress and next steps","d":"List completed items this week and planned items next week, referencing milestones.","o":"Project Manager"},{"t":"Show risks, issues and changes","d":"Include the top risks and issues with owners and the status of change requests.","o":"Project Manager"},{"t":"Make asks explicit","d":"State decisions or help needed, from whom and by when.","o":"Project Manager"},{"t":"Publish on time","d":"Publish by [day and time] in the agreed channel and archive in the project folder.","o":"Project Manager"},{"t":"Follow up asks","d":"Sponsor responds to asks within 3 business days or schedules a discussion.","o":"Project Sponsor"},{"t":"Consolidate the portfolio","d":"PMO compiles a portfolio view of all RAG ratings and flags red projects to leadership.","o":"PMO Lead"}],"checks":["RAG based on criteria, not opinion","Red status always has a recovery plan or ask","Report published on time","Previous asks followed up"],"kpis":[["On-time reports","95% of weeks"],["Watermelon projects (green turning red suddenly)","Zero"],["Asks answered","90% within 3 business days"]],"risks":[["Optimistic reporting hides problems","Objective RAG criteria and a no-blame culture for amber and red."],["Reports not read","Short format with explicit asks."],["Inconsistent formats","Single template maintained by the PMO."]],"related":["Risk and Issue Log Review","Weekly Leadership Meeting","Change Request Control"],"review":"Every 12 months"},{"id":"pm-client-deliverable-signoff","dept":"pm","title":"Client Deliverable Sign-off","summary":"Deliverables are quality-checked, submitted with acceptance criteria and formally accepted by the client.","tags":["client acceptance","sign-off","deliverable approval","uat","acceptance certificate","milestone payment"],"purpose":"To get clear, documented client acceptance of each deliverable so the project can move on and invoices can be raised. It avoids endless revision loops.","scope":"Covers deliverables defined in a contract or statement of work for client projects. It does not cover internal approvals or informal drafts shared for feedback.","definitions":[["Acceptance criteria","Measurable conditions a deliverable must meet, agreed in the SOW."],["Review period","Time the client has to accept or reject, for example [10] business days."],["Deemed acceptance","Contract term that treats a deliverable as accepted if no rejection is given within the review period."],["Revision round","One cycle of client feedback and rework."]],"roles":[["Project Manager","Submits deliverables and manages the acceptance process."],["Quality Reviewer","Checks the deliverable against criteria before submission."],["Client Approver","The named client person authorised to accept."],["Account Manager","Handles commercial issues and invoices on acceptance."]],"prereqs":["SOW with acceptance criteria and review period","Acceptance certificate template","Deliverable tracker","Internal quality checklist"],"steps":[{"t":"Confirm the approver","d":"At kickoff, confirm in writing who on the client side can accept each deliverable.","o":"Project Manager"},{"t":"Run an internal quality review","d":"Before submission, review the deliverable against acceptance criteria and the internal checklist. Fix all critical defects.","o":"Quality Reviewer"},{"t":"Submit formally","d":"Send the deliverable with the acceptance certificate, criteria checklist and the review deadline.","o":"Project Manager"},{"t":"Hold a walkthrough","d":"Offer a 30 to 60 minute walkthrough so the client understands what is delivered.","o":"Project Manager"},{"t":"Track the review period","d":"Send a reminder at the midpoint and 2 business days before the deadline.","o":"Project Manager"},{"t":"Collect consolidated feedback","d":"Ask for one consolidated set of feedback that references the acceptance criteria.","o":"Client Approver"},{"t":"Classify feedback","d":"Sort feedback into defects (rework within scope) and new requests (change requests).","o":"Project Manager"},{"t":"Rework within limits","d":"Fix defects within the agreed number of revision rounds, normally [2]. Further rounds go through change control.","o":"Project Manager"},{"t":"Obtain signed acceptance","d":"Get the signed certificate or written acceptance email from the Client Approver.","o":"Client Approver"},{"t":"Trigger invoicing","d":"Notify the Account Manager on acceptance so milestone invoices go out within 2 business days.","o":"Account Manager"},{"t":"File the record","d":"Store the deliverable version and acceptance evidence in the project folder.","o":"Project Manager"}],"checks":["Internal review completed before every submission","Acceptance from a named authorised approver","Feedback classified as defect or change","Invoice raised after acceptance"],"kpis":[["First-pass acceptance","70% or more of deliverables accepted without rework"],["Acceptance cycle time","Within the review period for 90% of deliverables"],["Invoice after acceptance","100% within 2 business days"]],"risks":[["Endless revisions","Revision round limit and change control for new requests."],["Acceptance by wrong person","Approver named in writing at kickoff."],["Delayed payment","Deemed acceptance clause and prompt invoicing."]],"related":["Change Request Control","Project Closure and Lessons Learned","Contract Review and Approval","Invoicing and Accounts Receivable"],"review":"Every 12 months, or after a client dispute"},{"id":"pm-project-closure-lessons-learned","dept":"pm","title":"Project Closure and Lessons Learned","summary":"Projects close formally with handover, final accounts, archived records and lessons captured and acted on.","tags":["project closure","lessons learned","retrospective","post-mortem","handover","close-out"],"purpose":"To end projects cleanly so that nothing is left open and the organisation gets better with each project. It releases people and budget and records what worked.","scope":"Covers completed, cancelled or paused projects. It does not cover ongoing support after handover, which follows the support or account management process.","definitions":[["Closure report","Summary of outcomes against objectives, budget, schedule and benefits."],["Handover","Transfer of deliverables, documentation and responsibility to the operating team or client."],["Lessons learned","Practical insights from the project, each with a recommended action."]],"roles":[["Project Manager","Runs the closure checklist and retrospective."],["Project Sponsor","Approves closure and confirms objectives met."],["Operations Owner","Receives the handover and accepts responsibility."],["Finance Team","Closes cost codes and confirms final costs."],["PMO Lead","Stores lessons and turns them into process improvements."]],"prereqs":["Client or stakeholder acceptance of final deliverables","Closure checklist","Final budget and timesheet data","Retrospective format"],"steps":[{"t":"Confirm final acceptance","d":"Confirm all deliverables are accepted and any open defects are agreed for support.","o":"Project Manager"},{"t":"Hand over to operations","d":"Transfer documentation, credentials, support contacts and known issues, and get the Operations Owner's written acceptance.","o":"Operations Owner"},{"t":"Close contracts and suppliers","d":"Confirm supplier deliverables are complete, final invoices received and contracts ended or transferred.","o":"Project Manager"},{"t":"Close the finances","d":"Finance closes cost codes within 10 business days and confirms final cost vs budget.","o":"Finance Team"},{"t":"Release resources","d":"Inform line managers of release dates and give brief feedback on each team member.","o":"Project Manager"},{"t":"Run the retrospective","d":"Hold a 60 to 90 minute session within 2 weeks of completion covering what went well, what did not and what to change, with input from the client where possible.","o":"Project Manager"},{"t":"Write actionable lessons","d":"Turn each lesson into a specific recommendation with an owner, for example updating a template or estimate.","o":"Project Manager"},{"t":"Write the closure report","d":"Summarise objectives, results, budget and schedule variance, benefits tracking plan and lessons.","o":"Project Manager"},{"t":"Approve closure","d":"Sponsor reviews the report and formally closes the project.","o":"Project Sponsor"},{"t":"Archive records","d":"Archive the project folder, revoke temporary access and set retention.","o":"Project Manager"},{"t":"Act on lessons","d":"PMO reviews lessons quarterly and updates standards, templates and estimating data.","o":"PMO Lead"}],"checks":["Written handover acceptance","Cost codes closed","Retrospective held within 2 weeks","Lessons have owners and actions","Access revoked"],"kpis":[["Closure within target","Closure report approved within 30 days of completion"],["Lessons implemented","70% of actions completed within 6 months"],["Open items at closure","Zero unowned items"]],"risks":[["Projects never formally closed","Closure checklist required to release budget and staff."],["Lessons recorded but ignored","Quarterly PMO review and owner per lesson."],["Lingering access to client systems","Access revocation in the checklist."]],"related":["Client Deliverable Sign-off","Project Kickoff","Document Retention and Disposal"],"review":"Every 12 months"},{"id":"pm-resource-capacity-planning","dept":"pm","title":"Resource Allocation and Capacity Planning","summary":"Demand for people is matched to available capacity, with conflicts resolved before they delay projects or burn people out.","tags":["resource planning","capacity planning","allocation","utilisation","staffing","workload","bench"],"purpose":"To allocate people to projects realistically and plan hiring or contractors ahead of need. It balances delivery commitments with sustainable workloads.","scope":"Covers allocation of employees and contractors to projects and major work across delivery teams. It does not cover hiring approvals or individual task assignment within a team.","definitions":[["Capacity","Available working hours after leave, holidays and non-project time."],["Demand","Hours required by planned and pipeline projects."],["Utilisation","Percentage of capacity spent on project work."],["Soft booking","Tentative allocation for a likely but unconfirmed project."]],"roles":[["Resource Manager","Maintains the resource plan and resolves allocation conflicts."],["Project Managers","Submit resource requests and forecast demand."],["Line Managers","Confirm availability, skills and development needs."],["Delivery Director","Decides priority conflicts and approves hiring or contractors."]],"prereqs":["Resource planning tool or spreadsheet","Skills matrix","Leave calendar","Sales pipeline with probabilities"],"steps":[{"t":"Calculate capacity","d":"Calculate monthly capacity per person, deducting leave, holidays and a [15 to 20%] allowance for internal work.","o":"Resource Manager"},{"t":"Submit demand","d":"Project Managers submit resource requests by role, skill, hours and dates at least [4] weeks ahead.","o":"Project Managers"},{"t":"Add pipeline demand","d":"Add soft bookings for pipeline deals above [60%] probability.","o":"Resource Manager"},{"t":"Match people to demand","d":"Allocate by skills, availability and development goals, keeping planned utilisation between [70 and 85%].","o":"Resource Manager"},{"t":"Confirm with line managers","d":"Line Managers confirm allocations and flag wellbeing or development concerns within 2 business days.","o":"Line Managers"},{"t":"Resolve conflicts","d":"Where demand exceeds capacity, present options (re-sequence, reduce scope, contractor, delay) to the Delivery Director.","o":"Resource Manager"},{"t":"Decide priorities","d":"Delivery Director decides priority conflicts within 3 business days based on strategic and commercial value.","o":"Delivery Director"},{"t":"Hold the weekly resource meeting","d":"Review next 4 weeks of allocations, changes and gaps in a 30-minute weekly meeting.","o":"Resource Manager"},{"t":"Forecast 3 months ahead","d":"Produce a monthly 3-month forecast of capacity vs demand by role to trigger hiring or contractor decisions early.","o":"Resource Manager"},{"t":"Track actual vs planned","d":"Compare timesheet actuals with plans monthly and adjust estimates and allocations.","o":"Resource Manager"}],"checks":["No one planned above [100%] for more than 2 consecutive weeks","Conflicts decided and recorded","3-month forecast updated monthly","Actuals compared with plan"],"kpis":[["Planned utilisation","Between 70% and 85% per person"],["Requests fulfilled on time","90%"],["Forecast accuracy","Within 10% of actual demand"]],"risks":[["Burnout from over-allocation","Utilisation caps and line manager review."],["Key person dependency","Skills matrix and cross-training plans."],["Late hiring causes delays","3-month forecast with hiring triggers."]],"related":["Project Kickoff","Weekly Status Reporting","Recruitment and Hiring","Quarterly OKR Setting"],"review":"Every 12 months, or after a major change in team size"}];
